  {"id":"g9-math-1-u1-1","grade":"g9","subject":"math","term":1,"unit":1,"no":1,"title":"الأنواع المختلفة من الأعداد","summary":"شرح متحرك لتصنيف الأعداد الطبيعية والكلية والصحيحة والنسبية وغير النسبية والمربعة والمكعبة، ثم أنشطة بثلاثة مستويات.","page":"lesson-types-of-numbers.html","video":"","pdf":"","notes":["الأعداد الطبيعية تبدأ من ١ (١، ٢، ٣، ...)، والأعداد الكلية تضيف الصفر (٠، ١، ٢، ...).","الأعداد الصحيحة تشمل الموجبة والصفر والسالبة دون كسور.","العدد النسبي يُكتب على صورة أ/ب حيث ب ≠ ٠، ويشمل الكسور العشرية المنتهية والدورية.","العدد غير النسبي لا يُكتب كسرًا مثل √٢ و √٣ و π.","الأعداد المربعة مثل ١، ٤، ٩، ١٦، والمكعبة مثل ١، ٨، ٢٧، ٦٤."],"exercises":["صنّف الأعداد الآتية: −٥ ، ٠٫٧٥ ، √٧ ، ٦٤.","اذكر عددًا يكون مربعًا ومكعبًا في الوقت نفسه."],"levels":{"easy":[{"type":"mcq","q":"أيُّ الأعداد الآتية عددٌ كليٌّ وليس طبيعيًّا؟","options":["٠","١","−١","٢"],"answer":0,"why":"الأعداد الطبيعية تبدأ من ١، بينما الكلية تضيف الصفر."},{"type":"mcq","q":"أيُّ الأعداد الآتية عددٌ غير نسبي؟","options":["٠٫٥","√٧","−٣","١/٤"],"answer":1,"why":"٧ ليس مربعًا كاملًا، لذا √٧ غير نسبي."},{"type":"mcq","q":"أيُّ الأعداد الآتية يُعدّ مربعًا كاملًا؟","options":["١٢","١٨","٢٥","٣٠"],"answer":2,"why":"٢٥ = ٥ × ٥ فهو مربع كامل."},{"type":"mcq","q":"العدد −٨ ينتمي إلى مجموعة الأعداد:","options":["الطبيعية","الكلية","الصحيحة الزوجية","غير النسبية"],"answer":2,"why":"−٨ عدد صحيح سالب ويقبل القسمة على ٢."}],"medium":[{"type":"mcq","q":"أيُّ الأعداد الآتية مربع ومكعب في آنٍ واحد؟","options":["١٦","٢٧","٦٤","٨١"],"answer":2,"why":"٦٤ = ٨² وأيضًا ٦٤ = ٤³."},{"type":"tfr","q":"كل عدد صحيح هو عدد نسبي.","answer":true,"reasons":["لأنه يمكن كتابة أي عدد صحيح على صورة كسر مقامه ١","لأن الأعداد الصحيحة فيها كسور عشرية","لأن الصفر ليس نسبيًّا"],"reason":0},{"type":"essay","q":"اذكر ثلاثة أعداد مربعة كاملة وثلاثة أعداد مكعبة كاملة.","model":"مربعة: ٤، ٩، ١٦ (أو ١، ٢٥، ٣٦). مكعبة: ١، ٨، ٢٧ (أو ٦٤، ١٢٥)."},{"type":"tfr","q":"العدد √٩ يُعدّ عددًا غير نسبي.","answer":false,"reasons":["لأن √٩ = ٣ وهو عدد صحيح ونسبي","لأن كل جذر غير نسبي","لأن ٩ عدد فردي"],"reason":0},{"type":"mcq","q":"العدد ٠٫٢٥ ينتمي إلى:","options":["الصحيحة","النسبية","غير النسبية","الطبيعية"],"answer":1,"why":"٠٫٢٥ = ١/٤ وهو عدد نسبي."},{"type":"essay","q":"ما الفرق بين الأعداد الطبيعية والأعداد الكلية؟","model":"الأعداد الطبيعية تبدأ من ١ (١، ٢، ٣...)، أما الأعداد الكلية فتبدأ من الصفر (٠، ١، ٢...)."},{"type":"tfr","q":"العدد ٠ يُعدّ عددًا زوجيًّا.","answer":true,"reasons":["لأنه يقبل القسمة على ٢ دون باقٍ (٠ ÷ ٢ = ٠)","لأنه عدد طبيعي","لأنه غير نسبي"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ مجموعة مما يأتي تحتوي على أعداد نسبية فقط؟","options":["{−٣، ٠٫٥، √١٦}","{√٢، ٥، ٠}","{π، ١/٢، ٤}","{√٥، √٧، ٣}"],"answer":0,"why":"−٣ و ٠٫٥ و √١٦ (= ٤) كلها نسبية."},{"type":"essay","q":"صنّف العدد −١٢ بذكر أربع مجموعات عددية ينتمي إليها.","model":"عدد صحيح، سالب، زوجي، نسبي، حقيقي."},{"type":"tfr","q":"العدد ٠٫٣٣٣... يُعدّ عددًا غير نسبي لأنه غير منتهٍ.","answer":false,"reasons":["لأنه كسر عشري دوري يساوي ١/٣ فهو نسبي","لأنه عدد صحيح","لأنه أكبر من ١"],"reason":0},{"type":"mcq","q":"أصغر عدد طبيعي هو:","options":["٠","١","−١","٢"],"answer":1,"why":"الأعداد الطبيعية تبدأ من ١."},{"type":"essay","q":"أعطِ مثالين لعددين غير نسبيين يقعان بين ٢ و ٣.","model":"مثال: √٥ ≈ ٢٫٢٣ ، √٦ ≈ ٢٫٤٥ ، √٧ ≈ ٢٫٦٤ ، √٨ ≈ ٢٫٨٢."},{"type":"tfr","q":"مجموع عددين فرديين يكون دائمًا عددًا زوجيًّا.","answer":true,"reasons":["لأن مثلًا ٣ + ٥ = ٨ وهو يقبل القسمة على ٢","لأن مجموع الفرديين فردي","لأن الأعداد الفردية لا تُجمع"],"reason":0},{"type":"mcq","q":"أيُّ الأعداد الآتية ليس عددًا صحيحًا؟","options":["−١٠","٠","√٢٥","٣٫٥"],"answer":3,"why":"٣٫٥ يحتوي على جزء عشري."},{"type":"essay","q":"هل العبارة «كل عدد نسبي هو عدد صحيح» صحيحة؟ فسّر بمثال.","model":"خطأ؛ مثلاً ١/٢ أو ٠٫٥ عدد نسبي لكنه ليس عددًا صحيحًا."},{"type":"tfr","q":"الأعداد الحقيقية تتكوّن من اتحاد الأعداد النسبية وغير النسبية.","answer":true,"reasons":["لأن كل عدد حقيقي إما نسبي أو غير نسبي","لأن الحقيقية لا تشمل الكسور","لأنها تشمل الطبيعية فقط"],"reason":0},{"type":"essay","q":"اكتب مثالًا لعدد: (١) صحيح سالب فردي، (٢) نسبي غير صحيح، (٣) غير نسبي.","model":"مثال: (١) −٧ ، (٢) ٣/٤ أو ٠٫٦ ، (٣) √٢ أو π."}]}},
  {"id":"g9-math-1-u1-2","grade":"g9","subject":"math","term":1,"unit":1,"no":2,"title":"الأعداد الأولية","summary":"شرح متحرك لمفهوم العدد الأولي والتحليل للعوامل الأولية وإيجاد ع.م.أ و م.م.أ، ثم أنشطة بثلاثة مستويات.","page":"lesson-prime-numbers.html","video":"","pdf":"","notes":["العدد الأولي عدد أكبر من ١ له عاملان مختلفان فقط: ١ والعدد نفسه.","العدد ١ ليس أوليًّا، والعدد ٢ هو العدد الأولي الزوجي الوحيد.","كل عدد مركّب يُحلّل إلى ضرب عوامل أولية بشجرة العوامل أو القسمة المتكررة.","ع.م.أ = حاصل ضرب العوامل الأولية المشتركة فقط بأصغر أُس.","م.م.أ = حاصل ضرب جميع العوامل الأولية بأكبر أُس."],"exercises":["حلّل العدد ٦٠ إلى عوامله الأولية.","أوجد ع.م.أ و م.م.أ للعددين ٢٤ و ٣٦."],"levels":{"easy":[{"type":"mcq","q":"أيُّ الأعداد الآتية عددٌ أولي؟","options":["١","٩","١٣","١٥"],"answer":2,"why":"١٣ لا يقبل القسمة إلا على ١ و ١٣."},{"type":"mcq","q":"ما العدد الأولي الزوجي الوحيد؟","options":["٠","٢","٤","٦"],"answer":1,"why":"أي عدد زوجي أكبر من ٢ يقبل القسمة على ٢."},{"type":"mcq","q":"ما التحليل الأولي للعدد ١٨؟","options":["٢ × ٩","٢ × ٣²","٣ × ٦","١ × ١٨"],"answer":1,"why":"١٨ = ٢ × ٣ × ٣ = ٢ × ٣²."},{"type":"mcq","q":"ما العامل المشترك الأكبر للعددين ١٢ و ١٨؟","options":["٣","٦","١٢","٣٦"],"answer":1,"why":"ع.م.أ(١٢، ١٨) = ٦."}],"medium":[{"type":"mcq","q":"ما المضاعف المشترك الأصغر للعددين ٤ و ٦؟","options":["٢","١٢","٢٤","١٠"],"answer":1,"why":"م.م.أ(٤، ٦) = ١٢."},{"type":"tfr","q":"العدد ١ يُعدّ أصغر عدد أولي.","answer":false,"reasons":["لأن للعدد ١ عاملًا واحدًا فقط، والعدد الأولي يجب أن يكون له عاملان مختلفان","لأن ١ عدد زوجي","لأن ١ يقبل القسمة على ٢"],"reason":0},{"type":"essay","q":"حلّل العدد ٣٦ إلى عوامله الأولية بصيغة القوى.","model":"٣٦ = ٤ × ٩ = ٢ × ٢ × ٣ × ٣ = ٢² × ٣²."},{"type":"tfr","q":"كل عدد فردي أكبر من ٢ هو عدد أولي.","answer":false,"reasons":["لأن مثلًا ٩ و ١٥ و ٢١ أعداد فردية لكنها مركّبة وليست أولية","لأن الأعداد الأولية كلها زوجية","لأن ٣ ليس أوليًّا"],"reason":0},{"type":"mcq","q":"إذا كان أ = ٢³ × ٣ و ب = ٢² × ٣²، فإن ع.م.أ(أ، ب) =","options":["٢² × ٣","٢³ × ٣²","٢ × ٣","٢³ × ٣"],"answer":0,"why":"نأخذ المشتركة بأصغر أُس: ٢² × ٣ = ١٢."},{"type":"essay","q":"أوجد م.م.أ للعددين ١٢ و ١٥.","model":"١٢ = ٢² × ٣ ، ١٥ = ٣ × ٥ ← م.م.أ = ٢² × ٣ × ٥ = ٦٠."},{"type":"tfr","q":"العدد ٢٩ عدد أولي.","answer":true,"reasons":["لأنه لا يقبل القسمة إلا على ١ و ٢٩","لأنه يقبل القسمة على ٣","لأنه عدد زوجي"],"reason":0}],"hard":[{"type":"mcq","q":"ما التحليل الأولي للعدد ١٢٠؟","options":["٢³ × ٣ × ٥","٢² × ٣ × ٥","٢³ × ١٥","٢⁴ × ٣"],"answer":0,"why":"١٢٠ = ٨ × ٣ × ٥ = ٢³ × ٣ × ٥."},{"type":"essay","q":"أوجد ع.م.أ و م.م.أ للعددين ٣٠ و ٤٥ باستخدام التحليل.","model":"٣٠ = ٢ × ٣ × ٥ ، ٤٥ = ٣² × ٥. ع.م.أ = ٣ × ٥ = ١٥. م.م.أ = ٢ × ٣² × ٥ = ٩٠."},{"type":"tfr","q":"لإيجاد م.م.أ نأخذ العوامل المشتركة فقط بأصغر أُس.","answer":false,"reasons":["لأن هذا تعريف ع.م.أ، أما م.م.أ فيأخذ جميع العوامل بأكبر أُس","لأن م.م.أ يساوي ١ دائمًا","لأننا نجمع العوامل"],"reason":0},{"type":"mcq","q":"عدد أولي يقع بين ٢٠ و ٢٥ هو:","options":["٢١","٢٢","٢٣","٢٤"],"answer":2,"why":"٢٣ عدد أولي، بينما ٢١ = ٣×٧."},{"type":"essay","q":"يرنّ جرس كل ١٢ دقيقة وجرس آخر كل ١٨ دقيقة. إذا رنّا معًا الساعة ٨:٠٠، متى يرنّان معًا مجددًا؟","model":"نجد م.م.أ(١٢، ١٨) = ٣٦ دقيقة ← يرنّان معًا الساعة ٨:٣٦."},{"type":"tfr","q":"حاصل ضرب ع.م.أ × م.م.أ لأي عددين يساوي حاصل ضرب العددين نفسيهما.","answer":true,"reasons":["فمثلاً للعددين ٤ و ٦: ع.م.أ=٢ و م.م.أ=١٢ و ٢×١٢ = ٤×٦ = ٢٤","لأن ع.م.أ أكبر من م.م.أ","لأنهما متساويان"],"reason":0},{"type":"mcq","q":"كم عددًا أوليًا يقع بين ١ و ١٠؟","options":["٣","٤","٥","٦"],"answer":1,"why":"الأعداد الأولية هي: ٢، ٣، ٥، ٧ (أربعة أعداد)."},{"type":"essay","q":"ما أكبر عدد من الأكياس المتطابقة يمكن تكوينه من ٢٤ تفاحة و ٣٦ برتقالة؟","model":"ع.م.أ(٢٤، ٣٦) = ١٢ كيسًا (في كل كيس تفاحتان و ٣ برتقالات)."},{"type":"tfr","q":"العدد ٥١ عدد أولي.","answer":false,"reasons":["لأن مجموع أرقامه ٦ يقبل القسمة على ٣، فـ ٥١ = ٣ × ١٧","لأنه عدد زوجي","لأنه ينتهي بـ ٥"],"reason":0},{"type":"essay","q":"حلّل العدد ١٨٠ إلى عوامله الأولية واكتبه بصيغة القوى.","model":"١٨٠ = ١٨ × ١٠ = (٢ × ٣²) × (٢ × ٥) = ٢² × ٣² × ٥."}]}},
  {"id":"g9-math-1-u1-3","grade":"g9","subject":"math","term":1,"unit":1,"no":3,"title":"القوى والجذور","summary":"شرح متحرك للأساس والأُس والجذر التربيعي والتكعيبي وإيجاد الجذور بالتحليل، ثم أنشطة بثلاثة مستويات.","page":"lesson-powers-and-roots.html","video":"","pdf":"","notes":["القوة اختصار للضرب المتكرر: ٥³ = ٥ × ٥ × ٥ = ١٢٥.","أي عدد غير الصفر أُس صفر يساوي ١ (أ⁰ = ١)، وأي عدد أُس ١ يساوي نفسه.","الجذر التربيعي (√) عكس التربيع، والجذر التكعيبي (∛) عكس التكعيب.","لإيجاد جذر عدد كبير بالتحليل: في التربيعي نقسم الأُس على ٢، وفي التكعيبي على ٣.","الأُس الزوجي لعدد سالب يعطي موجبًا، والفردي يعطي سالبًا."],"exercises":["احسب: ٢⁵ ، ٧⁰ ، √٨١ ، ∛(−٢٧).","أوجد √١٤٤ باستخدام التحليل للعوامل الأولية."],"levels":{"easy":[{"type":"mcq","q":"ما قيمة ٢⁵ ؟","options":["١٠","١٦","٣٢","٦٤"],"answer":2,"why":"٢ × ٢ × ٢ × ٢ × ٢ = ٣٢."},{"type":"mcq","q":"ما قيمة ٩⁰ ؟","options":["٠","١","٩","−١"],"answer":1,"why":"أي عدد غير الصفر أُس صفر يساوي ١."},{"type":"mcq","q":"ما قيمة √٦٤ ؟","options":["٦","٧","٨","١٦"],"answer":2,"why":"٨ × ٨ = ٦٤."},{"type":"mcq","q":"ما قيمة ∛٢٧ ؟","options":["٣","٩","٦","١٣٫٥"],"answer":0,"why":"٣ × ٣ × ٣ = ٢٧."}],"medium":[{"type":"mcq","q":"ما قيمة ∛(−٨) ؟","options":["٢","−٢","−٤","٤"],"answer":1,"why":"(−٢) × (−٢) × (−٢) = −٨."},{"type":"tfr","q":"قيمة ٥³ تساوي ١٥.","answer":false,"reasons":["لأن ٥³ = ٥ × ٥ × ٥ = ١٢٥ وليس ٥ × ٣","لأن ٥³ = ٥ + ٣","لأن ٥³ = ٥٠"],"reason":0},{"type":"essay","q":"أوجد قيمة √(٢⁴ × ٣²) باستخدام التحليل.","model":"نقسم كل أُس على ٢: ٢² × ٣¹ = ٤ × ٣ = ١٢."},{"type":"tfr","q":"قيمة (−٣)² تساوي +٩.","answer":true,"reasons":["لأن الأُس زوجي، و (−٣) × (−٣) = +٩","لأن الأُس فردي","لأن الناتج دائمًا سالب"],"reason":0},{"type":"mcq","q":"ما قيمة ١٥⁰ + ٤¹ ؟","options":["١","٤","٥","١٩"],"answer":2,"why":"١ + ٤ = ٥."},{"type":"essay","q":"احسب قيمة (−٢)³ + √٤٩.","model":"(−٢)³ = −٨ ، √٤٩ = ٧ ← −٨ + ٧ = −١."},{"type":"tfr","q":"لا يمكن إيجاد الجذر التكعيبي لعدد سالب.","answer":false,"reasons":["لأن حاصل ضرب عدد سالب في نفسه ٣ مرات يعطي سالبًا، مثل ∛(−٢٧) = −٣","لأن الجذر التكعيبي موجب دائمًا","لأن الأعداد السالبة ليس لها قوى"],"reason":0}],"hard":[{"type":"mcq","q":"ما قيمة ∛(٢³ × ٥³) ؟","options":["١٠","١٥","٣٠","١٠٠"],"answer":0,"why":"نقسم كل أُس على ٣: ٢¹ × ٥¹ = ١٠."},{"type":"essay","q":"اشرح الفرق بين (−٤)² و −٤².","model":"(−٤)² = (−٤)×(−٤) = +١٦ لأن السالب داخل القوس. أما −٤² = −(٤×٤) = −١٦."},{"type":"tfr","q":"قيمة (−١)¹⁰⁰ تساوي +١.","answer":true,"reasons":["لأن الأُس ١٠٠ عدد زوجي، فيلغي الإشارة السالبة","لأن ١٠٠ فردي","لأن الناتج −١٠٠"],"reason":0},{"type":"mcq","q":"إذا كان س² = ١٢١ و س > ٠، فما قيمة س؟","options":["٩","١١","١٢","١٣"],"answer":1,"why":"√١٢١ = ١١."},{"type":"essay","q":"أوجد ∛٢١٦ بالتحليل إلى العوامل الأولية.","model":"٢١٦ = ٢³ × ٣³ ← ∛٢١٦ = ٢ × ٣ = ٦."},{"type":"tfr","q":"قيمة √(٩ + ١٦) تساوي √٩ + √١٦.","answer":false,"reasons":["لأن √(٩+١٦) = √٢٥ = ٥، بينما √٩ + √١٦ = ٣ + ٤ = ٧","لأنهما متساويان دائمًا","لأن √٢٥ = ٧"],"reason":0},{"type":"mcq","q":"ما قيمة ٣⁴ ÷ ٣² ؟","options":["٣","٦","٩","٢٧"],"answer":2,"why":"٨١ ÷ ٩ = ٩ (أو ٣² = ٩)."},{"type":"essay","q":"مكعب حجمه ١٢٥ سم³. ما طول حرفه؟","model":"طول الحرف = ∛١٢٥ = ٥ سم."},{"type":"tfr","q":"قيمة ٠⁵ تساوي ١.","answer":false,"reasons":["لأن ٠ × ٠ × ٠ × ٠ × ٠ = ٠، وقاعدة أُس صفر لا تنطبق هنا","لأن أي قوة تساوي ١","لأن ٠⁵ = ٥"],"reason":0},{"type":"essay","q":"احسب قيمة: √١٠٠ − ∛٦٤ + ٢³.","model":"١٠ − ٤ + ٨ = ١٤."}]}},
  {"id":"g9-math-1-u1-4","grade":"g9","subject":"math","term":1,"unit":1,"no":4,"title":"الأعداد الموجّهة","summary":"شرح متحرك لمقارنة وجمع وطرح وضرب وقسمة الأعداد الموجّهة مع مسائل حياتية، ثم أنشطة بثلاثة مستويات.","page":"lesson-directed-numbers.html","video":"","pdf":"","notes":["على خط الأعداد: العدد الأقرب للصفر في الأعداد السالبة هو الأكبر (−٢ > −٧).","الجمع (نفس الإشارة): نجمع ونبقي الإشارة. (إشارتان مختلفتان): نطرح ونأخذ إشارة الأكبر.","الطرح: طرح عدد سالب يتحوّل إلى جمع: أ − (−ب) = أ + ب.","الضرب والقسمة: إشارتان متشابهتان ← موجب (+)، إشارتان مختلفتان ← سالب (−)."],"exercises":["احسب: (−٨) + ٥ ، ٦ − (−٤) ، (−٣) × (−٧).","درجة الحرارة −٣° وارتفعت ٨ درجات، كم أصبحت؟"],"levels":{"easy":[{"type":"mcq","q":"ما ناتج: (−٧) + ٤ ؟","options":["−١١","−٣","٣","١١"],"answer":1,"why":"نطرح ٧−٤ = ٣ بإشارة الأكبر (−)."},{"type":"mcq","q":"ما ناتج: ٥ − (−٣) ؟","options":["٢","−٨","٨","−٢"],"answer":2,"why":"٥ + ٣ = ٨."},{"type":"mcq","q":"ما ناتج: (−٦) × (−٤) ؟","options":["٢٤","−٢٤","−١٠","١٠"],"answer":0,"why":"سالب × سالب = موجب ٢٤."},{"type":"mcq","q":"ما ناتج: (−٣٦) ÷ ٩ ؟","options":["٤","−٤","−٢٧","٢٧"],"answer":1,"why":"سالب ÷ موجب = سالب ٤."}],"medium":[{"type":"mcq","q":"أيُّ العددين أكبر: −٣ أم −١٠ ؟","options":["−٣","−١٠","متساويان","لا يمكن المقارنة"],"answer":0,"why":"−٣ أقرب إلى الصفر ويقع يمين −١٠."},{"type":"tfr","q":"ناتج (−٥) + (−٦) يساوي +١١.","answer":false,"reasons":["لأن الإشارتين متشابهتان سالبتان، فنجمع ونبقي السالب: −١١","لأن سالب + سالب = موجب دائمًا","لأن الناتج −١"],"reason":0},{"type":"essay","q":"كانت درجة الحرارة −٤° فجرًا وارتفعت ١١ درجة ظهرًا. كم أصبحت؟","model":"−٤ + ١١ = +٧°."},{"type":"tfr","q":"ناتج قسمة عدد سالب على عدد سالب هو عدد موجب.","answer":true,"reasons":["لأن الإشارتين متشابهتان في القسمة تعطي موجبًا","لأن القسمة تعطي سالبًا دائمًا","لأن الناتج صفر"],"reason":0},{"type":"mcq","q":"ما ناتج: (−٢) × ٣ × (−٤) ؟","options":["−٢٤","٢٤","−٩","٩"],"answer":1,"why":"(−٦) × (−٤) = +٢٤."},{"type":"essay","q":"احسب: (−١٢) − (−٥).","model":"−١٢ + ٥ = −٧."},{"type":"tfr","q":"الصفر أصغر من أي عدد سالب.","answer":false,"reasons":["لأن الصفر أكبر من جميع الأعداد السالبة ويقع يمينها","لأن الصفر سالب","لأن الصفر يساوي −١"],"reason":0}],"hard":[{"type":"mcq","q":"ما قيمة: (−٤٨) ÷ (−٦) − ١٠ ؟","options":["−٢","١٨","−١٨","٢"],"answer":0,"why":"٨ − ١٠ = −٢."},{"type":"essay","q":"غواصة على عمق ١٥ مترًا تحت سطح البحر (−١٥ م)، هبطت ٨ أمتار أخرى ثم صعدت ٦ أمتار. أين أصبحت؟","model":"−١٥ − ٨ + ٦ = −٢٣ + ٦ = −١٧ مترًا (عمق ١٧ مترًا تحت السطح)."},{"type":"tfr","q":"إذا كان أ × ب = −١٢ و أ = −٣ فإن ب = −٤.","answer":false,"reasons":["لأن (−٣) × (+٤) = −١٢، إذن ب = +٤ وليس −٤","لأن ب = −٩","لأن الضرب يساوي +١٢"],"reason":0},{"type":"mcq","q":"رتّب تصاعديًا: −٥ ، ٣ ، −٩ ، ٠","options":["−٩، −٥، ٠، ٣","−٥، −٩، ٠، ٣","٠، ٣، −٥، −٩","٣، ٠، −٥، −٩"],"answer":0,"why":"الأصغر هو الأبعد يسارًا (−٩)."},{"type":"essay","q":"احسب: (−٣) × (٤ − ٩) + (−١٠) ÷ ٢.","model":"(−٣)×(−٥) + (−٥) = ١٥ − ٥ = ١٠."},{"type":"tfr","q":"ناتج (−١) × (−١) × (−١) يساوي −١.","answer":true,"reasons":["لأن ضرب ٣ أعداد سالبة يعطي سالبًا","لأن الناتج +١","لأن الناتج −٣"],"reason":0},{"type":"mcq","q":"ما العدد الذي إذا طُرح منه −٧ كان الناتج ١٠؟","options":["٣","١٧","−٣","−١٧"],"answer":0,"why":"س − (−٧) = ١٠ ← س + ٧ = ١٠ ← س = ٣."},{"type":"essay","q":"احسب الفرق بين درجة الحرارة القصوى +١٤° والدنيا −٦°.","model":"١٤ − (−٦) = ١٤ + ٦ = ٢٠ درجة."},{"type":"tfr","q":"ناتج (−٨) + ٨ يساوي صفرًا.","answer":true,"reasons":["لأنهما معكوسان جمعيان يجمعان إلى الصفر","لأن الناتج ١٦","لأن الناتج −١٦"],"reason":0},{"type":"essay","q":"أوجد عددين صحيحين حاصل ضربهما −١٥ ومجموعهما −٢.","model":"العددان هما −٥ و +٣ لأن (−٥)×٣ = −١٥ و −٥ + ٣ = −٢."}]}},
  {"id":"g9-math-1-u1-5","grade":"g9","subject":"math","term":1,"unit":1,"no":5,"title":"ترتيب العمليات الحسابية","summary":"شرح متحرك لأولويات الأقواس والقوى والجذور والضرب والقسمة والجمع والطرح، ثم أنشطة بثلاثة مستويات.","page":"lesson-order-of-operations.html","video":"","pdf":"","notes":["ترتيب الأولويات: ١) الأقواس، ٢) القوى والجذور، ٣) الضرب والقسمة، ٤) الجمع والطرح.","الضرب والقسمة متساويان في القوة (ننفّذ من اليمين إلى اليسار).","الجمع والطرح متساويان في القوة (ننفّذ من اليمين إلى اليسار).","شرطة الكسر تعمل كأقواس: نحسب البسط كاملًا والمقام كاملًا ثم نقسم."],"exercises":["احسب: ٤ + ٦ × ٢ ، (١٠ − ٤) × ٣².","احسب: ٢٤ ÷ ٦ × ٢."],"levels":{"easy":[{"type":"mcq","q":"ما قيمة: ٤ + ٦ × ٢ ؟","options":["٢٠","١٦","١٢","٢٤"],"answer":1,"why":"الضرب أولًا: ٦×٢ = ١٢ ثم ٤+١٢ = ١٦."},{"type":"mcq","q":"ما قيمة: (١٠ − ٤) × ٣ ؟","options":["١٨","−٢","٢٦","١٢"],"answer":0,"why":"القوس أولًا: ٦ × ٣ = ١٨."},{"type":"mcq","q":"ما قيمة: ٢٠ ÷ ٥ × ٢ ؟","options":["٢","٨","١٠","٤"],"answer":1,"why":"القسمة أولًا من اليمين: ٤ × ٢ = ٨."},{"type":"mcq","q":"ما قيمة: ٣ + ٢³ ؟","options":["١١","٩","١٢٥","٨"],"answer":0,"why":"القوة أولًا: ٢³ = ٨ ثم ٣ + ٨ = ١١."}],"medium":[{"type":"mcq","q":"ما قيمة: (١٥ + ٩) ÷ (٨ − ٢) ؟","options":["٤","٦","٣","١٢"],"answer":0,"why":"٢٤ ÷ ٦ = ٤."},{"type":"tfr","q":"في المسألة ١٢ − ٥ + ٣ نجمع ٥ + ٣ أولًا.","answer":false,"reasons":["لأن الجمع والطرح متساويان فنبدأ من اليمين: ١٢ − ٥ = ٧ ثم ٧ + ٣ = ١٠","لأن الجمع أقوى من الطرح","لأن الناتج ٤"],"reason":0},{"type":"essay","q":"احسب خطوة بخطوة: ١٨ − ١٢ ÷ ٣ + ٢ × ٤.","model":"١٢÷٣ = ٤ و ٢×٤ = ٨ ← ١٨ − ٤ + ٨ = ١٤ + ٨ = ٢٢."},{"type":"tfr","q":"شرطة الكسر تعني حساب البسط والمقام كاملين قبل القسمة.","answer":true,"reasons":["لأن شرطة الكسر تعمل كأقواس حول البسط والمقام","لأننا نقسم أول رقمين فقط","لأنها أقل أولوية من الجمع"],"reason":0},{"type":"mcq","q":"ما قيمة: ٥ + ٢ × (٧ − ٤)² ؟","options":["٢٣","٦٣","١١","٤١"],"answer":0,"why":"القوس ٣، التربيع ٩، الضرب ١٨، ثم ٥ + ١٨ = ٢٣."},{"type":"essay","q":"ضع أقواسًا في: ٣ + ٤ × ٢ = ١٤ لجعلها صحيحة.","model":"(٣ + ٤) × ٢ = ٧ × ٢ = ١٤."},{"type":"tfr","q":"في المسألة ٣ × ٤² نضرب ٣ × ٤ أولًا ثم نربّع.","answer":false,"reasons":["لأن القوى أقوى من الضرب: ٤² = ١٦ ثم ٣ × ١٦ = ٤٨","لأن الضرب أقوى من القوى","لأن الناتج ١٤٤"],"reason":0}],"hard":[{"type":"mcq","q":"ما قيمة: ٣٠ − ٢ × (٣ + √١٦) ؟","options":["١٦","١٤","١٩٦","٢٠"],"answer":0,"why":"√١٦ = ٤ ← القوس ٧ ← ٢×٧ = ١٤ ← ٣٠ − ١٤ = ١٦."},{"type":"essay","q":"احسب: (٤² + ٨) ÷ (١٠ − ∛٨).","model":"البسط: ١٦ + ٨ = ٢٤. المقام: ١٠ − ٢ = ٨. الناتج: ٢٤ ÷ ٨ = ٣."},{"type":"tfr","q":"ناتج ٤٨ ÷ ٨ ÷ ٢ يساوي ١٢.","answer":false,"reasons":["لأننا ننفذ من اليمين: ٤٨ ÷ ٨ = ٦ ثم ٦ ÷ ٢ = ٣","لأن ٨ ÷ ٢ = ٤ أولًا","لأن الناتج ٢٤"],"reason":0},{"type":"mcq","q":"ما قيمة: (−٢)³ + ٤ × ٥ − ٦ ÷ ٢ ؟","options":["٩","−٩","١٥","٢٥"],"answer":0,"why":"−٨ + ٢٠ − ٣ = ٩."},{"type":"essay","q":"اشرح لماذا (٢ + ٣)² ≠ ٢² + ٣².","model":"(٢+٣)² = ٥² = ٢٥، بينما ٢² + ٣² = ٤ + ٩ = ١٣."},{"type":"tfr","q":"في المسألة ٥ + [٣ × (٦ − ٢)] نحسب القوس الداخلي (٦ − ٢) أولًا.","answer":true,"reasons":["لأننا نبدأ دائمًا بالأقواس الداخلية ثم الخارجية","لأننا نجمع ٥ + ٣ أولًا","لأن الأقواس لا تغيّر الناتج"],"reason":0},{"type":"mcq","q":"ما قيمة: ١٠٠ − (٣² + ١) × ٤ ؟","options":["٦٠","٣٦٠","٨٤","٤٠"],"answer":0,"why":"القوس ٩+١ = ١٠ ← ١٠×٤ = ٤٠ ← ١٠٠ − ٤٠ = ٦٠."},{"type":"essay","q":"ضع أقواسًا لجعل العبارة صحيحة: ٢٠ − ٤ ÷ ٢ + ٦ = ١٤.","model":"(٢٠ − ٤) ÷ ٢ + ٦ = ١٦ ÷ ٢ + ٦ = ٨ + ٦ = ١٤."},{"type":"tfr","q":"القيمة العددية لـ ٥ × ٠ + ٧ تساوي ٧.","answer":true,"reasons":["لأن الضرب أولًا: ٥ × ٠ = ٠، ثم ٠ + ٧ = ٧","لأن الناتج صفر","لأن الناتج ٣٥"],"reason":0},{"type":"essay","q":"احسب: ٦ + ٢ × [١٠ − (٣ + ٢)]² ÷ ٥.","model":"القوس الداخلي ٥ ← الخارجي ١٠−٥ = ٥ ← التربيع ٢٥ ← ٢×٢٥÷٥ = ١٠ ← ٦ + ١٠ = ١٦."}]}},
  {"id":"g9-math-1-u2-1","grade":"g9","subject":"math","term":1,"unit":2,"no":1,"title":"الكسور المتكافئة","summary":"شرح متحرك للكسور المتكافئة والتبسيط لأبسط صورة والأعداد الكسرية ومقارنة الكسور، ثم أنشطة بثلاثة مستويات.","page":"lesson-equivalent-fractions.html","video":"","pdf":"","notes":["الكسور المتكافئة لها القيمة نفسها وتنتج بضرب أو قسمة البسط والمقام في نفس العدد.","التبسيط لأبسط صورة يكون بالقسمة على ع.م.أ للبسط والمقام.","للمقارنة بين كسرين نوحّد المقامين أولًا."],"exercises":["بسّط ١٨/٢٤ لأبسط صورة.","حوّل ٣ ٢/٥ إلى كسر غير اعتيادي."],"levels":{"easy":[{"type":"mcq","q":"ما أبسط صورة للكسر ١٦/٢٤ ؟","options":["٢/٣","٤/٦","٣/٤","١/٢"],"answer":0,"why":"نقسم البسط والمقام على ٨ ← ٢/٣."},{"type":"mcq","q":"إذا كان ٢/٥ = س/٣٠ فما قيمة س؟","options":["٦","١٢","١٥","١٠"],"answer":1,"why":"٥×٦ = ٣٠ ← ٢×٦ = ١٢."},{"type":"mcq","q":"ما الكسر غير الاعتيادي المكافئ للعدد الكسري ٢ ٣/٤ ؟","options":["٩/٤","١١/٤","٦/٤","٧/٤"],"answer":1,"why":"٢×٤ + ٣ = ١١ ← ١١/٤."},{"type":"mcq","q":"أيُّ الكسرين أكبر: ٣/٤ أم ٥/٨ ؟","options":["٣/٤","٥/٨","متساويان","لا يمكن"],"answer":0,"why":"٣/٤ = ٦/٨ > ٥/٨."}],"medium":[{"type":"mcq","q":"ما العدد الكسري المكافئ لـ ١٣/٤ ؟","options":["٣ ١/٤","٢ ٣/٤","٤ ١/٤","٣ ٣/٤"],"answer":0,"why":"١٣ ÷ ٤ = ٣ والباقي ١."},{"type":"tfr","q":"إضافة ٢ للبسط والمقام تعطي كسرًا مكافئًا.","answer":false,"reasons":["لأن الكسور المتكافئة تنتج بالضرب أو القسمة فقط وليس بالجمع","لأن الجمع يحفظ القيمة","لأن البسط فقط يتغير"],"reason":0},{"type":"essay","q":"بسّط الكسر ٣٦/٤٨ لأبسط صورة.","model":"ع.م.أ = ١٢ ← ٣٦÷١٢ = ٣ و ٤٨÷١٢ = ٤ ← ٣/٤."},{"type":"tfr","q":"الكسران ٣/٥ و ١٢/٢٠ متكافئان.","answer":true,"reasons":["لأن ضرب ٣ و ٥ في ٤ يعطي ١٢/٢٠","لأن ٣+٩ = ١٢","لأنهما مختلفان"],"reason":0},{"type":"mcq","q":"ما الكسر العشري المكافئ لـ ٣/٤ ؟","options":["٠٫٣٤","٠٫٧٥","٠٫٢٥","٠٫٥"],"answer":1,"why":"٣/٤ = ٧٥/١٠٠ = ٠٫٧٥."},{"type":"essay","q":"قارن بين ٢/٣ و ٣/٥ بتوحيد المقامين.","model":"٢/٣ = ١٠/١٥ و ٣/٥ = ٩/١٥ ← إذن ٢/٣ > ٣/٥."},{"type":"tfr","q":"الكسر ٧/٧ يُعدّ كسرًا غير اعتيادي يساوي ١.","answer":true,"reasons":["لأن بسطه يساوي مقامه وقيمته ١","لأنه أصغر من ١","لأنه يساوي صفرًا"],"reason":0}],"hard":[{"type":"mcq","q":"إذا كان ١٨/س = ٣/٤ فما قيمة س؟","options":["٢٠","٢٤","١٢","١٦"],"answer":1,"why":"٣×٦ = ١٨ ← ٤×٦ = ٢٤."},{"type":"essay","q":"رتّب تصاعديًا: ١/٢ ، ٢/٣ ، ٥/١٢.","model":"نوحّد على ١٢: ٦/١٢ ، ٨/١٢ ، ٥/١٢ ← الترتيب: ٥/١٢ ، ١/٢ ، ٢/٣."},{"type":"tfr","q":"أبسط صورة للكسر ١٥/٢٥ هي ٣/٥.","answer":true,"reasons":["بقسمة البسط والمقام على ٥ نحصل على ٣/٥","لأنه يقبل على ٢","لأنها ٥/٣"],"reason":0},{"type":"mcq","q":"ما الكسر المكافئ لـ ٠٫٦ في أبسط صورة؟","options":["٦/١٠","٣/٥","٢/٣","١/٦"],"answer":1,"why":"٦/١٠ ÷ ٢ = ٣/٥."},{"type":"essay","q":"حوّل ٤ ٣/٧ إلى كسر غير اعتيادي.","model":"٤ × ٧ + ٣ = ٣١ ← ٣١/٧."},{"type":"tfr","q":"الكسر ٤/٩ أكبر من ١/٢.","answer":false,"reasons":["لأن ٤/٩ = ٨/١٨ بينما ١/٢ = ٩/١٨، إذن ٤/٩ أصغر","لأن ٤ أكبر من ١","لأنهما متساويان"],"reason":0},{"type":"mcq","q":"أيُّ الكسور الآتية في أبسط صورة؟","options":["٦/٩","٨/١٢","٧/١٥","١٠/١٤"],"answer":2,"why":"لا يوجد عامل مشترك بين ٧ و ١٥ غير ١."},{"type":"essay","q":"اكتب ثلاثة كسور مكافئة للكسر ٢/٧.","model":"مثال: ٤/١٤ ، ٦/٢١ ، ٨/٢٨."},{"type":"tfr","q":"الكسر غير الاعتيادي بسطه دائمًا أصغر من مقامه.","answer":false,"reasons":["لأن بسطه أكبر من أو يساوي مقامه","لأن مقامه صفر","لأنه سالب دائمًا"],"reason":0},{"type":"essay","q":"أوجد قيمة س: (س + ١)/١٢ = ٣/٤.","model":"٣/٤ = ٩/١٢ ← س + ١ = ٩ ← س = ٨."}]}},
  {"id":"g9-math-1-u2-2","grade":"g9","subject":"math","term":1,"unit":2,"no":2,"title":"العمليات على الكسور","summary":"شرح متحرك لجمع وطرح وضرب وقسمة الكسور والأعداد الكسرية، ثم أنشطة بثلاثة مستويات.","page":"lesson-operations-on-fractions.html","video":"","pdf":"","notes":["في الجمع والطرح نوحّد المقامات أولًا ثم نجمع أو نطرح البسط فقط.","في الضرب: البسط × البسط على المقام × المقام.","في القسمة: نثبّت الأول ونحوّل ÷ إلى × ونقلب الثاني."],"exercises":["احسب: ١/٣ + ١/٤ ، ٣/٤ ÷ ٢/٥.","احسب: ١ ١/٢ × ٢ ١/٣."],"levels":{"easy":[{"type":"mcq","q":"ما ناتج: ١/٢ + ١/٦ ؟","options":["٢/٨","٢/٣","١/٣","٣/٦"],"answer":1,"why":"٣/٦ + ١/٦ = ٤/٦ = ٢/٣."},{"type":"mcq","q":"ما ناتج: ٣/٥ × ١٠/٩ ؟","options":["٢/٣","١/٣","٣٠/١٤","٣/٩"],"answer":0,"why":"نختصر ٣ مع ٩ و ٥ مع ١٠ ← ٢/٣."},{"type":"mcq","q":"ما ناتج: ٢/٣ ÷ ٤/٩ ؟","options":["٨/٢٧","٣/٢","٢/٣","١/٢"],"answer":1,"why":"٢/٣ × ٩/٤ = ١٨/١٢ = ٣/٢."},{"type":"mcq","q":"ما ناتج: ٥/٦ − ١/٣ ؟","options":["٤/٣","١/٢","٢/٣","١/٦"],"answer":1,"why":"٥/٦ − ٢/٦ = ٣/٦ = ١/٢."}],"medium":[{"type":"mcq","q":"ما ناتج: ١ ١/٢ × ٢ ؟","options":["٢ ١/٢","٣","٢","٣ ١/٢"],"answer":1,"why":"٣/٢ × ٢ = ٣."},{"type":"tfr","q":"عند جمع كسرين نجمع البسطين ونجمع المقامين معًا.","answer":false,"reasons":["لأننا نوحّد المقامين ونجمع البسطين فقط ويبقى المقام ثابتًا","لأن المقام يتضاعف","لأننا نضرب المقامين"],"reason":0},{"type":"essay","q":"احسب في أبسط صورة: ٣/٤ + ٢/٥.","model":"١٥/٢٠ + ٨/٢٠ = ٢٣/٢٠ = ١ ٣/٢٠."},{"type":"tfr","q":"مقلوب الكسر ٣/٧ هو ٧/٣.","answer":true,"reasons":["لأن حاصل ضربهما يساوي ١","لأنه −٣/٧","لأنه ٣/١"],"reason":0},{"type":"mcq","q":"ما ناتج: ٤ ÷ ١/٢ ؟","options":["٢","٨","١/٨","٤"],"answer":1,"why":"٤ × ٢ = ٨."},{"type":"essay","q":"احسب: ٢ ١/٣ ÷ ١ ١/٦.","model":"٧/٣ ÷ ٧/٦ = ٧/٣ × ٦/٧ = ٢."},{"type":"tfr","q":"في ضرب الكسور لا نحتاج لتوحيد المقامات.","answer":true,"reasons":["لأننا نضرب البسط في البسط والمقام في المقام مباشرة","لأن المقامات متساوية دائمًا","لأن الضرب كالجمع"],"reason":0}],"hard":[{"type":"mcq","q":"ما ناتج: ١ ١/٤ − ٣/٨ ؟","options":["٧/٨","٥/٨","١ ١/٨","٣/٤"],"answer":0,"why":"٥/٤ − ٣/٨ = ١٠/٨ − ٣/٨ = ٧/٨."},{"type":"essay","q":"مستطيل طوله ٢ ١/٢ م وعرضه ١ ١/٥ م. أوجد مساحته.","model":"المساحة = ٥/٢ × ٦/٥ = ٣ م²."},{"type":"tfr","q":"ناتج ١/٢ + ١/٣ × ٣ يساوي ٢ ١/٢.","answer":false,"reasons":["الضرب أولًا: ١/٣ × ٣ = ١، ثم ١/٢ + ١ = ١ ١/٢","لأن الجمع أولًا","لأن الناتج ١"],"reason":0},{"type":"mcq","q":"ما ناتج: (٣/٤)² ؟","options":["٦/٨","٩/١٦","٩/٤","٣/١٦"],"answer":1,"why":"٣/٤ × ٣/٤ = ٩/١٦."},{"type":"essay","q":"إذا كان طول شريط ٦ أمتار وقُسّم إلى قطع طول كل منها ٣/٤ متر، فكم قطعة نحصل عليها؟","model":"٦ ÷ ٣/٤ = ٦ × ٤/٣ = ٨ قطع."},{"type":"tfr","q":"حاصل ضرب أي كسر غير صفري في مقلوبه يساوي ١.","answer":true,"reasons":["مثل ٣/٥ × ٥/٣ = ١٥/١٥ = ١","لأنه يساوي صفرًا","لأنه يساوي ٢"],"reason":0},{"type":"mcq","q":"ما قيمة س إذا كان ٢/٣ × س = ٤ ؟","options":["٦","٨/٣","٢","١٢"],"answer":0,"why":"س = ٤ ÷ ٢/٣ = ٤ × ٣/٢ = ٦."},{"type":"essay","q":"احسب: (١/٢ + ١/٤) ÷ ٣/٨.","model":"٣/٤ × ٨/٣ = ٢."},{"type":"tfr","q":"العدد الكسري ٢ ٣/٥ يساوي ١٣/٥.","answer":true,"reasons":["لأن ٢ × ٥ + ٣ = ١٣ والمقام ٥","لأنه ١١/٥","لأنه ٦/٥"],"reason":0},{"type":"essay","q":"أكل أحمد ١/٣ كعكة وأكل أخوه ٢/٥ منها. ما الكسر المتبقي من الكعكة؟","model":"المأكول = ٥/١٥ + ٦/١٥ = ١١/١٥ ← المتبقي = ١ − ١١/١٥ = ٤/١٥."}]}},
  {"id":"g9-math-1-u2-3","grade":"g9","subject":"math","term":1,"unit":2,"no":3,"title":"النسب المئوية","summary":"شرح متحرك للنسبة المئوية والزيادة والنقصان المئوي ونسبة التغيّر، ثم أنشطة بثلاثة مستويات.","page":"lesson-percentages.html","video":"","pdf":"","notes":["النسبة المئوية هي كسر مقامه ١٠٠.","نسبة مئوية من كمية = (النسبة ÷ ١٠٠) × الكمية.","النسبة المئوية للتغيّر = (مقدار التغيّر ÷ القيمة الأصلية) × ١٠٠٪."],"exercises":["احسب ٢٠٪ من ١٥٠ ريالًا.","ارتفع سعر سلعة من ٥٠ إلى ٦٠ ريالًا، ما نسبة الزيادة؟"],"levels":{"easy":[{"type":"mcq","q":"ما قيمة ٣٠٪ من ٢٠٠ ؟","options":["٣٠","٦٠","٩٠","١٢٠"],"answer":1,"why":"(٣٠÷١٠٠) × ٢٠٠ = ٦٠."},{"type":"mcq","q":"حصل طالب على ١٦ من ٢٠. ما نسبته المئوية؟","options":["٧٥٪","٨٠٪","٨٥٪","٩٠٪"],"answer":1,"why":"(١٦÷٢٠) × ١٠٠٪ = ٨٠٪."},{"type":"mcq","q":"سلعة سعرها ٨٠ ريالًا عليها خصم ٢٥٪. كم سعرها بعد الخصم؟","options":["٦٠ ريالًا","٥٥ ريالًا","٦٥ ريالًا","٢٠ ريالًا"],"answer":0,"why":"٨٠ − ٢٠ = ٦٠ ريالًا."},{"type":"mcq","q":"ما الكسر العشري المكافئ لـ ١٥٪ ؟","options":["١٫٥","٠٫١٥","٠٫٠١٥","١٥"],"answer":1,"why":"١٥ ÷ ١٠٠ = ٠٫١٥."}],"medium":[{"type":"mcq","q":"ارتفع سعر قميص من ٢٠ إلى ٢٥ ريالًا. ما النسبة المئوية للزيادة؟","options":["٢٠٪","٢٥٪","٥٪","١٥٪"],"answer":1,"why":"(٥ ÷ ٢٠) × ١٠٠٪ = ٢٥٪."},{"type":"tfr","q":"لزيادة كمية بنسبة ١٠٪ نضربها في ١٫١.","answer":true,"reasons":["لأن ١٠٠٪ + ١٠٪ = ١١٠٪ = ١٫١","لأننا نضرب في ٠٫١","لأننا نضرب في ٠٫٩"],"reason":0},{"type":"essay","q":"سعر هاتف ١٢٠ ريالًا، زاد سعره بنسبة ١٥٪. كم أصبح سعره الجديد؟","model":"الزيادة = ١٥٪ × ١٢٠ = ١٨ ريالًا ← السعر الجديد = ١٢٠ + ١٨ = ١٣٨ ريالًا."},{"type":"tfr","q":"عند حساب النسبة المئوية للتغيّر نقسم على القيمة الجديدة.","answer":false,"reasons":["لأننا نقسم دائمًا على القيمة الأصلية","لأننا نقسم على ١٠٠ فقط","لأننا نضرب القيمتين"],"reason":0},{"type":"mcq","q":"ما النسبة المئوية المكافئة للكسر ٣/٨ ؟","options":["٣٧٫٥٪","٣٨٪","٣٠٪","٢٥٪"],"answer":0,"why":"٠٫٣٧٥ × ١٠٠٪ = ٣٧٫٥٪."},{"type":"essay","q":"انخفض عدد طلاب نادٍ من ٥٠ إلى ٤٠ طالبًا. احسب النسبة المئوية للنقصان.","model":"(١٠ ÷ ٥٠) × ١٠٠٪ = ٢٠٪."},{"type":"tfr","q":"خصم ٢٠٪ يعني أننا ندفع ٨٠٪ من السعر الأصلي.","answer":true,"reasons":["لأن ١٠٠٪ − ٢٠٪ = ٨٠٪","لأننا ندفع ٢٠٪ فقط","لأن السعر يزيد"],"reason":0}],"hard":[{"type":"mcq","q":"إذا كان ٢٠٪ من عدد يساوي ١٤، فما هو العدد؟","options":["٧٠","٢٨","٢٨٠","٥٦"],"answer":0,"why":"١٠٠٪ = ١٤ × ٥ = ٧٠."},{"type":"essay","q":"سلعة سعرها بعد خصم ٢٠٪ هو ٤٠ ريالًا. ما سعرها الأصلي؟","model":"٨٠٪ = ٤٠ ← ١٪ = ٠٫٥ ← ١٠٠٪ = ٥٠ ريالًا."},{"type":"tfr","q":"زيادة ١٠٪ ثم خصم ١٠٪ تعيد السعر كما كان تمامًا.","answer":false,"reasons":["فمثلاً ١٠٠ تصبح ١١٠ ثم خصم ١٠٪ (١١) تصبح ٩٩ وليس ١٠٠","لأن +١٠ و −١٠ يلغيان بعضهما","لأن السعر يصبح ١٠١"],"reason":0},{"type":"mcq","q":"ما قيمة ١٢٥٪ من ٨٠ ؟","options":["١٠٠","٩٠","١٢٠","٦٤"],"answer":0,"why":"١٫٢٥ × ٨٠ = ١٠٠."},{"type":"essay","q":"أودع سالم ٥٠٠ ريال بفائدة بسيطة ٤٪ سنويًا لمدة سنتين. كم مقدار الفائدة؟","model":"الفائدة = ٥٠٠ × ٤٪ × ٢ = ٤٠ ريالًا."},{"type":"tfr","q":"النسبة ٠٫٥٪ تساوي ٠٫٠٠٥.","answer":true,"reasons":["لأن ٠٫٥ ÷ ١٠٠ = ٠٫٠٠٥","لأنها تساوي ٠٫٥","لأنها تساوي ٠٫٠٥"],"reason":0},{"type":"mcq","q":"في صف ٣٠ طالبًا، غاب منهم ٣ طلاب. ما نسبة الحضور؟","options":["٩٠٪","١٠٪","٨٥٪","٩٥٪"],"answer":0,"why":"الحضور ٢٧ ← (٢٧÷٣٠)×١٠٠٪ = ٩٠٪."},{"type":"essay","q":"اشترى تاجر بضاعة بـ ٢٠٠ ريال وباعها بـ ٢٥٠ ريالًا. احسب نسبة الربح.","model":"الربح ٥٠ ← (٥٠÷٢٠٠)×١٠٠٪ = ٢٥٪."},{"type":"tfr","q":"إذا تضاعف سعر سلعة فإن نسبة الزيادة هي ١٠٠٪.","answer":true,"reasons":["لأن الزيادة تساوي السعر الأصلي، فتكون (الأصلي÷الأصلي)×١٠٠٪ = ١٠٠٪","لأن الزيادة ٢٠٠٪","لأن الزيادة ٥٠٪"],"reason":0},{"type":"essay","q":"احسب ٧٫٥٪ من ٤٠٠ ريال.","model":"(٧٫٥ ÷ ١٠٠) × ٤٠٠ = ٣٠ ريالًا."}]}},
  {"id":"g9-math-1-u2-4","grade":"g9","subject":"math","term":1,"unit":2,"no":4,"title":"الصيغة العلمية","summary":"شرح متحرك لكتابة الأعداد بالصيغة العلمية أ × ١٠ⁿ والتحويل والعمليات عليها، ثم أنشطة بثلاثة مستويات.","page":"lesson-standard-form.html","video":"","pdf":"","notes":["الصيغة العلمية: أ × ١٠ⁿ حيث ١ ≤ أ < ١٠ و ن عدد صحيح.","الأعداد الكبيرة أُسها موجب، والأعداد الصغيرة (أقل من ١) أُسها سالب.","في الضرب نجمع أُسس ١٠، وفي القسمة نطرحها."],"exercises":["اكتب ٤٧٠٠٠٠ و ٠٫٠٠٠٦٣ بالصيغة العلمية.","احسب: (٢ × ١٠³) × (٣ × ١٠⁴)."],"levels":{"easy":[{"type":"mcq","q":"كيف يُكتب ٥٢٠٠٠ بالصيغة العلمية؟","options":["٥٢ × ١٠³","٥٫٢ × ١٠⁴","٥٫٢ × ١٠⁻⁴","٠٫٥٢ × ١٠⁵"],"answer":1,"why":"نحرّك الفاصلة ٤ منازل لليسار."},{"type":"mcq","q":"كيف يُكتب ٠٫٠٠٨ بالصيغة العلمية؟","options":["٨ × ١٠⁻³","٨ × ١٠³","٠٫٨ × ١٠⁻²","٨ × ١٠⁻²"],"answer":0,"why":"نحرّك الفاصلة ٣ منازل لليمين."},{"type":"mcq","q":"ما الصيغة العادية للعدد ٢٫٥ × ١٠³ ؟","options":["٢٥٠","٢٥٠٠","٠٫٠٠٢٥","٢٥٠٠٠"],"answer":1,"why":"نحرّك الفاصلة ٣ منازل لليمين."},{"type":"mcq","q":"ما ناتج: (٣ × ١٠²) × (٢ × ١٠⁵) ؟","options":["٦ × ١٠⁷","٥ × ١٠⁷","٦ × ١٠¹⁰","٦ × ١٠³"],"answer":0,"why":"٣×٢ = ٦ و ٢+٥ = ٧."}],"medium":[{"type":"mcq","q":"ما الصيغة العادية للعدد ٤٫١ × ١٠⁻² ؟","options":["٤١٠","٠٫٠٤١","٠٫٤١","٠٫٠٠٤١"],"answer":1,"why":"نحرّك الفاصلة منزلتين لليسار."},{"type":"tfr","q":"العدد ٣٥ × ١٠⁴ مكتوب بالصيغة العلمية الصحيحة.","answer":false,"reasons":["لأن ٣٥ أكبر من ١٠، والصواب ٣٫٥ × ١٠⁵","لأن الأُس موجب","لأنه لا يحتوي على فاصلة"],"reason":0},{"type":"essay","q":"اكتب العدد ٠٫٠٠٠٠٤٥ بالصيغة العلمية.","model":"٤٫٥ × ١٠⁻⁵."},{"type":"tfr","q":"العدد ٧ × ١٠⁻⁴ أصغر من ١.","answer":true,"reasons":["لأن الأُس السالب يعني كسرًا عشريًّا صغيرًا (٠٫٠٠٠٧)","لأنه عدد سالب","لأنه أكبر من ٧"],"reason":0},{"type":"mcq","q":"ما ناتج: (٨ × ١٠⁶) ÷ (٢ × ١٠²) ؟","options":["٤ × ١٠⁴","٤ × ١٠³","٦ × ١٠⁴","٤ × ١٠⁸"],"answer":0,"why":"٨÷٢ = ٤ و ٦−٢ = ٤."},{"type":"essay","q":"رتّب تصاعديًا: ٣ × ١٠⁴ ، ٥ × ١٠³ ، ٢ × ١٠⁻².","model":"٢ × ١٠⁻² ، ٥ × ١٠³ ، ٣ × ١٠⁴."},{"type":"tfr","q":"في الصيغة العلمية أ × ١٠ⁿ يمكن أن تكون أ = ١٠.","answer":false,"reasons":["لأن الشرط ١ ≤ أ < ١٠ (أصغر تمامًا من ١٠)","لأن أ يجب أن تكون صفرًا","لأن أ عدد سالب"],"reason":0}],"hard":[{"type":"mcq","q":"ما ناتج: (٤ × ١٠³) × (٥ × ١٠²) بالصيغة العلمية؟","options":["٢٠ × ١٠⁵","٢ × ١٠⁶","٢ × ١٠⁵","٩ × ١٠⁵"],"answer":1,"why":"٢٠ × ١٠⁵ = ٢ × ١٠⁶."},{"type":"essay","q":"اكتب ناتج (٣ × ١٠⁴) + (٥ × ١٠³) بالصيغة العلمية.","model":"٣٠٠٠٠ + ٥٠٠٠ = ٣٥٠٠٠ = ٣٫٥ × ١٠⁴."},{"type":"tfr","q":"ناتج (٦ × ١٠⁻²) ÷ (٢ × ١٠⁻⁵) هو ٣ × ١٠³.","answer":true,"reasons":["لأن ٦÷٢ = ٣ و −٢ − (−٥) = −٢ + ٥ = +٣","لأن الأُس −٧","لأن الأُس −٣"],"reason":0},{"type":"mcq","q":"ما قيمة (٢ × ١٠³)² بالصيغة العلمية؟","options":["٤ × ١٠⁶","٢ × ١٠⁶","٤ × ١٠⁵","٤ × ١٠⁹"],"answer":0,"why":"٢² × (١٠³)² = ٤ × ١٠⁶."},{"type":"essay","q":"تبلغ سرعة الضوء ٣ × ١٠⁸ م/ث. كم مترًا يقطع الضوء في ٢٠ ثانية بالصيغة العلمية؟","model":"٢٠ × ٣ × ١٠⁸ = ٦٠ × ١٠⁸ = ٦ × ١٠⁹ متر."},{"type":"tfr","q":"العدد ٩٫٩ × ١٠³ أصغر من ١٫١ × ١٠⁴.","answer":true,"reasons":["لأن ٩٩٠٠ < ١١٠٠٠ (الأُس الأكبر هو الأكبر دائمًا في الأعداد الموجبة)","لأن ٩٫٩ أكبر من ١٫١","لأنهما متساويان"],"reason":0},{"type":"mcq","q":"كيف يُكتب العدد ٠٫٠٠٠١ بالصيغة العلمية؟","options":["١ × ١٠⁻⁴","١ × ١٠⁴","١٠ × ١٠⁻⁵","٠٫١ × ١٠⁻³"],"answer":0,"why":"١ × ١٠⁻⁴."},{"type":"essay","q":"احسب: (١٫٢ × ١٠⁵) ÷ (٤ × ١٠²).","model":"٠٫٣ × ١٠³ = ٣ × ١٠²."},{"type":"tfr","q":"الأُس السالب في الصيغة العلمية يعني أن العدد سالب.","answer":false,"reasons":["بل يعني أنه عدد موجب صغير محصور بين ٠ و ١","لأنه دائمًا أقل من الصفر","لأنه عدد صحيح"],"reason":0},{"type":"essay","q":"صحّح كتابة ٠٫٠٤ × ١٠⁶ لتصبح بالصيغة العلمية.","model":"٠٫٠٤ = ٤ × ١٠⁻² ← ٤ × ١٠⁻² × ١٠⁶ = ٤ × ١٠⁴."}]}},
  {"id":"g9-math-1-u2-5","grade":"g9","subject":"math","term":1,"unit":2,"no":5,"title":"الآلة الحاسبة والصيغة العلمية","summary":"شرح متحرك لاستخدام زر ×10ˣ / EXP في الآلة الحاسبة وقراءة الشاشة والتقريب، ثم أنشطة بثلاثة مستويات.","page":"lesson-calculator-standard-form.html","video":"","pdf":"","notes":["نستخدم زر ×10ˣ أو EXP لإدخال الصيغة العلمية مباشرة دون كتابة × ١٠.","حرف E على شاشة الآلة يعني × ١٠ أُس (لا يُكتب E في الاختبار).","استخدم الأقواس في القسمة وقرّب الناتج حسب المطلوب."],"exercises":["اكتب 4.2E-5 بالصيغة العلمية الصحيحة.","قرّب 3.468 × 10⁷ إلى ٣ أرقام معنوية."],"levels":{"easy":[{"type":"mcq","q":"إذا ظهر على الآلة 7.5E-4 فكيف يُكتب بالصيغة العلمية؟","options":["٧٫٥ × ١٠⁴","٧٫٥ × ١٠⁻⁴","٧٫٥ − ٤","٧٥ × ١٠⁻⁵"],"answer":1,"why":"E تعني × ١٠ أُس."},{"type":"mcq","q":"ما الزر الصحيح لإدخال الصيغة العلمية؟","options":["×10ˣ أو EXP","√","%","ANS"],"answer":0,"why":"هذا الزر يختصر × ١٠ أُس."},{"type":"mcq","q":"قرّب 6.278 × 10⁵ إلى ٣ أرقام معنوية:","options":["٦٫٢٧ × ١٠⁵","٦٫٢٨ × ١٠⁵","٦٫٣ × ١٠⁵","٦ × ١٠⁵"],"answer":1,"why":"الرقم الرابع ٨ كريم."},{"type":"mcq","q":"ما ناتج (٩ × ١٠⁹) ÷ (٣ × ١٠⁴) ؟","options":["٣ × ١٠⁵","٣ × ١٠¹³","٦ × ١٠⁵","٣ × ١٠⁴"],"answer":0,"why":"٩÷٣ = ٣ و ٩−٤ = ٥."}],"medium":[{"type":"mcq","q":"لإدخال ٥ × ١٠⁻⁶ في الآلة نضغط:","options":["٥ ثم ×10ˣ ثم (−) ثم ٦","٥ ثم × ثم ١٠ ثم ×10ˣ ثم −٦","٥ ثم − ثم ٦","١٠ ثم ×10ˣ ثم ٥"],"answer":0,"why":"لا نكتب × ١٠ مع زر ×10ˣ."},{"type":"tfr","q":"يصحّ كتابة 3.2E6 كإجابة نهائية في ورقة الاختبار.","answer":false,"reasons":["لأن E رمز شاشة الآلة فقط ويجب كتابتها ٣٫٢ × ١٠⁶","لأن E تعني خطأ","لأنها صيغة علمية معتمدة"],"reason":0},{"type":"essay","q":"كيف تكتب ناتج الآلة 1.05E9 بالصيغة العلمية ثم العادية؟","model":"العلمية: ١٫٠٥ × ١٠⁹. العادية: ١٠٥٠٠٠٠٠٠٠."},{"type":"tfr","q":"استخدام الأقواس حول المقام يمنع أخطاء القسمة في الآلة الحاسبة.","answer":true,"reasons":["لأنها تضمن قسمة البسط على المقام كاملًا","لأن الأقواس تلغي الأُس","لأنها لا تؤثر"],"reason":0},{"type":"mcq","q":"قرّب 4.829 × 10⁻³ إلى رقمين معنويين:","options":["٤٫٨ × ١٠⁻³","٤٫٩ × ١٠⁻³","٤٫٨٣ × ١٠⁻³","٥ × ١٠⁻³"],"answer":0,"why":"الرقم الثالث ٢ بخيل ← ٤٫٨ × ١٠⁻³."},{"type":"essay","q":"ما الخطأ في كتابة (3 × 10 ×10ˣ 4) على الآلة؟","model":"زر ×10ˣ يعني «× ١٠ أُس»، فكتابة × ١٠ قبله تضاعف القوة ١٠ مرات فتصبح ٣ × ١٠⁵ بدل ٣ × ١٠⁴."},{"type":"tfr","q":"عند تقريب 2.96 × 10⁴ إلى رقمين معنويين يصبح 3.0 × 10⁴.","answer":true,"reasons":["لأن ٦ تزيد ٩ إلى ١٠ فتصبح ٣٫٠ × ١٠⁴","لأنه يصبح ٢٫٩ × ١٠⁴","لأنه يصبح ٣ × ١٠⁵"],"reason":0}],"hard":[{"type":"mcq","q":"إذا أردت حساب (٦ × ١٠⁸) ÷ (٣ × ١٠⁴) بالضرب العادي دون زر ×10ˣ، يجب كتابة:","options":["6×10^8 ÷ (3×10^4)","6×10^8 ÷ 3×10^4","6 ÷ 3 × 10^12","6×10^8 × 3×10^4"],"answer":0,"why":"الأقواس حول المقام ضرورية."},{"type":"essay","q":"احسب (4.5 × 10⁷) ÷ (1.5 × 10³) واكتب الناتج بالصيغة العلمية.","model":"٤٫٥ ÷ ١٫٥ = ٣ و ٧ − ٣ = ٤ ← ٣ × ١٠⁴."},{"type":"tfr","q":"تظهر الآلة العدد 0.0000002 أحيانًا كـ 2E-7.","answer":true,"reasons":["لأن الفاصلة تحرّكت ٧ منازل لليمين","لأنه 2E7","لأنه 2E-6"],"reason":0},{"type":"mcq","q":"ما ناتج √(4 × 10⁸) ؟","options":["٢ × ١٠⁴","٢ × ١٠⁸","٤ × ١٠⁴","٢ × ١٠⁶"],"answer":0,"why":"√٤ = ٢ ونقسم الأُس ٨÷٢ = ٤ ← ٢ × ١٠⁴."},{"type":"essay","q":"قرّب 9.98 × 10⁵ إلى رقمين معنويين بالصيغة العلمية.","model":"تصبح ١٠٫٠ × ١٠⁵ = ١٫٠ × ١٠⁶."},{"type":"tfr","q":"يمكن حساب جمع عددين بالصيغة العلمية مباشرة باستخدام زر ×10ˣ في الآلة.","answer":true,"reasons":["لأن الآلة توحّد القوى تلقائيًا وتجمع بدقة","لأن الجمع لا يعمل مع ×10ˣ","لأنها للضرب فقط"],"reason":0},{"type":"mcq","q":"ما قيمة (3 × 10⁻²)³ ؟","options":["٢٫٧ × ١٠⁻⁵","٩ × ١٠⁻⁶","٢٧ × ١٠⁻⁶","٣ × ١٠⁻⁶"],"answer":0,"why":"٢٧ × ١٠⁻⁶ = ٢٫٧ × ١٠⁻⁵."},{"type":"essay","q":"اشرح كيف تدخل (٢٫٤ × ١٠⁻³) × (٥ × ١٠⁷) على الآلة وتقرأ الناتج.","model":"نضغط 2.4 [×10ˣ] −3 × 5 [×10ˣ] 7 = فيظهر 120000 وهو ١٫٢ × ١٠⁵."},{"type":"tfr","q":"العدد 5E0 على شاشة الآلة يساوي 5.","answer":true,"reasons":["لأن ٥ × ١٠⁰ = ٥ × ١ = ٥","لأنه يساوي صفرًا","لأنه يساوي ٥٠"],"reason":0},{"type":"essay","q":"احسب (٨٫٤ × ١٠⁶) ÷ (٢٫١ × ١٠⁻²) بالصيغة العلمية.","model":"٨٫٤÷٢٫١ = ٤ و ٦ − (−٢) = ٨ ← ٤ × ١٠⁸."}]}},
  {"id":"g9-math-1-u2-6","grade":"g9","subject":"math","term":1,"unit":2,"no":6,"title":"الأعداد النسبية والأعداد غير النسبية","summary":"شرح متحرك للتمييز بين النسبي وغير النسبي وتحويل الكسر الدوري إلى كسر اعتيادي، ثم أنشطة بثلاثة مستويات.","page":"lesson-rational-irrational-numbers.html","video":"","pdf":"","notes":["النسبي يُكتب كسرًا أ/ب، ويشمل الكسور العشرية المنتهية والدورية وجذور المربعات الكاملة.","غير النسبي لا يُكتب كسرًا، مثل الجذور الصماء (√٢، √٥) و π.","لتحويل كسر عشري دوري مثل ٠٫٧٧٧... نضرب في ١٠ ونطرح."],"exercises":["حوّل ٠٫٧٧٧... إلى كسر اعتيادي.","صنّف: √٣٦ ، √١٠ ، ٢٢/٧ ، π."],"levels":{"easy":[{"type":"mcq","q":"أيُّ الأعداد الآتية نسبي؟","options":["√٣","√٣٦","π","√٥"],"answer":1,"why":"√٣٦ = ٦ وهو نسبي."},{"type":"mcq","q":"ما الكسر الاعتيادي المكافئ لـ ٠٫٥٥٥... ؟","options":["٥/١٠","٥/٩","١/٥","٥/٩٩"],"answer":1,"why":"٩س = ٥ ← س = ٥/٩."},{"type":"mcq","q":"العدد ٢٢/٧ يُعدّ عددًا:","options":["نسبيًّا","غير نسبي","صحيحًا","طبيعيًّا"],"answer":0,"why":"مكتوب على صورة كسر أ/ب."},{"type":"mcq","q":"أيُّ الأعداد الآتية غير نسبي؟","options":["٠٫٣٣٣...","√١٠","−٧","٠٫٧٥"],"answer":1,"why":"١٠ ليس مربعًا كاملًا."}],"medium":[{"type":"mcq","q":"ما الكسر الاعتيادي المكافئ لـ ٠٫٢٢٢... ؟","options":["٢/٩","٢/١٠","١/٢","٢/٩٩"],"answer":0,"why":"٢/٩."},{"type":"tfr","q":"العدد ٠٫١٢١٢١٢... عدد غير نسبي.","answer":false,"reasons":["لأنه كسر عشري دوري متكرر يساوي ١٢/٩٩ = ٤/٣٣ فهو نسبي","لأنه غير منتهٍ","لأنه أكبر من ١"],"reason":0},{"type":"essay","q":"حوّل الكسر الدوري ٠٫٤٤٤... إلى كسر اعتيادي بالخطوات.","model":"س = ٠٫٤٤٤... ← ١٠س = ٤٫٤٤٤... ← بالطرح ٩س = ٤ ← س = ٤/٩."},{"type":"tfr","q":"العدد √(٩/١٦) عدد نسبي.","answer":true,"reasons":["لأن √(٩/١٦) = ٣/٤ وهو كسر اعتيادي","لأن كل جذر غير نسبي","لأنه يساوي ٩/١٦"],"reason":0},{"type":"mcq","q":"العدد ٣ + √٢ يُصنّف بأنه:","options":["نسبي","غير نسبي","صحيح","كلي"],"answer":1,"why":"مجموع نسبي مع غير نسبي = غير نسبي."},{"type":"essay","q":"لماذا يُعدّ π غير نسبي بينما ٣٫١٤ نسبي؟","model":"π كسر عشري غير منتهٍ وغير دوري، أما ٣٫١٤ فهو تقريب منتهٍ يساوي ٣١٤/١٠٠."},{"type":"tfr","q":"العدد ∛٢٧ عدد نسبي.","answer":true,"reasons":["لأن ∛٢٧ = ٣ وهو عدد صحيح ونسبي","لأنه جذر أصم","لأنه يساوي ٩"],"reason":0}],"hard":[{"type":"mcq","q":"ما ناتج √٢ × √٨ ؟","options":["عدد غير نسبي","٤ (عدد نسبي)","√١٠","١٦"],"answer":1,"why":"√١٦ = ٤ وهو عدد نسبي!"},{"type":"essay","q":"حوّل ٠٫٢٧٢٧٢٧... إلى كسر اعتيادي في أبسط صورة.","model":"١٠٠س = ٢٧٫٢٧... ← ٩٩س = ٢٧ ← س = ٢٧/٩٩ = ٣/١١."},{"type":"tfr","q":"حاصل ضرب عددين غير نسبيين يكون دائمًا غير نسبي.","answer":false,"reasons":["مثلاً √٢ × √٢ = ٢ وهو عدد نسبي","لأن غير النسبي × غير النسبي = غير نسبي دائمًا","لأن الناتج صفر"],"reason":0},{"type":"mcq","q":"أيُّ الأعداد الآتية نسبي؟","options":["√٣ + √٣","√٥ × √٥","٢π","١ + √٧"],"answer":1,"why":"√٥ × √٥ = ٥ وهو نسبي."},{"type":"essay","q":"اذكر عددين غير نسبيين حاصل ضربهما عدد نسبي.","model":"مثال: √٣ و √٣ (ضربهما ٣) أو √٢ و √٨ (ضربهما ٤)."},{"type":"tfr","q":"العدد ٠٫١٠١٠٠١٠٠٠١... عدد غير نسبي.","answer":true,"reasons":["لأنه غير منتهٍ ولا يتكرر بنمط دوري ثابت","لأنه كسر دوري","لأنه يساوي ١/١٠"],"reason":0},{"type":"mcq","q":"الكسر الدوري ٠٫٩٩٩... يساوي:","options":["١","٩/١٠","٠٫٩","غير نسبي"],"answer":0,"why":"٩س = ٩ ← س = ١."},{"type":"essay","q":"هل √(١٦ + ٩) نسبي أم غير نسبي؟ علّل.","model":"√٢٥ = ٥، إذن هو عدد نسبي."},{"type":"tfr","q":"كل جذر تربيعي لعدد أولي هو عدد غير نسبي.","answer":true,"reasons":["لأن العدد الأولي ليس مربعًا كاملًا أبدًا","لأن الأعداد الأولية مربعة","لأن √٢ = ١٫٤"],"reason":0},{"type":"essay","q":"حوّل ٠٫١٦٦٦... إلى كسر اعتيادي.","model":"١٠س = ١٫٦٦٦... و ١٠٠س = ١٦٫٦٦٦... ← ٩٠س = ١٥ ← س = ١٥/٩٠ = ١/٦."}]}},
  {"id":"g9-math-1-u3-1","grade":"g9","subject":"math","term":1,"unit":3,"no":1,"title":"استخدام الحروف (المتغيرات) لتمثيل القيم المجهولة","summary":"شرح متحرك للمتغيرات وقواعد الكتابة الجبرية وترجمة الجمل اللفظية، ثم أنشطة بثلاثة مستويات.","page":"lesson-variables-unknowns.html","video":"","pdf":"","notes":["المتغير حرف (مثل س، ص) يمثّل قيمة مجهولة.","في الجبر نحذف علامة × ونضع العدد قبل الحرف (٤س)، ونكتب القسمة كسرًا (س/٣).","العبارة الجبرية بلا علامة (=)، أما المعادلة فتحتوي على (=)."],"exercises":["اكتب عبارة جبرية لـ: «أقل من ضعف س بمقدار ٥».","مستطيل طوله ل وعرضه ض، اكتب عبارة لمحيطه."],"levels":{"easy":[{"type":"mcq","q":"كيف نكتب «أقل من العدد س بمقدار ٧»؟","options":["٧ − س","س − ٧","س + ٧","٧س"],"answer":1,"why":"نطرح ٧ من س ← س − ٧."},{"type":"mcq","q":"كيف نكتب «ضعف ص مضافًا إليه ٣»؟","options":["٢ص + ٣","ص + ٦","٢(ص+٣)","٣ص + ٢"],"answer":0,"why":"ضعف ص = ٢ص ثم + ٣."},{"type":"mcq","q":"ما الصيغة الجبرية لـ (أ × أ × ٤)؟","options":["٤أ٢","٤أ²","٨أ","٤ + أ²"],"answer":1,"why":"العدد أولًا ثم أ² ← ٤أ²."},{"type":"mcq","q":"اشترى سالم (ن) دفاتر بسعر ريالين للدفتر وقلمًا بريال. التكلفة:","options":["٢ن + ١","ن + ٣","٢(ن+١)","٣ن"],"answer":0,"why":"٢ن + ١."}],"medium":[{"type":"mcq","q":"ما العبارة الجبرية لـ «نصف العدد س مطروحًا منه ٤»؟","options":["س/٢ − ٤","(س − ٤)/٢","٢س − ٤","٤ − س/٢"],"answer":0,"why":"نصف س هو س/٢ ثم نطرح ٤."},{"type":"tfr","q":"العبارة الجبرية ٣س + ٥ تُعدّ معادلة.","answer":false,"reasons":["لأنها لا تحتوي على علامة يساوي (=)","لأن فيها متغيرًا","لأن فيها جمعًا"],"reason":0},{"type":"essay","q":"عمر خالد الآن (ع) سنة. اكتب عبارة لعمره قبل ٣ سنوات وبعد ٧ سنوات.","model":"قبل ٣ سنوات: ع − ٣. بعد ٧ سنوات: ع + ٧."},{"type":"tfr","q":"نكتب ١ × س في الجبر ببساطة س.","answer":true,"reasons":["لأن معامل الواحد يُحذف اختصارًا في الكتابة الجبرية","لأنها تساوي ١","لأنها تساوي صفرًا"],"reason":0},{"type":"mcq","q":"مربع طول ضلعه (س). ما محيطه؟","options":["س²","٤س","٢س","س + ٤"],"answer":1,"why":"المحيط = ٤ × طول الضلع = ٤س."},{"type":"essay","q":"اكتب عبارة جبرية لـ: «مجموع مربع العدد س وثلاثة أمثال العدد ص».","model":"س² + ٣ص."},{"type":"tfr","q":"العبارة «أكثر من س بـ ٥» تساوي س + ٥.","answer":true,"reasons":["لأن «أكثر من» تدل على الجمع","لأنها تعني ٥س","لأنها س − ٥"],"reason":0}],"hard":[{"type":"mcq","q":"عدد صحيح هو (ن)، ما العدد الصحيح الذي يليه مباشرة؟","options":["ن + ١","٢ن","ن − ١","ن + ٢"],"answer":0,"why":"العدد التالي يزيد بـ ١."},{"type":"essay","q":"مستطيل طوله ضعف عرضه (ض). اكتب عبارة لمحيطه ومساحته بدلالة ض.","model":"الطول = ٢ض. المحيط = ٢(٢ض + ض) = ٦ض. المساحة = ٢ض × ض = ٢ض²."},{"type":"tfr","q":"العبارة ٥ − س تساوي س − ٥ دائمًا.","answer":false,"reasons":["لأن الطرح ليس إبداليًّا، فمثلاً ٥−٢ = ٣ بينما ٢−٥ = −٣","لأنهما متساويتان","لأن س = ٥ دائمًا"],"reason":0},{"type":"mcq","q":"ثلاثة أعداد زوجية متتالية أصغرها (س). ما أكبرها؟","options":["س + ٢","س + ٤","س + ٣","٣س"],"answer":1,"why":"الأعداد: س ، س+٢ ، س+٤."},{"type":"essay","q":"ترجم العبارة الجبرية ٢(س + ٣) إلى جملة لفظية.","model":"ضعف مجموع العدد س و ٣."},{"type":"tfr","q":"الكتابة الجبرية لـ (س ÷ ٥) هي س/٥.","answer":true,"reasons":["لأن القسمة في الجبر تُكتب على صورة كسر","لأنها ٥س","لأنها ٥/س"],"reason":0},{"type":"mcq","q":"إذا كان سعر القلم س ريالًا وسعر الكتاب ص ريالًا، فما سعر ٣ أقلام وكتابين؟","options":["٣س + ٢ص","٥س ص","٢س + ٣ص","٦س ص"],"answer":0,"why":"٣س + ٢ص."},{"type":"essay","q":"مثلث متطابق الضلعين طول قاعدته (ق) وطول كل من ضلعيه المتساويين (أ). اكتب محيطه.","model":"المحيط = ٢أ + ق."},{"type":"tfr","q":"في الحد الجبري −٧س²، المعامل العددي هو ٧.","answer":false,"reasons":["لأن المعامل يؤخذ بإشارته وهو −٧","لأنه ٢","لأنه س"],"reason":0},{"type":"essay","q":"مع علي (م) ريالًا، أنفق ٥ ريالات ثم قسّم الباقي بالتساوي على أخويه. كم نصيب كل أخ؟","model":"(م − ٥) ÷ ٢."}]}},
  {"id":"g9-math-1-u3-2","grade":"g9","subject":"math","term":1,"unit":3,"no":2,"title":"التعويض","summary":"شرح متحرك للتعويض بالأعداد الموجبة والسالبة والقوى وفي الصيغ، ثم أنشطة بثلاثة مستويات.","page":"lesson-substitution.html","video":"","pdf":"","notes":["التعويض هو استبدال المتغير بقيمته العددية ثم تطبيق ترتيب العمليات.","ضع العدد السالب داخل أقواس دائمًا عند التعويض.","احسب القوى قبل الضرب."],"exercises":["أوجد قيمة ٥س − ٣ص عندما س = ٤ و ص = ٢.","أوجد قيمة ٣س² + ١ عندما س = −٢."],"levels":{"easy":[{"type":"mcq","q":"ما قيمة ٤س − ٥ عندما س = ٣ ؟","options":["٧","١٧","٢","١٢"],"answer":0,"why":"٤(٣) − ٥ = ٧."},{"type":"mcq","q":"ما قيمة س² + ٤ عندما س = −٣ ؟","options":["−٥","١٣","−١٣","٥"],"answer":1,"why":"(−٣)² + ٤ = ٩ + ٤ = ١٣."},{"type":"mcq","q":"ما قيمة ٢أ + ٣ب عندما أ = ٥ و ب = −٢ ؟","options":["٤","١٦","−٤","١٠"],"answer":0,"why":"١٠ − ٦ = ٤."},{"type":"mcq","q":"إذا كان م = (أ + ب) ÷ ٢، فما م عندما أ = ٨ و ب = ١٢ ؟","options":["١٠","١٤","٢٠","٤"],"answer":0,"why":"٢٠ ÷ ٢ = ١٠."}],"medium":[{"type":"mcq","q":"ما قيمة ٣س² عندما س = ٢ ؟","options":["١٢","٣٦","٦","١٨"],"answer":0,"why":"التربيع أولًا: ٢² = ٤ ← ٣×٤ = ١٢."},{"type":"tfr","q":"قيمة ٥ − س عندما س = −٣ تساوي ٢.","answer":false,"reasons":["لأن ٥ − (−٣) = ٥ + ٣ = ٨","لأن ٥ − ٣ = ٢","لأن الناتج −٨"],"reason":0},{"type":"essay","q":"أوجد قيمة س³ − ٢س عندما س = −٢.","model":"(−٢)³ − ٢(−٢) = −٨ + ٤ = −٤."},{"type":"tfr","q":"عند التعويض بـ س = −٤ في س² يكون الناتج موجبًا.","answer":true,"reasons":["لأن (−٤)² = (−٤)×(−٤) = +١٦","لأنه −١٦","لأنه −٨"],"reason":0},{"type":"mcq","q":"في الصيغة ف = ع × ن، إذا كان ع = ٦٠ و ن = ٢٫٥، فإن ف =","options":["١٢٠","١٥٠","١٨٠","١٢٥"],"answer":1,"why":"٦٠ × ٢٫٥ = ١٥٠."},{"type":"essay","q":"أوجد قيمة (٣أ − ب) ÷ ٢ عندما أ = ٦ و ب = ٤.","model":"(١٨ − ٤) ÷ ٢ = ١٤ ÷ ٢ = ٧."},{"type":"tfr","q":"قيمة ٢(س + ٣) عندما س = ٤ تساوي ١١.","answer":false,"reasons":["لأن القوس أولًا: ٤+٣ = ٧ ← ٢×٧ = ١٤","لأن ٢×٤ + ٣ = ١١","لأنها ١٠"],"reason":0}],"hard":[{"type":"mcq","q":"ما قيمة ٢س² − ٣س + ١ عندما س = −١ ؟","options":["٦","٠","−٤","٢"],"answer":0,"why":"٢(١) − ٣(−١) + ١ = ٢ + ٣ + ١ = ٦."},{"type":"essay","q":"مساحة شبه المنحرف م = ١/٢ (أ + ب) ع. أوجد م عندما أ = ٥، ب = ٩، ع = ٤.","model":"م = ١/٢ × (٥ + ٩) × ٤ = ١/٢ × ١٤ × ٤ = ٢٨."},{"type":"tfr","q":"قيمة −س² عندما س = ٣ تساوي ٩.","answer":false,"reasons":["لأن السالب خارج التربيع: −(٣²) = −٩","لأنها (−٣)²","لأنها −٦"],"reason":0},{"type":"mcq","q":"ما قيمة √(أ² + ب²) عندما أ = ٦ و ب = ٨ ؟","options":["١٠","١٤","١٠٠","٤٨"],"answer":0,"why":"√(٣٦ + ٦٤) = √١٠٠ = ١٠."},{"type":"essay","q":"إذا كان ع = م + ت ن، أوجد ع عندما م = ١٠، ت = −٢، ن = ٣.","model":"ع = ١٠ + (−٢)(٣) = ١٠ − ٦ = ٤."},{"type":"tfr","q":"إذا كان س = ٠ فإن قيمة ٥س³ + ٧ تساوي ٧.","answer":true,"reasons":["لأن ٥(٠) + ٧ = ٠ + ٧ = ٧","لأنها صفر","لأنها ١٢"],"reason":0},{"type":"mcq","q":"ما قيمة أ/ب + ب/أ عندما أ = ٢ و ب = ٤ ؟","options":["٢٫٥","٢","٣","١٫٥"],"answer":0,"why":"٢/٤ + ٤/٢ = ٠٫٥ + ٢ = ٢٫٥."},{"type":"essay","q":"أوجد قيمة ٣س(ص − س) عندما س = −٢ و ص = ٣.","model":"٣(−٢)(٣ − (−٢)) = (−٦)(٥) = −٣٠."},{"type":"tfr","q":"عند التعويض بـ س = ١/٢ في ٤س² + ١ يكون الناتج ٢.","answer":true,"reasons":["لأن (١/٢)² = ١/٤ ← ٤×(١/٤) + ١ = ١ + ١ = ٢","لأن الناتج ٣","لأن الناتج ٥"],"reason":0},{"type":"essay","q":"تحويل الحرارة: ف = ١٫٨ م + ٣٢. أوجد ف عندما م = ٢٥°.","model":"ف = ١٫٨(٢٥) + ٣٢ = ٤٥ + ٣٢ = ٧٧°."}]}},
  {"id":"g9-math-1-u3-3","grade":"g9","subject":"math","term":1,"unit":3,"no":3,"title":"تبسيط العبارات الجبرية","summary":"شرح متحرك لتجميع الحدود المتشابهة وضرب وقسمة الحدود الجبرية، ثم أنشطة بثلاثة مستويات.","page":"lesson-simplifying-expressions.html","video":"","pdf":"","notes":["الحدود المتشابهة لها نفس المتغير ونفس الأُس.","في الجمع والطرح نجمع الحدود المتشابهة فقط.","في الضرب والقسمة نضرب/نقسم الأعداد معًا والحروف معًا."],"exercises":["بسّط: ٤س + ٥ص − س + ٢ص.","بسّط: ٣س × ٤ص ، ١٨س² ÷ ٦س."],"levels":{"easy":[{"type":"mcq","q":"بسّط: ٥س + ٣ص − ٢س + ص","options":["٣س + ٤ص","٧س + ٤ص","٣س + ٣ص","٧س ص"],"answer":0,"why":"(٥−٢)س + (٣+١)ص = ٣س + ٤ص."},{"type":"mcq","q":"بسّط: ٤أ × ٣ب","options":["٧أ ب","١٢أ ب","١٢أ²","أ ب"],"answer":1,"why":"٤×٣ = ١٢ و أ×ب = أ ب."},{"type":"mcq","q":"بسّط: ١٨س² ÷ ٦س","options":["٣س","٣س²","١٢س","٣"],"answer":0,"why":"١٨÷٦ = ٣ و س²÷س = س."},{"type":"mcq","q":"هل ٣س و ٤س² حدان متشابهان؟","options":["نعم","لا، لاختلاف الأُس","نعم = ٧س³","نعم = ٧س²"],"answer":1,"why":"الأُس في الأول ١ وفي الثاني ٢."}],"medium":[{"type":"mcq","q":"بسّط: ٢أ × ٥أ","options":["٧أ","١٠أ","١٠أ²","٧أ²"],"answer":2,"why":"٢×٥ = ١٠ و أ×أ = أ²."},{"type":"tfr","q":"الحدان ٣س ص و ٥ص س متشابهان.","answer":true,"reasons":["لأن الضرب إبدالي، فـ س ص = ص س","لأن ترتيبهما مختلف","لأنهما غير متشابهين"],"reason":0},{"type":"essay","q":"بسّط: ٧س² + ٣س − ٢س² − ٥س.","model":"(٧−٢)س² + (٣−٥)س = ٥س² − ٢س."},{"type":"tfr","q":"ناتج س + س هو س².","answer":false,"reasons":["لأن س + س = ٢س، أما س × س = س²","لأنهما متساويان","لأن الناتج س"],"reason":0},{"type":"mcq","q":"بسّط: ١٥أ ب ÷ ٥أ","options":["٣ب","٣أ","١٠ب","٣أ ب"],"answer":0,"why":"تختصر أ مع أ و ١٥÷٥ = ٣ ← ٣ب."},{"type":"essay","q":"أوجد محيط مثلث أطوال أضلاعه: ٢س ، ٣س + ١ ، س + ٤.","model":"المحيط = ٢س + ٣س + ١ + س + ٤ = ٦س + ٥."},{"type":"tfr","q":"ناتج ٤س × ٠ يساوي ٤س.","answer":false,"reasons":["لأن أي مقدار ضرب صفر يساوي صفرًا","لأنه يساوي ٤","لأنه يساوي س"],"reason":0}],"hard":[{"type":"mcq","q":"بسّط: −٣س × (−٤س²)","options":["١٢س³","−١٢س³","١٢س²","−٧س³"],"answer":0,"why":"سالب×سالب = +١٢ و س×س² = س³."},{"type":"essay","q":"بسّط: ٦أ ب + ٤أ − ٢ب أ + ٣أ.","model":"بما أن ب أ = أ ب: (٦−٢)أ ب + (٤+٣)أ = ٤أ ب + ٧أ."},{"type":"tfr","q":"تبسيط ٨س² ÷ ٢س² هو ٤س.","answer":false,"reasons":["لأن س² تختصر مع س² فيبقى العدد ٤ فقط","لأنه ٤س²","لأنه ٦"],"reason":0},{"type":"mcq","q":"بسّط: ٢س × ٣ص × ٤س","options":["٢٤س²ص","٩س²ص","٢٤س ص","٢٤س ص²"],"answer":0,"why":"٢×٣×٤ = ٢٤ و س×س×ص = س²ص."},{"type":"essay","q":"مستطيل مساحته ٢٤س² وعرضه ٤س. ما طوله؟","model":"الطول = المساحة ÷ العرض = ٢٤س² ÷ ٤س = ٦س."},{"type":"tfr","q":"العبارة ٥س − ٥س تساوي س.","answer":false,"reasons":["لأن ٥س − ٥س = ٠","لأنها تساوي ١","لأنها ٥"],"reason":0},{"type":"mcq","q":"بسّط: ٣س/٤ + س/٤","options":["س","٤س/٨","٣س/٨","س/٢"],"answer":0,"why":"٤س/٤ = س."},{"type":"essay","q":"بسّط الكسر الجبري: (١٢س³ص) ÷ (٤س ص).","model":"١٢÷٤ = ٣ ، س³÷س = س² ، ص÷ص = ١ ← ٣س²."},{"type":"tfr","q":"في العبارة ٣س + ٥ص − ٢س، المعامل النهائي لـ س هو ١.","answer":true,"reasons":["لأن ٣س − ٢س = ١س = س","لأنه ٥","لأنه −٢"],"reason":0},{"type":"essay","q":"بسّط: ٩أ² − ٣أ + ٤ − ٥أ² + ٧أ − ١٠.","model":"٤أ² + ٤أ − ٦."}]}},
  {"id":"g9-math-1-u3-4","grade":"g9","subject":"math","term":1,"unit":3,"no":4,"title":"التعامل مع الأقواس","summary":"شرح متحرك لخاصية التوزيع وفكّ الأقواس مع السالب وتجميع الحدود، ثم أنشطة بثلاثة مستويات.","page":"lesson-working-with-brackets.html","video":"","pdf":"","notes":["نضرب ما خارج القوس في كل حد داخل القوس.","الإشارة السالبة أمام القوس تعكس إشارة كل حد بداخله.","بعد فكّ الأقواس نجمع الحدود المتشابهة."],"exercises":["فكّ: −٣(س − ٢) ، ٣س(س + ٢).","فكّ وبسّط: ٤(ص + ٣) − ٢(ص − ٥)."],"levels":{"easy":[{"type":"mcq","q":"فكّ: ٤(س − ٣)","options":["٤س − ٣","٤س − ١٢","٤س + ١٢","س − ١٢"],"answer":1,"why":"٤×س − ٤×٣ = ٤س − ١٢."},{"type":"mcq","q":"فكّ: −٢(ص − ٥)","options":["−٢ص − ١٠","−٢ص + ١٠","−٢ص − ٥","٢ص − ١٠"],"answer":1,"why":"−٢×(−٥) = +١٠."},{"type":"mcq","q":"فكّ: ٣س(س + ٢)","options":["٣س² + ٦س","٣س² + ٢","٣س + ٦س","٦س²"],"answer":0,"why":"٣س×س + ٣س×٢ = ٣س² + ٦س."},{"type":"mcq","q":"بسّط: ٢(س + ٣) + ٣(س − ١)","options":["٥س + ٣","٥س + ٩","٥س + ٢","٦س + ٣"],"answer":0,"why":"٢س+٦ + ٣س−٣ = ٥س + ٣."}],"medium":[{"type":"mcq","q":"فكّ: −(س − ٤)","options":["−س − ٤","−س + ٤","س + ٤","−٤س"],"answer":1,"why":"السالب يعكس الإشارتين ← −س + ٤."},{"type":"tfr","q":"فكّ القوس ٥(٢س + ١) هو ١٠س + ١.","answer":false,"reasons":["لأن ٥ تُضرب في ١ أيضًا: ١٠س + ٥","لأن ٥×٢ = ٧","لأن القوس يُحذف فقط"],"reason":0},{"type":"essay","q":"فكّ وبسّط: ٥(س + ٢) − ٢(س + ٣).","model":"٥س + ١٠ − ٢س − ٦ = ٣س + ٤."},{"type":"tfr","q":"ناتج س(س − ٣) هو س² − ٣س.","answer":true,"reasons":["لأن س×س = س² و س×(−٣) = −٣س","لأنه ٢س − ٣","لأنه س² − ٣"],"reason":0},{"type":"mcq","q":"فكّ وبسّط: ٣(٢أ − ١) − ٤أ","options":["٢أ − ٣","٢أ − ١","١٠أ − ٣","٢أ + ٣"],"answer":0,"why":"٦أ − ٣ − ٤أ = ٢أ − ٣."},{"type":"essay","q":"فكّ وبسّط: ٢س(س + ٤) + س(س − ٢).","model":"٢س² + ٨س + س² − ٢س = ٣س² + ٦س."},{"type":"tfr","q":"فكّ −٣(٢س + ٥) هو −٦س − ١٥.","answer":true,"reasons":["لأن −٣×٢س = −٦س و −٣×٥ = −١٥","لأنه −٦س + ١٥","لأنه ٦س − ١٥"],"reason":0}],"hard":[{"type":"mcq","q":"فكّ وبسّط: ٤(ص + ٣) − ٢(ص − ٥)","options":["٢ص + ٢٢","٢ص + ٢","٢ص − ٢٢","٦ص + ٢٢"],"answer":0,"why":"٤ص + ١٢ − ٢ص + ١٠ = ٢ص + ٢٢."},{"type":"essay","q":"فكّ وبسّط: س(٢س − ٣) − ٢س(س − ٤).","model":"٢س² − ٣س − ٢س² + ٨س = ٥س."},{"type":"tfr","q":"العبارة ٣(س − ٢) − ٣(س + ٢) تساوي صفرًا.","answer":false,"reasons":["لأن ٣س − ٦ − ٣س − ٦ = −١٢ وليس صفرًا","لأنهما متساويتان","لأنها ٦س"],"reason":0},{"type":"mcq","q":"فكّ وبسّط: ١٠ − ٢(٣س − ٤)","options":["١٨ − ٦س","٢ − ٦س","٢٤س − ٣٢","١٨ + ٦س"],"answer":0,"why":"١٠ − ٦س + ٨ = ١٨ − ٦س."},{"type":"essay","q":"مستطيل طوله (٢س + ٣) وعرضه ٤. اكتب عبارة لمساحته في أبسط صورة.","model":"المساحة = ٤(٢س + ٣) = ٨س + ١٢."},{"type":"tfr","q":"في العبارة ٥ − ٢(س + ١) نحسب ٥ − ٢ = ٣ أولًا ثم نضرب.","answer":false,"reasons":["لأن الضرب أقوى من الطرح: نفك −٢(س+١) أولًا ← ٥ − ٢س − ٢ = ٣ − ٢س","لأن الطرح أولًا","لأن الناتج ٣س + ٣"],"reason":0},{"type":"mcq","q":"فكّ: ٢أ ب(٣أ − ٢ب)","options":["٦أ²ب − ٤أ ب²","٦أ ب − ٤أ ب","٥أ²ب − ٤أ ب²","٦أ² − ٤ب²"],"answer":0,"why":"٢أ ب×٣أ = ٦أ²ب و ٢أ ب×(−٢ب) = −٤أ ب²."},{"type":"essay","q":"أثبت أن ٢(٣س + ٤) + ٣(٢س − ١) = ١٢س + ٥.","model":"٦س + ٨ + ٦س − ٣ = ١٢س + ٥."},{"type":"tfr","q":"فكّ −س(−س − ١) هو س² + س.","answer":true,"reasons":["لأن سالب × سالب = موجب في الحدين","لأنه −س² − س","لأنه س² − س"],"reason":0},{"type":"essay","q":"فكّ وبسّط: ٣[٢(س + ١) − س].","model":"داخل القوس: ٢س + ٢ − س = س + ٢ ← ٣(س + ٢) = ٣س + ٦."}]}},
  {"id":"g9-math-1-u3-5","grade":"g9","subject":"math","term":1,"unit":3,"no":5,"title":"الأسس","summary":"شرح متحرك لقوانين الأسس الخمسة (الضرب والقسمة وقوة القوة والأُس الصفري والسالب)، ثم أنشطة بثلاثة مستويات.","page":"lesson-indices.html","video":"","pdf":"","notes":["الضرب (نفس الأساس): نجمع الأُسس (سᵐ × سⁿ = سᵐ⁺ⁿ).","القسمة: نطرح الأُسس (سᵐ ÷ سⁿ = سᵐ⁻ⁿ).","قوة القوة: نضرب الأُسس ((سᵐ)ⁿ = سᵐ×ⁿ).","الأُس الصفري = ١ (س⁰ = ١)، والأُس السالب = المقلوب (س⁻ⁿ = ١/سⁿ)."],"exercises":["بسّط: ٣س² × ٤س⁵ ، (٢س³)².","أوجد قيمة: ٥⁻² ، ٧⁰."],"levels":{"easy":[{"type":"mcq","q":"بسّط: س⁵ × س³","options":["س¹⁵","س⁸","س²","٢س⁸"],"answer":1,"why":"في الضرب نجمع الأُسس: ٥+٣ = ٨."},{"type":"mcq","q":"بسّط: (ص⁴)³","options":["ص⁷","ص¹²","٣ص⁴","ص"],"answer":1,"why":"قوة القوة نضرب الأُسس: ٤×٣ = ١٢."},{"type":"mcq","q":"ما قيمة ٥⁻² ؟","options":["−١٠","١/٢٥","−٢٥","٢٥"],"answer":1,"why":"١/٥² = ١/٢٥."},{"type":"mcq","q":"بسّط: ١٢أ⁷ ÷ ٤أ²","options":["٣أ⁵","٨أ⁵","٣أ⁹","٣أ¹⁴"],"answer":0,"why":"١٢÷٤ = ٣ و ٧−٢ = ٥."}],"medium":[{"type":"mcq","q":"بسّط: (٢س³)²","options":["٢س⁶","٤س⁶","٤س⁵","٢س⁵"],"answer":1,"why":"نربّع ٢ فتصبح ٤ و (س³)² = س⁶."},{"type":"tfr","q":"قيمة ٥س⁰ تساوي ١.","answer":false,"reasons":["لأن س⁰ = ١، إذن ٥ × ١ = ٥ وليس ١","لأن أي شيء فيه صفر يساوي صفرًا","لأنها ٥س"],"reason":0},{"type":"essay","q":"بسّط واكتب بأُس موجب: س³ ÷ س⁷.","model":"س³⁻⁷ = س⁻⁴ = ١/س⁴."},{"type":"tfr","q":"الأُس السالب يجعل العدد سالبًا.","answer":false,"reasons":["بل يقلب العدد إلى المقام (مقلوب) دون تغيير إشارته","لأن ٢⁻³ = −٨","لأن السالب يضرب الأساس"],"reason":0},{"type":"mcq","q":"ما قيمة ٢⁻³ ؟","options":["−٦","−٨","١/٨","١/٦"],"answer":2,"why":"١/٢³ = ١/٨."},{"type":"essay","q":"بسّط: (٣س² × ٤س⁴) ÷ (٢س³).","model":"١٢س⁶ ÷ ٢س³ = ٦س³."},{"type":"tfr","q":"ناتج س⁴ × ص³ يساوي (س ص)⁷.","answer":false,"reasons":["لأن الأساسين مختلفان (س و ص) فلا نجمع الأُسس","لأننا نجمع الأُسس دائمًا","لأنها س ص¹²"],"reason":0}],"hard":[{"type":"mcq","q":"ما قيمة (٢/٣)⁻² ؟","options":["٩/٤","٤/٩","−٤/٩","−٩/٤"],"answer":0,"why":"نقلب الكسر ونربّع: (٣/٢)² = ٩/٤."},{"type":"essay","q":"أوجد قيمة ن إذا كان ٢ⁿ = ١/١٦.","model":"١/١٦ = ١/٢⁴ = ٢⁻⁴ ← إذن ن = −٤."},{"type":"tfr","q":"ناتج س⁻² × س⁵ يساوي س³.","answer":true,"reasons":["لأننا نجمع الأُسس: −٢ + ٥ = +٣","لأنه س⁻⁷","لأنه س⁻¹⁰"],"reason":0},{"type":"mcq","q":"بسّط: (٣أ²ب³)²","options":["٩أ⁴ب⁶","٦أ⁴ب⁶","٩أ⁴ب⁵","٣أ⁴ب⁶"],"answer":0,"why":"٣² = ٩ و أ⁴ و ب⁶."},{"type":"essay","q":"بسّط: س⁻³ ÷ س⁻⁵.","model":"س⁻³⁻⁽⁻⁵⁾ = س⁻³⁺⁵ = س²."},{"type":"tfr","q":"قيمة (٥س)⁰ تساوي ١ (حيث س ≠ ٠).","answer":true,"reasons":["لأن القوس كاملًا مرفوع للأُس صفر فيساوي ١","لأنها تساوي ٥","لأنها تساوي صفرًا"],"reason":0},{"type":"mcq","q":"إذا كان ٣س = ٨١، فما قيمة س؟","options":["٣","٤","٢٧","٩"],"answer":1,"why":"٣⁴ = ٨١ (لاحظ: ٣ أس س = ٨١ ← س = ٤)."},{"type":"essay","q":"بسّط: (٢س⁴)³ ÷ ٤س⁸.","model":"٨س¹² ÷ ٤س⁸ = ٢س⁴."},{"type":"tfr","q":"القيمة ٤⁻¹ + ٢⁻¹ تساوي ٣/٤.","answer":true,"reasons":["لأن ١/٤ + ١/٢ = ١/٤ + ٢/٤ = ٣/٤","لأنها ٦⁻¹","لأنها −٦"],"reason":0},{"type":"essay","q":"أوجد قيمة ن: ٥³ × ٥ⁿ = ٥⁹.","model":"٣ + ن = ٩ ← ن = ٦."}]}},
  {"id":"g9-math-1-u4-1","grade":"g9","subject":"math","term":1,"unit":4,"no":1,"title":"الدائرة","summary":"شرح متحرك لأجزاء الدائرة: نصف القطر والقطر والوتر والقوس والقطاع والقطعة والمماس، ثم أنشطة بثلاثة مستويات.","page":"lesson-the-circle.html","video":"","pdf":"","notes":["القطر = ٢ × نصف القطر (ق = ٢نق)، وهو أطول وتر في الدائرة.","القطاع الدائري محصور بين نصفي قطرين وقوس.","القطعة الدائرية محصورة بين وتر وقوس.","المماس يلمس الدائرة في نقطة واحدة ويكون عموديًّا على نصف القطر (٩٠°)."],"exercises":["دائرة قطرها ١٨ سم، كم نصف قطرها؟","فرّق بين القطاع الدائري والقطعة الدائرية."],"levels":{"easy":[{"type":"mcq","q":"ما أطول وتر في أي دائرة؟","options":["نصف القطر","القطر","المماس","القوس"],"answer":1,"why":"القطر يمر بالمركز وهو أطول وتر."},{"type":"mcq","q":"المنطقة بين نصفي قطرين وقوس تُسمّى:","options":["قطعة دائرية","قطاعًا دائريًّا","وترًا","مماسًّا"],"answer":1,"why":"القطاع الدائري يشبه قطعة البيتزا."},{"type":"mcq","q":"دائرة قطرها ١٤ سم، كم نصف قطرها؟","options":["٧ سم","٢٨ سم","١٤ سم","٣٫٥ سم"],"answer":0,"why":"١٤ ÷ ٢ = ٧ سم."},{"type":"mcq","q":"ما قياس الزاوية بين المماس ونصف القطر عند نقطة التماس؟","options":["٤٥°","٩٠°","١٨٠°","٦٠°"],"answer":1,"why":"المماس عمودي على نصف القطر (٩٠°)."}],"medium":[{"type":"mcq","q":"المنطقة المحصورة بين وتر وقوس تُسمّى:","options":["قطاعًا","قطعة دائرية","قطرًا","محيطًا"],"answer":1,"why":"القطعة الدائرية يفصلها وتر."},{"type":"tfr","q":"كل وتر في الدائرة يمرّ بمركزها.","answer":false,"reasons":["القطر فقط هو الوتر الذي يمر بالمركز، وهناك أوتار كثيرة لا تمر بالمركز","لأن كل الأوتار أقطار","لأن الوتر خارج الدائرة"],"reason":0},{"type":"essay","q":"عرّف المماس واذكر علاقته بنصف القطر عند نقطة التماس.","model":"المماس خط مستقيم يلمس الدائرة في نقطة واحدة فقط، ويكون عموديًّا على نصف القطر عندها (يصنع زاوية ٩٠°)."},{"type":"tfr","q":"إذا كان نصف قطر دائرة ٥٫٥ سم فإن قطرها ١١ سم.","answer":true,"reasons":["لأن ق = ٢ × ٥٫٥ = ١١ سم","لأن ق = ٥٫٥ ÷ ٢","لأن ق = ١٠ سم"],"reason":0},{"type":"mcq","q":"المسار الخارجي الكامل للدائرة يُسمّى:","options":["القطر","المحيط","الوتر","القطاع"],"answer":1,"why":"المحيط هو طول الإطار الخارجي."},{"type":"essay","q":"ما الفرق بين القوس الأصغر والقوس الأكبر؟","model":"القوس الأصغر أقصر من نصف الدائرة، والقوس الأكبر أطول من نصف الدائرة."},{"type":"tfr","q":"المماس يقطع الدائرة في نقطتين.","answer":false,"reasons":["المماس يلمسها في نقطة واحدة فقط، أما القاطع فيقطعها في نقطتين","لأنه يمر بالمركز","لأنه وتر"],"reason":0}],"hard":[{"type":"mcq","q":"نصف الدائرة يُعدّ في الوقت نفسه:","options":["قطاعًا وقطعة دائرية","مماسًّا فقط","وترًا فقط","زاوية حادة"],"answer":0,"why":"لأن القطر وتر وهو أيضًا نصفا قطرين على استقامة واحدة."},{"type":"essay","q":"إذا رُسم مماس لدائرة مركزها م عند نقطة أ، وكانت ب نقطة على المماس حيث م أ = ٦ سم و أ ب = ٨ سم، أوجد طول م ب.","model":"المثلث م أ ب قائم عند أ ← م ب = √(٦² + ٨²) = √١٠٠ = ١٠ سم."},{"type":"tfr","q":"جميع أنصاف أقطار الدائرة الواحدة متساوية في الطول.","answer":true,"reasons":["لأن كل نقطة على المحيط تبعد نفس المسافة عن المركز","لأنها تختلف حسب الاتجاه","لأن القطر أقصر منها"],"reason":0},{"type":"mcq","q":"كم عدد الأقطار التي يمكن رسمها في الدائرة؟","options":["١","٢","٤","عدد لا نهائي"],"answer":3,"why":"يمر بالمركز عدد لا نهائي من الأقطار."},{"type":"essay","q":"لماذا يُعدّ المثلث المكوّن من نصفي قطرين ووتر مثلثًا متطابق الضلعين؟","model":"لأن نصفي القطرين متساويان في الطول دائمًا."},{"type":"tfr","q":"القطر يقسم الدائرة إلى نصفين متطابقين.","answer":true,"reasons":["لأنه يمر بمركز الدائرة","لأنه لا يمر بالمركز","لأنه مماس"],"reason":0},{"type":"mcq","q":"دائرتان متحدتا المركز، نصف قطر الصغرى ٤ سم والكبرى ٧ سم. ما عرض الحلقة بينهما؟","options":["٣ سم","١١ سم","٦ سم","١٫٥ سم"],"answer":0,"why":"٧ − ٤ = ٣ سم."},{"type":"essay","q":"اشرح كيف تميّز بين الوتر والقاطع في الدائرة.","model":"الوتر قطعة مستقيمة طرفاها على محيط الدائرة، أما القاطع فخط مستقيم يمتد خارج الدائرة ويقطعها في نقطتين."},{"type":"tfr","q":"الزاوية المركزية رأسها يقع على محيط الدائرة.","answer":false,"reasons":["رأسها يقع في مركز الدائرة، أما المحيطية فرأسها على المحيط","لأنها ٩٠° دائمًا","لأنها خارج الدائرة"],"reason":0},{"type":"essay","q":"دائرة نصف قطرها ٨ سم، ما طول أطول وتر يمكن رسمه بداخلها؟","model":"أطول وتر هو القطر = ٢ × ٨ = ١٦ سم."}]}},
  {"id":"g9-math-1-u4-2","grade":"g9","subject":"math","term":1,"unit":4,"no":2,"title":"الزوايا","summary":"شرح متحرك لأنواع الزوايا والزوايا على مستقيم وحول نقطة وزوايا التوازي (F و Z و U)، ثم أنشطة بثلاثة مستويات.","page":"lesson-angles.html","video":"","pdf":"","notes":["الزوايا على خط مستقيم مجموعها ١٨٠°، وحول نقطة مجموعها ٣٦٠°.","الزوايا المتقابلة بالرأس (X) متساوية.","مع التوازي: المتناظرة (F) متساوية، والمتبادلة (Z) متساوية، والمتحالفة (U) مجموعها ١٨٠°."],"exercises":["زاويتان على مستقيم إحداهما ٦٥°، أوجد الأخرى.","زاويتان متحالفتان إحداهما ١٣٠°، أوجد الأخرى."],"levels":{"easy":[{"type":"mcq","q":"زاويتان على خط مستقيم إحداهما ٦٥°. كم الأخرى؟","options":["٢٥°","١١٥°","٢٩٥°","٦٥°"],"answer":1,"why":"١٨٠ − ٦٥ = ١١٥°."},{"type":"mcq","q":"ما العلاقة بين الزاويتين المتبادلتين (Z) مع التوازي؟","options":["متساويتان","مجموعهما ١٨٠°","مجموعهما ٩٠°","مجموعهما ٣٦٠°"],"answer":0,"why":"المتبادلتان متساويتان."},{"type":"mcq","q":"زاويتان متحالفتان (U) إحداهما ١٣٠°. كم الأخرى؟","options":["١٣٠°","٥٠°","٩٠°","٤٠°"],"answer":1,"why":"١٨٠ − ١٣٠ = ٥٠°."},{"type":"mcq","q":"ثلاث زوايا حول نقطة، اثنتان منها ١٠٠° و ١٤٠°. كم الثالثة؟","options":["١٢٠°","٦٠°","١٠٠°","١٨٠°"],"answer":0,"why":"٣٦٠ − ٢٤٠ = ١٢٠°."}],"medium":[{"type":"mcq","q":"الزاوية التي قياسها ٢١٠° تُسمّى زاوية:","options":["حادة","منفرجة","منعكسة","مستقيمة"],"answer":2,"why":"أكبر من ١٨٠° وأقل من ٣٦٠°."},{"type":"tfr","q":"الزاويتان المتقابلتان بالرأس مجموعهما ١٨٠° دائمًا.","answer":false,"reasons":["بل هما متساويتان في القياس دائمًا","لأنهما ٩٠° دائمًا","لأنهما غير متساويتين"],"reason":0},{"type":"essay","q":"اذكر الفرق بين الزوايا المتناظرة (F) والمتحالفة (U) بين مستقيمين متوازيين.","model":"المتناظرة متساوية في القياس، أما المتحالفة فمجموعهما ١٨٠°."},{"type":"tfr","q":"مجموع الزاويتين المتتامتين يساوي ٩٠°.","answer":true,"reasons":["التتام = ٩٠°، والتكامل = ١٨٠°","لأنهما ١٨٠°","لأنهما ٣٦٠°"],"reason":0},{"type":"mcq","q":"إذا تقاطع مستقيمان وكانت إحدى الزوايا ٤٠°، فما قياس الزاوية المقابلة لها بالرأس؟","options":["٤٠°","١٤٠°","٥٠°","٩٠°"],"answer":0,"why":"المتقابلتان بالرأس متساويتان."},{"type":"essay","q":"أربع زوايا متساوية متجمعة حول نقطة واحدة. ما قياس كل زاوية؟","model":"٣٦٠° ÷ ٤ = ٩٠°."},{"type":"tfr","q":"الزاوية المستقيمة قياسها ١٨٠°.","answer":true,"reasons":["وهي تشبه خطًا مستقيمًا","لأنها ٩٠°","لأنها ٣٦٠°"],"reason":0}],"hard":[{"type":"mcq","q":"زاويتان على مستقيم قياسهما (٢س) و (٣س + ٣٠). ما قيمة س؟","options":["٣٠°","٣٦°","٢٥°","٤٠°"],"answer":0,"why":"٥س + ٣٠ = ١٨٠ ← ٥س = ١٥٠ ← س = ٣٠°."},{"type":"essay","q":"زاويتان متبادلتان بين متوازيين قياسهما (٣س − ١٠) و (س + ٥٠). أوجد س.","model":"٣س − ١٠ = س + ٥٠ ← ٢س = ٦٠ ← س = ٣٠°."},{"type":"tfr","q":"إذا كانت زاوية حادة ٥٠° فإن الزاوية المنعكسة المقابلة لها ٣١٠°.","answer":true,"reasons":["لأن ٣٦٠° − ٥٠° = ٣١٠°","لأنها ١٣٠°","لأنها ٢٣٠°"],"reason":0},{"type":"mcq","q":"زاويتان متحالفتان قياسهما س و ٣س. ما قياس الزاوية الكبرى؟","options":["١٣٥°","٤٥°","١٢٠°","٩٠°"],"answer":0,"why":"٤س = ١٨٠ ← س = ٤٥° ← الكبرى ٣×٤٥ = ١٣٥°."},{"type":"essay","q":"متى يكون مستقيمان متوازيين إذا قطعهما قاطع؟ اذكر شرطين.","model":"إذا تساوت زاويتان متبادلتان، أو تساوت زاويتان متناظرتان، أو كان مجموع زاويتين متحالفتين ١٨٠°."},{"type":"tfr","q":"الزاوية المنفرجة قياسها أكبر من ٩٠° وأقل من ١٨٠°.","answer":true,"reasons":["وهذا تعريف الزاوية المنفرجة","لأنها أقل من ٩٠°","لأنها أكبر من ١٨٠°"],"reason":0},{"type":"mcq","q":"كم زاوية قائمة تصنع دورة كاملة (٣٦٠°)؟","options":["٢","٣","٤","٦"],"answer":2,"why":"٣٦٠ ÷ ٩٠ = ٤ زوايا قائمة."},{"type":"essay","q":"إذا كانت الزاوية المتقابلة بالرأس لزاوية قياسها (٢س + ١٠) تساوي ٧٠°، فأوجد س.","model":"٢س + ١٠ = ٧٠ ← ٢س = ٦٠ ← س = ٣٠°."},{"type":"tfr","q":"الزوايا المتناظرة تقع على جهتين مختلفتين من القاطع.","answer":false,"reasons":["المتناظرة تقع في نفس الجهة من القاطع، أما المتبادلة فعلى جهتين مختلفتين","لأنها داخلية فقط","لأنها مجموعها ١٨٠°"],"reason":0},{"type":"essay","q":"خمس زوايا حول نقطة، أربع منها قياس كل منها ٧٠°. ما قياس الخامسة؟","model":"٣٦٠° − (٤ × ٧٠°) = ٣٦٠° − ٢٨٠° = ٨٠°."}]}},
  {"id":"g9-math-1-u4-3","grade":"g9","subject":"math","term":1,"unit":4,"no":3,"title":"الإنشاءات الهندسية","summary":"شرح متحرك لإنشاء المثلث والمنصّف العمودي ومنصّف الزاوية بالمسطرة والفرجار، ثم أنشطة بثلاثة مستويات.","page":"lesson-geometric-constructions.html","video":"","pdf":"","notes":["لا تمسح أقواس الفرجار أبدًا لأنها دليل صحة الإنشاء.","في المنصّف العمودي نفتح الفرجار فتحة أكبر من نصف طول القطعة.","منصّف الزاوية يقسمها إلى زاويتين متساويتين دون منقلة."],"exercises":["اشرح خطوات إنشاء المنصّف العمودي لقطعة أ ب.","كيف تنشئ زاوية ٣٠° بالفرجار فقط؟"],"levels":{"easy":[{"type":"mcq","q":"لإنشاء المنصّف العمودي لقطعة طولها ٨ سم، نفتح الفرجار:","options":["٣ سم","٤ سم","أكبر من ٤ سم","١ سم"],"answer":2,"why":"يجب أن تكون الفتحة أكبر من نصف القطعة ليتقاطع القوسان."},{"type":"mcq","q":"لماذا لا نمسح أقواس الفرجار بعد الإنشاء؟","options":["لأنها دليل صحة الطريقة","لأنها تجمّل الرسم فقط","يجوز مسحها","لا سبب"],"answer":0,"why":"الأقواس تثبت استخدام الفرجار بدقة."},{"type":"mcq","q":"إذا نصّفنا زاوية قائمة (٩٠°) بالفرجار، فما قياس كل جزء؟","options":["٣٠°","٤٥°","٦٠°","٩٠°"],"answer":1,"why":"٩٠ ÷ ٢ = ٤٥°."},{"type":"mcq","q":"ما قياس كل زاوية في مثلث متطابق الأضلاع منشأ بالفرجار؟","options":["٤٥°","٦٠°","٩٠°","١٢٠°"],"answer":1,"why":"١٨٠ ÷ ٣ = ٦٠°."}],"medium":[{"type":"mcq","q":"الأدوات المسموح بها في الإنشاءات الهندسية هي:","options":["المسطرة والفرجار","المنقلة فقط","المثلث فقط","الآلة الحاسبة"],"answer":0,"why":"المسطرة والفرجار وقلم رصاص حاد."},{"type":"tfr","q":"المنصّف العمودي لقطعة مستقيمة يصنع معها زاوية ٩٠°.","answer":true,"reasons":["لأنه عمودي عليها ويقسمها إلى نصفين متساويين","لأنه يصنع ٦٠°","لأنه يوازيها"],"reason":0},{"type":"essay","q":"كيف تنشئ زاوية قياسها ٣٠° باستخدام المسطرة والفرجار فقط؟","model":"ننشئ زاوية ٦٠° (بإنشاء مثلث متطابق الأضلاع)، ثم ننصّفها بالفرجار فنحصل على ٣٠°."},{"type":"tfr","q":"إذا فتحنا الفرجار فتحة أصغر من نصف القطعة يتقاطع القوسان.","answer":false,"reasons":["لن يتقاطع القوسان أبدًا، لذا يجب أن تكون الفتحة أكبر من النصف","سيتقاطعان عند المنتصف","سيتقاطعان عند الطرف"],"reason":0},{"type":"mcq","q":"أيُّ نقطة تقع على المنصّف العمودي للقطعة أ ب تكون:","options":["أقرب لـ أ","أقرب لـ ب","على بُعدين متساويين من أ و ب","خارج المستوى"],"answer":2,"why":"هذه الخاصية الهندسية للمنصّف العمودي."},{"type":"essay","q":"اشرح خطوات إنشاء منصّف زاوية بالفرجار.","model":"١) نرسم قوسًا من رأس الزاوية يقطع ضلعيها. ٢) من نقطتي التقاطع نرسم قوسين متقاطعين داخل الزاوية. ٣) نصل الرأس بنقطة التقاطع."},{"type":"tfr","q":"يمكن إنشاء مثلث أطوال أضلاعه ٢ سم، ٣ سم، ٨ سم.","answer":false,"reasons":["لأن مجموع الضلعين الأصغرين (٢+٣=٥) أصغر من الضلع الثالث (٨) فلا يتقاطع القوسان","لأن كل ٣ أعداد تكوّن مثلثًا","لأن ٨ عدد زوجي"],"reason":0}],"hard":[{"type":"mcq","q":"أيُّ أطوال أضلاع لا يمكن أن تشكّل مثلثًا؟","options":["٣، ٤، ٥","٥، ٥، ٨","٢، ٤، ٧","٦، ٧، ٨"],"answer":2,"why":"٢ + ٤ = ٦ < ٧ فلا يتقاطع القوسان."},{"type":"essay","q":"كيف تنشئ زاوية ٤٥° باستخدام المسطرة والفرجار فقط؟","model":"ننشئ زاوية ٩٠° (بالمنصّف العمودي لقطعة مستقيمة) ثم ننصّفها بالفرجار إلى ٤٥°."},{"type":"tfr","q":"أي نقطة تقع على منصّف الزاوية تبعد البعد نفسه عن ضلعي الزاوية.","answer":true,"reasons":["وهذه خاصية هندسية أساسية لمنصّف الزاوية","لأنها أقرب لأحد الضلعين","لأنها تقع على الرأس فقط"],"reason":0},{"type":"mcq","q":"إذا أنشأنا منصّف الزاوية لزاوية قياسها ١٢٠° ثم نصّفنا أحد النصفين، نحصل على:","options":["٣٠°","٦٠°","٤٠°","١٥°"],"answer":0,"why":"١٢٠ ÷ ٢ = ٦٠ ← ٦٠ ÷ ٢ = ٣٠°."},{"type":"essay","q":"في مثلث أ ب ج، كيف تجد نقطة تبعد البعد نفسه عن الرؤوس أ و ب و ج؟","model":"ننشئ المنصّفين العموديين لضلعين، فنقطة تقاطعهما هي مركز الدائرة المارة بالرؤوس وتبعد البعد نفسه عنها."},{"type":"tfr","q":"يجب تغيير فتحة الفرجار عند رسم القوس من (ب) بعد رسمه من (أ) في المنصّف العمودي.","answer":false,"reasons":["يجب الحفاظ على نفس فتحة الفرجار تمامًا لضمان التساوي","يجب مضاعفتها","لا يهم"],"reason":0},{"type":"mcq","q":"نقطة تقاطع منصّفات زوايا المثلث هي:","options":["مركز الدائرة الداخلية الماسة لأضلاعه","خارج المثلث دائمًا","أحد رؤوس المثلث","منتصف القاعدة"],"answer":0,"why":"تبعد البعد نفسه عن الأضلاع الثلاثة."},{"type":"essay","q":"ما شرط تكوين مثلث من ثلاث قطع مستقيمة أطوالها أ، ب، ج؟","model":"يجب أن يكون مجموع طولي أي ضلعين أكبر من طول الضلع الثالث."},{"type":"tfr","q":"يمكن إنشاء زاوية ١٢٠° بالفرجار عبر رسم زاويتين متجاورتين قياس كل منهما ٦٠°.","answer":true,"reasons":["لأن ٦٠° + ٦٠° = ١٢٠°","لأن ١٢٠° لا تُنشأ بالفرجار","لأنها ٣ × ٦٠°"],"reason":0},{"type":"essay","q":"ارسم خطوات إنشاء مثلث أطوال أضلاعه ٧ سم، ٥ سم، ٤ سم.","model":"١) نرسم القاعدة ٧ سم بالمسطرة. ٢) نفتح الفرجار ٥ سم ونرسم قوسًا من الطرف الأول. ٣) نفتح الفرجار ٤ سم ونرسم قوسًا من الطرف الثاني يقطعه. ٤) نصل نقطة التقاطع بالطرفين."}]}},
  {"id":"g9-math-1-u4-4","grade":"g9","subject":"math","term":1,"unit":4,"no":4,"title":"المثلثات","summary":"شرح متحرك لتصنيف المثلثات ومجموع زوايا المثلث والزاوية الخارجية، ثم أنشطة بثلاثة مستويات.","page":"lesson-triangles.html","video":"","pdf":"","notes":["مجموع قياسات زوايا أي مثلث = ١٨٠°.","في المثلث متطابق الضلعين زاويتا القاعدة متساويتان.","الزاوية الخارجية للمثلث تساوي مجموع الزاويتين الداخليتين البعيدتين."],"exercises":["مثلث زاويتاه ٥٠° و ٧٥°، أوجد الثالثة.","مثلث متطابق الضلعين زاوية رأسه ٤٠°، أوجد زاويتي القاعدة."],"levels":{"easy":[{"type":"mcq","q":"مثلث زاويتاه ٦٠° و ٧٠°. ما قياس الثالثة؟","options":["٤٠°","٥٠°","٦٠°","٣٠°"],"answer":1,"why":"١٨٠ − ١٣٠ = ٥٠°."},{"type":"mcq","q":"مثلث متطابق الضلعين زاوية رأسه ٨٠°. ما قياس كل زاوية قاعدة؟","options":["٥٠°","٨٠°","١٠٠°","٤٠°"],"answer":0,"why":"(١٨٠ − ٨٠) ÷ ٢ = ٥٠°."},{"type":"mcq","q":"الزاوية الخارجية لمثلث زاويتاه الداخليتان البعيدتان ٤٥° و ٧٥° تساوي:","options":["١٢٠°","٦٠°","١١٠°","١٣٠°"],"answer":0,"why":"٤٥ + ٧٥ = ١٢٠°."},{"type":"mcq","q":"مثلث قائم الزاوية إحدى حادتيه ٣٥°. ما قياس الحادة الأخرى؟","options":["٦٥°","٥٥°","٤٥°","٣٥°"],"answer":1,"why":"٩٠ − ٣٥ = ٥٥°."}],"medium":[{"type":"mcq","q":"ما نوع المثلث الذي قياسات زواياه ٤٠°، ٥٠°، ٩٠°؟","options":["حاد الزوايا","قائم الزاوية","منفرج الزاوية","متطابق الأضلاع"],"answer":1,"why":"لوجود زاوية ٩٠°."},{"type":"tfr","q":"يمكن أن يحتوي المثلث على زاويتين قائمتين.","answer":false,"reasons":["لأن ٩٠° + ٩٠° = ١٨٠° ولن يتبقى شيء للزاوية الثالثة","لأن مجموع الزوايا ٣٦٠°","لأنه مربع"],"reason":0},{"type":"essay","q":"مثلث متطابق الضلعين إحدى زاويتي قاعدته ٦٥°. أوجد زاوية رأسه.","model":"زاويتا القاعدة ٦٥° و ٦٥° ← الرأس = ١٨٠ − ١٣٠ = ٥٠°."},{"type":"tfr","q":"في المثلث متطابق الأضلاع كل زاوية تساوي ٦٠°.","answer":true,"reasons":["لأن ١٨٠° ÷ ٣ = ٦٠°","لأنها ٩٠°","لأنها ٤٥°"],"reason":0},{"type":"mcq","q":"زاوية خارجية لمثلث قياسها ١٣٠° وإحدى الداخليتين البعيدتين ٥٥°. كم الأخرى؟","options":["٧٥°","٥٠°","١٨٥°","٦٥°"],"answer":0,"why":"١٣٠ − ٥٥ = ٧٥°."},{"type":"essay","q":"اشرح لماذا تكون الزاويتان الحادتان في المثلث القائم متتامتين.","model":"لأن مجموع زوايا المثلث ١٨٠°، وبحذف القائمة ٩٠° يبقى ٩٠° للزاويتين الحادتين."},{"type":"tfr","q":"الزاوية الخارجية للمثلث تكون دائمًا أكبر من كل من الزاويتين الداخليتين البعيدتين.","answer":true,"reasons":["لأنها تساوي مجموعهما معًا","لأنها أصغر منهما","لأنها تساوي ١٨٠°"],"reason":0}],"hard":[{"type":"mcq","q":"قياسات زوايا مثلث هي س، ٢س، ٣س. ما قياس أكبر زاوية؟","options":["٩٠°","٦٠°","٣٠°","١٢٠°"],"answer":0,"why":"٦س = ١٨٠ ← س = ٣٠° ← الكبرى ٩٠°."},{"type":"essay","q":"مثلث متطابق الضلعين إحدى زواياه ١٠٠°. هل ١٠٠° هي زاوية الرأس أم القاعدة؟ أوجد باقي الزوايا.","model":"لا بد أن تكون زاوية الرأس (لأن زاويتي قاعدة ١٠٠° مجموعهما ٢٠٠° > ١٨٠°). إذن زاويتا القاعدة = (١٨٠−١٠٠)÷٢ = ٤٠° لكل منهما."},{"type":"tfr","q":"مجموع الزوايا الخارجية الثلاث للمثلث يساوي ٣٦٠°.","answer":true,"reasons":["لأن مجموع الزوايا الخارجية لأي مضلّع محدّب = ٣٦٠°","لأنه ١٨٠°","لأنه ٥٤٠°"],"reason":0},{"type":"mcq","q":"مثلث قائم الزاوية ومتطابق الضلعين، قياس كل زاوية حادة فيه:","options":["٤٥°","٦٠°","٣٠°","٩٠°"],"answer":0,"why":"٩٠ ÷ ٢ = ٤٥°."},{"type":"essay","q":"زاويتا مثلث هما (٢س + ١٠) و (س + ٢٠) والزاوية الخارجية البعيدة عنهما ١٢٠°. أوجد س.","model":"٢س + ١٠ + س + ٢٠ = ١٢٠ ← ٣س + ٣٠ = ١٢٠ ← ٣س = ٩٠ ← س = ٣٠°."},{"type":"tfr","q":"في المثلث المنفرج الزاوية، الزاويتان الأخريان حادتان دائمًا.","answer":true,"reasons":["لأن الزاوية المنفرجة > ٩٠° فيبقى للزاويتين الأخريين أقل من ٩٠°","لأنهما قائمتان","لأن إحداهما منفرجة"],"reason":0},{"type":"mcq","q":"ما قياس الزاوية الخارجية عند أي رأس في مثلث متطابق الأضلاع؟","options":["١٢٠°","٦٠°","١٨٠°","٩٠°"],"answer":0,"why":"٦٠° + ٦٠° = ١٢٠°."},{"type":"essay","q":"النسبة بين زوايا مثلث هي ٢ : ٣ : ٤. أوجد قياس كل زاوية.","model":"مجموع الأجزاء ٩ ← الجزء = ١٨٠÷٩ = ٢٠° ← الزوايا: ٤٠°، ٦٠°، ٨٠°."},{"type":"tfr","q":"الضلع المقابل للزاوية الكبرى في المثلث هو أطول أضلاعه.","answer":true,"reasons":["وهذه قاعدة متباينة المثلث بين الأضلاع والزوايا","لأنه أقصر أضلاعه","لأن الأضلاع لا علاقة لها بالزوايا"],"reason":0},{"type":"essay","q":"في مثلث أ ب ج، زاوية أ ضعف زاوية ب، وزاوية ج تساوي ٦٠°. أوجد أ و ب.","model":"٢ب + ب + ٦٠ = ١٨٠ ← ٣ب = ١٢٠ ← ب = ٤٠° و أ = ٨٠°."}]}},
  {"id":"g9-math-1-u4-5","grade":"g9","subject":"math","term":1,"unit":4,"no":5,"title":"الأشكال الرباعية","summary":"شرح متحرك لمجموع زوايا الرباعي وخصائص الأشكال الرباعية الستة، ثم أنشطة بثلاثة مستويات.","page":"lesson-quadrilaterals.html","video":"","pdf":"","notes":["مجموع زوايا أي شكل رباعي = ٣٦٠°.","في متوازي الأضلاع: المتقابلتان متساويتان والمتتاليتان مجموعهما ١٨٠°.","الأقطار متعامدة في: المربع والمعيّن والطائرة الورقية.","شبه المنحرف له زوج واحد فقط من الأضلاع المتوازية."],"exercises":["شكل رباعي زواياه ١١٠°، ٨٥°، ٧٥°، أوجد الرابعة.","قارن بين المستطيل والمعيّن."],"levels":{"easy":[{"type":"mcq","q":"شكل رباعي ثلاث زوايا فيه ١٠٠°، ٩٠°، ٨٠°. ما الرابعة؟","options":["٨٠°","٩٠°","١٠٠°","٧٠°"],"answer":1,"why":"٣٦٠ − ٢٧٠ = ٩٠°."},{"type":"mcq","q":"أيُّ شكل رباعي له زوج واحد فقط من الأضلاع المتوازية؟","options":["متوازي الأضلاع","شبه المنحرف","المعيّن","المستطيل"],"answer":1,"why":"شبه المنحرف."},{"type":"mcq","q":"في متوازي الأضلاع، إحدى زواياه ٦٥°. ما قياس المجاورة لها؟","options":["٦٥°","١١٥°","١٢٥°","٩٠°"],"answer":1,"why":"١٨٠ − ٦٥ = ١١٥°."},{"type":"mcq","q":"شكل رباعي أضلاعه الأربعة متساوية وليست زواياه قائمة بالضرورة:","options":["المستطيل","المعيّن","شبه المنحرف","الطائرة الورقية"],"answer":1,"why":"المعيّن."}],"medium":[{"type":"mcq","q":"أيُّ شكل رباعي قطراه متساويان ومتعامدان؟","options":["المستطيل","المربع","المعيّن","متوازي الأضلاع"],"answer":1,"why":"المربع يجمع كل الخصائص."},{"type":"tfr","q":"كل مربع هو مستطيل ومعيّن في الوقت نفسه.","answer":true,"reasons":["لأن المربع يحقق جميع خصائص المستطيل وجميع خصائص المعيّن","لأن المربع ليس مستطيلًا","لأن أضلاعه مختلفة"],"reason":0},{"type":"essay","q":"اذكر ثلاثة أشكال رباعية أقطارها متعامدة.","model":"المربع، المعيّن، الطائرة الورقية (الدالتون)."},{"type":"tfr","q":"قطرا المستطيل متعامدان دائمًا.","answer":false,"reasons":["قطرا المستطيل متساويان وينصّف كل منهما الآخر لكنهما غير متعامدين إلا إذا كان مربعًا","لأنهما يصنعان ٩٠° دائمًا","لأنهما متوازيان"],"reason":0},{"type":"mcq","q":"في الطائرة الورقية، كم زوجًا من الزوايا المتقابلة المتساوية؟","options":["زوج واحد","زوجان","لا يوجد","أربعة"],"answer":0,"why":"زوج واحد فقط."},{"type":"essay","q":"في معيّن قياس إحدى زواياه ٧٠°. أوجد قياسات الزوايا الثلاث الأخرى.","model":"المقابلة لها ٧٠°، وكل من المجاورتين ١٨٠ − ٧٠ = ١١٠°."},{"type":"tfr","q":"مجموع زوايا أي شكل رباعي يساوي مجموع زوايا مثلثين.","answer":true,"reasons":["لأن القطر يقسمه لمثلثين: ٢ × ١٨٠° = ٣٦٠°","لأنه ١٨٠°","لأنه ٥٤٠°"],"reason":0}],"hard":[{"type":"mcq","q":"زوايا شكل رباعي هي س، ٢س، ٣س، ٤س. ما قيمة س؟","options":["٣٦°","١٨°","٤٠°","٣٠°"],"answer":0,"why":"١٠س = ٣٦٠ ← س = ٣٦°."},{"type":"essay","q":"شبه منحرف متطابق الساقين إحدى زاويتي قاعدته السفلية ٦٥°. أوجد باقي زواياه.","model":"زاوية القاعدة الأخرى ٦٥°، وكل من الزاويتين العلويتين ١٨٠ − ٦٥ = ١١٥°."},{"type":"tfr","q":"كل متوازي أضلاع هو مستطيل.","answer":false,"reasons":["المستطيل يحتاج زوايا قائمة ٩٠°، وهو حالة خاصة من متوازي الأضلاع وليس العكس","لأن زوايا متوازي الأضلاع ٩٠° دائمًا","لأنهما متطابقان"],"reason":0},{"type":"mcq","q":"في طائرة ورقية، الزاويتان غير المتساويتين ١١٠° و ٥٠°. ما قياس كل من الزاويتين المتساويتين؟","options":["١٠٠°","٢٠٠°","٨٠°","٩٠°"],"answer":0,"why":"(٣٦٠ − ١٦٠) ÷ ٢ = ١٠٠°."},{"type":"essay","q":"متوازي أضلاع فيه زاويتان متقابلتان قياسهما (٢س + ٢٠) و (٣س − ١٠). أوجد س.","model":"٢س + ٢٠ = ٣س − ١٠ ← س = ٣٠°."},{"type":"tfr","q":"قطرا المعيّن ينصّفان زواياه.","answer":true,"reasons":["وهذه من خصائص المعيّن والمربع","لأنهما لا ينصّفان الزوايا","لأنهما متوازيان"],"reason":0},{"type":"mcq","q":"مجموع الزاويتين المتتاليتين في متوازي الأضلاع يساوي:","options":["٩٠°","١٨٠°","٣٦٠°","١٢٠°"],"answer":1,"why":"لأنهما زاويتان متحالفتان بين متوازيين."},{"type":"essay","q":"لماذا لا يمكن أن يحتوي الشكل الرباعي على أربع زوايا منفرجة؟","model":"لأن مجموع ٤ زوايا أكبر من ٩٠° سيكون أكبر من ٣٦٠°، وهذا مستحيل."},{"type":"tfr","q":"شبه المنحرف له قطران متساويان دائمًا.","answer":false,"reasons":["يتساوى القطران في شبه المنحرف متطابق الساقين فقط","لأن كل شبه منحرف مستطيل","لأن أقطاره متعامدة"],"reason":0},{"type":"essay","q":"أوجد قياس الزاوية الرابعة لرباعي زواياه ٨٥°، ١١٥°، ٩٥°.","model":"٣٦٠ − (٨٥ + ١١٥ + ٩٥) = ٣٦٠ − ٢٩٥ = ٦٥°."}]}},
  {"id":"g9-math-1-u4-6","grade":"g9","subject":"math","term":1,"unit":4,"no":6,"title":"مضلّعات أخرى","summary":"شرح متحرك لمجموع الزوايا الداخلية والخارجية للمضلّعات المنتظمة وإيجاد عدد الأضلاع، ثم أنشطة بثلاثة مستويات.","page":"lesson-other-polygons.html","video":"","pdf":"","notes":["مجموع الزوايا الداخلية لأي مضلّع = (ن − ٢) × ١٨٠°.","مجموع الزوايا الخارجية لأي مضلّع محدّب = ٣٦٠° دائمًا.","في المضلّع المنتظم: الزاوية الخارجية = ٣٦٠° ÷ ن، وعدد الأضلاع ن = ٣٦٠° ÷ الخارجية."],"exercises":["أوجد مجموع الزوايا الداخلية للثماني.","مضلّع منتظم زاويته الداخلية ١٣٥°، كم عدد أضلاعه؟"],"levels":{"easy":[{"type":"mcq","q":"ما مجموع الزوايا الداخلية للسداسي (٦ أضلاع)؟","options":["٥٤٠°","٧٢٠°","٩٠٠°","٣٦٠°"],"answer":1,"why":"(٦−٢) × ١٨٠ = ٧٢٠°."},{"type":"mcq","q":"ما مجموع الزوايا الخارجية لمضلّع ذي ١٠ أضلاع؟","options":["٣٦٠°","١٤٤٠°","١٨٠°","١٨٠٠°"],"answer":0,"why":"مجموع الخارجية ٣٦٠° دائمًا."},{"type":"mcq","q":"مضلّع منتظم زاويته الخارجية ٤٥°. كم عدد أضلاعه؟","options":["٦","٨","٩","١٠"],"answer":1,"why":"٣٦٠ ÷ ٤٥ = ٨ أضلاع."},{"type":"mcq","q":"ما قياس كل زاوية داخلية في الخماسي المنتظم؟","options":["١٠٨°","١٢٠°","٩٠°","١٣٥°"],"answer":0,"why":"٥٤٠ ÷ ٥ = ١٠٨°."}],"medium":[{"type":"mcq","q":"ما قياس كل زاوية خارجية في العشاري المنتظم (١٠ أضلاع)؟","options":["٣٦°","١٤٤°","١٨°","٧٢°"],"answer":0,"why":"٣٦٠ ÷ ١٠ = ٣٦°."},{"type":"tfr","q":"مجموع الزوايا الخارجية للثماني أكبر من مجموع الزوايا الخارجية للمثلث.","answer":false,"reasons":["لأن مجموع الزوايا الخارجية لأي مضلّع محدّب يساوي ٣٦٠° دائمًا","لأن الثماني أكبر","لأن المثلث ١٨٠°"],"reason":0},{"type":"essay","q":"أوجد قياس كل زاوية داخلية في الثماني المنتظم.","model":"الخارجية = ٣٦٠÷٨ = ٤٥° ← الداخلية = ١٨٠ − ٤٥ = ١٣٥°."},{"type":"tfr","q":"المضلّع المنتظم تتساوى فيه الأضلاع فقط دون الزوايا.","answer":false,"reasons":["يجب أن تتساوى جميع أضلاعه وجميع زواياه معًا","لأن الزوايا لا تهم","مثل المعيّن"],"reason":0},{"type":"mcq","q":"مضلّع مجموع زواياه الداخلية ٩٠٠°. كم عدد أضلاعه؟","options":["٦","٧","٨","٩"],"answer":1,"why":"٩٠٠÷١٨٠ = ٥ ← ن − ٢ = ٥ ← ن = ٧."},{"type":"essay","q":"أوجد عدد أضلاع مضلّع منتظم قياس زاويته الداخلية ١٥٠°.","model":"الخارجية = ١٨٠ − ١٥٠ = ٣٠° ← ن = ٣٦٠ ÷ ٣٠ = ١٢ ضلعًا."},{"type":"tfr","q":"الزاوية الداخلية والزاوية الخارجية عند نفس الرأس مجموعهما ١٨٠°.","answer":true,"reasons":["لأنهما متجاورتان على خط مستقيم واحد","لأنهما ٩٠°","لأنهما ٣٦٠°"],"reason":0}],"hard":[{"type":"mcq","q":"هل يمكن أن يكون قياس الزاوية الخارجية لمضلّع منتظم ٥٠°؟","options":["نعم","لا، لأن ٣٦٠ لا يقبل القسمة على ٥٠","نعم لسباعي","نعم لثماني"],"answer":1,"why":"٣٦٠ ÷ ٥٠ = ٧٫٢ ليس عددًا صحيحًا."},{"type":"essay","q":"أوجد مجموع الزوايا الداخلية لمضلّع ذي ١٢ ضلعًا.","model":"(١٢ − ٢) × ١٨٠ = ١٠ × ١٨٠ = ١٨٠٠°."},{"type":"tfr","q":"المعيّن يُعدّ مضلّعًا منتظمًا.","answer":false,"reasons":["لأن زواياه ليست متساوية جميعها (إلا إذا كان مربعًا)","لأن أضلاعه متساوية","لأنه رباعي"],"reason":0},{"type":"mcq","q":"ما عدد المثلثات التي ينقسم إليها التساعي (٩ أضلاع) من أحد رؤوسه؟","options":["٧","٨","٩","٦"],"answer":0,"why":"ن − ٢ = ٩ − ٢ = ٧ مثلثات."},{"type":"essay","q":"خماسي قياس أربع زوايا فيه ١٠٠°، ١١٠°، ١٢٠°، ٩٥°. أوجد الزاوية الخامسة.","model":"مجموع الخماسي ٥٤٠° ← الخامسة = ٥٤٠ − ٤٢٥ = ١١٥°."},{"type":"tfr","q":"كلما زاد عدد أضلاع المضلّع المنتظم، صَغُرت زاويته الخارجية وكَبُرت زاويته الداخلية.","answer":true,"reasons":["لأن ٣٦٠ ÷ ن تصغر كلما كبرت ن، فتكبر ١٨٠ − الخارجية","لأنهما لا تتغيران","لأن الخارجية تكبر"],"reason":0},{"type":"mcq","q":"مضلّع منتظم زاويته الداخلية تساوي ضعف زاويته الخارجية. ما هو؟","options":["السداسي المنتظم","المربع","الخماسي المنتظم","المثلث"],"answer":0,"why":"٢س + س = ١٨٠ ← س = ٦٠° (خارجية) ← ن = ٣٦٠÷٦٠ = ٦."},{"type":"essay","q":"أوجد عدد أضلاع مضلّع مجموع زواياه الداخلية ١٤٤٠°.","model":"١٤٤٠ ÷ ١٨٠ = ٨ ← ن − ٢ = ٨ ← ن = ١٠ أضلاع."},{"type":"tfr","q":"في السداسي المنتظم قياس كل زاوية داخلية ١٢٠°.","answer":true,"reasons":["لأن ٧٢٠ ÷ ٦ = ١٢٠°","لأنها ١٠٨°","لأنها ١٣٥°"],"reason":0},{"type":"essay","q":"تلتقي ثلاث بلاطات متطابقة من مضلّع منتظم حول نقطة واحدة لتغطية الأرضية بلا فراغ. ما نوع المضلّع؟","model":"زاوية كل بلاطة = ٣٦٠ ÷ ٣ = ١٢٠° ← السداسي المنتظم!"}]}},
  {"id":"g9-math-1-u5-1","grade":"g9","subject":"math","term":1,"unit":5,"no":1,"title":"تقريب الأعداد","summary":"شرح متحرك للتقريب لأقرب منزلة عشرية ولأقرب أرقام معنوية، ثم أنشطة بثلاثة مستويات.","page":"lesson-rounding-numbers.html","video":"","pdf":"","notes":["الأرقام ٠–٤ بخيلة لا تزيد، والأرقام ٥–٩ كريمة تزيد ١.","المنازل العشرية تُعدّ بعد الفاصلة فقط.","الأرقام المعنوية تبدأ من أول رقم غير صفري من اليسار، ونضع أصفارًا لحفظ القيمة المكانية في الأعداد الكبيرة."],"exercises":["قرّب ٨٫٤٧٦ إلى منزلتين عشريتين.","قرّب ٤٧٨٢٠ و ٠٫٠٠٦٣٨ إلى رقمين معنويين."],"levels":{"easy":[{"type":"mcq","q":"قرّب ٨٫٤٧٦ إلى منزلتين عشريتين:","options":["٨٫٤٧","٨٫٤٨","٨٫٥","٨٫٤"],"answer":1,"why":"الرقم الثالث ٦ كريم ← ٨٫٤٨."},{"type":"mcq","q":"قرّب ٥٦٣٩٠ إلى رقمين معنويين:","options":["٥٦","٥٦٠٠٠","٥٧٠٠٠","٥٦٤٠٠"],"answer":1,"why":"نحفظ المنازل بأصفار ← ٥٦٠٠٠."},{"type":"mcq","q":"قرّب ٠٫٠٠٣٨٧ إلى رقمين معنويين:","options":["٠٫٠١","٠٫٠٠٣٨","٠٫٠٠٣٩","٠٫٠٠٤"],"answer":2,"why":"أول رقمين معنويين ٣ و ٨ وبعدهما ٧ ← ٠٫٠٠٣٩."},{"type":"mcq","q":"كم رقمًا معنويًا في ٠٫٠٥٠٤ ؟","options":["٢","٣","٥","٤"],"answer":1,"why":"٥ و ٠ و ٤ ← ٣ أرقام معنوية."}],"medium":[{"type":"mcq","q":"قرّب ٣٧٤٨ لأقرب مئة:","options":["٣٧٠٠","٣٨٠٠","٣٧٥٠","٤٠٠٠"],"answer":0,"why":"العشرات ٤ بخيل ← ٣٧٠٠."},{"type":"tfr","q":"الأصفار على يسار العدد العشري الصغير مثل ٠٫٠٠٤ تُعدّ أرقامًا معنوية.","answer":false,"reasons":["لأن العدّ يبدأ من أول رقم غير صفري من اليسار (٤)","لأن كل صفر معنوي","لأنها بعد الفاصلة"],"reason":0},{"type":"essay","q":"قرّب العدد ٠٫٠٧٩٦ إلى رقمين معنويين.","model":"أول رقمين معنويين ٧ و ٩ وبعدهما ٦ كريم فتصبح ٨٠ ← ٠٫٠٨٠."},{"type":"tfr","q":"تقريب ٤٩٨ لأقرب عشرة هو ٥٠٠.","answer":true,"reasons":["لأن الآحاد ٨ كريم فيزيد ٩ إلى ١٠ ← ٥٠٠","لأنه ٤٩٠","لأنه ٤٠٠"],"reason":0},{"type":"mcq","q":"قرّب ٩٫٩٩٦ إلى منزلتين عشريتين:","options":["٩٫٩٩","١٠٫٠٠","٩٫٩","١٠٫١"],"answer":1,"why":"٦ تزيد ٩٩ إلى ١٠٠ ← ١٠٫٠٠."},{"type":"essay","q":"ما الفرق بين التقريب لـ ٢ منزلة عشرية والتقريب لـ ٢ رقم معنوي للعدد ٠٫٠٤٨٢؟","model":"لمنزلتين عشريتين: ٠٫٠٥. لرقمين معنويين: ٠٫٠٤٨."},{"type":"tfr","q":"في العدد ٢٠٥٠، الصفر بين ٢ و ٥ يُعدّ رقمًا معنويًا.","answer":true,"reasons":["لأن الأصفار الواقعة بين أرقام غير صفرية تكون معنوية دائمًا","لأن الصفر ليس معنويًا أبدًا","لأنه في الآحاد"],"reason":0}],"hard":[{"type":"mcq","q":"قرّب ٩٩٧٤ إلى رقمين معنويين:","options":["١٠٠٠٠","٩٩٠٠","٩٠٠٠","١٠٠٠"],"answer":0,"why":"٧ تزيد ٩٩ إلى ١٠٠ ← ١٠٠٠٠."},{"type":"essay","q":"قرّب ٠٫٠٠٠٨٠٤٩ إلى ٣ أرقام معنوية.","model":"٨، ٠، ٤ وبعدها ٩ ← ٠٫٠٠٠٨٠٥."},{"type":"tfr","q":"تقريب ٣٫٤٩ لأقرب عدد صحيح هو ٤.","answer":false,"reasons":["ننظر للجزء من عشرة فقط وهو ٤ (بخيل) ← الناتج ٣ وليس ٤","لأن ٩ تزيد ٤ إلى ٥ ثم ٣ إلى ٤","لأنه ٣٫٥"],"reason":0},{"type":"mcq","q":"أيُّ عدد مما يأتي له ٤ أرقام معنوية؟","options":["٠٫٠٢٠٥٠","٠٫٠٠٤٥","٢٣٠","٠٫٠١٠٢"],"answer":0,"why":"٢ و ٠ و ٥ و ٠ (الصفر الأخير بعد الفاصلة معنوي) = ٤."},{"type":"essay","q":"قرّب ١٢٣٤٥٦ إلى: (١) رقم معنوي واحد، (٢) ٣ أرقام معنوية.","model":"(١) ١٠٠٠٠٠. (٢) ١٢٣٠٠٠."},{"type":"tfr","q":"عند تقريب ٤٫٥٠٠ لأقرب عدد صحيح يكون الناتج ٥.","answer":true,"reasons":["لأن الجزء من عشرة هو ٥ (كريم)","لأنه ٤","لأنه ٤٫٥"],"reason":0},{"type":"mcq","q":"قرّب ٠٫٠٩٩٥ إلى ٣ أرقام معنوية:","options":["٠٫٠٩٩٥","٠٫١٠٠","٠٫٠٩٩","٠٫١"],"answer":0,"why":"٠٫٠٩٩٥ فيه بالفعل ٣ أرقام معنوية!"},{"type":"essay","q":"لماذا نكتب الصفر في ٤٫٥٠ عند التقريب لمنزلتين عشريتين؟","model":"لإظهار دقة التقريب وأنه مقرّب لمنزلتين عشريتين."},{"type":"tfr","q":"تقريب ٦٤٩ لأقرب مئة هو ٧٠٠.","answer":false,"reasons":["رقم العشرات ٤ بخيل ← ٦٠٠","لأن ٩ تزيد ٤","لأنه ٦٥٠"],"reason":0},{"type":"essay","q":"قرّب ٠٫٠٠٧٩٩٦ إلى ٣ أرقام معنوية.","model":"٧، ٩، ٩ وبعدها ٦ ← ٠٫٠٠٨٠٠."}]}},
  {"id":"g9-math-1-u5-2","grade":"g9","subject":"math","term":1,"unit":5,"no":2,"title":"التقدير","summary":"شرح متحرك لتقدير نواتج العمليات بتقريب كل عدد لرقم معنوي واحد وتقدير الجذور، ثم أنشطة بثلاثة مستويات.","page":"lesson-estimation.html","video":"","pdf":"","notes":["لتقدير أي عملية: نقرّب كل عدد إلى رقم معنوي واحد ثم نحسب ذهنيًا.","القسمة على ٠٫٥ تعني الضرب في ٢.","لتقدير الجذر التربيعي نبحث عن أقرب مربع كامل."],"exercises":["قدّر: ٣٩٫٤ × ٥٫٢ ، (٢٩٫٤ × ٤٫١) ÷ ٠٫٤٨.","قدّر قيمة √٥٠ و ∛٦٥."],"levels":{"easy":[{"type":"mcq","q":"ما أفضل تقدير لناتج ٣٩٫٤ × ٥٫٢ ؟","options":["٢٠٠","١٥٠","٢٥٠","١٨٠"],"answer":0,"why":"٤٠ × ٥ = ٢٠٠."},{"type":"mcq","q":"ما أفضل تقدير لـ (١٩٫٨ × ٣٫١) ÷ ٠٫٥١ ؟","options":["٣٠","٦٠","١٢٠","٢٤٠"],"answer":2,"why":"(٢٠×٣) ÷ ٠٫٥ = ٦٠ ÷ ٠٫٥ = ١٢٠."},{"type":"mcq","q":"ما أفضل تقدير لقيمة √٨٣ ؟","options":["٨","٩","١٠","٧"],"answer":1,"why":"أقرب مربع كامل ٨١ ← √٨١ = ٩."},{"type":"mcq","q":"ما أفضل تقدير لناتج ٤١٨ ÷ ٦٫٩ ؟","options":["٦٠","٧٠","٥٠","٨٠"],"answer":0,"why":"٤٢٠ ÷ ٧ = ٦٠."}],"medium":[{"type":"mcq","q":"ما أفضل تقدير لقيمة ∛٢٨ ؟","options":["٣","٤","٥","٩"],"answer":0,"why":"أقرب مكعب كامل ٢٧ ← ∛٢٧ = ٣."},{"type":"tfr","q":"القسمة على ٠٫٥ تعطي نصف العدد.","answer":false,"reasons":["القسمة على ٠٫٥ تعني الضرب في ٢ فتضاعف العدد","لأن ١٠ ÷ ٠٫٥ = ٥","لأنها لا تغيّر العدد"],"reason":0},{"type":"essay","q":"قدّر ناتج: (٤٨٫٢ + ٣١٫٩) ÷ ٣٫٨.","model":"(٥٠ + ٣٠) ÷ ٤ = ٨٠ ÷ ٤ = ٢٠."},{"type":"tfr","q":"تقدير ناتج ٢٫٩ × ٣٫١ هو ٩.","answer":true,"reasons":["نقرّب إلى ٣ × ٣ = ٩","لأنه ٦","لأنه ١٢"],"reason":0},{"type":"mcq","q":"ما أفضل تقدير لقيمة √١٥٠ ؟","options":["١٢","١٠","١٥","١١"],"answer":0,"why":"أقرب مربع كامل ١٤٤ ← √١٤٤ = ١٢."},{"type":"essay","q":"اشترى خالد ١٩ دفترًا سعر الواحد ١٫٩٥ ريال. قدّر التكلفة الإجمالية.","model":"٢٠ × ٢ = ٤٠ ريالًا تقريبًا."},{"type":"tfr","q":"التقدير يفيد في التحقق من معقولية ناتج الآلة الحاسبة.","answer":true,"reasons":["لأنه يكشف فورًا أخطاء الفاصلة العشرية أو الإدخال","لأنه يعطي الإجابة الدقيقة دائمًا","لأنه بديل عن الآلة"],"reason":0}],"hard":[{"type":"mcq","q":"ما أفضل تقدير لـ (٥٩٫٤ × ١٠٫٢) ÷ ٠٫١٩ ؟","options":["٣٠٠٠","٣٠٠","١٢٠","٦٠٠"],"answer":0,"why":"(٦٠ × ١٠) ÷ ٠٫٢ = ٦٠٠ ÷ ٠٫٢ = ٦٠٠ × ٥ = ٣٠٠٠."},{"type":"essay","q":"قدّر قيمة: √(٣٩٫٢ × ٩٫٨).","model":"√(٤٠ × ١٠) = √٤٠٠ = ٢٠."},{"type":"tfr","q":"تقدير ٧٫٨ × ٥٫٩ أكبر من القيمة الحقيقية.","answer":true,"reasons":["لأننا قرّبنا كلا العددين لأعلى (٨ × ٦ = ٤٨ > ٤٦٫٠٢)","لأنه أصغر","لأنه مساوٍ لها"],"reason":0},{"type":"mcq","q":"ما أفضل تقدير لـ ٠٫٤٩ × ٦٠٫٢ ؟","options":["٣٠","١٢٠","٣٠٠","١٥"],"answer":0,"why":"٠٫٥ × ٦٠ = ٣٠."},{"type":"essay","q":"قدّر قيمة: (٢٫٩٥)³ + √٢٤.","model":"٣³ + √٢٥ = ٢٧ + ٥ = ٣٢."},{"type":"tfr","q":"في التقدير، قسمة عدد على ٠٫٢٥ تساوي ضربه في ٤.","answer":true,"reasons":["لأن ١ ÷ ٠٫٢٥ = ٤","لأنها قسمة على ٤","لأنها ضرب في ٢"],"reason":0},{"type":"mcq","q":"سيارة تقطع ٣٨٥ كم في ٤٫٩ ساعة. قدّر سرعتها المتوسطة.","options":["٨٠ كم/س","٦٠ كم/س","١٠٠ كم/س","٥٠ كم/س"],"answer":0,"why":"٤٠٠ ÷ ٥ = ٨٠ كم/س."},{"type":"essay","q":"قدّر ناتج (٨١٫٢ − ١٩٫٧) ÷ ٠٫٢٩.","model":"(٨٠ − ٢٠) ÷ ٠٫٣ = ٦٠ ÷ ٠٫٣ = ٢٠٠."},{"type":"tfr","q":"أقرب عدد صحيح لقيمة √٣٠ هو ٦.","answer":false,"reasons":["٣٠ تقع بين ٢٥ (٥²) و ٣٦ (٦²)، وهي أقرب لـ ٢٥ (الفرق ٥) من ٣٦ (الفرق ٦) ← ٥٫٥ أقرب لـ ٥","لأنها ٦ بالضبط","لأنها ٧"],"reason":0},{"type":"essay","q":"قدّر مساحة دائرة نصف قطرها ٤٫٩ سم (استخدم π ≈ ٣).","model":"م = π نق² ≈ ٣ × ٥² = ٣ × ٢٥ = ٧٥ سم²."}]}},
  {"id":"g9-math-1-u5-3","grade":"g9","subject":"math","term":1,"unit":5,"no":3,"title":"الحدود العليا والحدود الدنيا","summary":"شرح متحرك للحد الأدنى والحد الأعلى ومتباينة الخطأ وحدود العمليات الحسابية، ثم أنشطة بثلاثة مستويات.","page":"lesson-upper-lower-bounds.html","video":"","pdf":"","notes":["الحد الأدنى = العدد − نصف وحدة الدقة، والحد الأعلى = العدد + نصف وحدة الدقة.","متباينة الخطأ: الحد الأدنى ≤ س < الحد الأعلى.","في الطرح: أعلى (أ−ب) = أعلى أ − أدنى ب."],"exercises":["أوجد الحدين الأدنى والأعلى للعدد ٤٠ (لأقرب ١٠).","اكتب متباينة الخطأ للطول ٦٫٤ م (لأقرب ٠٫١ م)."],"levels":{"easy":[{"type":"mcq","q":"طول حبل ١٥ م لأقرب متر. ما الحد الأدنى لطوله؟","options":["١٤ م","١٤٫٥ م","١٥٫٥ م","١٤٫٩ م"],"answer":1,"why":"١٥ − ٠٫٥ = ١٤٫٥ م."},{"type":"mcq","q":"كتلة صندوق ٧٠٠ جم لأقرب ١٠٠ جم. ما الحد الأعلى؟","options":["٧٠٥ جم","٧٥٠ جم","٨٠٠ جم","٧٤٩ جم"],"answer":1,"why":"٧٠٠ + ٥٠ = ٧٥٠ جم."},{"type":"mcq","q":"ما متباينة الخطأ لـ س = ٤٫٢ لأقرب ٠٫١؟","options":["٤٫١٥ ≤ س < ٤٫٢٥","٤٫١ ≤ س < ٤٫٣","٤٫١٥ < س ≤ ٤٫٢٥","٤٫١٥ ≤ س ≤ ٤٫٢٥"],"answer":0,"why":"نصف ٠٫١ = ٠٫٠٥، و ≤ عند الأدنى و < عند الأعلى."},{"type":"mcq","q":"الحد الأعلى لناتج الطرح (أ − ب) يساوي:","options":["أعلى أ − أعلى ب","أعلى أ − أدنى ب","أدنى أ − أعلى ب","أدنى أ − أدنى ب"],"answer":1,"why":"أكبر فرق = أكبر قيمة − أصغر قيمة."}],"medium":[{"type":"mcq","q":"طول قلم ١٢٫٤ سم لأقرب ٠٫١ سم. ما الحد الأعلى؟","options":["١٢٫٤٥ سم","١٢٫٥ سم","١٢٫٩ سم","١٢٫٤١ سم"],"answer":0,"why":"١٢٫٤ + ٠٫٠٥ = ١٢٫٤٥ سم."},{"type":"tfr","q":"في متباينة الخطأ نضع إشارة (≤) عند الحد الأعلى.","answer":false,"reasons":["نضع (<) فقط عند الحد الأعلى لأن الحد الأعلى نفسه يُقرّب للعدد التالي","لأنها دائمًا ≤","لأنها ="],"reason":0},{"type":"essay","q":"مستطيل طوله ٨ سم وعرضه ٥ سم لأقرب سم. أوجد الحد الأعلى لمساحته.","model":"أعلى طول ٨٫٥، أعلى عرض ٥٫٥ ← أعلى مساحة = ٨٫٥ × ٥٫٥ = ٤٦٫٧٥ سم²."},{"type":"tfr","q":"الحد الأدنى للعدد ٥٠ المقرّب لأقرب ١٠ هو ٤٥.","answer":true,"reasons":["نصف ١٠ = ٥ ← ٥٠ − ٥ = ٤٥","لأنه ٤٩٫٥","لأنه ٤٠"],"reason":0},{"type":"mcq","q":"الحد الأدنى لمحيط مربع طول ضلعه ٦ سم لأقرب سم هو:","options":["٢٢ سم","٢٤ سم","٢٦ سم","٢٠ سم"],"answer":0,"why":"أدنى ضلع ٥٫٥ ← ٤ × ٥٫٥ = ٢٢ سم."},{"type":"essay","q":"أوجد الحد الأدنى للفرق (أ − ب) إذا كان أ = ٢٠ و ب = ١٠ لأقرب عدد صحيح.","model":"أدنى أ = ١٩٫٥، أعلى ب = ١٠٫٥ ← أدنى فرق = ١٩٫٥ − ١٠٫٥ = ٩."},{"type":"tfr","q":"الحد الأعلى لمجموع عددين يساوي مجموع حديهما الأعليين.","answer":true,"reasons":["أعلى(أ+ب) = أعلى أ + أعلى ب","لأنه أعلى + أدنى","لأنه أدنى + أدنى"],"reason":0}],"hard":[{"type":"mcq","q":"لإيجاد الحد الأعلى لناتج القسمة (أ ÷ ب) نحسب:","options":["أعلى أ ÷ أدنى ب","أعلى أ ÷ أعلى ب","أدنى أ ÷ أعلى ب","أدنى أ ÷ أدنى ب"],"answer":0,"why":"أكبر بسط مقسوم على أصغر مقام."},{"type":"essay","q":"عدّاء قطع ١٠٠ م (لأقرب متر) في ١٠ ثوانٍ (لأقرب ثانية). احسب الحد الأعلى لسرعته.","model":"أعلى مسافة = ١٠٠٫٥ م، أدنى زمن = ٩٫٥ ث ← أعلى سرعة = ١٠٠٫٥ ÷ ٩٫٥ ≈ ١٠٫٥٨ م/ث."},{"type":"tfr","q":"الحد الأدنى للعدد ٠٫٤ المقرّب لأقرب منزلة عشرية هو ٠٫٣٥.","answer":true,"reasons":["نصف ٠٫١ = ٠٫٠٥ ← ٠٫٤ − ٠٫٠٥ = ٠٫٣٥","لأنه ٠٫٣","لأنه ٠٫٣٩"],"reason":0},{"type":"mcq","q":"طول سلك ٣٠٠ سم لأقرب ١٠ سم. ما متباينة الخطأ؟","options":["٢٩٥ ≤ ل < ٣٠٥","٢٥٠ ≤ ل < ٣٥٠","٢٩٩٫٥ ≤ ل < ٣٠٠٫٥","٢٩٠ ≤ ل < ٣١٠"],"answer":0,"why":"نصف ١٠ = ٥ ← [٢٩٥، ٣٠٥[."},{"type":"essay","q":"هل يمكن وضع صندوقين كتلة كل منهما ٢٥ كجم (لأقرب كجم) في مصعد حمولته القصوى ٥٠ كجم بأمان مؤكد؟","model":"أعلى كتلة للصندوق الواحد ٢٥٫٥ كجم ← أعلى كتلة للاثنين = ٥١ كجم > ٥٠ كجم، إذن لا يمكن التأكد من الأمان!"},{"type":"tfr","q":"إذا كان س = ٥٫٠٠ لأقرب منزلتين عشريتين فإن الحد الأعلى هو ٥٫٠٠٥.","answer":true,"reasons":["نصف ٠٫٠١ = ٠٫٠٠٥ ← ٥٫٠٠ + ٠٫٠٠٥ = ٥٫٠٠٥","لأنه ٥٫٠٥","لأنه ٥٫٥"],"reason":0},{"type":"mcq","q":"الحد الأدنى لمساحة مثلث قاعدته ١٠ سم وارتفاعه ٦ سم (لأقرب سم):","options":["٢٦٫١٢٥ سم²","٣٠ سم²","٣٤٫١٢٥ سم²","٢٥ سم²"],"answer":0,"why":"١/٢ × ٩٫٥ × ٥٫٥ = ٢٦٫١٢٥ سم²."},{"type":"essay","q":"أوجد الحد الأدنى لناتج القسمة ١٠٠ ÷ ٢٠ (مقرّبين لأقرب ١٠).","model":"أدنى ١٠٠ = ٩٥، أعلى ٢٠ = ٢٥ ← أدنى قسمة = ٩٥ ÷ ٢٥ = ٣٫٨."},{"type":"tfr","q":"الحد الأعلى للعدد ١٢٫٥ المقرّب لأقرب ٠٫٥ هو ١٢٫٧٥.","answer":true,"reasons":["نصف ٠٫٥ = ٠٫٢٥ ← ١٢٫٥ + ٠٫٢٥ = ١٢٫٧٥","لأنه ١٣","لأنه ١٢٫٥٥"],"reason":0},{"type":"essay","q":"طول قطعة خشب ٤٫٠ م لأقرب ٠٫١ م. قُطع منها ١٫٥ م لأقرب ٠٫١ م. ما أكبر طول متبقٍّ ممكن؟","model":"أعلى ٤٫٠ = ٤٫٠٥، أدنى ١٫٥ = ١٫٤٥ ← أكبر متبقٍّ = ٤٫٠٥ − ١٫٤٥ = ٢٫٦ م."}]}},
  {"id":"g9-math-1-u6-1","grade":"g9","subject":"math","term":1,"unit":6,"no":1,"title":"فكّ الأقواس","summary":"شرح متحرك لفكّ حاصل ضرب قوسين والمربّع الكامل والفرق بين مربعين، ثم أنشطة بثلاثة مستويات.","page":"lesson-expanding-brackets.html","video":"","pdf":"","notes":["لفكّ قوسين نضرب كل حد في الأول في كل حد في الثاني ثم نجمع المتشابهة.","المربّع الكامل: (أ + ب)² = أ² + ٢أ ب + ب² (لا تنسَ الحد الأوسط!).","الفرق بين مربعين: (أ + ب)(أ − ب) = أ² − ب²."],"exercises":["فكّ وبسّط: (س + ٤)(س + ٣) ، (س − ٥)(س + ٢).","فكّ: (س + ٣)² ، (ص + ٦)(ص − ٦)."],"levels":{"easy":[{"type":"mcq","q":"فكّ وبسّط: (س + ٤)(س + ٣)","options":["س² + ٧س + ١٢","س² + ١٢س + ٧","س² + ٧","س² + ١٢"],"answer":0,"why":"س² + ٣س + ٤س + ١٢."},{"type":"mcq","q":"فكّ وبسّط: (س − ٥)(س + ٢)","options":["س² − ٣س − ١٠","س² + ٣س − ١٠","س² − ٧س − ١٠","س² − ١٠"],"answer":0,"why":"س² + ٢س − ٥س − ١٠."},{"type":"mcq","q":"فكّ وبسّط: (س + ٣)²","options":["س² + ٩","س² + ٦س + ٩","س² + ٣س + ٩","٢س + ٦"],"answer":1,"why":"(س+٣)(س+٣) = س² + ٦س + ٩."},{"type":"mcq","q":"فكّ وبسّط: (ص + ٦)(ص − ٦)","options":["ص² − ١٢ص − ٣٦","ص² − ٣٦","ص² + ٣٦","ص² − ١٢"],"answer":1,"why":"فرق بين مربعين ← ص² − ٣٦."}],"medium":[{"type":"mcq","q":"فكّ وبسّط: (س − ٤)²","options":["س² − ٨س + ١٦","س² − ١٦","س² − ٨س − ١٦","س² + ٨س + ١٦"],"answer":0,"why":"(−٤)² = +١٦ والحد الأوسط −٨س."},{"type":"tfr","q":"فكّ (س + ٥)² يساوي س² + ٢٥.","answer":false,"reasons":["لأننا نسينا الحد الأوسط +١٠س؛ الصواب س² + ١٠س + ٢٥","لأنها قاعدة صحيحة","لأن ٥² = ١٠"],"reason":0},{"type":"essay","q":"فكّ وبسّط: (٢س + ١)(س + ٣).","model":"٢س² + ٦س + س + ٣ = ٢س² + ٧س + ٣."},{"type":"tfr","q":"ناتج (س − ٣)(س + ٣) يحتوي على حدّين فقط.","answer":true,"reasons":["لأن الحدين الأوسطين −٣س و +٣س يلغيان بعضهما فيبقى س² − ٩","لأنه يحتوي على ٣ حدود","لأنه س² + ٩"],"reason":0},{"type":"mcq","q":"فكّ وبسّط: (س − ٢)(س − ٥)","options":["س² − ٧س + ١٠","س² − ٧س − ١٠","س² + ٧س + ١٠","س² − ٣س + ١٠"],"answer":0,"why":"(−٢)×(−٥) = +١٠ و −٢س−٥س = −٧س."},{"type":"essay","q":"مستطيل طوله (س + ٥) وعرضه (س − ٢). أوجد مساحته في أبسط صورة.","model":"(س + ٥)(س − ٢) = س² + ٣س − ١٠."},{"type":"tfr","q":"في فكّ (أ − ب)² يكون الحد الأخير (+ب²) موجبًا دائمًا.","answer":true,"reasons":["لأن (−ب) × (−ب) = +ب²","لأنه سالب دائمًا","لأنه صفر"],"reason":0}],"hard":[{"type":"mcq","q":"فكّ وبسّط: (٣س − ٢)(٢س + ٥)","options":["٦س² + ١١س − ١٠","٦س² − ١١س − ١٠","٦س² + ١٩س − ١٠","٥س² + ١١س − ١٠"],"answer":0,"why":"٦س² + ١٥س − ٤س − ١٠ = ٦س² + ١١س − ١٠."},{"type":"essay","q":"فكّ وبسّط: (٢س + ٣)².","model":"٤س² + ١٢س + ٩."},{"type":"tfr","q":"فكّ (٢س − ٥)(٢س + ٥) هو ٤س² − ٢٥.","answer":true,"reasons":["لأنه فرق بين مربعين: (٢س)² − ٥² = ٤س² − ٢٥","لأنه ٢س² − ٢٥","لأنه ٤س² + ٢٥"],"reason":0},{"type":"mcq","q":"فكّ وبسّط: (س + ٢)² − س²","options":["٤س + ٤","٤","٢س + ٤","س² + ٤"],"answer":0,"why":"س² + ٤س + ٤ − س² = ٤س + ٤."},{"type":"essay","q":"فكّ وبسّط: (س + ١)(س + ٢) + (س + ٣)(س − ١).","model":"(س² + ٣س + ٢) + (س² + ٢س − ٣) = ٢س² + ٥س − ١."},{"type":"tfr","q":"إذا كان (س + أ)(س + ٢) = س² + ٧س + ١٠ فإن أ = ٥.","answer":true,"reasons":["لأن ٥ + ٢ = ٧ و ٥ × ٢ = ١٠","لأن أ = ٨","لأن أ = ٥٠"],"reason":0},{"type":"mcq","q":"ما معامل س في فكّ (٣س − ٤)² ؟","options":["−٢٤","−١٢","٢٤","١٦"],"answer":0,"why":"٢ × ٣س × (−٤) = −٢٤س."},{"type":"essay","q":"أثبت أن (ن + ١)² − (ن − ١)² = ٤ن.","model":"(ن² + ٢ن + ١) − (ن² − ٢ن + ١) = ٤ن."},{"type":"tfr","q":"فكّ (س + ٣)(س + ٣) يختلف عن فكّ (س + ٣)².","answer":false,"reasons":["هما متطابقان تمامًا ويعطيان س² + ٦س + ٩","لأن التربيع يعطي حدين فقط","لأنهما مختلفان"],"reason":0},{"type":"essay","q":"فكّ وبسّط: (س + ١)(س + ٢)(س + ٣) في خطوتين.","model":"(س² + ٣س + ٢)(س + ٣) = س³ + ٦س² + ١١س + ٦."}]}},
  {"id":"g9-math-1-u6-2","grade":"g9","subject":"math","term":1,"unit":6,"no":2,"title":"تحليل العبارات الجبرية إلى عوامل","summary":"شرح متحرك للتحليل بإخراج العامل المشترك الأكبر والفرق بين مربعين وثلاثية الحدود، ثم أنشطة بثلاثة مستويات.","page":"lesson-factorising-expressions.html","video":"","pdf":"","notes":["التحليل عكس فكّ الأقواس.","أخرج العامل المشترك الأكبر (العدد + المتغير بأصغر أُس) أولًا.","تحقّق دائمًا بفكّ الأقواس ذهنيًا."],"exercises":["حلّل تحليلًا تامًا: ٨س² − ١٢س ص.","حلّل: س² − ١٦ ، س² + ٥س + ٦."],"levels":{"easy":[{"type":"mcq","q":"حلّل: ١٠س + ١٥","options":["٥(٢س + ٣)","٢(٥س + ١٥)","٥(٢س + ١٥)","١٠(س + ٥)"],"answer":0,"why":"ع.م.أ = ٥ ← ٥(٢س + ٣)."},{"type":"mcq","q":"حلّل تحليلًا تامًا: ٦س² − ٩س","options":["٣(٢س² − ٣س)","٣س(٢س − ٣)","س(٦س − ٩)","٣س(٢س + ٣)"],"answer":1,"why":"ع.م.أ = ٣س."},{"type":"mcq","q":"حلّل: س² − ٢٥","options":["(س − ٥)²","(س + ٥)(س − ٥)","س(س − ٢٥)","(س + ٥)²"],"answer":1,"why":"فرق بين مربعين."},{"type":"mcq","q":"حلّل: ٤أ ب + ٨أ","options":["٤(أ ب + ٢أ)","٤أ(ب + ٢)","٢أ(٢ب + ٤)","٤ب(أ + ٢)"],"answer":1,"why":"ع.م.أ = ٤أ."}],"medium":[{"type":"mcq","q":"حلّل: س² + ٧س + ١٢","options":["(س + ٣)(س + ٤)","(س + ٢)(س + ٦)","(س + ١)(س + ١٢)","(س − ٣)(س − ٤)"],"answer":0,"why":"٣×٤ = ١٢ و ٣+٤ = ٧."},{"type":"tfr","q":"التحليل التام لـ ٨س + ١٢ هو ٢(٤س + ٦).","answer":false,"reasons":["لأن ٤س + ٦ لا يزال فيها عامل مشترك ٢؛ التحليل التام ٤(٢س + ٣)","لأن ٢ هو ع.م.أ","لأنه لا يُحلّل"],"reason":0},{"type":"essay","q":"حلّل تحليلًا تامًا: ١٢س²ص − ١٨س ص².","model":"ع.م.أ = ٦س ص ← ٦س ص(٢س − ٣ص)."},{"type":"tfr","q":"يمكن تحليل العبارة س² + ٩ كفرق بين مربعين.","answer":false,"reasons":["لأن الإشارة جمع (+) وليس طرح (−)، ومجموع مربعين لا يُحلّل في الأعداد الحقيقية","لأنها (س+٣)(س−٣)","لأنها (س+٣)²"],"reason":0},{"type":"mcq","q":"حلّل: س² − ٥س + ٦","options":["(س − ٢)(س − ٣)","(س + ٢)(س + ٣)","(س − ٦)(س + ١)","(س − ١)(س − ٦)"],"answer":0,"why":"(−٢)×(−٣) = +٦ و −٢−٣ = −٥."},{"type":"essay","q":"حلّل: ٤س² − ٤٩.","model":"فرق بين مربعين: (٢س + ٧)(٢س − ٧)."},{"type":"tfr","q":"العامل المشترك الأكبر في س³ + س² هو س².","answer":true,"reasons":["نأخذ المتغير المشترك بأصغر أُس وهو س²","لأنه س³","لأنه س"],"reason":0}],"hard":[{"type":"mcq","q":"حلّل: س² + ٢س − ١٥","options":["(س + ٥)(س − ٣)","(س − ٥)(س + ٣)","(س + ١٥)(س − ١)","(س − ٥)(س − ٣)"],"answer":0,"why":"٥×(−٣) = −١٥ و ٥ − ٣ = +٢."},{"type":"essay","q":"حلّل تحليلًا تامًا: ٢س² − ١٨.","model":"نخرج ٢ أولًا: ٢(س² − ٩) ← فرق بين مربعين: ٢(س + ٣)(س − ٣)."},{"type":"tfr","q":"تحليل س² − ٨س + ١٦ هو (س − ٤)².","answer":true,"reasons":["لأنه مربع كامل: (س − ٤)(س − ٤)","لأنه (س+٤)(س−٤)","لأنه (س−٨)(س−٢)"],"reason":0},{"type":"mcq","q":"حلّل بالتجميع: أ س + أ ص + ب س + ب ص","options":["(أ + ب)(س + ص)","(أ + س)(ب + ص)","أ ب(س + ص)","(أ − ب)(س + ص)"],"answer":0,"why":"أ(س+ص) + ب(س+ص) = (أ+ب)(س+ص)."},{"type":"essay","q":"استخدم الفرق بين مربعين لحساب ٥٣² − ٤٧² ذهنيًا.","model":"(٥٣ + ٤٧)(٥٣ − ٤٧) = ١٠٠ × ٦ = ٦٠٠."},{"type":"tfr","q":"تحليل ٩س² − ١ هو (٣س + ١)(٣س − ١).","answer":true,"reasons":["لأن جذر ٩س² هو ٣س وجذر ١ هو ١","لأنه (٩س+١)(٩س−١)","لأنه ٣(س²−١)"],"reason":0},{"type":"mcq","q":"حلّل: س² − س − ١٢","options":["(س − ٤)(س + ٣)","(س + ٤)(س − ٣)","(س − ٦)(س + ٢)","(س − ١٢)(س + ١)"],"answer":0,"why":"(−٤)×٣ = −١٢ و −٤ + ٣ = −١."},{"type":"essay","q":"حلّل تحليلًا تامًا: ٣س³ − ١٢س.","model":"٣س(س² − ٤) = ٣س(س + ٢)(س − ٢)."},{"type":"tfr","q":"ناتج تحليل س² + ٦س هو س(س + ٦).","answer":true,"reasons":["بإخراج س كعامل مشترك","لأنه (س+٣)(س+٢)","لأنه ٦س²"],"reason":0},{"type":"essay","q":"إذا كانت مساحة مستطيل س² + ٨س + ١٥، فأوجد بُعديه بدلالة س.","model":"نحلّل: (س + ٣)(س + ٥) ← البُعدان هما (س + ٥) و (س + ٣)."}]}},
  {"id":"g9-math-1-u6-3","grade":"g9","subject":"math","term":1,"unit":6,"no":3,"title":"استخدام الصيغ وإعادة تنظيمها","summary":"شرح متحرك لجعل متغير آخر موضوع الصيغة بالعمليات العكسية، ثم أنشطة بثلاثة مستويات.","page":"lesson-rearranging-formulae.html","video":"","pdf":"","notes":["موضوع الصيغة هو المتغير الموجود وحده في طرف.","نستخدم العمليات العكسية (+⇄−، ×⇄÷، س²⇄√) من الأبعد إلى الأقرب."],"exercises":["اجعل س موضوع الصيغة في ص = ٣س + ٥.","اجعل نق موضوع الصيغة في م = π نق²."],"levels":{"easy":[{"type":"mcq","q":"إذا كان ص = ٢س − ٤، فما صيغة (س)؟","options":["س = (ص + ٤) ÷ ٢","س = (ص − ٤) ÷ ٢","س = ٢ص + ٤","س = ص/٢ + ٤"],"answer":0,"why":"نجمع ٤ ثم نقسم على ٢."},{"type":"mcq","q":"في ح = ٢ل + ٢ض، ما صيغة (ل)؟","options":["ل = (ح − ٢ض) ÷ ٢","ل = ح − ٢ض","ل = (ح + ٢ض) ÷ ٢","ل = ح/٢ − ٢ض"],"answer":0,"why":"نطرح ٢ض ثم نقسم على ٢."},{"type":"mcq","q":"إذا كان أ = ب² + ٣، فما قيمة (ب) الموجبة؟","options":["ب = √(أ − ٣)","ب = √أ − ٣","ب = (أ − ٣)²","ب = أ − ٩"],"answer":0,"why":"نطرح ٣ أولًا ثم نأخذ الجذر."},{"type":"mcq","q":"في ع = ف ÷ ن، ما صيغة (ن)؟","options":["ن = ف × ع","ن = ف ÷ ع","ن = ع ÷ ف","ن = ف − ع"],"answer":1,"why":"ن = ف ÷ ع."}],"medium":[{"type":"mcq","q":"في م = (ق ع) ÷ ٢، ما صيغة (ع)؟","options":["ع = ٢م ÷ ق","ع = م ÷ ٢ق","ع = ٢م ق","ع = ق ÷ ٢م"],"answer":0,"why":"نضرب في ٢ ثم نقسم على ق."},{"type":"tfr","q":"في ص = م س + ج، المتغير (ص) هو موضوع الصيغة.","answer":true,"reasons":["لأنه وحده في طرف ومعامله ١","لأن م هو الموضوع","لأن ج هو الموضوع"],"reason":0},{"type":"essay","q":"اجعل (ت) موضوع الصيغة في: ع = م + ت ن.","model":"ع − م = ت ن ← ت = (ع − م) ÷ ن."},{"type":"tfr","q":"عكس الجذر التربيعي هو القسمة على ٢.","answer":false,"reasons":["عكس الجذر التربيعي هو التربيع (أُس ٢)","لأنه الضرب في ٢","لأنه الطرح"],"reason":0},{"type":"mcq","q":"إذا كان أ = √س + ٢، فما صيغة (س)؟","options":["س = (أ − ٢)²","س = أ² − ٢","س = أ² − ٤","س = √(أ − ٢)"],"answer":0,"why":"√س = أ − ٢ ← نربّع الطرفين: س = (أ − ٢)²."},{"type":"essay","q":"اجعل (س) موضوع الصيغة في: ص = ٣(س − ٤).","model":"ص ÷ ٣ = س − ٤ ← س = (ص ÷ ٣) + ٤."},{"type":"tfr","q":"في الصيغة ح = ل × ض × ع، يكون ع = ح ÷ (ل ض).","answer":true,"reasons":["بقسمة الطرفين على ل ض","لأن ع = ح × ل ض","لأن ع = ح − ل ض"],"reason":0}],"hard":[{"type":"mcq","q":"إذا كان ص = (٢س + ١) ÷ ٣، فما صيغة (س)؟","options":["س = (٣ص − ١) ÷ ٢","س = (٣ص + ١) ÷ ٢","س = ٣ص − ١","س = (ص − ١) ÷ ٦"],"answer":0,"why":"٣ص = ٢س + ١ ← س = (٣ص − ١) ÷ ٢."},{"type":"essay","q":"اجعل (س) موضوع الصيغة في: أ س + ب = ج س + د.","model":"أ س − ج س = د − ب ← س(أ − ج) = د − ب ← س = (د − ب) ÷ (أ − ج)."},{"type":"tfr","q":"إذا كان ص = ١٠ − ٢س فإن س = (١٠ − ص) ÷ ٢.","answer":true,"reasons":["٢س = ١٠ − ص ← س = (١٠ − ص) ÷ ٢","لأن س = (ص + ١٠)÷٢","لأن س = ص − ١٠"],"reason":0},{"type":"mcq","q":"في م = ٤π نق²، ما صيغة (نق) الموجبة؟","options":["نق = √(م ÷ ٤π)","نق = م ÷ ٤π","نق = √م ÷ ٤π","نق = ٤π ÷ م"],"answer":0,"why":"نق² = م ÷ ٤π ← نأخذ الجذر للطرف كاملًا."},{"type":"essay","q":"اجعل (ف) موضوع الصيغة في: ع² = م² + ٢ ت ف.","model":"٢ ت ف = ع² − م² ← ف = (ع² − م²) ÷ (٢ت)."},{"type":"tfr","q":"للتخلص من المقام في أ = ب/س نضرب الطرفين في س.","answer":true,"reasons":["فتصبح أ س = ب ← س = ب/أ","لأننا نقسم على س","لأننا نطرح س"],"reason":0},{"type":"mcq","q":"إذا كان ١/س = أ + ب، فإن س =","options":["١ ÷ (أ + ب)","أ + ب","١/أ + ١/ب","−(أ + ب)"],"answer":0,"why":"نقلب الطرفين: س = ١ ÷ (أ + ب)."},{"type":"essay","q":"اجعل (ب) موضوع الصيغة في: م = ١/٢ (أ + ب) ع.","model":"٢م = (أ + ب)ع ← ٢م/ع = أ + ب ← ب = (٢م/ع) − أ."},{"type":"tfr","q":"في ص = √(س/٢)، يكون س = ٢ص².","answer":true,"reasons":["نربّع الطرفين: ص² = س/٢ ← نضرب في ٢: س = ٢ص²","لأن س = ص²/٢","لأن س = ٤ص²"],"reason":0},{"type":"essay","q":"في صيغة الحرارة ف = ١٫٨ م + ٣٢، اجعل (م) موضوع الصيغة.","model":"ف − ٣٢ = ١٫٨ م ← م = (ف − ٣٢) ÷ ١٫٨."}]}},
  {"id":"g9-math-1-u6-4","grade":"g9","subject":"math","term":1,"unit":6,"no":4,"title":"حلّ المعادلات","summary":"شرح متحرك لحل المعادلات الخطية بمتغير في الطرفين والأقواس والكسور، ثم أنشطة بثلاثة مستويات.","page":"lesson-solving-equations.html","video":"","pdf":"","notes":["فكّ الأقواس وتخلّص من المقامات أولًا.","جمّع حدود المجهول في طرف والأعداد في الطرف الآخر.","تحقّق دائمًا بالتعويض في المعادلة الأصلية."],"exercises":["حلّ: ٥س − ٣ = ٢س + ٩.","حلّ: (٢س + ١) ÷ ٣ = ٥."],"levels":{"easy":[{"type":"mcq","q":"ما حلّ: ٣س + ٥ = ٢٠ ؟","options":["٣","٥","١٥","٨"],"answer":1,"why":"٣س = ١٥ ← س = ٥."},{"type":"mcq","q":"ما حلّ: ٦س − ٤ = ٢س + ١٢ ؟","options":["٢","٤","٨","٣"],"answer":1,"why":"٤س = ١٦ ← س = ٤."},{"type":"mcq","q":"ما حلّ: ٢(س − ٣) = ١٠ ؟","options":["٨","٢","٥","٧"],"answer":0,"why":"٢س − ٦ = ١٠ ← س = ٨."},{"type":"mcq","q":"ما حلّ: (س + ٤) ÷ ٣ = ٦ ؟","options":["١٤","١٨","٢٢","٢"],"answer":0,"why":"س + ٤ = ١٨ ← س = ١٤."}],"medium":[{"type":"mcq","q":"ما حلّ: ١٠ − ٢س = ٤ ؟","options":["٣","−٣","٧","−٧"],"answer":0,"why":"−٢س = −٦ ← س = ٣."},{"type":"tfr","q":"الحل س = ٢ يحقق المعادلة ٤س − ١ = ٧.","answer":true,"reasons":["لأن ٤(٢) − ١ = ٨ − ١ = ٧","لأن ٤(٢) − ١ = ٩","لأنه لا يحققها"],"reason":0},{"type":"essay","q":"حلّ المعادلة: ٤(س + ٢) = ٢(س + ٩).","model":"٤س + ٨ = ٢س + ١٨ ← ٢س = ١٠ ← س = ٥."},{"type":"tfr","q":"في المعادلة س/٣ + ٢ = ٥ نطرح ٢ أولًا فتصبح س/٣ = ٣.","answer":true,"reasons":["ثم نضرب في ٣ فتكون س = ٩","لأننا نضرب في ٣ فقط لـ س","لأن س = ١"],"reason":0},{"type":"mcq","q":"ما حلّ: ٥س + ٣ = ٥س − ١ ؟","options":["لا يوجد حل","س = ٠","س = ٤","س = −٤"],"answer":0,"why":"تختفي س وتبقى ٣ = −١ (مستحيل)."},{"type":"essay","q":"حلّ المعادلة: (٣س − ١) ÷ ٤ = ٥.","model":"٣س − ١ = ٢٠ ← ٣س = ٢١ ← س = ٧."},{"type":"tfr","q":"حلّ المعادلة −٣س = ١٥ هو س = ٥.","answer":false,"reasons":["١٥ ÷ (−٣) = −٥ وليس +٥","لأن س = ١٨","لأن س = −١٢"],"reason":0}],"hard":[{"type":"mcq","q":"ما حلّ: س/٢ + س/٣ = ٥ ؟","options":["٦","٥","١٠","١٢"],"answer":0,"why":"نضرب في ٦: ٣س + ٢س = ٣٠ ← ٥س = ٣٠ ← س = ٦."},{"type":"essay","q":"حلّ المعادلة: ٣(٢س − ١) − ٢(س + ٤) = ٩.","model":"٦س − ٣ − ٢س − ٨ = ٩ ← ٤س − ١١ = ٩ ← ٤س = ٢٠ ← س = ٥."},{"type":"tfr","q":"للمعادلة ٢(س + ٣) = ٢س + ٦ عدد لا نهائي من الحلول.","answer":true,"reasons":["لأن الطرفين متطابقان تمامًا لكل قيمة لـ س","لأن س = ٠ فقط","لأنه لا يوجد حل"],"reason":0},{"type":"mcq","q":"ما حلّ: ١٢ ÷ س = ٣ ؟","options":["٤","٣٦","٩","١/٤"],"answer":0,"why":"٣س = ١٢ ← س = ٤."},{"type":"essay","q":"حلّ المعادلة: (س + ٢)/٣ = (س − ١)/٢.","model":"ضرب تبادلي: ٢(س + ٢) = ٣(س − ١) ← ٢س + ٤ = ٣س − ٣ ← س = ٧."},{"type":"tfr","q":"إذا كان ٠٫٥س = ٨ فإن س = ٤.","answer":false,"reasons":["٨ ÷ ٠٫٥ = ١٦ وليس ٤","لأن نصف ٨ هو ٤","لأن س = ٨٫٥"],"reason":0},{"type":"mcq","q":"ما حلّ: ٥ − (س − ٢) = ١٠ ؟","options":["−٣","٣","٧","−٧"],"answer":0,"why":"٥ − س + ٢ = ١٠ ← ٧ − س = ١٠ ← س = −٣."},{"type":"essay","q":"حلّ المعادلة: (٢س + ٥)/٣ − ١ = ٤.","model":"(٢س + ٥)/٣ = ٥ ← ٢س + ٥ = ١٥ ← ٢س = ١٠ ← س = ٥."},{"type":"tfr","q":"في المعادلة س² = ٢٥ يوجد حلّان هما +٥ و −٥.","answer":true,"reasons":["لأن ٥² = ٢٥ وأيضًا (−٥)² = ٢٥","لأنه يوجد حل واحد فقط","لأن س = ١٢٫٥"],"reason":0},{"type":"essay","q":"حلّ المعادلة: ٧س − ٤(س − ٢) = ٢٠.","model":"٧س − ٤س + ٨ = ٢٠ ← ٣س = ١٢ ← س = ٤."}]}},
  {"id":"g9-math-1-u6-5","grade":"g9","subject":"math","term":1,"unit":6,"no":5,"title":"المعادلات الخطية الآنية","summary":"شرح متحرك لحل المعادلات الخطية الآنية بالحذف والتعويض والرسم البياني، ثم أنشطة بثلاثة مستويات.","page":"lesson-linear-simultaneous-equations.html","video":"","pdf":"","notes":["الحذف: إذا اختلفت إشارتا المجهول المتساوي المعامل نجمع، وإذا تشابهتا نطرح.","التعويض: نكتب أحد المجهولين بدلالة الآخر ونعوّضه في المعادلة الثانية.","الرسم البياني: نقطة تقاطع المستقيمين هي حلّ المعادلتين."],"exercises":["حلّ: س + ص = ٩ ، س − ص = ١.","حلّ: ص = ٢س ، س + ص = ١٢."],"levels":{"easy":[{"type":"mcq","q":"إذا كان س + ص = ٨ و س − ص = ٢، فما س؟","options":["٣","٥","٦","٤"],"answer":1,"why":"بالجمع: ٢س = ١٠ ← س = ٥."},{"type":"mcq","q":"إذا كان ٣س + ص = ١١ و س + ص = ٥، فما س؟","options":["٢","٣","٤","٦"],"answer":1,"why":"بالطرح: ٢س = ٦ ← س = ٣."},{"type":"mcq","q":"إذا كان ص = ٣س و س + ص = ١٦، فما ص؟","options":["٤","١٢","١٠","٨"],"answer":1,"why":"٤س = ١٦ ← س = ٤ ← ص = ١٢."},{"type":"mcq","q":"حلّ المعادلتين الآنيتين بيانيًّا هو:","options":["نقطة الأصل","نقطة تقاطع المستقيمين","ميل المستقيم","المقطع الصادي"],"answer":1,"why":"نقطة التقاطع تحقق المعادلتين معًا."}],"medium":[{"type":"mcq","q":"حلّ المعادلتين س + ص = ٧ و س − ص = ٣ هو:","options":["(٥، ٢)","(٢، ٥)","(٤، ٣)","(٦، ١)"],"answer":0,"why":"٢س = ١٠ ← س = ٥ ، ص = ٢."},{"type":"tfr","q":"لحل س + ص = ١٠ و ٢س + ص = ١٥ نجمع المعادلتين لحذف ص.","answer":false,"reasons":["إشارتا ص متشابهتان (+ص و +ص) فنطرح المعادلتين لحذف ص","لأن الجمع يحذف ص دائمًا","لأن س تختفي"],"reason":0},{"type":"essay","q":"حلّ المعادلتين بالتعويض: ص = س + ٢ ، ٢س + ص = ١١.","model":"٢س + (س + ٢) = ١١ ← ٣س = ٩ ← س = ٣ ، ص = ٥. الحل (٣، ٥)."},{"type":"tfr","q":"الحل (٣، ٢) يحقق المعادلتين س + ص = ٥ و س − ص = ١.","answer":true,"reasons":["لأن ٣ + ٢ = ٥ و ٣ − ٢ = ١","لأنه يحقق الأولى فقط","لأنه لا يحقق أيًّا منهما"],"reason":0},{"type":"mcq","q":"إذا كان ٢س + ص = ٩ و س + ٢ص = ٩، فما قيمة س؟","options":["٣","٢","٤","١"],"answer":0,"why":"نضرب الأولى في ٢ ونطرح: ٣س = ٩ ← س = ٣."},{"type":"essay","q":"حلّ بالحذف: ٢س + ٣ص = ١٣ ، ٢س − ص = ٥.","model":"بالطرح: ٤ص = ٨ ← ص = ٢ ← ٢س − ٢ = ٥ ← س = ٣٫٥."},{"type":"tfr","q":"إذا كان المستقيمان متوازيين فإنه لا يوجد حلّ للمعادلتين الآنيتين.","answer":true,"reasons":["لأنهما لا يتقاطعان أبدًا","لأن لهما حلًا واحدًا","لأنهما يتقاطعان في الأصل"],"reason":0}],"hard":[{"type":"mcq","q":"مجموع عددين ٢٠ والفرق بينهما ٦. ما العدد الأصغر؟","options":["٧","١٣","١٤","٦"],"answer":0,"why":"س = ١٣ ، ص = ٧."},{"type":"essay","q":"حلّ المعادلتين: ٣س + ٢ص = ١٦ ، ٢س − ص = ٦.","model":"نضرب الثانية في ٢: ٤س − ٢ص = ١٢. بالجمع: ٧س = ٢٨ ← س = ٤، ثم ص = ٢. الحل (٤، ٢)."},{"type":"tfr","q":"يختلف حل المعادلتين الآنيتين إذا حللناهما بالتعويض بدل الحذف.","answer":false,"reasons":["الحل وحيد وثابت مهما اختلفت الطريقة","لأن التعويض أدق","لأن الحذف يعطي إجابة مختلفة"],"reason":0},{"type":"mcq","q":"سعر قلمين ودفتر ٥ ريالات، وسعر قلم ودفتر ٣ ريالات. كم سعر القلم؟","options":["ريالان","ريال واحد","٣ ريالات","٤ ريالات"],"answer":0,"why":"بالطرح: قلم واحد = ٥ − ٣ = ريالان."},{"type":"essay","q":"حلّ: ٥س − ٢ص = ١١ ، ٣س + ص = ١١.","model":"نضرب الثانية في ٢: ٦س + ٢ص = ٢٢. بالجمع: ١١س = ٣٣ ← س = ٣، ص = ٢."},{"type":"tfr","q":"النقطة (٤، −١) هي حلّ لـ س + ص = ٣ و ٢س + ص = ٧.","answer":true,"reasons":["٤ + (−١) = ٣ و ٢(٤) + (−١) = ٧","لأنها لا تحقق الثانية","لأنها لا تحقق الأولى"],"reason":0},{"type":"mcq","q":"إذا كان ص = ٢س − ١ و ص = س + ٤، فما قيمة س؟","options":["٥","٣","٤","٦"],"answer":0,"why":"٢س − ١ = س + ٤ ← س = ٥."},{"type":"essay","q":"اشترى أحمد ٣ تفاحات وبرتقالتين بـ ١٫٦ ريال، واشترى سالم تفاحتين وبرتقالتين بـ ١٫٢ ريال. أوجد سعر التفاحة والبرتقالة.","model":"بالطرح: تفاحة = ٠٫٤ ريال ← برتقالتان = ٠٫٤ ← برتقالة = ٠٫٢ ريال."},{"type":"tfr","q":"الزوج (٠، ٥) يحقق المعادلة ٣س + ص = ٥.","answer":true,"reasons":["لأن ٣(٠) + ٥ = ٥","لأنه يساوي ٨","لأنه يساوي ٠"],"reason":0},{"type":"essay","q":"حلّ: ٢س + ٥ص = ١٩ ، ٣س + ٢ص = ١٢.","model":"نضرب الأولى في ٢ والثانية في ٥: ٤س+١٠ص=٣٨ و ١٥س+١٠ص=٦٠ ← بالطرح ١١س = ٢٢ ← س = ٢، ص = ٣."}]}},
  {"id":"g9-math-1-u6-6","grade":"g9","subject":"math","term":1,"unit":6,"no":6,"title":"كتابة المعادلات لحلّ المسائل","summary":"شرح متحرك لتحويل المسائل اللفظية والهندسية والأعمار إلى معادلات وحلّها، ثم أنشطة بثلاثة مستويات.","page":"lesson-setting-up-equations.html","video":"","pdf":"","notes":["افرض الكمية المجهولة (الأصغر عادةً) بـ س.","كوّن المعادلة من العلاقة المعطاة ثم حلّها.","تحقّق من منطقية الإجابة واكتب وحدة القياس."],"exercises":["مجموع ثلاثة أعداد متتالية ٣٦، ما هي؟","مستطيل طوله يزيد عن عرضه ٤ سم ومحيطه ٢٨ سم، أوجد أبعاده."],"levels":{"easy":[{"type":"mcq","q":"ثلاثة أمثال عدد + ٥ = ٢٦. ما العدد؟","options":["٧","٦","٨","٩"],"answer":0,"why":"٣س = ٢١ ← س = ٧."},{"type":"mcq","q":"مجموع عددين متتاليين ٢٥. ما الأصغر؟","options":["١١","١٢","١٣","١٠"],"answer":1,"why":"٢س + ١ = ٢٥ ← س = ١٢."},{"type":"mcq","q":"زوايا مثلث س، س، ٢س. ما قيمة س؟","options":["٤٥°","٦٠°","٣٠°","٩٠°"],"answer":0,"why":"٤س = ١٨٠ ← س = ٤٥°."},{"type":"mcq","q":"عمر سارة ضعف عمر أخيها ومجموع عمريهما ٣٠ سنة. كم عمر أخيها؟","options":["١٠ سنوات","١٥ سنة","٢٠ سنة","٥ سنوات"],"answer":0,"why":"٣س = ٣٠ ← س = ١٠."}],"medium":[{"type":"mcq","q":"مربع محيطه (٤س + ١٢) يساوي ٣٦ سم. ما قيمة س؟","options":["٦","٩","٣","١٢"],"answer":0,"why":"٤س = ٢٤ ← س = ٦."},{"type":"tfr","q":"إذا كان أصغر ثلاثة أعداد متتالية هو س، فإن مجموعها يساوي ٣س + ٣.","answer":true,"reasons":["س + (س+١) + (س+٢) = ٣س + ٣","لأنه ٣س + ٢","لأنه ٣س"],"reason":0},{"type":"essay","q":"مجموع ثلاثة أعداد زوجية متتالية ٥٤. أوجد الأعداد الثلاثة.","model":"س + (س+٢) + (س+٤) = ٥٤ ← ٣س + ٦ = ٥٤ ← ٣س = ٤٨ ← س = ١٦ ← الأعداد: ١٦، ١٨، ٢٠."},{"type":"tfr","q":"مستطيل طوله (س + ٣) وعرضه س، يكون محيطه ٢س + ٣.","answer":false,"reasons":["المحيط = ٢(الطول + العرض) = ٢(٢س + ٣) = ٤س + ٦","لأن المحيط هو الطول + العرض فقط","لأنه س² + ٣س"],"reason":0},{"type":"mcq","q":"فكّر محمد في عدد، ضربه في ٤ ثم طرح ٧ فكان الناتج ٢١. ما العدد؟","options":["٧","٥","٨","٦"],"answer":0,"why":"٤س − ٧ = ٢١ ← ٤س = ٢٨ ← س = ٧."},{"type":"essay","q":"مثلث متطابق الضلعين محيطه ٢٦ سم، طول قاعدته ٨ سم. أوجد طول كل من ضلعيه المتساويين.","model":"٢س + ٨ = ٢٦ ← ٢س = ١٨ ← س = ٩ سم."},{"type":"tfr","q":"قُسّم مبلغ ٦٠ ريالًا بين شخصين بحيث يأخذ الأول ضعف الثاني، فيأخذ الأول ٤٠ ريالًا.","answer":true,"reasons":["٢س + س = ٦٠ ← س = ٢٠ ← الأول ٢×٢٠ = ٤٠ ريالًا","لأنه يأخذ ٣٠","لأنه يأخذ ٢٠"],"reason":0}],"hard":[{"type":"mcq","q":"عمر أب الآن ٤٠ سنة وعمر ابنه ١٠ سنوات. بعد كم سنة يصبح عمر الأب ضعف عمر ابنه؟","options":["٢٠ سنة","١٠ سنوات","١٥ سنة","٣٠ سنة"],"answer":0,"why":"٤٠ + س = ٢(١٠ + س) ← ٤٠ + س = ٢٠ + ٢س ← س = ٢٠."},{"type":"essay","q":"أطوال أضلاع مثلث هي (س + ٢)، (٢س − ١)، (س + ٥) ومحيطه ٣٠ سم. أوجد قيمة س.","model":"٤س + ٦ = ٣٠ ← ٤س = ٢٤ ← س = ٦ سم."},{"type":"tfr","q":"إذا كان مجموع عددين ١٨ وأحدهما يزيد عن الآخر بـ ٤، فإن العددين هما ١١ و ٧.","answer":true,"reasons":["١١ + ٧ = ١٨ و ١١ − ٧ = ٤","لأنهما ١٢ و ٦","لأنهما ١٠ و ٨"],"reason":0},{"type":"mcq","q":"عدد إذا أُضيف نصفه إلى ربعه كان الناتج ١٥. ما العدد؟","options":["٢٠","١٢","١٦","٢٤"],"answer":0,"why":"س/٢ + س/٤ = ١٥ ← ٣س/٤ = ١٥ ← س = ٢٠."},{"type":"essay","q":"شكل رباعي زواياه س، س + ٢٠، ٢س، ٢س − ٢٠. أوجد قيمة س.","model":"٦س = ٣٦٠° ← س = ٦٠°."},{"type":"tfr","q":"محيط خماسي منتظم طول ضلعه (س − ١) يساوي ٥س − ١.","answer":false,"reasons":["٥(س − ١) = ٥س − ٥ وليس ٥س − ١","لأن ٥×١ = ١","لأنه س − ٥"],"reason":0},{"type":"mcq","q":"اشترى علي ٤ أقلام بسعر س ريال للقلم ودفع ٥ ريالات، فكان الباقي ١٫٨ ريال. ما سعر القلم؟","options":["٠٫٨ ريال","١٫٢ ريال","٠٫٧ ريال","١ ريال"],"answer":0,"why":"٥ − ٤س = ١٫٨ ← ٤س = ٣٫٢ ← س = ٠٫٨ ريال."},{"type":"essay","q":"عددان فرديان متتاليان مجموعهما ٤٨. أوجد العددين.","model":"س + (س + ٢) = ٤٨ ← ٢س = ٤٦ ← س = ٢٣ ← العددان ٢٣ و ٢٥."},{"type":"tfr","q":"إذا كان س + ١٠ = ٣س فإن س = ٥.","answer":true,"reasons":["٢س = ١٠ ← س = ٥","لأن س = ١٠","لأن س = ٢٫٥"],"reason":0},{"type":"essay","q":"مستطيل طوله ٣ أمثال عرضه، ومحيطه ٤٨ سم. أوجد مساحته.","model":"العرض س والطول ٣س ← ٢(٤س) = ٤٨ ← ٨س = ٤٨ ← س = ٦ سم، الطول ١٨ سم ← المساحة = ٦ × ١٨ = ١٠٨ سم²."}]}},
  {"id":"g9-math-1-u6-7","grade":"g9","subject":"math","term":1,"unit":6,"no":7,"title":"المتباينات الخطية","summary":"شرح متحرك لرموز المتباينات وتمثيلها على خط الأعداد وحلّها وعكس الرمز مع السالب، ثم أنشطة بثلاثة مستويات.","page":"lesson-linear-inequalities.html","video":"","pdf":"","notes":["دائرة مفتوحة (○) مع (< ، >)، ومغلقة (●) مع (≤ ، ≥).","تُحلّ المتباينة كالمعادلة، لكن عند الضرب أو القسمة في عدد سالب نعكس رمز المتباينة فورًا."],"exercises":["حلّ: ٣س − ٤ ≤ ١١ ، −٢س > ١٠.","اذكر الأعداد الصحيحة في: −٢ < س ≤ ٣."],"levels":{"easy":[{"type":"mcq","q":"ما حلّ: ٢س + ٣ > ١١ ؟","options":["س > ٤","س < ٤","س > ٧","س ≥ ٤"],"answer":0,"why":"٢س > ٨ ← س > ٤."},{"type":"mcq","q":"ما حلّ: −٣س ≤ ١٢ ؟","options":["س ≤ −٤","س ≥ −٤","س ≥ ٤","س ≤ ٤"],"answer":1,"why":"القسمة على −٣ تعكس الرمز ← س ≥ −٤."},{"type":"mcq","q":"الأعداد الصحيحة في ١ ≤ س < ٤ هي:","options":["١، ٢، ٣","٢، ٣","١، ٢، ٣، ٤","٢، ٣، ٤"],"answer":0,"why":"١ داخل و ٤ غير داخل."},{"type":"mcq","q":"لتمثيل س ≥ ٥ على خط الأعداد نضع عند ٥:","options":["دائرة مفتوحة وسهمًا لليمين","دائرة مغلقة وسهمًا لليمين","دائرة مغلقة وسهمًا لليسار","دائرة مفتوحة وسهمًا لليسار"],"answer":1,"why":"وجود يساوي = مغلقة، أكبر = يمين."}],"medium":[{"type":"mcq","q":"ما حلّ: ٥س − ٢ ≤ ٣س + ٨ ؟","options":["س ≤ ٥","س ≥ ٥","س ≤ ٣","س < ٥"],"answer":0,"why":"٢س ≤ ١٠ ← س ≤ ٥."},{"type":"tfr","q":"عند طرح عدد سالب من طرفي المتباينة نعكس اتجاه رمز المتباينة.","answer":false,"reasons":["الجمع والطرح لا يعكسان الرمز أبدًا؛ الضرب والقسمة في عدد سالب فقط يعكسانه","لأن كل عملية بسالب تعكس الرمز","لأن الطرح يعكس الرمز"],"reason":0},{"type":"essay","q":"حلّ المتباينة: ٤(س − ١) > ٢س + ٦.","model":"٤س − ٤ > ٢س + ٦ ← ٢س > ١٠ ← س > ٥."},{"type":"tfr","q":"العدد −٣ يحقق المتباينة س < −٢.","answer":true,"reasons":["لأن −٣ أصغر من −٢ (يقع يساره على خط الأعداد)","لأن −٣ أكبر من −٢","لأنه يساويه"],"reason":0},{"type":"mcq","q":"ما أكبر عدد صحيح يحقق المتباينة ٢س < ١١ ؟","options":["٥","٦","٤","٥٫٥"],"answer":0,"why":"س < ٥٫٥ ← أكبر عدد صحيح هو ٥."},{"type":"essay","q":"اذكر الأعداد الصحيحة التي تحقق: −٣ ≤ س < ٢.","model":"−٣ ، −٢ ، −١ ، ٠ ، ١."},{"type":"tfr","q":"حلّ المتباينة −س > ٥ هو س < −٥.","answer":true,"reasons":["بالضرب أو القسمة على −١ نعكس الرمز ← س < −٥","لأنه س > −٥","لأنه س < ٥"],"reason":0}],"hard":[{"type":"mcq","q":"ما حلّ المتباينة المركّبة: ٣ ≤ ٢س − ١ < ٩ ؟","options":["٢ ≤ س < ٥","١ ≤ س < ٤","٢ < س ≤ ٥","٤ ≤ س < ١٠"],"answer":0,"why":"نجمع ١: ٤ ≤ ٢س < ١٠ ← نقسم على ٢: ٢ ≤ س < ٥."},{"type":"essay","q":"حلّ المتباينة: ١٠ − ٣س ≥ ١.","model":"−٣س ≥ −٩ ← نقسم على −٣ ونعكس: س ≤ ٣."},{"type":"tfr","q":"إذا كان س > ٣ فإن −٢س > −٦.","answer":false,"reasons":["الضرب في −٢ يعكس الرمز فتصبح −٢س < −٦","لأن الرمز لا يتغير","لأنها تساوي ٦"],"reason":0},{"type":"mcq","q":"ما أصغر عدد صحيح يحقق ٣س − ٢ > ١٠ ؟","options":["٥","٤","٣","٦"],"answer":0,"why":"٣س > ١٢ ← س > ٤ ← أصغر عدد صحيح هو ٥."},{"type":"essay","q":"مع سالم ٢٠ ريالًا، يريد شراء أقلام سعر الواحد ١٫٥ ريال ودفتر بـ ٢ ريال. ما أكبر عدد من الأقلام يمكنه شراؤه؟","model":"١٫٥س + ٢ ≤ ٢٠ ← ١٫٥س ≤ ١٨ ← س ≤ ١٢ قلمًا."},{"type":"tfr","q":"المتباينة س/٢ − ١ < ٣ حلّها س < ٨.","answer":true,"reasons":["س/٢ < ٤ ← س < ٨","لأنها س < ٤","لأنها س < ٢"],"reason":0},{"type":"mcq","q":"أيُّ عدد لا يحقق المتباينة −٢ < س ≤ ٣ ؟","options":["−٢","−١","٠","٣"],"answer":0,"why":"−٢ غير داخل لأن الرمز (<) بلا يساوي."},{"type":"essay","q":"حلّ: ٥ − ٢(س + ١) ≤ ٩.","model":"٥ − ٢س − ٢ ≤ ٩ ← ٣ − ٢س ≤ ٩ ← −٢س ≤ ٦ ← س ≥ −٣."},{"type":"tfr","q":"يمكن تمثيل المتباينة س ≠ ٤ على خط الأعداد بنقطة واحدة.","answer":false,"reasons":["س ≠ ٤ تشمل جميع الأعداد الحقيقية ما عدا ٤","لأنها تساوي ٤","لأنها لا تُرسم"],"reason":0},{"type":"essay","q":"أوجد الأعداد الصحيحة المشتركة بين س > −١ و ٢س ≤ ٦.","model":"س > −١ و س ≤ ٣ ← الأعداد الصحيحة: ٠، ١، ٢، ٣."}]}},
  {"id":"g9-math-1-u7-1","grade":"g9","subject":"math","term":1,"unit":7,"no":1,"title":"رسم المستقيمات","summary":"شرح متحرك لمعادلة المستقيم ص = م س + ج وحساب الميل والتوازي والتعامد، ثم أنشطة بثلاثة مستويات.","page":"lesson-drawing-straight-lines.html","video":"","pdf":"","notes":["س = عدد (مستقيم رأسي)، ص = عدد (مستقيم أفقي).","ص = م س + ج حيث م الميل و ج المقطع الصادي.","الميل م = (ص₂ − ص₁) ÷ (س₂ − س₁).","المتوازيان لهما نفس الميل (م₁ = م₂)، والمتعامدان حاصل ضرب ميليهما −١."],"exercises":["أوجد ميل المستقيم المار بـ (١، ٢) و (٤، ٨).","اكتب معادلة مستقيم يوازي ص = ٢س + ١ ويمر بـ (٠، −٣)."],"levels":{"easy":[{"type":"mcq","q":"في ص = ٤س − ٥، ما الميل والمقطع الصادي؟","options":["م = ٤ ، ج = −٥","م = −٥ ، ج = ٤","م = ٤ ، ج = ٥","م = −٤ ، ج = ٥"],"answer":0,"why":"معامل س هو الميل والحد الثابت هو المقطع."},{"type":"mcq","q":"ما ميل المستقيم المار بـ (٢، ٣) و (٥، ١٢)؟","options":["٢","٣","٤","٩"],"answer":1,"why":"(١٢−٣)÷(٥−٢) = ٩÷٣ = ٣."},{"type":"mcq","q":"أيُّ مستقيم يوازي ص = ٣س + ٢ ؟","options":["ص = ٣س − ٧","ص = −٣س + ٢","ص = ٢س + ٣","ص = ١/٣ س + ٢"],"answer":0,"why":"المتوازيان لهما نفس الميل ٣."},{"type":"mcq","q":"ما ميل العمودي على مستقيم ميله ٢/٣ ؟","options":["٣/٢","−٣/٢","−٢/٣","٢/٣"],"answer":1,"why":"نقلب الكسر ونعكس الإشارة ← −٣/٢."}],"medium":[{"type":"mcq","q":"المستقيم س = ٤ هو مستقيم:","options":["أفقي","رأسي","مائل ميله ٤","يمر بالأصل"],"answer":1,"why":"س = عدد يكون رأسيًّا دائمًا."},{"type":"tfr","q":"ميل المستقيم الأفقي ص = ٥ يساوي صفرًا.","answer":true,"reasons":["لأن فرق الصادات يساوي صفرًا","لأنه غير معرّف","لأنه يساوي ٥"],"reason":0},{"type":"essay","q":"أوجد معادلة المستقيم الذي ميله ٢ ويقطع محور الصادات عند (٠، ٥).","model":"ص = ٢س + ٥."},{"type":"tfr","q":"النقطة (٢، ٧) تقع على المستقيم ص = ٣س + ١.","answer":true,"reasons":["نعوّض س = ٢: ص = ٣(٢) + ١ = ٧ ✓","لأن ٣(٢)+١ = ٦","لأنها لا تحقق المعادلة"],"reason":0},{"type":"mcq","q":"ما المقطع الصادي للمستقيم ٢ص = ٦س + ٨ ؟","options":["٨","٤","٣","٦"],"answer":1,"why":"نقسم على ٢: ص = ٣س + ٤ ← ج = ٤."},{"type":"essay","q":"أوجد ميل المستقيم المار بـ (٣، ٥) و (٥، ١).","model":"م = (١ − ٥) ÷ (٥ − ٣) = −٤ ÷ ٢ = −٢."},{"type":"tfr","q":"المستقيمان ص = ٢س + ١ و ص = −٢س + ١ متعامدان.","answer":false,"reasons":["حاصل ضرب ميليهما ٢ × (−٢) = −٤ ≠ −١؛ العمودي على ٢ ميله −١/٢","لأن الإشارتين مختلفتان","لأنهما متوازيان"],"reason":0}],"hard":[{"type":"mcq","q":"ما معادلة المستقيم المار بـ (٢، ٥) وميله ٣؟","options":["ص = ٣س − ١","ص = ٣س + ٥","ص = ٣س + ١","ص = ٢س + ١"],"answer":0,"why":"٥ = ٣(٢) + ج ← ج = −١ ← ص = ٣س − ١."},{"type":"essay","q":"أوجد معادلة المستقيم العمودي على ص = ١/٢ س + ٣ ويمر بالنقطة (٠، ٤).","model":"ميل العمودي = −٢، والمقطع ج = ٤ ← ص = −٢س + ٤."},{"type":"tfr","q":"المستقيم ص = −س يمر بنقطة الأصل وميله −١.","answer":true,"reasons":["ج = ٠ فيمر بـ (٠، ٠)، ومعامل س هو −١","لأن ميله +١","لأنه أفقي"],"reason":0},{"type":"mcq","q":"أين يقطع المستقيم ص = ٢س − ٦ محور السينات؟","options":["(٣، ٠)","(٠، −٦)","(−٣، ٠)","(٦، ٠)"],"answer":0,"why":"نضع ص = ٠: ٢س − ٦ = ٠ ← س = ٣."},{"type":"essay","q":"أوجد معادلة المستقيم المار بالنقطتين (١، ٣) و (٣، ٧).","model":"م = (٧−٣)÷(٣−١) = ٢. ثم ٣ = ٢(١) + ج ← ج = ١ ← ص = ٢س + ١."},{"type":"tfr","q":"ميل المستقيم الرأسي س = ٢ غير معرّف.","answer":true,"reasons":["لأن فرق السينات يساوي صفرًا ولا تجوز القسمة على صفر","لأنه يساوي صفرًا","لأنه يساوي ٢"],"reason":0},{"type":"mcq","q":"إذا كان المستقيمان ص = ك س + ١ و ٢ص = ٨س − ٣ متوازيين، فما قيمة ك؟","options":["٤","٨","٢","−٤"],"answer":0,"why":"الثاني: ص = ٤س − ١٫٥ ← ك = ٤."},{"type":"essay","q":"هل المستقيمان ص = ٣س + ٢ و س + ٣ص = ٦ متعامدان؟ فسّر.","model":"ميل الأول ٣. الثاني: ص = −١/٣ س + ٢، ميله −١/٣. وبما أن ٣ × (−١/٣) = −١ ← نعم متعامدان!"},{"type":"tfr","q":"في المعادلة ٢س + ص = ٦، ميل المستقيم هو ٢.","answer":false,"reasons":["نكتبها ص = −٢س + ٦ ← الميل هو −٢ وليس +٢","لأن معامل س هو ٢","لأن الميل ٦"],"reason":0},{"type":"essay","q":"أوجد نقطة تقاطع المستقيمين ص = ٢س + ١ و ص = ٧.","model":"٢س + ١ = ٧ ← س = ٣ ← النقطة (٣، ٧)."}]}},
  {"id":"g9-math-1-u7-2","grade":"g9","subject":"math","term":1,"unit":7,"no":2,"title":"القطعة المستقيمة","summary":"شرح متحرك لقانون نقطة المنتصف وقانون طول القطعة المستقيمة (المسافة)، ثم أنشطة بثلاثة مستويات.","page":"lesson-line-segments.html","video":"","pdf":"","notes":["نقطة المنتصف = ( (س₁+س₂)÷٢ ، (ص₁+ص₂)÷٢ ).","طول القطعة المستقيمة = √[ (س₂−س₁)² + (ص₂−ص₁)² ]."],"exercises":["أوجد منتصف وطول القطعة بين (١، ٢) و (٤، ٦).","أوجد منتصف القطعة بين (−٤، ٦) و (٢، −٢)."],"levels":{"easy":[{"type":"mcq","q":"ما منتصف القطعة بين (٢، ٤) و (٨، ١٠)؟","options":["(٥، ٧)","(٦، ٦)","(١٠، ١٤)","(٣، ٣)"],"answer":0,"why":"(٢+٨)÷٢ = ٥ و (٤+١٠)÷٢ = ٧."},{"type":"mcq","q":"ما طول القطعة بين (٠، ٠) و (٣، ٤)؟","options":["٥","٧","١٢","٢٥"],"answer":0,"why":"√(٩ + ١٦) = ٥."},{"type":"mcq","q":"ما منتصف القطعة بين (−٦، ٢) و (٢، ٨)؟","options":["(−٢، ٥)","(−٤، ٥)","(٢، ٥)","(−٢، ١٠)"],"answer":0,"why":"(−٦+٢)÷٢ = −٢ و (٢+٨)÷٢ = ٥."},{"type":"mcq","q":"ما طول القطعة بين (٢، ١) و (٨، ٩)؟","options":["١٠","١٤","٨","٦"],"answer":0,"why":"√(٦² + ٨²) = √١٠٠ = ١٠."}],"medium":[{"type":"mcq","q":"ما طول القطعة بين (−١، ٢) و (٣، ٥)؟","options":["٥","٧","٢٥","٤"],"answer":0,"why":"فرق س = ٤، فرق ص = ٣ ← √(١٦+٩) = ٥."},{"type":"tfr","q":"منتصف القطعة بين (أ، ب) و (−أ، −ب) هو نقطة الأصل (٠، ٠).","answer":true,"reasons":["لأن (أ−أ)÷٢ = ٠ و (ب−ب)÷٢ = ٠","لأنه (أ، ب)","لأنه (١، ١)"],"reason":0},{"type":"essay","q":"أوجد طول القطعة بين (٢، ٥) و (٢، −٣).","model":"القطعة رأسية: الطول = |٥ − (−٣)| = ٨ وحدات."},{"type":"tfr","q":"طول القطعة المستقيمة يمكن أن يكون سالبًا.","answer":false,"reasons":["الطول والمسافة دائمًا قيَم غير سالبة (موجبة)","لأن الإحداثيات قد تكون سالبة","لأن الطرح يعطي سالبًا"],"reason":0},{"type":"mcq","q":"إذا كانت م(٤، ٥) منتصف أ ب حيث أ(٢، ٣)، فما إحداثيا ب؟","options":["(٦، ٧)","(٣، ٤)","(٨، ١٠)","(٢، ٢)"],"answer":0,"why":"(٢+س)÷٢ = ٤ ← س = ٦، و (٣+ص)÷٢ = ٥ ← ص = ٧."},{"type":"essay","q":"أوجد منتصف وطول القطعة الواصلة بين (٠، ٢) و (٦، ١٠).","model":"المنتصف = (٣، ٦). الطول = √(٦² + ٨²) = ١٠ وحدات."},{"type":"tfr","q":"قانون طول القطعة المستقيمة مشتق من نظرية فيثاغورس.","answer":true,"reasons":["لأن القطعة تمثّل وتر مثلث قائم ضلعاه فرق السينات وفرق الصادات","لأنه من مساحة المثلث","لأنه من قانون الميل"],"reason":0}],"hard":[{"type":"mcq","q":"دائرة قطرها أ ب حيث أ(−٢، ١) و ب(٤، ٩). ما إحداثيا مركزها؟","options":["(١، ٥)","(٢، ١٠)","(٣، ٤)","(−١، ٥)"],"answer":0,"why":"المركز هو منتصف القطر: (١، ٥)."},{"type":"essay","q":"في السؤال السابق، أوجد طول نصف قطر الدائرة.","model":"القطر = √(٦² + ٨²) = ١٠ ← نصف القطر = ١٠ ÷ ٢ = ٥ وحدات."},{"type":"tfr","q":"طول القطعة بين (١، ١) و (٤، ٥) يساوي طول القطعة بين (٠، ٠) و (٣، ٤).","answer":true,"reasons":["كلاهما له فرق س = ٣ وفرق ص = ٤ فيساوي ٥ وحدات","لأن النقاط مختلفة فالأطوال مختلفة","لأن الأول أطول"],"reason":0},{"type":"mcq","q":"ما طول القطعة بين (−٣، −٢) و (٩، ٣)؟","options":["١٣","١٢","١٧","١٥"],"answer":0,"why":"فرق س = ١٢، فرق ص = ٥ ← √(١٤٤+٢٥) = √١٦٩ = ١٣."},{"type":"essay","q":"أثبت أن المثلث الذي رؤوسه أ(٠، ٠)، ب(٤، ٠)، ج(٢، ٣) متطابق الضلعين.","model":"أ ج = √(٢² + ٣²) = √١٣، و ب ج = √((−٢)² + ٣²) = √١٣ ← أ ج = ب ج فهو متطابق الضلعين."},{"type":"tfr","q":"إذا كان منتصف أ(١، ٢) و ب(س، ٦) هو (٥، ٤) فإن س = ٩.","answer":true,"reasons":["(١ + س) ÷ ٢ = ٥ ← ١ + س = ١٠ ← س = ٩","لأن س = ٤","لأن س = ٦"],"reason":0},{"type":"mcq","q":"ما المسافة بين النقطتين (٥، −٢) و (٥، ٦)؟","options":["٨","٤","١٠","٦"],"answer":0,"why":"|٦ − (−٢)| = ٨."},{"type":"essay","q":"أوجد معادلة المنصّف العمودي للقطعة بين أ(٠، ٠) و ب(٤، ٤).","model":"المنتصف = (٢، ٢). ميل أ ب = ١ ← ميل العمودي = −١ ← ص = −س + ٤."},{"type":"tfr","q":"تقع النقطة (٣، ٥) على دائرة مركزها (٠، ١) ونصف قطرها ٥.","answer":true,"reasons":["المسافة من المركز = √(٣² + ٤²) = ٥ = نصف القطر","لأن المسافة ٦","لأن المسافة ٤"],"reason":0},{"type":"essay","q":"إذا كانت م(−١، ٣) منتصف القطعة أ ب حيث أ(٣، −١)، فأوجد إحداثيي ب.","model":"(٣+س)÷٢ = −١ ← س = −٥. (−١+ص)÷٢ = ٣ ← ص = ٧. إذن ب(−٥، ٧)."}]}},
  {"id":"g9-math-1-u8-1","grade":"g9","subject":"math","term":1,"unit":8,"no":1,"title":"التماثل في الأشكال ثنائية الأبعاد","summary":"شرح متحرك لخطوط التماثل ورتبة التماثل الدوراني في الأشكال والمضلّعات، ثم أنشطة بثلاثة مستويات.","page":"lesson-2d-symmetry.html","video":"","pdf":"","notes":["خط التماثل يطوي الشكل إلى نصفين متطابقين.","رتبة التماثل الدوراني هي عدد مرات انطباق الشكل على نفسه في دورة ٣٦٠°.","في المضلّع المنتظم: عدد خطوط التماثل = الرتبة الدورانية = عدد الأضلاع (ن)."],"exercises":["اذكر عدد خطوط التماثل والرتبة الدورانية للمربع والمستطيل ومتوازي الأضلاع."],"levels":{"easy":[{"type":"mcq","q":"كم عدد خطوط التماثل في المستطيل؟","options":["٢","٤","٠","١"],"answer":0,"why":"أفقي ورأسي فقط."},{"type":"mcq","q":"ما رتبة التماثل الدوراني لمتوازي الأضلاع؟","options":["٠","١","٢","٤"],"answer":2,"why":"ينطبق مرتين (عند ١٨٠° و ٣٦٠°)."},{"type":"mcq","q":"كم عدد خطوط التماثل في الخماسي المنتظم؟","options":["٣","٥","١٠","١"],"answer":1,"why":"يساوي عدد أضلاعه = ٥."},{"type":"mcq","q":"أيُّ شكل له عدد لا نهائي من خطوط التماثل؟","options":["المربع","السداسي المنتظم","الدائرة","المعيّن"],"answer":2,"why":"الدائرة."}],"medium":[{"type":"mcq","q":"كم عدد خطوط التماثل في المثلث متطابق الضلعين؟","options":["١","٢","٣","٠"],"answer":0,"why":"خط واحد يمر بالرأس ومنتصف القاعدة."},{"type":"tfr","q":"قطر المستطيل يُعدّ خط تماثل له.","answer":false,"reasons":["عند طي المستطيل حول قطره لا ينطبق الرأسان المتقابلان (إلا في المربع)","لأنه يقسمه لمثلثين متطابقين","لأنه له ٤ خطوط تماثل"],"reason":0},{"type":"essay","q":"قارن بين المعيّن ومتوازي الأضلاع من حيث خطوط التماثل والرتبة الدورانية.","model":"المعيّن: ٢ خط تماثل ورتبة دورانية ٢. متوازي الأضلاع: ٠ خط تماثل ورتبة دورانية ٢."},{"type":"tfr","q":"أقل رتبة تماثل دوراني لأي شكل هندسي هي ١.","answer":true,"reasons":["لأن أي شكل ينطبق على نفسه مرة واحدة على الأقل بعد دوران ٣٦٠°","لأنها صفر","لأنها ٢"],"reason":0},{"type":"mcq","q":"ما رتبة التماثل الدوراني للطائرة الورقية؟","options":["١","٢","٤","٠"],"answer":0,"why":"لا تنطبق إلا بعد ٣٦٠° كاملة ← رتبة ١."},{"type":"essay","q":"اذكر شكلًا رباعيًّا له خط تماثل واحد ورتبة دورانية ١.","model":"الطائرة الورقية أو شبه المنحرف متطابق الساقين."},{"type":"tfr","q":"للمثلث مختلف الأضلاع ٠ خطوط تماثل ورتبة دورانية ١.","answer":true,"reasons":["لأن أضلاعه وزواياه مختلفة جميعها","لأن له خط تماثل واحد","لأن رتبته ٣"],"reason":0}],"hard":[{"type":"mcq","q":"شكل له خطّان للتماثل ورتبة تماثل دوراني ٢ وجميع أضلاعه متساوية، ما هو؟","options":["المعيّن","المستطيل","المربع","الطائرة الورقية"],"answer":0,"why":"المعيّن."},{"type":"essay","q":"اذكر حرفًا إنجليزيًا له تماثل دوراني من الرتبة ٢ وليس له أي خط تماثل.","model":"الحرف N أو S أو Z."},{"type":"tfr","q":"المضلّع الثماني المنتظم له ٨ خطوط تماثل ورتبة دورانية ٨.","answer":true,"reasons":["في أي مضلّع منتظم، الخطوط = الرتبة = ن = ٨","لأن له ٤ خطوط فقط","لأن رتبته ٤"],"reason":0},{"type":"mcq","q":"ما أصغر زاوية دوران تجعل السداسي المنتظم ينطبق على نفسه؟","options":["٦٠°","٩٠°","١٢٠°","٤٥°"],"answer":0,"why":"٣٦٠° ÷ ٦ = ٦٠°."},{"type":"essay","q":"هل يمكن لشكل أن يكون له تماثل دوراني من الرتبة ٢ دون أن يكون له أي خط تماثل؟ أعطِ مثالًا.","model":"نعم، متوازي الأضلاع له ٠ خطوط تماثل ورتبة دورانية ٢."},{"type":"tfr","q":"للحرف H خطّا تماثل ورتبة تماثل دوراني ٢.","answer":true,"reasons":["له خط أفقي وخط رأسي وينطبق عند ١٨٠° و ٣٦٠°","له خط واحد فقط","رتبته ٤"],"reason":0},{"type":"mcq","q":"كم خط تماثل لشبه المنحرف متطابق الساقين؟","options":["١","٢","٠","٤"],"answer":0,"why":"خط واحد رأسي في المنتصف."},{"type":"essay","q":"ما أصغر زاوية دوران ينطبق فيها الخماسي المنتظم على نفسه؟","model":"٣٦٠° ÷ ٥ = ٧٢°."},{"type":"tfr","q":"للمربع ٤ خطوط تماثل ورتبة دورانية ٢.","answer":false,"reasons":["رتبته الدورانية ٤ وليس ٢","خطوطه ٢ فقط","رتبته ١"],"reason":0},{"type":"essay","q":"صنّف الأشكال التالية حسب عدد خطوط التماثل: مربع، مستطيل، مثلث متطابق الأضلاع، متوازي أضلاع.","model":"مربع (٤)، مثلث متطابق الأضلاع (٣)، مستطيل (٢)، متوازي أضلاع (٠)."}]}},
  {"id":"g9-math-1-u8-2","grade":"g9","subject":"math","term":1,"unit":8,"no":2,"title":"التماثل في الأشكال ثلاثية الأبعاد","summary":"شرح متحرك لمستويات التماثل ومحاور الدوران في المجسّمات، ثم أنشطة بثلاثة مستويات.","page":"lesson-3d-symmetry.html","video":"","pdf":"","notes":["مستوى التماثل يقسم المجسّم إلى نصفين متطابقين كالمرآة.","متوازي المستطيلات (٣ مستويات)، المكعب (٩ مستويات)، الهرم الرباعي القائم (٤ مستويات).","الأسطوانة والمخروط والكرة لها عدد لا نهائي من مستويات التماثل."],"exercises":["قارن بين مستويات التماثل في المكعب ومتوازي المستطيلات."],"levels":{"easy":[{"type":"mcq","q":"كم عدد مستويات التماثل في المكعب؟","options":["٣","٦","٩","١٢"],"answer":2,"why":"٣ توازي الأوجه + ٦ قطرية = ٩."},{"type":"mcq","q":"كم عدد مستويات التماثل في متوازي مستطيلات مختلف الأبعاد؟","options":["٣","٦","٩","١"],"answer":0,"why":"٣ مستويات فقط."},{"type":"mcq","q":"ما رتبة التماثل الدوراني للهرم الرباعي القائم حول محوره الرأسي؟","options":["٢","٤","٨","١"],"answer":1,"why":"القاعدة مربعة ← رتبة ٤."},{"type":"mcq","q":"كم عدد مستويات التماثل في الكرة؟","options":["٤","٩","عدد لا نهائي","١"],"answer":2,"why":"أي مستوى يمر بالمركز."}],"medium":[{"type":"mcq","q":"كم عدد مستويات التماثل في الهرم الرباعي القائم (قاعدته مربعة)؟","options":["٤","٢","٥","٨"],"answer":0,"why":"٤ مستويات تمر برأس الهرم."},{"type":"tfr","q":"للمنشور الثلاثي المنتظم ٤ مستويات تماثل.","answer":true,"reasons":["٣ مستويات طولية + مستوى واحد في المنتصف العرضي = ٤","له ٣ فقط","له ٦"],"reason":0},{"type":"essay","q":"اذكر مجسّمين لهما عدد لا نهائي من مستويات التماثل.","model":"الكرة، والأسطوانة، والمخروط الدائري القائم."},{"type":"tfr","q":"متوازي المستطيلات له نفس عدد مستويات التماثل في المكعب.","answer":false,"reasons":["متوازي المستطيلات له ٣ (أو ٥ إذا كانت قاعدته مربعة)، بينما المكعب له ٩","لأن كليهما له ٩","لأن كليهما له ٦"],"reason":0},{"type":"mcq","q":"ما رتبة التماثل الدوراني للمكعب حول المحور المار بمركزي وجهين متقابلين؟","options":["٢","٣","٤","٦"],"answer":2,"why":"الوجه مربع ← رتبة ٤."},{"type":"essay","q":"كم مستوى تماثل لمتوازي مستطيلات قاعدته مربعة وارتفاعه مختلف عن ضلع القاعدة؟","model":"٥ مستويات (٤ رأسية للقاعدة المربعة + ١ أفقي في المنتصف)."},{"type":"tfr","q":"للمخروط الدائري القائم محور تماثل دوراني واحد فقط.","answer":true,"reasons":["وهو المحور الواصل بين رأسه ومركز قاعدته الدائرية","له محوران","ليس له محور"],"reason":0}],"hard":[{"type":"mcq","q":"كم عدد مستويات التماثل في منشور قاعدته سداسي منتظم؟","options":["٧","٦","١٢","٨"],"answer":0,"why":"٦ مستويات طولية + ١ أفقي في المنتصف = ٧."},{"type":"essay","q":"اشرح لماذا يحتوي المكعب على ٩ مستويات تماثل.","model":"٣ مستويات تمر بمنتصفات الأحرف وتوازي الأوجه، و ٦ مستويات قطرية تمر بكل زوج من الأحرف المتقابلة."},{"type":"tfr","q":"رتبة التماثل الدوراني للمكعب حول القطر الواصل بين رأسين متقابلين هي ٣.","answer":true,"reasons":["لأن ٣ أوجه تلتقي عند كل رأس فينطبق ٣ مرات في الدورة","لأنها ٤","لأنها ٢"],"reason":0},{"type":"mcq","q":"كم عدد مستويات التماثل في هرم قاعدته مستطيل (غير مربع)؟","options":["٢","٤","١","٣"],"answer":0,"why":"مستويان فقط يمران بالرأس ومنتصفات أضلاع المستطيل."},{"type":"essay","q":"كم مستوى تماثل للأسطوانة الدائرية القائمة؟ وهل لها مستوى تماثل أفقي؟","model":"لها عدد لا نهائي من المستويات الرأسية المارة بالمحور + مستوى واحد أفقي في منتصف ارتفاعها (الإجمالي عدد لا نهائي)."},{"type":"tfr","q":"الهرم الثلاثي المنتظم (رباعي الأوجه) له ٦ مستويات تماثل.","answer":true,"reasons":["كل مستوى يمر بحرف ومنتصف الحرف المقابل، وبما أن له ٦ أحرف فله ٦ مستويات","له ٣ فقط","له ٤ فقط"],"reason":0},{"type":"mcq","q":"ما رتبة التماثل الدوراني لمنشور خماسي منتظم حول محوره الطولي؟","options":["٥","١٠","٢","١"],"answer":0,"why":"القاعدة خماسي منتظم ← رتبة ٥."},{"type":"essay","q":"ما الفرق بين خط التماثل ومستوى التماثل؟","model":"خط التماثل يُستخدم للأشكال ثنائية الأبعاد (المسطّحة)، أما مستوى التماثل فيُستخدم للمجسّمات ثلاثية الأبعاد."},{"type":"tfr","q":"للمنشور السداسي المنتظم ٦ محاور تماثل دوراني فقط.","answer":false,"reasons":["له محور رئيس رتبته ٦ بالإضافة إلى ٦ محاور عرضية رتبة كل منها ٢","له محور واحد فقط","ليس له محاور"],"reason":0},{"type":"essay","q":"اذكر عدد مستويات التماثل لكل من: مكعب، هرم رباعي قائم، متوازي مستطيلات (٢×٣×٥).","model":"مكعب (٩)، هرم رباعي قائم (٤)، متوازي مستطيلات (٣)."}]}},
  {"id":"g9-math-1-u8-3","grade":"g9","subject":"math","term":1,"unit":8,"no":3,"title":"التحويلات الهندسية","summary":"شرح متحرك للانعكاس والإزاحة والدوران والتكبير ووصفها الكامل، ثم أنشطة بثلاثة مستويات.","page":"lesson-transformations.html","video":"","pdf":"","notes":["الانعكاس يُوصف بمعادلة خط المرآة.","الإزاحة تُوصف بمتجه (أفقي، رأسي).","الدوران يُوصف بـ: الزاوية + الاتجاه + مركز الدوران.","التكبير يُوصف بـ: معامل التكبير (ك) + مركز التكبير."],"exercises":["أوجد صورة (٢، ٥) بإزاحة (٤، −٢).","أوجد صورة (٤، ٣) بالانعكاس في محور س."],"levels":{"easy":[{"type":"mcq","q":"صورة (٢، ٥) بإزاحة ٤ يمينًا و ٢ لأسفل هي:","options":["(٦، ٣)","(−٢، ٧)","(٦، ٧)","(−٢، ٣)"],"answer":0,"why":"(٢+٤ ، ٥−٢) = (٦، ٣)."},{"type":"mcq","q":"صورة (٤، ٣) بالانعكاس في محور السينات (ص = ٠) هي:","options":["(−٤، ٣)","(٤، −٣)","(−٤، −٣)","(٣، ٤)"],"answer":1,"why":"نعكس إشارة ص ← (٤، −٣)."},{"type":"mcq","q":"مثلث قاعدته ٤ سم كُبّر بمعامل ٣. كم طول القاعدة في الصورة؟","options":["٧ سم","١٢ سم","١٫٣ سم","٣٦ سم"],"answer":1,"why":"٤ × ٣ = ١٢ سم."},{"type":"mcq","q":"لوصف الدوران كاملًا نذكر:","options":["الزاوية فقط","الزاوية والاتجاه","الزاوية والاتجاه والمركز","المتجه"],"answer":2,"why":"٣ معلومات أساسية."}],"medium":[{"type":"mcq","q":"صورة (٣، −٢) بدوران ١٨٠° حول نقطة الأصل (٠، ٠) هي:","options":["(−٣، ٢)","(−٣، −٢)","(٣، ٢)","(−٢، ٣)"],"answer":0,"why":"دوران ١٨٠° يعكس الإشارتين ← (−٣، ٢)."},{"type":"tfr","q":"التكبير يحافظ على أطوال أضلاع الشكل الأصلي.","answer":false,"reasons":["التكبير يغيّر الأطوال بمعامل ك (تشابه)، بينما الانعكاس والإزاحة والدوران تحافظ عليها (تطابق)","لأن الصورة مطابقة للأصل","لأن الزوايا تتغير"],"reason":0},{"type":"essay","q":"أوجد صورة النقطة (١، ٤) بالانعكاس في المستقيم س = ٣.","model":"تبعد عن س = ٣ بمقدار وحدتين يسارًا ← صورتها تبعد وحدتين يمينًا عند (٥، ٤)."},{"type":"tfr","q":"في دوران ١٨٠° لا يُشترط ذكر الاتجاه (مع أم عكس عقارب الساعة).","answer":true,"reasons":["لأن الدوران ١٨٠° في أي اتجاه يعطي الصورة نفسها تمامًا","لأنه لا يدور","لأنه انعكاس"],"reason":0},{"type":"mcq","q":"إذا كان معامل التكبير ك = ١/٢، فإن الشكل:","options":["يكبر للضعف","يصغر للنصف","لا يتغير","ينعكس"],"answer":1,"why":"معامل بين ٠ و ١ يعني تصغيرًا."},{"type":"essay","q":"اذكر عناصر الوصف الكامل لكل من: الإزاحة، والتكبير.","model":"الإزاحة: متجه الإزاحة. التكبير: معامل التكبير ومركز التكبير."},{"type":"tfr","q":"صورة (٢، ٥) بالانعكاس في المستقيم ص = س هي (٥، ٢).","answer":true,"reasons":["لأن الانعكاس في ص = س يبدّل الإحداثيين س و ص","لأنها (−٢، −٥)","لأنها (٢، −٥)"],"reason":0}],"hard":[{"type":"mcq","q":"صورة (٢، ٣) بدوران ٩٠° عكس عقارب الساعة حول (٠، ٠) هي:","options":["(−٣، ٢)","(٣، −٢)","(−٢، −٣)","(٣، ٢)"],"answer":0,"why":"(س، ص) ← (−ص، س) = (−٣، ٢)."},{"type":"essay","q":"مثلث مساحته ٦ سم² كُبّر بمعامل تكبير ٣. ما مساحة صورته؟","model":"المساحة تُضرب في مربع المعامل (ك²): ٦ × ٣² = ٦ × ٩ = ٥٤ سم²."},{"type":"tfr","q":"التكبير يحافظ على قياسات زوايا الشكل.","answer":true,"reasons":["الأطوال تتغير بنسبة ك، أما الزوايا فتبقى متساوية تمامًا","لأن الزوايا تتضاعف","لأن الشكل يتشوه"],"reason":0},{"type":"mcq","q":"إذا أُزيحت (أ، ب) بمتجه (−٣، ٥) فأصبحت (١، ٢)، فما النقطة الأصلية؟","options":["(٤، −٣)","(−٢، ٧)","(٤، ٧)","(−٢، −٣)"],"answer":0,"why":"أ − ٣ = ١ ← أ = ٤، و ب + ٥ = ٢ ← ب = −٣."},{"type":"essay","q":"أوجد معادلة خط المرآة الذي يعكس النقطة (١، ٢) إلى (١، ٨).","model":"س ثابتة و ص تغيّرت من ٢ إلى ٨ ← المنتصف (٢+٨)÷٢ = ٥ ← الخط ص = ٥."},{"type":"tfr","q":"صورة (٤، −١) بالانعكاس في محور الصادات (س = ٠) هي (−٤، −١).","answer":true,"reasons":["الانعكاس في محور الصادات يعكس إشارة س فقط","لأنها (٤، ١)","لأنها (−٤، ١)"],"reason":0},{"type":"mcq","q":"ما معامل التكبير الذي يحوّل ضلعًا طوله ٦ سم إلى ٢ سم؟","options":["١/٣","٣","−٣","٤"],"answer":0,"why":"طول الصورة ÷ الأصل = ٢ ÷ ٦ = ١/٣."},{"type":"essay","q":"أوجد صورة (٣، ١) بدوران ٩٠° مع عقارب الساعة حول (٠، ٠).","model":"(س، ص) ← (ص، −س) = (١، −٣)."},{"type":"tfr","q":"إذا كان مركز التكبير (٠، ٠) ومعامل التكبير ٢، فإن صورة (٣، −٢) هي (٦، −٤).","answer":true,"reasons":["نضرب الإحداثيين في ٢ ← (٦، −٤)","لأنها (٥، ٠)","لأنها (١٫٥، −١)"],"reason":0},{"type":"essay","q":"صف التحويل الذي ينقل أ(١، ١)، ب(٣، ١) إلى أَ(١، −١)، بَ(٣، −١).","model":"انعكاس في محور السينات (المستقيم ص = ٠)."}]}},
  {"id":"g9-math-1-u8-4","grade":"g9","subject":"math","term":1,"unit":8,"no":4,"title":"تركيب التحويلات الهندسية","summary":"شرح متحرك لتركيب التحويلات وأهمية الترتيب والتحويل الواحد المكافئ، ثم أنشطة بثلاثة مستويات.","page":"lesson-combined-transformations.html","video":"","pdf":"","notes":["تركيب التحويلات يعني تطبيق تحويل أول ثم تحويل ثانٍ على الصورة الناتجة.","إزاحتان متتاليتان = إزاحة واحدة (نجمع المتجهين).","انعكاسان في مستقيمين متوازيين = إزاحة، وفي متعامدين = دوران ١٨٠°."],"exercises":["أوجد الإزاحة المكافئة لـ (٤، −١) ثم (−٢، ٥).","أوجد صورة (١، ٢) بإزاحة (٢، ٠) ثم انعكاس في محور س."],"levels":{"easy":[{"type":"mcq","q":"إزاحة (٤، −١) تليها إزاحة (−٢، ٥) تكافئ:","options":["(٢، ٤)","(٦، ٤)","(٢، ٦)","(−٢، −٤)"],"answer":0,"why":"(٤−٢ ، −١+٥) = (٢، ٤)."},{"type":"mcq","q":"انعكاس في محور س يليه انعكاس في محور ص يكافئ:","options":["إزاحة","دورانًا ١٨٠° حول (٠، ٠)","تكبيرًا","دورانًا ٩٠°"],"answer":1,"why":"مستقيمان متعامدان ← دوران ١٨٠°."},{"type":"mcq","q":"انعكاسان متتاليان في مستقيمين متوازيين يكافئان:","options":["إزاحة","دورانًا ٩٠°","تكبيرًا","انعكاسًا"],"answer":0,"why":"إزاحة."},{"type":"mcq","q":"أُزيحت (١، ٢) بمتجه (٢، ٠) ثم عُكست في محور س. الصورة النهائية:","options":["(٣، −٢)","(−٣، ٢)","(٣، ٢)","(−١، −٢)"],"answer":0,"why":"(١، ٢) ← (٣، ٢) ← (٣، −٢)."}],"medium":[{"type":"mcq","q":"انعكاس في محور ص يليه انعكاس آخر في محور ص نفسه يعيد الشكل إلى:","options":["موقعه الأصلي تمامًا","الربع الثالث","إزاحة ٢","دوران ٩٠°"],"answer":0,"why":"انعكاسان في نفس الخط يلغيان بعضهما."},{"type":"tfr","q":"تغيير ترتيب التحويلات الهندسية يعطي دائمًا نفس الصورة النهائية.","answer":false,"reasons":["الترتيب مهم جدًا في تركيب التحويلات وقد يعطي صورتين مختلفتين تمامًا","لأن التركيب إبدالي دائمًا","لأن الصورة لا تتغير"],"reason":0},{"type":"essay","q":"أوجد صورة (٢، ٣) بالانعكاس في محور ص ثم إزاحة (١، −٢).","model":"بعد الانعكاس: (−٢، ٣). بعد الإزاحة: (−٢+١ ، ٣−٢) = (−١، ١)."},{"type":"tfr","q":"دوران ٩٠° مع عقارب الساعة يليه دوران ٩٠° مع عقارب الساعة حول نفس المركز يكافئ دورانًا ١٨٠°.","answer":true,"reasons":["لأن ٩٠° + ٩٠° = ١٨٠°","لأنه يعود للأصل","لأنه إزاحة"],"reason":0},{"type":"mcq","q":"تكبير بمعامل ٢ يليه تكبير بمعامل ٣ حول نفس المركز يكافئ تكبيرًا بمعامل:","options":["٥","٦","١٫٥","١"],"answer":1,"why":"٢ × ٣ = ٦."},{"type":"essay","q":"أوجد صورة (٣، ١) بدوران ١٨٠° حول (٠، ٠) ثم انعكاس في محور س.","model":"بعد الدوران: (−٣، −١). بعد الانعكاس في محور س: (−٣، ١)."},{"type":"tfr","q":"إزاحة بمتجه (٣، −٢) تليها إزاحة بمتجه (−٣، ٢) تعيد الشكل لمكانه الأصلي.","answer":true,"reasons":["لأن مجموع المتجهين (٠، ٠)","لأن المجموع (٦، −٤)","لأنه ينعكس"],"reason":0}],"hard":[{"type":"mcq","q":"انعكاس في المستقيم س = ١ يليه انعكاس في المستقيم س = ٤ يكافئ إزاحة أفقية مقدارها:","options":["٦ وحدات لليمين","٣ وحدات لليمين","٦ وحدات لليسار","وحدتان"],"answer":0,"why":"مقدار الإزاحة = ضعف المسافة بين المتوازيين = ٢ × (٤−١) = ٦ لليمين."},{"type":"essay","q":"أثبت أن انعكاس (س، ص) في محور س ثم في محور ص يعطي (−س، −ص).","model":"(س، ص) ← محور س: (س، −ص) ← محور ص: (−س، −ص)، وهو دوران ١٨٠° حول الأصل."},{"type":"tfr","q":"تركيب إزاحتين عملية إبدالية (لا يهم الترتيب).","answer":true,"reasons":["لأن جمع المتجهات إبدالي: (أ+ج، ب+د) = (ج+أ، د+ب)","لأن الترتيب يغيّر الناتج","لأنها لا تُجمع"],"reason":0},{"type":"mcq","q":"صورة (٢، ١) بالانعكاس في ص = س ثم دوران ٩٠° عكس عقارب الساعة حول الأصل:","options":["(−٢، ١)","(١، ٢)","(−١، ٢)","(٢، −١)"],"answer":0,"why":"(٢، ١) ← (١، ٢) ← (−٢، ١)."},{"type":"essay","q":"عُكست النقطة (٤، ٢) في س = ٠ ثم في ص = ٠. ما التحويل الواحد المكافئ؟","model":"دوران بزاوية ١٨٠° حول نقطة الأصل (٠، ٠)، والصورة (−٤، −٢)."},{"type":"tfr","q":"دوران ٩٠° مع عقارب الساعة يليه دوران ٢٧٠° مع عقارب الساعة حول نفس المركز يعيد الشكل لأصله.","answer":true,"reasons":["لأن ٩٠° + ٢٧٠° = ٣٦٠° (دورة كاملة)","لأنه ١٨٠°","لأنه انعكاس"],"reason":0},{"type":"mcq","q":"ما التحويل العكسي لإزاحة بمتجه (٥، −٣)؟","options":["إزاحة (−٥، ٣)","إزاحة (٥، ٣)","انعكاس","دوران ٩٠°"],"answer":0,"why":"نعكس إشارتي المتجه للعودة للأصل."},{"type":"essay","q":"نفّذ على (١، ٣): (أ) إزاحة (٢، ٠) ثم انعكاس في ص = ٠. (ب) انعكاس في ص = ٠ ثم إزاحة (٢، ٠). قارن.","model":"(أ) (٣، ٣) ← (٣، −٣). (ب) (١، −٣) ← (٣، −٣). هنا تساويا لأن الإزاحة موازية لخط المرآة!"},{"type":"tfr","q":"تكبير بمعامل ٢ يليه تكبير بمعامل ١/٢ حول نفس المركز يعيد الشكل لحجمه الأصلي.","answer":true,"reasons":["لأن ٢ × ١/٢ = ١","لأن المعامل يصبح ٢٫٥","لأن الشكل يصغر"],"reason":0},{"type":"essay","q":"أوجد صورة (٢، −١) بتركيب: انعكاس في س = ٢ ثم انعكاس في ص = ١.","model":"النقطة تقع على س = ٢ فتبقى (٢، −١)، ثم انعكاسها في ص = ١ يعطي (٢، ٣)."}]}},
  {"id":"g9-math-1-u9-1","grade":"g9","subject":"math","term":1,"unit":9,"no":1,"title":"المتتاليات","summary":"شرح متحرك للمتتاليات الخطية وإيجاد الحد العام (النوني) والتحقق من الانتماء، ثم أنشطة بثلاثة مستويات.","page":"lesson-sequences.html","video":"","pdf":"","notes":["المتتالية الخطية لها فرق ثابت بين كل حدين متتاليين.","الحد العام حₙ = (الفرق الثابت × ن) + التعديل.","للتحقق هل عدد ينتمي للمتتالية نساويه بالحد العام؛ فإن كانت ن عددًا صحيحًا موجبًا فهو ينتمي."],"exercises":["أوجد الحد العام للمتتالية: ٥، ٨، ١١، ١٤، ...","هل العدد ٣٥ حدّ في المتتالية ٣ن + ٢؟"],"levels":{"easy":[{"type":"mcq","q":"ما الحد العام للمتتالية: ٤، ٩، ١٤، ١٩، ... ؟","options":["٥ن − ١","٥ن + ٤","٤ن + ٥","ن + ٥"],"answer":0,"why":"الفرق ٥ ← ٥ن، وعند ن=١ نطرح ١ ← ٥ن − ١."},{"type":"mcq","q":"إذا كان الحد العام ٤ن + ٣، فما الحد السابع؟","options":["٢٨","٣١","٢٤","٣٥"],"answer":1,"why":"٤(٧) + ٣ = ٣١."},{"type":"mcq","q":"ما الحد التالي في: ١٨، ١٥، ١٢، ٩، ... ؟","options":["٦","٥","٣","٧"],"answer":0,"why":"نطرح ٣ ← ٩ − ٣ = ٦."},{"type":"mcq","q":"هل العدد ٢٢ حدّ في المتتالية ٤ن + ١ ؟","options":["نعم","لا","نعم هو الخامس","نعم هو السادس"],"answer":1,"why":"٤ن = ٢١ ← ن = ٥٫٢٥ (ليس صحيحًا) ← لا."}],"medium":[{"type":"mcq","q":"ما الحد العام للمتتالية المتناقصة: ٢٠، ١٦، ١٢، ٨، ... ؟","options":["٢٤ − ٤ن","٢٠ − ٤ن","٤ن + ١٦","١٦ − ٤ن"],"answer":0,"why":"الفرق −٤ ← −٤ن + ٢٤."},{"type":"tfr","q":"في المتتالية الخطية، معامل (ن) في الحد العام هو دائمًا الفرق الثابت.","answer":true,"reasons":["لأنه يمثّل مقدار الزيادة أو النقصان في كل خطوة","لأنه الحد الأول دائمًا","لأنه يساوي ١"],"reason":0},{"type":"essay","q":"أوجد أول أربعة حدود في المتتالية التي حدّها العام ٣ن − ٢.","model":"ن=١: ١ ، ن=٢: ٤ ، ن=٣: ٧ ، ن=٤: ١٠."},{"type":"tfr","q":"المتتالية ٢، ٤، ٨، ١٦، ... هي متتالية خطية (حسابية).","answer":false,"reasons":["الفرق غير ثابت (٢، ٤، ٨)، بل نضرب في ٢ فهي هندسية وليست خطية","لأنها تزيد بانتظام","لأن حدودها زوجية"],"reason":0},{"type":"mcq","q":"ما رتبة الحد الذي قيمته ٤٧ في المتتالية ٥ن + ٢ ؟","options":["٩","١٠","٨","١١"],"answer":0,"why":"٥ن + ٢ = ٤٧ ← ٥ن = ٤٥ ← ن = ٩."},{"type":"essay","q":"أوجد الحد العام للمتتالية: ٧، ١٠، ١٣، ١٦، ... ثم أوجد الحد العشرين.","model":"الفرق ٣ ← الحد العام = ٣ن + ٤. الحد العشرون = ٣(٢٠) + ٤ = ٦٤."},{"type":"tfr","q":"الحد العاشر في المتتالية ن² هو ١٠٠.","answer":true,"reasons":["لأن ١٠² = ١٠٠","لأنه ٢٠","لأنه ١٠"],"reason":0}],"hard":[{"type":"mcq","q":"ما الحد العام للمتتالية: ١، ٤، ٩، ١٦، ٢٥، ... ؟","options":["ن²","٢ن","ن + ٣","ن³"],"answer":0,"why":"مربعات الأعداد الطبيعية: ن²."},{"type":"essay","q":"أوجد أول حدٍّ سالب في المتتالية ٢٥ − ٤ن.","model":"٢٥ − ٤ن < ٠ ← ٢٥ < ٤ن ← ن > ٦٫٢٥ ← ن = ٧. الحد السابع = ٢٥ − ٢٨ = −٣."},{"type":"tfr","q":"العدد ١٠٠ ينتمي للمتتالية ٣ن + ١.","answer":true,"reasons":["٣ن + ١ = ١٠٠ ← ٣ن = ٩٩ ← ن = ٣٣ (عدد صحيح موجب)","لأن ١٠٠ لا يقبل على ٣","لأن ن كسر"],"reason":0},{"type":"mcq","q":"متتالية حدّها العام ن² + ١. ما الحد الخامس؟","options":["٢٦","٢٥","١١","١٠"],"answer":0,"why":"٥² + ١ = ٢٦."},{"type":"essay","q":"أوجد الحد العام للمتتالية: ٣، ٦، ١١، ١٨، ٢٧، ...","model":"نلاحظ أنها ن² + ٢: ١+٢=٣، ٤+٢=٦، ٩+٢=١١، ١٦+٢=١٨."},{"type":"tfr","q":"إذا كان الحد الأول في متتالية خطية ٥ والفرق الثابت −٣ فإن الحد الرابع هو −٤.","answer":true,"reasons":["الحدود: ٥، ٢، −١، −٤","لأنه −١","لأنه ١٤"],"reason":0},{"type":"mcq","q":"ما الفرق بين الحد العاشر والحد السادس في متتالية فرقها الثابت ٤؟","options":["١٦","٤","٢٠","١٢"],"answer":0,"why":"(١٠ − ٦) × ٤ = ٤ × ٤ = ١٦."},{"type":"essay","q":"متتالية خطية حدّها الثالث ١١ وحدّها السادس ٢٠. أوجد حدّها العام.","model":"الفرق بين ٦ و ٣ هو ٣ خطوات، و ٢٠−١١ = ٩ ← الفرق الثابت = ٩÷٣ = ٣ ← ٣ن. عند ن=٣: ٩ ونريد ١١ ← ٣ن + ٢."},{"type":"tfr","q":"في المتتالية ٢ن − ١، جميع الحدود أعداد فردية.","answer":true,"reasons":["١، ٣، ٥، ٧، ... وهي صيغة الأعداد الفردية","لأنها زوجية","لأن فيها أعدادًا سالبة"],"reason":0},{"type":"essay","q":"كم عدد الحدود الأصغر من ٥٠ في المتتالية ٤ن + ٣؟","model":"٤ن + ٣ < ٥٠ ← ٤ن < ٤٧ ← ن < ١١٫٧٥ ← ١١ حدًّا."}]}},
  {"id":"g9-math-1-u9-2","grade":"g9","subject":"math","term":1,"unit":9,"no":2,"title":"المجموعات","summary":"شرح متحرك لرموز المجموعات والتقاطع والاتحاد والمتمّمة وأشكال فِن، ثم أنشطة بثلاثة مستويات.","page":"lesson-sets.html","video":"","pdf":"","notes":["∈ ينتمي، ∉ لا ينتمي، ⊂ جزئية من، ∅ المجموعة الخالية.","التقاطع (أ ∩ ب): العناصر المشتركة فقط.","الاتحاد (أ ∪ ب): جميع العناصر في أ و ب دون تكرار.","المتمّمة (أَ): العناصر في الشاملة ش وليست في أ."],"exercises":["إذا كانت ش = {١..٦} و أ = {٢، ٤، ٦} و ب = {١، ٢، ٣}، أوجد أ∩ب، أ∪ب، أَ."],"levels":{"easy":[{"type":"mcq","q":"إذا كان أ = {٢، ٤، ٦} و ب = {٤، ٦، ٨}، فما أ ∩ ب ؟","options":["{٤، ٦}","{٢، ٤، ٦، ٨}","{٢، ٨}","∅"],"answer":0,"why":"المشتركة فقط: ٤ و ٦."},{"type":"mcq","q":"إذا كان أ = {١، ٣} و ب = {٣، ٥}، فما أ ∪ ب ؟","options":["{٣}","{١، ٣، ٥}","{١، ٥}","{١، ٣، ٣، ٥}"],"answer":1,"why":"الكل دون تكرار."},{"type":"mcq","q":"إذا كانت ش = {١، ٢، ٣، ٤، ٥} و أ = {١، ٢}، فما أَ ؟","options":["{١، ٢}","{٣، ٤، ٥}","∅","{٥}"],"answer":1,"why":"خارج أ داخل الشاملة."},{"type":"mcq","q":"ماذا يرمز الرمز ∅ ؟","options":["المجموعة الشاملة","المجموعة الخالية","التقاطع","الاتحاد"],"answer":1,"why":"المجموعة الخالية."}],"medium":[{"type":"mcq","q":"ما عدد عناصر المجموعة أ = {أ، ب، ج، د، هـ} أي ن(أ)؟","options":["٤","٥","٦","٠"],"answer":1,"why":"عدد العناصر = ٥."},{"type":"tfr","q":"إذا كان أ ∩ ب = ∅ فإنهما مجموعتان منفصلتان (لا عناصر مشتركة بينهما).","answer":true,"reasons":["لأن تقاطعهما خالٍ تمامًا","لأنهما متساويتان","لأن أ ⊂ ب"],"reason":0},{"type":"essay","q":"لتكن ش = {١، ٢، ٣، ٤، ٥، ٦} و س = {١، ٣، ٥} و ص = {٢، ٣، ٤}. أوجد: (١) س ∩ ص، (٢) سَ.","model":"(١) {٣}. (٢) {٢، ٤، ٦}."},{"type":"tfr","q":"يُسمح بتكرار العنصر نفسه مرتين داخل قوسي المجموعة.","answer":false,"reasons":["لا يُكرّر العنصر داخل المجموعة أبدًا","لأن التكرار يزيد عدد العناصر","لأنه واجب في الاتحاد"],"reason":0},{"type":"mcq","q":"أيُّ عبارة مما يأتي صحيحة لـ أ = {٢، ٤} و ب = {٢، ٤، ٦، ٨}؟","options":["أ ⊂ ب","ب ⊂ أ","أ = ب","أ ∩ ب = ∅"],"answer":0,"why":"كل عناصر أ موجودة في ب."},{"type":"essay","q":"في صف ٣٠ طالبًا، ١٨ يحبون كرة القدم، ١٥ يحبون السباحة، و ٥ يحبون الرياضتين معًا. كم طالبًا يحب كرة القدم فقط؟","model":"١٨ − ٥ = ١٣ طالبًا."},{"type":"tfr","q":"ناتج أ ∪ أَ يساوي المجموعة الشاملة ش.","answer":true,"reasons":["لأن أ مع كل ما خارج أ يشكّلان الشاملة كاملةً","لأنه ∅","لأنه أ"],"reason":0}],"hard":[{"type":"mcq","q":"في صف ٢٥ طالبًا: ١٤ يدرسون الفرنسية، ١٢ يدرسون الألمانية، و ٤ لا يدرسون أيًّا منهما. كم طالبًا يدرس اللغتين معًا؟","options":["٥","٤","٦","٣"],"answer":0,"why":"يدرسون لغة على الأقل = ٢٥ − ٤ = ٢١ ← التقاطع = (١٤ + ١٢) − ٢١ = ٥."},{"type":"essay","q":"لتكن ش = {١..٨}، أ = {١، ٢، ٣، ٤}، ب = {٣، ٤، ٥، ٦}. أوجد (أ ∪ ب)َ.","model":"أ ∪ ب = {١، ٢، ٣، ٤، ٥، ٦} ← متمّمتها = {٧، ٨}."},{"type":"tfr","q":"ناتج أ ∩ أَ يساوي ∅ دائمًا.","answer":true,"reasons":["لا يمكن لعنصر أن يكون داخل أ وخارجها في الوقت نفسه","لأنه يساوي ش","لأنه يساوي أ"],"reason":0},{"type":"mcq","q":"إذا كان ن(أ) = ١٠، ن(ب) = ٨، ن(أ ∩ ب) = ٣، فما ن(أ ∪ ب)؟","options":["١٥","١٨","٢١","١٢"],"answer":0,"why":"ن(أ∪ب) = ١٠ + ٨ − ٣ = ١٥."},{"type":"essay","q":"اشرح معنى المنطقة أ ∩ بَ في شكل فِن.","model":"هي العناصر الموجودة في المجموعة أ فقط وليست في ب."},{"type":"tfr","q":"المجموعة الخالية ∅ هي مجموعة جزئية من أي مجموعة.","answer":true,"reasons":["وهذه قاعدة أساسية في نظرية المجموعات","لأنها تحتوي على صفر","لأنها تساوي ش"],"reason":0},{"type":"mcq","q":"كم عدد المجموعات الجزئية للمجموعة {١، ٢}؟","options":["٤","٢","٣","١"],"answer":0,"why":"∅ ، {١} ، {٢} ، {١، ٢} (٢² = ٤)."},{"type":"essay","q":"لتكن ش = {الأعداد الصحيحة من ١ إلى ١٠}، أ = {مضاعفات ٣}، ب = {الأعداد الزوجية}. أوجد أ ∩ ب.","model":"أ = {٣، ٦، ٩}، ب = {٢، ٤، ٦، ٨، ١٠} ← أ ∩ ب = {٦}."},{"type":"tfr","q":"إذا كان أ ⊂ ب فإن أ ∩ ب = أ.","answer":true,"reasons":["لأن كل عناصر أ مشتركة مع ب","لأنه يساوي ب","لأنه ∅"],"reason":0},{"type":"essay","q":"في استبيان لـ ٤٠ شخصًا: ٢٢ يفضلون الشاي، ٢٥ يفضلون القهوة، و ١٠ يفضلون كليهما. كم شخصًا لا يفضل أيًّا منهما؟","model":"ن(شاي ∪ قهوة) = ٢٢ + ٢٥ − ١٠ = ٣٧ ← لا يفضل أيًّا منهما = ٤٠ − ٣٧ = ٣ أشخاص."}]}},
  {"id":"g9-math-2-u10-1","grade":"g9","subject":"math","term":2,"unit":10,"no":1,"title":"النسب المئوية","summary":"شرح متحرك بـ SVG لدرس النسب المئوية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-percentages-t2.html","video":"","pdf":"","notes":["النسبة المئوية = (الجزء ÷ الكل) × ١٠٠٪.","وحّد الوحدات دائمًا قبل حساب النسبة المئوية (١ ريال = ١٠٠٠ بيسة، ١ كم = ١٠٠٠ م).","نسبة التغير = (مقدار الزيادة أو النقصان ÷ القيمة الأصلية) × ١٠٠٪."],"exercises":["احسب النسبة المئوية للزيادة إذا ارتفع سعر دراجة هوائية من ٤٠ ريالًا إلى ٤٦ ريالًا عُمانيًا.","عبّر عن ٧٥٠ مترًا كنسبة مئوية من ٣ كيلومترات موضّحًا خطوة تحويل الوحدات.","اشترى سالم هاتفًا بسعر ٨٠ ريالًا بخصم ١٥٪. كم قيمة الخصم؟ وكم يدفع؟"],"levels":{"easy":[{"type":"mcq","q":"ما قيمة ٢٥٪ من ٨٠ ريالًا عُمانيًا؟","options":["٤٠ ريالًا","١٥ ريالًا","٢٥ ريالًا","٢٠ ريالًا"],"answer":3,"why":"٢٥٪ = الربع، وربع ٨٠ يساوي ٢٠."},{"type":"mcq","q":"حصل طالب على ١٨ من ٢٠ في اختبار قصير، ما نسبته المئوية؟","options":["٩٠٪","٨٠٪","٨٥٪","٩٥٪"],"answer":0,"why":"(١٨ ÷ ٢٠) × ١٠٠٪ = ٩٠٪."},{"type":"mcq","q":"ما الكسر العشري المكافئ للنسبة المئوية ٦٫٥٪؟","options":["٠٫٦٥","٠٫٠٦٥","٦٫٥","٠٫٠٠٦٥"],"answer":1,"why":"نقسم ٦٫٥ على ١٠٠ فينتج ٠٫٠٦٥."},{"type":"mcq","q":"ما النسبة المئوية لـ ٥٠٠ بيسة من ٢ ريال عُماني؟","options":["٢٫٥٪","٥٠٪","٢٥٪","٢٠٪"],"answer":2,"why":"٢ ريال = ٢٠٠٠ بيسة؛ (٥٠٠ ÷ ٢٠٠٠) × ١٠٠٪ = ٢٥٪."}],"medium":[{"type":"mcq","q":"ارتفع سعر منتج من ٢٠ ريالًا إلى ٢٥ ريالًا، ما النسبة المئوية للزيادة؟","options":["١٢٥٪","٢٠٪","٥٪","٢٥٪"],"answer":3,"why":"التغير = ٥؛ (٥ ÷ ٢٠) × ١٠٠٪ = ٢٥٪."},{"type":"mcq","q":"انخفض عدد الحضور من ٥٠ إلى ٤٠، ما النسبة المئوية للنقصان؟","options":["٢٠٪","٢٥٪","١٠٪","٨٠٪"],"answer":0,"why":"النقصان = ١٠؛ (١٠ ÷ ٥٠) × ١٠٠٪ = ٢٠٪."},{"type":"mcq","q":"ما النسبة المئوية المكافئة للكسر ٣/٨؟","options":["٣٨٪","٣٧٫٥٪","٣٠٪","٦٢٫٥٪"],"answer":1,"why":"٣ ÷ ٨ = ٠٫٣٧٥ = ٣٧٫٥٪."},{"type":"tfr","q":"١ ريال عُماني يساوي ١٠٠٠ بيسة، لذا ٢٥٠ بيسة تمثل ٢٥٪ من الريال.","answer":true,"reasons":["لأن (٢٥٠ ÷ ١٠٠٠) × ١٠٠٪ = ٢٥٪","لأن الريال ١٠٠ بيسة فقط","لأنها تمثل ٢٫٥٪ فقط"],"reason":0},{"type":"tfr","q":"يمكن أن تزيد النسبة المئوية عن ١٠٠٪ عند مقارنة كمية أكبر من الكمية الأصلية.","answer":true,"reasons":["النسبة المئوية لا تتجاوز ١٠٠٪ أبدًا","مثل تضاعف الإنتاج إلى ٢٠٠٪","تصل فقط إلى ١١٠٪"],"reason":1},{"type":"essay","q":"احسب النسبة المئوية للزيادة إذا ارتفع سعر دراجة هوائية من ٤٠ ريالًا إلى ٤٦ ريالًا عُمانيًا.","model":"مقدار الزيادة = ٤٦ − ٤٠ = ٦ ريالات. النسبة المئوية للزيادة = (٦ ÷ ٤٠) × ١٠٠٪ = ١٥٪."},{"type":"essay","q":"عبّر عن ٧٥٠ مترًا كنسبة مئوية من ٣ كيلومترات موضّحًا خطوة تحويل الوحدات.","model":"٣ كم = ٣٠٠٠ م. النسبة = (٧٥٠ ÷ ٣٠٠٠) × ١٠٠٪ = ٢٥٪."}],"hard":[{"type":"mcq","q":"ما قيمة ١٢٠٪ من ٥٠؟","options":["٧٠","٥٥","٦٠","١٢"],"answer":2,"why":"١٫٢ × ٥٠ = ٦٠."},{"type":"mcq","q":"عند حساب النسبة المئوية للتغير، نقسم مقدار التغير على:","options":["١٠٠","القيمة الجديدة","مجموع القيمتين","القيمة الأصلية"],"answer":3,"why":"نسبة التغير تُنسب دائمًا إلى القيمة الأصلية."},{"type":"mcq","q":"كم يساوي ١٥٪ من ٢٠٠ متر؟","options":["٣٠ مترًا","١٥ مترًا","٢٠ مترًا","٤٥ مترًا"],"answer":0,"why":"٠٫١٥ × ٢٠٠ = ٣٠ مترًا."},{"type":"mcq","q":"ما النسبة المئوية لـ ٣٠ دقيقة من ساعتين؟","options":["١٥٪","٢٥٪","٣٠٪","٥٠٪"],"answer":1,"why":"ساعتان = ١٢٠ دقيقة؛ (٣٠ ÷ ١٢٠) × ١٠٠٪ = ٢٥٪."},{"type":"tfr","q":"لحساب النسبة المئوية للنقصان نقسم مقدار النقصان على القيمة الجديدة.","answer":false,"reasons":["نضرب في القيمة الجديدة","القسمة على الجديدة أدق","بل نقسم دائمًا على القيمة الأصلية"],"reason":2},{"type":"tfr","q":"النسبة المئوية ٥٪ تساوي ٠٫٥ في الصورة العشرية.","answer":false,"reasons":["بل ٥ ÷ ١٠٠ = ٠٫٠٥ أما ٠٫٥ فهي ٥٠٪","نعم ٥٪ = ٠٫٥","تساوي ٥٫٠"],"reason":0},{"type":"tfr","q":"يجب توحيد الوحدات قبل التعبير عن كمية كنسبة مئوية من كمية أخرى.","answer":true,"reasons":["لا يؤثر اختلاف الوحدات","لضمان صحة المقارنة بين الكميتين","فقط في وحدات الزمن"],"reason":1},{"type":"essay","q":"اشترى سالم هاتفًا بسعر ٨٠ ريالًا بخصم ١٥٪. كم قيمة الخصم؟ وكم يدفع؟","model":"قيمة الخصم = ٠٫١٥ × ٨٠ = ١٢ ريالًا. السعر بعد الخصم = ٨٠ − ١٢ = ٦٨ ريالًا."},{"type":"essay","q":"في صف به ٣٢ طالبًا، تغيّب ٤ طلاب. احسب النسبة المئوية للطلاب الحاضرين.","model":"الحاضرون = ٣٢ − ٤ = ٢٨ طالبًا. النسبة = (٢٨ ÷ ٣٢) × ١٠٠٪ = ٨٧٫٥٪."},{"type":"essay","q":"فسّر لماذا يعطي ١٠٪ من ٢٠٠ نفس النتيجة التي يعطيها ٢٠٠٪ من ١٠.","model":"لأن (١٠/١٠٠)×٢٠٠ = ٢٠، و(٢٠٠/١٠٠)×١٠ = ٢٠؛ فالضرب عملية إبدالية."}]}},
  {"id":"g9-math-2-u10-2","grade":"g9","subject":"math","term":2,"unit":10,"no":2,"title":"التعامل مع النسبة","summary":"شرح متحرك بـ SVG لدرس التعامل مع النسبة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-working-with-ratios.html","video":"","pdf":"","notes":["لتبسيط نسبة: وحّد الوحدات أولًا ثم اقسم الحدين على ع.م.أ.","لكتابة نسبة بصورة ١ : ن نقسم الطرفين على الحد الأول.","في مسائل التقسيم: قيمة الجزء = المبلغ الكلي ÷ مجموع الأجزاء."],"exercises":["قُسّم ربح قدره ١٢٠ ريالًا عُمانيًا بين ثلاثة شركاء بنسبة ٢ : ٣ : ٥. احسب نصيب كل شريك.","بسّط النسبة ٠٫٧٥ كجم : ٣٠٠ جم موضّحًا خطوات الحل.","نسبة زوايا مثلث هي ٢ : ٣ : ٤. أوجد قياس كل زاوية في المثلث."],"levels":{"easy":[{"type":"mcq","q":"ما أبسط صورة للنسبة ١٨ : ٢٤؟","options":["٣ : ٤","٩ : ١٢","٢ : ٣","٦ : ٨"],"answer":0,"why":"بقسمة الطرفين على ع.م.أ وهو ٦ نحصل على ٣ : ٤."},{"type":"mcq","q":"بسّط النسبة ٥٠٠ مل : ٢ لتر إلى أبسط صورة:","options":["٢٥٠ : ١","١ : ٤","١ : ٢","٥ : ٢"],"answer":1,"why":"٢ لتر = ٢٠٠٠ مل؛ ٥٠٠ : ٢٠٠٠ = ١ : ٤."},{"type":"mcq","q":"قُسّم مبلغ ٦٠ ريالًا بنسبة ١ : ٢ : ٣. ما أكبر نصيب؟","options":["١٠ ريالات","٢٠ ريالًا","٣٠ ريالًا","٤٠ ريالًا"],"answer":2,"why":"مجموع الأجزاء = ٦؛ الجزء = ١٠؛ أكبر نصيب = ٣ × ١٠ = ٣٠."},{"type":"mcq","q":"اكتب النسبة ٥ : ١٢ بصورة ١ : ن:","options":["١ : ٠٫٤","١ : ٢٫٥","١ : ٧","١ : ٢٫٤"],"answer":3,"why":"بقسمة الطرفين على ٥ يكون ١٢ ÷ ٥ = ٢٫٤."}],"medium":[{"type":"mcq","q":"ما أبسط صورة للنسبة ٠٫٤ : ١٫٢؟","options":["١ : ٣","٤ : ١٢","١ : ٤","٢ : ٥"],"answer":0,"why":"بالضرب في ١٠ تصبح ٤ : ١٢ ثم بالقسمة على ٤ تصبح ١ : ٣."},{"type":"mcq","q":"نسبة الأولاد إلى البنات في نادٍ هي ٣ : ٥. إذا كان عدد الأولاد ١٢، فكم عدد البنات؟","options":["١٥","٢٠","١٨","٢٤"],"answer":1,"why":"الجزء = ١٢ ÷ ٣ = ٤؛ البنات = ٥ × ٤ = ٢٠."},{"type":"mcq","q":"ما أبسط صورة للنسبة ١/٣ : ١/٤؟","options":["١ : ١٢","٣ : ٤","٤ : ٣","٣ : ١"],"answer":2,"why":"نضرب الطرفين في ١٢ فتصبح ٤ : ٣."},{"type":"tfr","q":"النسبة ٢ : ٣ تكافئ النسبة ٣ : ٢.","answer":false,"reasons":["النسبة عملية إبدالية","الترتيب مهم في النسبة ولا يصح عكس الحدين","تتكافآن دائمًا"],"reason":1},{"type":"tfr","q":"يجب توحيد الوحدات قبل تبسيط أي نسبة بين كميتين.","answer":true,"reasons":["التحويل مطلوب للكتلة فقط","يمكن التبسيط مباشرة دون تحويل","حتى تكون المقارنة على نفس المقياس"],"reason":2},{"type":"essay","q":"قُسّم ربح قدره ١٢٠ ريالًا عُمانيًا بين ثلاثة شركاء بنسبة ٢ : ٣ : ٥. احسب نصيب كل شريك.","model":"مجموع الأجزاء = ٢+٣+٥ = ١٠. قيمة الجزء = ١٢٠ ÷ ١٠ = ١٢ ريالًا. الأنصبة: ٢٤ ريالًا، ٣٦ ريالًا، ٦٠ ريالًا."},{"type":"essay","q":"بسّط النسبة ٠٫٧٥ كجم : ٣٠٠ جم موضّحًا خطوات الحل.","model":"٠٫٧٥ كجم = ٧٥٠ جم. النسبة ٧٥٠ : ٣٠٠، نقسم على ١٥٠ فتصبح ٥ : ٢."}],"hard":[{"type":"mcq","q":"قُسّمت قطعة قماش طولها ٣٦ مترًا بنسبة ٤ : ٥. ما طول القطعة الأقصر؟","options":["١٢ مترًا","٢٠ مترًا","١٨ مترًا","١٦ مترًا"],"answer":3,"why":"مجموع الأجزاء = ٩؛ الجزء = ٤ م؛ الأقصر = ٤ × ٤ = ١٦ م."},{"type":"mcq","q":"تزيد حصة أحمد عن حصة خالد بنسبة ٥ : ٢ وبفارق ١٥ ريالًا. ما قيمة الجزء الواحد؟","options":["٥ ريالات","٣ ريالات","٧٫٥ ريالات","١٠ ريالات"],"answer":0,"why":"فرق الأجزاء = ٥ − ٢ = ٣ أجزاء = ١٥ ريالًا ← الجزء = ٥ ريالات."},{"type":"mcq","q":"بسّط النسبة ٢ ساعة : ٤٥ دقيقة:","options":["٢ : ٤٥","٨ : ٣","٣ : ٨","٤ : ٣"],"answer":1,"why":"٢ ساعة = ١٢٠ دقيقة؛ ١٢٠ : ٤٥ ÷ ١٥ = ٨ : ٣."},{"type":"mcq","q":"إذا كانت نسبة أ : ب = ٢ : ٣ ونسبة ب : ج = ٣ : ٥ فإن أ : ج تساوي:","options":["٢ : ٣","٥ : ٢","٢ : ٥","٦ : ٥"],"answer":2,"why":"بما أن ب مشتركة بالقيمة ٣ نفسها، فإن أ : ب : ج = ٢ : ٣ : ٥."},{"type":"tfr","q":"عند تقسيم ٨٠ ريالًا بنسبة ٣ : ٥ فإن قيمة الجزء الواحد هي ١٠ ريالات.","answer":true,"reasons":["لأن مجموع الأجزاء ٣+٥=٨ و٨٠÷٨=١٠","لأن ٨٠÷٥=١٦","لأن ٨٠÷٣=٢٦٫٦"],"reason":0},{"type":"tfr","q":"النسبة المبسّطة لأبسط صورة يُكتب بجانبها وحدة القياس دائمًا.","answer":false,"reasons":["يجب كتابة سم أو م","النسبة بلا وحدات بعد توحيد الوحدات واختصارها","تُكتب بوحدة الأكبر"],"reason":1},{"type":"tfr","q":"لكتابة نسبة أ : ب بصورة ١ : ن نقسم كلا الحدين على أ.","answer":true,"reasons":["نطرح أ من ب","نقسم على ب","فيصبح الحد الأول أ÷أ = ١ والثاني ب÷أ"],"reason":2},{"type":"essay","q":"نسبة زوايا مثلث هي ٢ : ٣ : ٤. أوجد قياس كل زاوية في المثلث.","model":"مجموع زوايا المثلث ١٨٠°، مجموع الأجزاء = ٩، الجزء = ٢٠°. الزوايا: ٤٠°، ٦٠°، ٨٠°."},{"type":"essay","q":"في وصفة حلوى عُمانية، نسبة السكر إلى الطحين ٢ : ٥. إذا استخدم الطاهي ٣٥٠ جم طحين، فكم جرامًا من السكر يحتاج؟","model":"٥ أجزاء = ٣٥٠ جم ← الجزء = ٧٠ جم. السكر = ٢ × ٧٠ = ١٤٠ جم."},{"type":"essay","q":"وفّر ماجد وسعيد مبلغين بنسبة ٤ : ٧، فإذا زاد ما وفّره سعيد عن ماجد بمقدار ٢١ ريالًا، فكم وفّر كل منهما؟","model":"فرق الأجزاء = ٧ − ٤ = ٣ أجزاء = ٢١ ريالًا ← الجزء = ٧ ريالات. ماجد = ٢٨ ريالًا، سعيد = ٤٩ ريالًا."}]}},
  {"id":"g9-math-2-u10-3","grade":"g9","subject":"math","term":2,"unit":10,"no":3,"title":"النسبة ومقياس الرسم","summary":"شرح متحرك بـ SVG لدرس النسبة ومقياس الرسم (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-ratio-and-scale.html","video":"","pdf":"","notes":["مقياس الرسم = الطول في الرسم : الطول الحقيقي (بعد توحيد الوحدات).","١ م = ١٠٠ سم، ١ كم = ١٠٠٠٠٠ سم.","١ : ن مقياس تصغير (خرائط ومخططات)، بينما ن : ١ مقياس تكبير (أجسام دقيقة)."],"exercises":["على خريطة لسلطنة عُمان مقياسها ١ : ٢٠٠٠٠٠٠، كانت المسافة بين مدينتين ٧٫٥ سم. احسب المسافة الحقيقية بالكيلومتر.","غرفة مستطيلة أبعادها الحقيقية ٨ م × ٥ م. أوجد أبعادها على مخطط مقياسه ١ : ٢٠٠.","نموذج مصغّر لسفينة تقليدية عُمانية طوله ٤٠ سم، بينما طول السفينة الحقيقي ٢٠ مترًا. أوجد مقياس الرسم."],"levels":{"easy":[{"type":"mcq","q":"خريطة بمقياس ١ : ٥٠٠٠٠؛ كم مترًا حقيقيًا يمثل ١ سم على الخريطة؟","options":["٥٠ مترًا","٥٠٠ متر","٥٠٠٠ متر","٥ أمتار"],"answer":1,"why":"٥٠٠٠٠ سم ÷ ١٠٠ = ٥٠٠ متر."},{"type":"mcq","q":"مقياس رسم مخطط منزل هو ١ : ١٠٠. إذا كان طول صالة في المخطط ٦ سم، فما طولها الحقيقي؟","options":["٠٫٦ متر","٦٠ مترًا","٦ أمتار","٦٠٠ متر"],"answer":2,"why":"٦ × ١٠٠ = ٦٠٠ سم = ٦ أمتار."},{"type":"mcq","q":"طريق طوله الحقيقي ١٢ كم، كم سنتيمترًا يكون طوله على خريطة مقياسها ١ : ٣٠٠٠٠٠؟","options":["٤٠ سم","٣٦ سم","٠٫٤ سم","٤ سم"],"answer":3,"why":"١٢ كم = ١٢٠٠٠٠٠ سم؛ ١٢٠٠٠٠٠ ÷ ٣٠٠٠٠٠ = ٤ سم."},{"type":"mcq","q":"ظهرت حديقة طولها الحقيقي ٥٠ مترًا بطول ٥ سم في رسم. ما مقياس الرسم؟","options":["١ : ١٠٠٠","١ : ١٠","١ : ١٠٠","١ : ٥٠٠"],"answer":0,"why":"٥٠ م = ٥٠٠٠ سم؛ ٥ : ٥٠٠٠ = ١ : ١٠٠٠."}],"medium":[{"type":"mcq","q":"مقياس الرسم ١٠ : ١ يُستخدم لـ:","options":["تصغير الخرائط","تكبير الأجسام الدقيقة","تساوي الحجمين","قياس الكتلة"],"answer":1,"why":"عندما يكون الحد الأول أكبر من ١ فهو مقياس تكبير."},{"type":"mcq","q":"كم سنتيمترًا في الكيلومتر الواحد؟","options":["١٠٠٠٠ سم","١٠٠٠ سم","١٠٠٠٠٠ سم","١٠٠ سم"],"answer":2,"why":"١ كم = ١٠٠٠ م × ١٠٠ سم/م = ١٠٠٠٠٠ سم."},{"type":"mcq","q":"على خريطة مقياسها ١ : ٢٥٠٠٠٠، المسافة بين ولايتين ٨ سم. ما المسافة الحقيقية بالكيلومتر؟","options":["٣١٫٢٥ كم","٢ كم","٢٠٠ كم","٢٠ كم"],"answer":3,"why":"٨ × ٢٥٠٠٠٠ = ٢٠٠٠٠٠٠ سم ÷ ١٠٠٠٠٠ = ٢٠ كم."},{"type":"tfr","q":"المقياس ١ : ١٠٠ يعني أن ١ سم على المخطط يمثل ١ متر في الواقع.","answer":true,"reasons":["لأن ١٠٠ سم = ١ كم","لأن ١٠٠ سم = ١٠ أمتار","لأن ١٠٠ سم = ١ متر"],"reason":2},{"type":"tfr","q":"في مقياس الرسم ١ : ٥٠٠٠٠٠ تكون الصورة أكبر من الجسم الحقيقي.","answer":false,"reasons":["بل أصغر ٥٠٠٠٠٠ مرة (مقياس تصغير)","أكبر ٥٠٠٠٠٠ مرة","مساوية للحقيقة"],"reason":0},{"type":"essay","q":"على خريطة لسلطنة عُمان مقياسها ١ : ٢٠٠٠٠٠٠، كانت المسافة بين مدينتين ٧٫٥ سم. احسب المسافة الحقيقية بالكيلومتر.","model":"٧٫٥ × ٢٠٠٠٠٠٠ = ١٥٠٠٠٠٠٠ سم. بالقسمة على ١٠٠٠٠٠ تكون المسافة = ١٥٠ كم."},{"type":"essay","q":"غرفة مستطيلة أبعادها الحقيقية ٨ م × ٥ م. أوجد أبعادها على مخطط مقياسه ١ : ٢٠٠.","model":"الطول: ٨٠٠ ÷ ٢٠٠ = ٤ سم. العرض: ٥٠٠ ÷ ٢٠٠ = ٢٫٥ سم."}],"hard":[{"type":"mcq","q":"إذا كان طول حشرة حقيقيًا ٣ مم ورُسمت بمقياس ٢٠ : ١، فما طولها في الرسم؟","options":["٦٠ مم (٦ سم)","١٫٥ مم","٢٣ مم","٦٠٠ مم"],"answer":0,"why":"٣ × ٢٠ = ٦٠ مم = ٦ سم."},{"type":"mcq","q":"ملعب طوله ٨٠ مترًا وعرضه ٤٠ مترًا رُسم بمقياس ١ : ١٠٠٠. ما أبعاده على الرسم؟","options":["٨٠ سم × ٤٠ سم","٨ سم × ٤ سم","٠٫٨ سم × ٠٫٤ سم","٤ سم × ٢ سم"],"answer":1,"why":"٨٠٠٠÷١٠٠٠ = ٨ سم، ٤٠٠٠÷١٠٠٠ = ٤ سم."},{"type":"mcq","q":"أي المقياسين الآتيين يُظهر تفاصيل أكثر لمنطقة معينة؟","options":["كلاهما متساوٍ","١ : ١٠٠٠٠٠٠","١ : ١٠٠٠٠","لا علاقة للمقياس بالتفاصيل"],"answer":2,"why":"كلما صغر المقام، كان التكبير النسبي أكبر والتفاصيل أوضح."},{"type":"mcq","q":"مقياس خريطة ١ : ٥٠٠٠٠٠، فإذا كانت المسافة الحقيقية ٣٥ كم، فكم طولها على الخريطة؟","options":["٧٠ سم","١٧٫٥ سم","٠٫٧ سم","٧ سم"],"answer":3,"why":"٣٥٠٠٠٠٠ ÷ ٥٠٠٠٠٠ = ٧ سم."},{"type":"tfr","q":"لإيجاد المسافة الحقيقية من الخريطة نضرب الطول المقيس في مقام المقياس ثم نحوّل الوحدة.","answer":true,"reasons":["نقسم على مقام المقياس","ثم نقسم على ١٠٠ للمتر أو ١٠٠٠٠٠ للكيلومتر","نجمع المقياس مع الطول"],"reason":1},{"type":"tfr","q":"يمكن حساب مقياس الرسم مباشرة بقسمة الطول بالسم على الطول بالمتر دون تحويل.","answer":false,"reasons":["نحوّل للمتر فقط","لا حاجة لتوحيد الوحدات","يجب توحيد الوحدات أولًا إلى سنتيمتر"],"reason":2},{"type":"tfr","q":"مقياس الرسم ١٥ : ١ مناسب لرسم أجزاء دقيقة في ساعة يد أو حشرة صغيرة.","answer":true,"reasons":["لأنه مقياس تكبير يكبّر الأبعاد ١٥ مرة","لأنه مقياس تصغير","لأنه خاص بالخرائط الجغرافية"],"reason":0},{"type":"essay","q":"نموذج مصغّر لسفينة تقليدية عُمانية طوله ٤٠ سم، بينما طول السفينة الحقيقي ٢٠ مترًا. أوجد مقياس الرسم.","model":"٢٠ م = ٢٠٠٠ سم. المقياس = ٤٠ : ٢٠٠٠، بالقسمة على ٤٠ = ١ : ٥٠."},{"type":"essay","q":"قارن بين مقياس التصغير ومقياس التكبير مع مثال عددي لكل منهما.","model":"مقياس التصغير (١ : ن حيث ن > ١) مثل ١ : ١٠٠٠٠ للخرائط. مقياس التكبير (ن : ١ حيث ن > ١) مثل ٢٠ : ١ للحشرات والدوائر الدقيقة."},{"type":"essay","q":"إذا كان طول جسر على خريطة مقياسها ١ : ٢٥٠٠٠ يساوي ٣٫٢ سم، فما طوله الحقيقي بالأمتار؟","model":"٣٫٢ × ٢٥٠٠٠ = ٨٠٠٠٠ سم ÷ ١٠٠ = ٨٠٠ متر."}]}},
  {"id":"g9-math-2-u10-4","grade":"g9","subject":"math","term":2,"unit":10,"no":4,"title":"التناسب","summary":"شرح متحرك بـ SVG لدرس التناسب (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-proportion.html","video":"","pdf":"","notes":["طردي: ص = ك س (ص÷س ثابت، وخط مستقيم يمر بالأصل).","عكسي: ص = ك ÷ س (س×ص ثابت).","اختبر منطقيًا قبل الحساب: هل الزيادة تزيد الآخر (طردي) أم تقلّله (عكسي)؟"],"exercises":["تستهلك سيارة ١٥ لترًا من الوقود لقطع ١٨٠ كم. كم لترًا تحتاج لقطع ٣٠٠ كم بنفس المعدل؟","يحتاج ٥ مزارعين إلى ١٢ يومًا لجني محصول مزرعة في الباطنة. كم يومًا يحتاج ٦ مزارعين بنفس الكفاءة؟","قارن بين التناسب الطردي والتناسب العكسي من حيث المعادلة وثابت التناسب ومثال حياتي لكل منهما."],"levels":{"easy":[{"type":"mcq","q":"ثمن ٥ أقلام هو ٢٫٥ ريال عُماني. ما ثمن ٨ أقلام من نفس النوع؟","options":["٤٫٥ ريالات","٣٫٥ ريالات","٤ ريالات","٥ ريالات"],"answer":2,"why":"ثمن القلم = ٠٫٥ ريال؛ ٨ × ٠٫٥ = ٤ ريالات (تناسب طردي)."},{"type":"mcq","q":"يُنجز ٦ عمال مشروعًا في ١٠ أيام. كم يومًا يحتاج ١٢ عاملًا لإنجاز المشروع نفسه؟","options":["٦ أيام","٢٠ يومًا","٨ أيام","٥ أيام"],"answer":3,"why":"تناسب عكسي: ٦ × ١٠ = ٦٠؛ ٦٠ ÷ ١٢ = ٥ أيام."},{"type":"mcq","q":"أي العلاقات الآتية تمثل تناسبًا طرديًا؟","options":["ص = ٥س","س × ص = ٢٠","ص = ٢س + ٣","ص = ١٢ ÷ س"],"answer":0,"why":"التناسب الطردي صورته ص = ك س بدون حد ثابت مضاف."},{"type":"mcq","q":"أي العلاقات الآتية تمثل تناسبًا عكسيًا؟","options":["ص = ٤س","س × ص = ٣٦","ص ÷ س = ٩","ص = س + ٥"],"answer":1,"why":"في التناسب العكسي حاصل الضرب س × ص ثابت."}],"medium":[{"type":"mcq","q":"تقطع حافلة مسافة في ٤ ساعات بسرعة ٦٠ كم/س. ما السرعة اللازمة لقطعها في ٣ ساعات؟","options":["٧٥ كم/س","٤٥ كم/س","٨٠ كم/س","٩٠ كم/س"],"answer":2,"why":"المسافة = ٤ × ٦٠ = ٢٤٠ كم؛ السرعة = ٢٤٠ ÷ ٣ = ٨٠ كم/س."},{"type":"mcq","q":"يمر التمثيل البياني للتناسب الطردي دائمًا بالنقطة:","options":["(١، ٠)","(١، ١)","(٠، ١)","(٠، ٠)"],"answer":3,"why":"لأن عندما س = ٠ تكون ص = ك × ٠ = ٠."},{"type":"mcq","q":"إذا كانت ص تتناسب عكسيًا مع س، وكانت ص = ٨ عندما س = ٣، فما قيمة ص عندما س = ٦؟","options":["٤","١٦","٢","١٢"],"answer":0,"why":"ك = ٨ × ٣ = ٢٤؛ ص = ٢٤ ÷ ٦ = ٤."},{"type":"tfr","q":"العلاقة بين عدد العمال والزمن اللازم لإنجاز عمل ثابت هي علاقة تناسب عكسي.","answer":true,"reasons":["لأن زيادة العمال تقلل الزمن بنفس النسبة","تناسب طردي","ليست علاقة تناسب"],"reason":0},{"type":"tfr","q":"المعادلة ص = ٣س + ٢ تمثل تناسبًا طرديًا بين س و ص.","answer":false,"reasons":["نعم لأنها خطية","لأن المستقيم لا يمر بنقطة الأصل (٠، ٠)","تمثل تناسبًا عكسيًا"],"reason":1},{"type":"essay","q":"تستهلك سيارة ١٥ لترًا من الوقود لقطع ١٨٠ كم. كم لترًا تحتاج لقطع ٣٠٠ كم بنفس المعدل؟","model":"المعدل = ١٨٠ ÷ ١٥ = ١٢ كم لكل لتر. اللترات المطلوبة = ٣٠٠ ÷ ١٢ = ٢٥ لترًا (تناسب طردي)."},{"type":"essay","q":"يحتاج ٥ مزارعين إلى ١٢ يومًا لجني محصول مزرعة في الباطنة. كم يومًا يحتاج ٦ مزارعين بنفس الكفاءة؟","model":"تناسب عكسي: ٥ × ١٢ = ٦٠ يوم عمل. الزمن لـ ٦ مزارعين = ٦٠ ÷ ٦ = ١٠ أيام."}],"hard":[{"type":"mcq","q":"يملأ ٣ صنابير متماثلة خزانًا في ٨ ساعات. كم ساعة يحتاج ٤ صنابير لملء نفس الخزان؟","options":["١٠٫٦ ساعات","٦ ساعات","٤ ساعات","٥ ساعات"],"answer":1,"why":"٣ × ٨ = ٢٤؛ ٢٤ ÷ ٤ = ٦ ساعات (تناسب عكسي)."},{"type":"mcq","q":"تحتاج وصفة لـ ٤ أشخاص إلى ٣٠٠ جم أرز. كم جرامًا نحتاج لـ ١٠ أشخاص؟","options":["٦٠٠ جم","١٢٠ جم","٧٥٠ جم","٩٠٠ جم"],"answer":2,"why":"للشخص الواحد ٧٥ جم؛ ١٠ × ٧٥ = ٧٥٠ جم (تناسب طردي)."},{"type":"mcq","q":"إذا تضاعفت قيمة س ثلاث مرات في تناسب عكسي، فإن قيمة ص:","options":["تزيد بمقدار ٣","تتضاعف ثلاث مرات","تبقى ثابتة","تقل إلى الثلث"],"answer":3,"why":"لأن حاصل الضرب س × ص يظل ثابتًا."},{"type":"mcq","q":"تناسب طردي فيه ص = ٢١ عندما س = ٧. ما ثابت التناسب ك؟","options":["٣","١٤٧","١٤","١/٣"],"answer":0,"why":"ك = ص ÷ س = ٢١ ÷ ٧ = ٣."},{"type":"tfr","q":"في التناسب العكسي، حاصل ضرب أي زوج متقابل (س × ص) يساوي مقدارًا ثابتًا.","answer":true,"reasons":["بل المجموع ثابت","بل حاصل القسمة ثابت","وهو ثابت التناسب ك = س × ص"],"reason":2},{"type":"tfr","q":"إذا كانت تكلفة ٤ كجم تفاح ٣٫٢ ريالات، فإن تكلفة ١ كجم تساوي ٠٫٨ ريال.","answer":true,"reasons":["طريقة الوحدة: ٣٫٢ ÷ ٤ = ٠٫٨ ريال","تساوي ١٫٢ ريال","تساوي ٠٫٤ ريال"],"reason":0},{"type":"tfr","q":"عند ثبات المسافة، تتناسب السرعة طرديًا مع الزمن.","answer":false,"reasons":["نعم طرديًا","بل عكسيًا؛ كلما زادت السرعة قل الزمن","لا علاقة بينهما"],"reason":1},{"type":"essay","q":"قارن بين التناسب الطردي والتناسب العكسي من حيث المعادلة وثابت التناسب ومثال حياتي لكل منهما.","model":"الطردي: ص = ك س، ك = ص÷س، مثل عدد الكتب وثمنها. العكسي: ص = ك/س، ك = س×ص، مثل السرعة والزمن لمسافة ثابتة."},{"type":"essay","q":"إذا كانت ص تتناسب طرديًا مع س، وكانت ص = ٣٥ عندما س = ٥، اكتب المعادلة وأوجد ص عندما س = ٩.","model":"ك = ٣٥ ÷ ٥ = ٧، المعادلة ص = ٧س. عندما س = ٩ ← ص = ٧ × ٩ = ٦٣."},{"type":"essay","q":"في جدول: (س=٢، ص=١٨)، (س=٣، ص=١٢)، (س=٦، ص=٦). حدّد نوع التناسب واكتب المعادلة.","model":"س×ص = ٢×١٨ = ٣×١٢ = ٦×٦ = ٣٦ (ثابت). إذن تناسب عكسي ومعادلته ص = ٣٦ ÷ س."}]}},
  {"id":"g9-math-2-u10-5","grade":"g9","subject":"math","term":2,"unit":10,"no":5,"title":"زيادة أو نقصان الكمية بنسبة مُعطاة","summary":"شرح متحرك بـ SVG لدرس زيادة أو نقصان الكمية بنسبة مُعطاة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-percentage-increase-decrease.html","video":"","pdf":"","notes":["زيادة س٪ ← × (١ + س/١٠٠)؛ نقصان س٪ ← × (١ − س/١٠٠).","إيجاد القيمة الأصلية (العكسية) = القيمة الجديدة ÷ عامل الضرب.","انتبه للنسب الصغيرة: ٥٪ = ٠٫٠٥ ← عامل الزيادة ١٫٠٥ وليس ١٫٥."],"exercises":["بعد زيادة بنسبة ١٥٪ أصبح سعر تذكرة طيران ٩٢ ريالًا. احسب السعر الأصلي قبل الزيادة.","متجر أعلن عن خصم ٣٠٪، فدفع ناصر ٢٨ ريالًا ثمنًا لمعطف. ما السعر الأصلي للمعطف؟","أثبت عدديًا أن زيادة مبلغ ١٠٠ ريال بنسبة ٢٥٪ ثم تخفيض الناتج بنسبة ٢٠٪ يعيده إلى ١٠٠ ريال."],"levels":{"easy":[{"type":"mcq","q":"ما عامل الضرب لزيادة كمية بنسبة ١٢٪؟","options":["١٢","٠٫١٢","٠٫٨٨","١٫١٢"],"answer":3,"why":"١ + ٠٫١٢ = ١٫١٢."},{"type":"mcq","q":"ما عامل الضرب لنقصان كمية بنسبة ١٥٪؟","options":["٠٫٨٥","١٫١٥","٠٫١٥","٨٥"],"answer":0,"why":"١ − ٠٫١٥ = ٠٫٨٥."},{"type":"mcq","q":"جهاز حاسوب سعره ٣٠٠ ريال قبل ضريبة ٥٪. ما سعره الشامل للضريبة؟","options":["٣٠٥ ريالات","٣١٥ ريالًا","٣٥٠ ريالًا","٢٨٥ ريالًا"],"answer":1,"why":"٣٠٠ × ١٫٠٥ = ٣١٥ ريالًا."},{"type":"mcq","q":"خُفّض سعر حقيبة بنسبة ٢٥٪ فأصبح ١٥ ريالًا. ما سعرها الأصلي؟","options":["٢٥ ريالًا","١٨٫٧٥ ريالًا","٢٠ ريالًا","١٩ ريالًا"],"answer":2,"why":"١٥ ÷ ٠٫٧٥ = ٢٠ ريالًا."}],"medium":[{"type":"mcq","q":"ما عامل الضرب لزيادة كمية بنسبة ٤٪؟","options":["٠٫٠٤","١٫٤","٠٫٩٦","١٫٠٤"],"answer":3,"why":"٤٪ = ٠٫٠٤ ← ١ + ٠٫٠٤ = ١٫٠٤."},{"type":"mcq","q":"ارتفع عدد زوار معرض الكتاب بنسبة ٢٠٪ فأصبح ٦٠٠٠ زائر. كم كان عددهم الأصلي؟","options":["٥٠٠٠ زائر","٤٨٠٠ زائر","٥٨٠٠ زائر","٧٢٠٠ زائر"],"answer":0,"why":"٦٠٠٠ ÷ ١٫٢٠ = ٥٠٠٠ زائر."},{"type":"mcq","q":"إذا خُفّض سعر سلعة بمقدار ٣٠٪، فإن سعرها الجديد يساوي السعر الأصلي مضروبًا في:","options":["٠٫٣٠","٠٫٧٠","١٫٣٠","٣٫٠"],"answer":1,"why":"١٠٠٪ − ٣٠٪ = ٧٠٪ = ٠٫٧٠."},{"type":"tfr","q":"لإيجاد السعر الأصلي بعد خصم ٢٠٪، نقسم السعر الجديد على ٠٫٨٠.","answer":true,"reasons":["نضرب في ١٫٢٠","لأن السعر الجديد يمثل ٨٠٪ من السعر الأصلي","نقسم على ٠٫٢٠"],"reason":1},{"type":"tfr","q":"زيادة سعر بنسبة ١٠٪ ثم تخفيضه بنسبة ١٠٪ يعيده تمامًا إلى سعره الأصلي.","answer":false,"reasons":["بل يزيد ١٪","نعم يلغي كل منهما الآخر","بل يصبح ٠٫٩٩ من الأصل أي أقل بـ ١٪"],"reason":2},{"type":"essay","q":"بعد زيادة بنسبة ١٥٪ أصبح سعر تذكرة طيران ٩٢ ريالًا. احسب السعر الأصلي قبل الزيادة.","model":"عامل الضرب = ١٫١٥. السعر الأصلي = ٩٢ ÷ ١٫١٥ = ٨٠ ريالًا عُمانيًا."},{"type":"essay","q":"متجر أعلن عن خصم ٣٠٪، فدفع ناصر ٢٨ ريالًا ثمنًا لمعطف. ما السعر الأصلي للمعطف؟","model":"عامل الضرب = ٠٫٧٠. السعر الأصلي = ٢٨ ÷ ٠٫٧٠ = ٤٠ ريالًا."}],"hard":[{"type":"mcq","q":"زادت كمية بنسبة ٢٠٪ ثم نقصت بنسبة ٢٠٪. ما النتيجة الصافية مقارنة بالأصل؟","options":["زيادة ٤٪","لا تتغير","نقصان ٤٪","نقصان ٢٠٪"],"answer":2,"why":"١٫٢ × ٠٫٨ = ٠٫٩٦ أي نقصان صافي ٤٪."},{"type":"mcq","q":"عامل الضرب ٠٫٩٣ يمثل:","options":["زيادة بنسبة ٩٣٪","نقصانًا بنسبة ٩٣٪","زيادة بنسبة ٧٪","نقصانًا بنسبة ٧٪"],"answer":3,"why":"١ − ٠٫٩٣ = ٠٫٠٧ = ٧٪ نقصان."},{"type":"mcq","q":"سعر دراجة ٦٠ ريالًا، ما سعرها بعد خصم ٣٥٪؟","options":["٣٩ ريالًا","٢١ ريالًا","٢٥ ريالًا","٤٥ ريالًا"],"answer":0,"why":"٦٠ × ٠٫٦٥ = ٣٩ ريالًا."},{"type":"mcq","q":"عامل الضرب ١٫٢٥ يمثل:","options":["نقصانًا بنسبة ٢٥٪","زيادة بنسبة ٢٥٪","زيادة بنسبة ١٢٥٪","زيادة بنسبة ٢٫٥٪"],"answer":1,"why":"١٫٢٥ − ١ = ٠٫٢٥ = ٢٥٪ زيادة."},{"type":"tfr","q":"عامل الضرب لزيادة ٥٪ هو ١٫٥.","answer":false,"reasons":["بل ١٫٠٥؛ أما ١٫٥ فتمثل زيادة ٥٠٪","نعم ١٫٥","بل ٠٫٩٥"],"reason":0},{"type":"tfr","q":"عامل الضرب ١٫٠٠ يعني عدم حدوث أي زيادة أو نقصان.","answer":true,"reasons":["يعني زيادة ١٠٠٪","لأن ضرب أي عدد في ١ يبقيه كما هو","يعني نقصان ١٠٠٪"],"reason":1},{"type":"tfr","q":"يمكن حساب السعر الشامل لضريبة ٥٪ بضرب السعر الأصلي في ١٫٠٥.","answer":true,"reasons":["بضربه في ٠٫٠٥","بضربه في ٠٫٩٥","لأن ١٠٠٪ + ٥٪ = ١٠٥٪ = ١٫٠٥"],"reason":2},{"type":"essay","q":"أثبت عدديًا أن زيادة مبلغ ١٠٠ ريال بنسبة ٢٥٪ ثم تخفيض الناتج بنسبة ٢٠٪ يعيده إلى ١٠٠ ريال.","model":"١٠٠ × ١٫٢٥ = ١٢٥ ريالًا؛ ثم ١٢٥ × ٠٫٨٠ = ١٠٠ ريال (لأن ١٫٢٥ × ٠٫٨٠ = ١)."},{"type":"essay","q":"سعر ثلاجة ٢٤٠ ريالًا، خُفّض بنسبة ١٠٪ في الأسبوع الأول، ثم خُفّض السعر الجديد بنسبة ١٠٪ أخرى. ما السعر النهائي؟","model":"٢٤٠ × ٠٫٩ × ٠٫٩ = ٢٤٠ × ٠٫٨١ = ١٩٤٫٤ ريالًا عُمانيًا."},{"type":"essay","q":"اشرح لماذا يخطئ من يحسب السعر الأصلي بعد خصم ٢٥٪ بضرب السعر الجديد في ١٫٢٥.","model":"لأن ٢٥٪ من السعر المخفّض أقل من ٢٥٪ من السعر الأصلي؛ الصواب هو القسمة على ٠٫٧٥."}]}},
  {"id":"g9-math-2-u11-1","grade":"g9","subject":"math","term":2,"unit":11,"no":1,"title":"فكّ أكثر من مجموعتَي أقواس","summary":"شرح متحرك بـ SVG لدرس فكّ أكثر من مجموعتَي أقواس (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-expanding-brackets.html","video":"","pdf":"","notes":["فك ٣ أقواس: فك قوسين أولًا وبسّطهما، ثم اضرب الناتج في القوس الثالث.","احذر: (س + أ)³ ≠ س³ + أ³؛ بل = (س+أ)(س+أ)².","تحقق دائمًا من ناتج الفك بالتعويض بـ س = ١ في السؤال والناتج."],"exercises":["فك العبارة (س + ٢)(س − ١)(س + ٤) وبسّطها، ثم تحقق من إجابتك عند س = ١.","فك وبسّط العبارة (س − ٣)³.","صندوق على شكل متوازي مستطيلات أبعاده (س+١)، (س+٣)، (٢س−١). اكتب عبارة حجمه في أبسط صورة."],"levels":{"easy":[{"type":"mcq","q":"ما ناتج فك (س + ١)(س + ٢)(س + ٣)؟","options":["س³ + ٦س² + ١١س + ٦","س³ + ٦","س³ + ٥س² + ٦س + ٦","س³ + ٦س² + ٦س + ٦"],"answer":0,"why":"فك أول قوسين س²+٣س+٢ ثم الضرب في (س+٣) يعطي س³+٦س²+١١س+٦."},{"type":"mcq","q":"ما الحد الثابت (المطلق) في مفكوك (س − ٢)(س + ٣)(س − ٤)؟","options":["−٢٤","+٢٤","−٩","+١٢"],"answer":1,"why":"الحد الثابت = (−٢)(+٣)(−٤) = +٢٤."},{"type":"mcq","q":"ما ناتج فك (س + ١)³؟","options":["س³ + ٢س² + ٢س + ١","س³ + ١","س³ + ٣س² + ٣س + ١","س³ + ٣س + ١"],"answer":2,"why":"(س+١)(س²+٢س+١) = س³ + ٣س² + ٣س + ١."},{"type":"mcq","q":"ما درجة العبارة الناتجة من ضرب ثلاثة أقواس خطية في س؟","options":["الدرجة الرابعة","الدرجة الثانية","الدرجة الأولى","الدرجة الثالثة (تكعيبية)"],"answer":3,"why":"س × س × س = س³."}],"medium":[{"type":"mcq","q":"ما معامل س² في مفكوك (س + ٢)(س + ٣)(س + ٤)؟","options":["٩","٢٤","٢٦","٦"],"answer":0,"why":"معامل س² يساوي مجموع الأعداد ٢ + ٣ + ٤ = ٩."},{"type":"mcq","q":"ما ناتج فك (س − ١)(س + ١)(س + ٢)؟","options":["س³ − ٢س² + س − ٢","س³ + ٢س² − س − ٢","س³ + ٢س² + س + ٢","س³ − ٢"],"answer":1,"why":"(س²−١)(س+٢) = س³ + ٢س² − س − ٢."},{"type":"mcq","q":"ما ناتج فك (س − ٢)³؟","options":["س³ − ٦س² − ١٢س − ٨","س³ − ٨","س³ − ٦س² + ١٢س − ٨","س³ + ٦س² + ١٢س + ٨"],"answer":2,"why":"(س−٢)(س²−٤س+٤) = س³ − ٦س² + ١٢س − ٨."},{"type":"tfr","q":"(س + ٢)³ تساوي س³ + ٨.","answer":false,"reasons":["تساوي س³ + ٦س + ٨","نعم الأس يتوزع على الجمع","ينقصها الحدود الوسطى؛ الصواب س³ + ٦س² + ١٢س + ٨"],"reason":2},{"type":"tfr","q":"يمكن فك أي قوسين أولًا في حاصل ضرب ثلاثة أقواس لأن الضرب تجميعي وإبدالي.","answer":true,"reasons":["ويُفضّل البدء بأسهل قوسين ثم الضرب في الثالث","يجب البدء من اليمين دائمًا","تتغير النتيجة بتغيير الترتيب"],"reason":0},{"type":"essay","q":"فك العبارة (س + ٢)(س − ١)(س + ٤) وبسّطها، ثم تحقق من إجابتك عند س = ١.","model":"(س+٢)(س−١)=س²+س−٢. بالضرب في (س+٤): س³+٤س²+س²+٤س−٢س−٨ = س³+٥س²+٢س−٨. تحقق عند س=١: (٣)(٠)(٥)=٠، و١+٥+٢−٨=٠."},{"type":"essay","q":"فك وبسّط العبارة (س − ٣)³.","model":"(س−٣)(س²−٦س+٩) = س³ − ٦س² + ٩س − ٣س² + ١٨س − ٢٧ = س³ − ٩س² + ٢٧س − ٢٧."}],"hard":[{"type":"mcq","q":"للتحقق السريع من صحة فك (س+أ)(س+ب)(س+ج) يمكننا:","options":["قسمة الناتج على ٣","جمع المعاملات فقط دون تعويض","حذف الحد الأوسط","التعويض بقيمة بسيطة مثل س = ١ في الطرفين"],"answer":3,"why":"تساوي القيمتين عند س = ١ يؤكد دقة الفك."},{"type":"mcq","q":"متوازي مستطيلات أبعاده س، (س+١)، (س+٢). ما عبارة حجمه المفكوكة؟","options":["س³ + ٣س² + ٢س","س³ + ٢","س² + ٣س + ٢","٣س + ٣"],"answer":0,"why":"س(س² + ٣س + ٢) = س³ + ٣س² + ٢س."},{"type":"mcq","q":"ما معامل س³ في مفكوك (٢س + ١)(س − ١)(٣س + ٢)؟","options":["٥","٦","٢","٣"],"answer":1,"why":"٢س × س × ٣س = ٦س³."},{"type":"mcq","q":"كم حدًا ينتج قبل التبسيط عند ضرب مقدار من ٣ حدود في قوس من حدّين؟","options":["٣ حدود","٥ حدود","٦ حدود","٩ حدود"],"answer":2,"why":"٣ × ٢ = ٦ حدود ثم نجمع المتشابه منها."},{"type":"tfr","q":"الحد المطلق في مفكوك (س + أ)(س + ب)(س + ج) يساوي أ × ب × ج.","answer":true,"reasons":["يساوي أ + ب + ج","لأنه ناتج ضرب الثوابت الثلاثة معًا","يساوي صفرًا دائمًا"],"reason":1},{"type":"tfr","q":"ناتج فك (س − ١)(س + ١)(س + ٥) هو س³ + ٥س² − س − ٥.","answer":true,"reasons":["لأنه س³ − ٥","لأنه س³ + ٥س² + س + ٥","لأن (س² − ١)(س + ٥) = س³ + ٥س² − س − ٥"],"reason":2},{"type":"tfr","q":"فك ثلاثة أقواس خطية في س يعطي دائمًا عبارة تربيعية.","answer":false,"reasons":["بل عبارة تكعيبية من الدرجة الثالثة","نعم تربيعية","يعطي عبارة خطية"],"reason":0},{"type":"essay","q":"صندوق على شكل متوازي مستطيلات أبعاده (س+١)، (س+٣)، (٢س−١). اكتب عبارة حجمه في أبسط صورة.","model":"(س+١)(س+٣) = س²+٤س+٣. بالضرب في (٢س−١): ٢س³ − س² + ٨س² − ٤س + ٦س − ٣ = ٢س³ + ٧س² + ٢س − ٣."},{"type":"essay","q":"فك وبسّط (س + ٢)(س − ٢)(س + ٥).","model":"أولًا فرق بين مربعين: (س+٢)(س−٢) = س²−٤. ثم (س²−٤)(س+٥) = س³ + ٥س² − ٤س − ٢٠."},{"type":"essay","q":"اكتشف الخطأ في قول طالب: «(س + ٤)³ = س³ + ٦٤» وصحّحه.","model":"الخطأ توزيع الأس على الجمع وإغفال الحدود الوسطى. الصواب: (س+٤)(س²+٨س+١٦) = س³ + ١٢س² + ٤٨س + ٦٤."}]}},
  {"id":"g9-math-2-u11-2","grade":"g9","subject":"math","term":2,"unit":11,"no":2,"title":"تحليل العبارات الجبرية إلى عوامل","summary":"شرح متحرك بـ SVG لدرس تحليل العبارات الجبرية إلى عوامل (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-factorising-expressions.html","video":"","pdf":"","notes":["أخرج ع.م.أ دائمًا في البداية قبل أي خطوة تحليل.","فرق المربعين: أ² − ب² = (أ−ب)(أ+ب)، بينما مجموع المربعين لا يتحلل حقيقيًا.","في أ س² + ب س + ج نبحث عن عددين ضربهما أ×ج ومجموعهما ب."],"exercises":["حلّل تحليلًا تامًا: ٣س² − ٢٧.","حلّل العبارة التربيعية: ٢س² + ٧س − ١٥ بخطوات واضحة.","احسب قيمة ٩٩² − ١ ذهنيًا باستخدام تحليل الفرق بين مربعين."],"levels":{"easy":[{"type":"mcq","q":"حلّل العبارة س² − ٤٩ تحليلًا تامًا:","options":["(س − ٧)²","(س − ٧)(س + ٧)","(س + ٧)²","(س − ٤٩)(س + ١)"],"answer":1,"why":"فرق بين مربعين: س² − ٧² = (س − ٧)(س + ٧)."},{"type":"mcq","q":"حلّل س² + ٨س + ١٥ إلى عاملين:","options":["(س − ٣)(س − ٥)","(س + ١)(س + ١٥)","(س + ٣)(س + ٥)","(س + ٢)(س + ٦)"],"answer":2,"why":"٣ × ٥ = ١٥ و ٣ + ٥ = ٨."},{"type":"mcq","q":"حلّل س² − ٣س − ١٠:","options":["(س − ١٠)(س + ١)","(س + ٥)(س − ٢)","(س − ٥)(س − ٢)","(س − ٥)(س + ٢)"],"answer":3,"why":"(−٥)(+٢) = −١٠ و −٥ + ٢ = −٣."},{"type":"mcq","q":"حلّل ٢س² − ١٨ تحليلًا تامًا:","options":["٢(س − ٣)(س + ٣)","٢(س² − ٩)","(٢س − ٦)(س + ٣)","٢(س − ٩)(س + ١)"],"answer":0,"why":"نخرج ع.م.أ وهو ٢ أولًا ثم نحلّل الفرق بين مربعين."}],"medium":[{"type":"mcq","q":"حلّل ٢س² + ٥س + ٣:","options":["(٢س + ١)(س + ٣)","(٢س + ٣)(س + ١)","(٢س − ٣)(س − ١)","(س + ٣)(س + ٢)"],"answer":1,"why":"فكّها: ٢س² + ٢س + ٣س + ٣ = ٢س² + ٥س + ٣."},{"type":"mcq","q":"حلّل ٣س² − ١٢س بإخراج ع.م.أ:","options":["س(٣س − ١٢)","٣(س² − ٤س)","٣س(س − ٤)","٣س(س + ٤)"],"answer":2,"why":"العامل المشترك الأكبر هو ٣س."},{"type":"mcq","q":"حلّل ٤س² − ٢٥:","options":["(٢س − ٢٥)(٢س + ١)","(٤س − ٥)(س + ٥)","(٢س − ٥)²","(٢س − ٥)(٢س + ٥)"],"answer":3,"why":"فرق بين مربعين: (٢س)² − ٥²."},{"type":"tfr","q":"العبارة س² + ١٦ يمكن تحليلها إلى (س + ٤)(س + ٤).","answer":false,"reasons":["مفكوك (س+٤)² هو س²+٨س+١٦، أما س²+١٦ فلا تتحلل حقيقيًا","نعم مجموع مربعين يتحلل هكذا","تتحلل إلى (س−٤)(س+٤)"],"reason":0},{"type":"tfr","q":"أول خطوة في أي مسألة تحليل هي البحث عن العامل المشترك الأكبر.","answer":true,"reasons":["نبحث عن ع.م.أ في النهاية فقط","لأن إخراجه يبسّط العبارة ويكشف التحليل التالي","ع.م.أ لا يُستخدم مع التربيعية"],"reason":1},{"type":"essay","q":"حلّل تحليلًا تامًا: ٣س² − ٢٧.","model":"نخرج ع.م.أ = ٣: ٣(س² − ٩) = ٣(س − ٣)(س + ٣)."},{"type":"essay","q":"حلّل العبارة التربيعية: ٢س² + ٧س − ١٥ بخطوات واضحة.","model":"أ×ج = −٣٠؛ العددان +١٠ و−٣. ٢س² + ١٠س − ٣س − ١٥ = ٢س(س+٥) − ٣(س+٥) = (٢س−٣)(س+٥)."}],"hard":[{"type":"mcq","q":"أي العبارات الآتية تمثل مربعًا كاملًا؟","options":["س² + ٦س + ٩","س² + ٦س + ٦","س² + ٩","س² − ٦س − ٩"],"answer":0,"why":"س² + ٦س + ٩ = (س + ٣)²."},{"type":"mcq","q":"حلّل بالتجميع: أس + ٢أ + ٣س + ٦:","options":["(س + ٣)(أ + ٢)","(س + ٢)(أ + ٣)","(س − ٢)(أ + ٣)","(أ + ٦)(س + ١)"],"answer":1,"why":"أ(س+٢) + ٣(س+٢) = (س+٢)(أ+٣)."},{"type":"mcq","q":"حلّل ٣س² + ١٠س − ٨:","options":["(٣س − ٤)(س + ٢)","(٣س + ٢)(س − ٤)","(٣س − ٢)(س + ٤)","(٣س + ٤)(س − ٢)"],"answer":2,"why":"٣س² + ١٢س − ٢س − ٨ = ٣س² + ١٠س − ٨."},{"type":"mcq","q":"مستطيل مساحته س² + ٩س + ٢٠، إذا كان أحد بعديه (س + ٤) فما البعد الآخر؟","options":["س + ٤","س + ١٦","س − ٥","س + ٥"],"answer":3,"why":"س² + ٩س + ٢٠ = (س + ٤)(س + ٥)."},{"type":"tfr","q":"في الثلاثي س² + ب س + ج، إذا كان ج سالبًا فإن إشارتَي القوسين مختلفتان.","answer":true,"reasons":["تكونان سالبتين دائمًا","تكونان متشابهتين","لأن حاصل ضرب عددين يكون سالبًا فقط عند اختلاف إشارتيهما"],"reason":2},{"type":"tfr","q":"التحليل التام للعبارة ٥س² − ٢٠ هو ٥(س² − ٤).","answer":false,"reasons":["لم يكتمل؛ س²−٤ فرق مربعين فالتحليل التام ٥(س−٢)(س+٢)","نعم هذا تحليل تام","الصواب ٥(س−٤)²"],"reason":0},{"type":"tfr","q":"يمكن التحقق من صحة التحليل بإعادة فك الأقواس الناتجة.","answer":true,"reasons":["لا يمكن التحقق بالفك","لأن التحليل وفك الأقواس عمليتان متعاكستان","التحقق يكون بالقسمة فقط"],"reason":1},{"type":"essay","q":"احسب قيمة ٩٩² − ١ ذهنيًا باستخدام تحليل الفرق بين مربعين.","model":"٩٩² − ١² = (٩٩ − ١)(٩٩ + ١) = ٩٨ × ١٠٠ = ٩٨٠٠."},{"type":"essay","q":"حلّل العبارة ذات الحدود الأربعة: ٢س ص − ٦س + ٥ص − ١٥.","model":"٢س(ص − ٣) + ٥(ص − ٣) = (ص − ٣)(٢س + ٥)."},{"type":"essay","q":"فسّر لماذا س² − ٩ تتحلّل بينما س² + ٩ لا تتحلّل في الأعداد الحقيقية.","model":"س² − ٩ فرق مربعين (س−٣)(س+٣) لأن الحدين الأوسطين +٣س و−٣س يلغيان بعضهما، أما س² + ٩ فموجبة دائمًا ولا جذر حقيقي لها."}]}},
  {"id":"g9-math-2-u11-3","grade":"g9","subject":"math","term":2,"unit":11,"no":3,"title":"حلّ المُعادلات التربيعية","summary":"شرح متحرك بـ SVG لدرس حلّ المُعادلات التربيعية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-solving-quadratic-equations.html","video":"","pdf":"","notes":["رتّب المعادلة أولًا: أ س² + ب س + ج = ٠، ولا تقسم على س أبدًا.","القانون العام: س = (−ب ± √(ب² − ٤أج)) ÷ (٢أ).","إشارة المميّز ب² − ٤أج تحدد عدد الحلول الحقيقية (موجب: ٢، صفر: ١، سالب: ٠)."],"exercises":["حلّ المعادلة س² − ٢س − ١٥ = ٠ بالتحليل إلى عوامل.","حلّ المعادلة ٢س² + ٥س − ٣ = ٠ باستخدام القانون العام.","حلّ المعادلة س² − ٦س − ٢ = ٠ بإكمال المربع لأقرب منزلتين عشريتين."],"levels":{"easy":[{"type":"mcq","q":"ما حلا المعادلة (س − ٤)(س + ٧) = ٠؟","options":["س = ٤ أو س = ٧","س = −٤ أو س = ٧","س = ٤ أو س = −٧","س = −٤ أو س = −٧"],"answer":2,"why":"بخاصية الضرب الصفري نساوي كل قوس بالصفر."},{"type":"mcq","q":"ما حلا المعادلة س² − ٩س + ٢٠ = ٠؟","options":["٤ و −٥","−٤ و −٥","٢ و ١٠","٤ و ٥"],"answer":3,"why":"(س − ٤)(س − ٥) = ٠ ← س = ٤ أو ٥."},{"type":"mcq","q":"ما حلا المعادلة س² = ٦س؟","options":["٠ و ٦","٦ فقط","−٦ و ٦","٠ و −٦"],"answer":0,"why":"س(س − ٦) = ٠ ← س = ٠ أو س = ٦."},{"type":"mcq","q":"ما حلا المعادلة ٢س² − ٥س − ٣ = ٠؟","options":["−٣ و ١/٢","٣ و −١/٢","٣ و ١/٢","−٣ و −١/٢"],"answer":1,"why":"(٢س + ١)(س − ٣) = ٠ ← س = −١/٢ أو س = ٣."}],"medium":[{"type":"mcq","q":"عند حل س² + ٨س − ٩ = ٠ بإكمال المربع، ما القوس المربع المكافئ لـ س² + ٨س؟","options":["(س + ٤)² + ١٦","(س + ٨)² − ٦٤","(س + ٤)² − ١٦","(س − ٤)² − ١٦"],"answer":2,"why":"نصف ٨ هو ٤ ومربعه ١٦."},{"type":"mcq","q":"في المعادلة ٣س² − ٢س − ٥ = ٠، ما قيم أ، ب، ج في القانون العام؟","options":["أ=١، ب=−٢، ج=−٥","أ=٣، ب=٢، ج=٥","أ=٣، ب=−٢، ج=٥","أ=٣، ب=−٢، ج=−٥"],"answer":3,"why":"نأخذ كل معامل مع إشارته."},{"type":"mcq","q":"كم عدد الحلول الحقيقية للمعادلة س² − ٦س + ٩ = ٠؟","options":["حل حقيقي وحيد (س = ٣)","حلّان مختلفان","لا توجد حلول حقيقية","ثلاثة حلول"],"answer":0,"why":"(س − ٣)² = ٠ ← س = ٣ فقط (المميّز = ٠)."},{"type":"tfr","q":"قسمة طرفَي المعادلة س² = ٥س على س طريقة صحيحة لإيجاد جميع الحلول.","answer":false,"reasons":["نعم تعطي الحل الوحيد س = ٥","تضيع الحل س = ٠؛ الصواب التحليل س(س − ٥) = ٠","تزيد عدد الحلول"],"reason":1},{"type":"tfr","q":"يمكن تطبيق خاصية الضرب الصفري فقط عندما يكون أحد طرفي المعادلة مساويًا للصفر.","answer":true,"reasons":["لا يشترط وجود الصفر","يمكن تطبيقها لأي عدد","فإذا كان (س−١)(س−٢) = ٦ لا يجوز مساواة كل قوس بـ ٦"],"reason":2},{"type":"essay","q":"حلّ المعادلة س² − ٢س − ١٥ = ٠ بالتحليل إلى عوامل.","model":"(س − ٥)(س + ٣) = ٠ ← س = ٥ أو س = −٣."},{"type":"essay","q":"حلّ المعادلة ٢س² + ٥س − ٣ = ٠ باستخدام القانون العام.","model":"أ=٢، ب=٥، ج=−٣. المميّز = ٢٥ − ٤(٢)(−٣) = ٤٩. س = (−٥ ± ٧) ÷ ٤ ← س = ١/٢ أو س = −٣."}],"hard":[{"type":"mcq","q":"ما قيمة المميّز ب² − ٤أج للمعادلة س² + ٤س + ٥ = ٠؟","options":["+٣٦","−٤ (لا حل حقيقي)","٠","+٤"],"answer":1,"why":"١٦ − ٤(١)(٥) = ١٦ − ٢٠ = −٤ < ٠."},{"type":"mcq","q":"ما حلا المعادلة س² − ٣٦ = ٠؟","options":["٣٦ و −٣٦","٦ فقط","٦ و −٦","٠ و ٦"],"answer":2,"why":"(س − ٦)(س + ٦) = ٠ ← س = ±٦."},{"type":"mcq","q":"إذا طُلِب في الاختبار حل معادلة تربيعية «لأقرب منزلتين عشريتين»، فأنسب طريقة هي:","options":["التحليل فقط","التخمين العشوائي","القسمة على س","القانون العام (أو إكمال المربع)"],"answer":3,"why":"لأن الجذور غالبًا غير نسبية ولا تتحلل بأعداد صحيحة."},{"type":"mcq","q":"ما حلا المعادلة (س − ٢)² = ٢٥؟","options":["٧ و −٣","٧ فقط","٢٧ و −٢٣","٥ و −٥"],"answer":0,"why":"س − ٢ = ±٥ ← س = ٧ أو س = −٣."},{"type":"tfr","q":"القانون العام يحل أي معادلة تربيعية لها حلول حقيقية حتى لو لم تتحلل بأعداد صحيحة.","answer":true,"reasons":["لأنه صيغة عامة مشتقة من إكمال المربع","يعمل فقط للمعادلات القابلة للتحليل","يعمل فقط عندما أ = ١"],"reason":0},{"type":"tfr","q":"إذا كان المميّز ب² − ٤أج < ٠ فإن للمعادلة التربيعية حلّين حقيقيين.","answer":false,"reasons":["لها حلّان سالبان","بل لا توجد لها حلول حقيقية لعدم وجود جذر حقيقي لعدد سالب","لها حل واحد فقط"],"reason":1},{"type":"tfr","q":"المعادلة س² + ٤ = ٠ ليس لها حلول في الأعداد الحقيقية.","answer":true,"reasons":["حلها ٠","حلاها ٢ و−٢","لأن س² = −٤ ومربع أي عدد حقيقي غير سالب"],"reason":2},{"type":"essay","q":"حلّ المعادلة س² − ٦س − ٢ = ٠ بإكمال المربع لأقرب منزلتين عشريتين.","model":"(س − ٣)² − ٩ − ٢ = ٠ ← (س − ٣)² = ١١ ← س = ٣ ± √١١ ≈ ٦٫٣٢ أو −٠٫٣٢."},{"type":"essay","q":"أعاد طالب حلّ المعادلة (س−١)(س+٢) = ٤ بكتابة س−١=٤ أو س+٢=٤. بيّن خطأه واكتب الحل الصحيح.","model":"خاصية الضرب الصفري تعمل فقط مع الصفر. الصواب: س²+س−٢=٤ ← س²+س−٦=٠ ← (س+٣)(س−٢)=٠ ← س=−٣ أو س=٢."},{"type":"essay","q":"متى يكون للمعادلة التربيعية حلّان حقيقيان؟ ومتى يكون لها حل وحيد؟ ومتى لا يكون لها حل حقيقي؟","model":"حسب المميّز ب²−٤أج: إن كان موجبًا فحلّان، وإن كان صفرًا فحل وحيد مكرر، وإن كان سالبًا فلا حل حقيقي."}]}},
  {"id":"g9-math-2-u11-4","grade":"g9","subject":"math","term":2,"unit":11,"no":4,"title":"مسائل تطبيقية على حلّ المُعادلات التربيعية","summary":"شرح متحرك بـ SVG لدرس مسائل تطبيقية على حلّ المُعادلات التربيعية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-quadratic-word-problems.html","video":"","pdf":"","notes":["افرض المجهول س، اكتب المعادلة، حلّها، ثم افحص منطقية الحلول.","ارفض الحل السالب في الأطوال والأزمنة والأعمار، واحتفظ به في مسائل الأعداد غير المشروطة.","عند إضافة إطار بعرض س حول مستطيل من كل الجهات، أضف ٢س لكل من الطول والعرض."],"exercises":["مستطيل يزيد طوله على مثلي عرضه بمقدار ١ سم، ومساحته ٥٥ سم². أوجد أبعاده.","مثلث قائم الزاوية أطوال أضلاعه (س−١)، س، (س+١) سم. أوجد أطوال أضلاعه الثلاثة.","مجموع عدد موجب ومربعه يساوي ٤٢. ما هو العدد؟"],"levels":{"easy":[{"type":"mcq","q":"مستطيل يزيد طوله على عرضه بـ ٣ سم ومساحته ٤٠ سم². ما عرضه؟","options":["١٠ سم","٨ سم","٤ سم","٥ سم"],"answer":3,"why":"س(س+٣)=٤٠ ← س²+٣س−٤٠=٠ ← (س+٨)(س−٥)=٠ ← س=٥ سم."},{"type":"mcq","q":"عددان موجبان متتاليان حاصل ضربهما ٧٢. ما هما؟","options":["٨ و ٩","٧ و ١٠","٦ و ١٢","−٩ و −٨"],"answer":0,"why":"س(س+١)=٧٢ ← س=٨ (نرفض −٩ لأنه طلب موجبين)."},{"type":"mcq","q":"لماذا نرفض الحل س = −٦ عند إيجاد طول ضلع حديقة؟","options":["لأنه عدد زوجي","لأن الأطوال كميات موجبة لا تكون سالبة","لأنه لا يحقق المعادلة","لأن المساحة سالبة"],"answer":1,"why":"الطول والزمن والعمر يجب أن تكون موجبة."},{"type":"mcq","q":"مثلث قائم الزاوية ضلعا القائمة فيه س و(س+١) والوتر ٥ سم. ما قيمة س؟","options":["٢ سم","٤ سم","٣ سم","٥ سم"],"answer":2,"why":"س²+(س+١)²=٢٥ ← ٢س²+٢س−٢٤=٠ ← س²+س−١٢=٠ ← س=٣."}],"medium":[{"type":"mcq","q":"عددان زوجيان موجبان متتاليان حاصل ضربهما ٤٨. ما العدد الأكبر؟","options":["١٢","٦","١٠","٨"],"answer":3,"why":"س(س+٢)=٤٨ ← س=٦ والأكبر ٨."},{"type":"mcq","q":"مستطيل محيطه ٢٠ سم ومساحته ٢٤ سم². إذا كان عرضه س فطوله يساوي:","options":["١٠ − س","٢٠ − س","١٠ + س","٢٤ − س"],"answer":0,"why":"نصف المحيط = الطول + العرض = ١٠ ← الطول = ١٠ − س."},{"type":"mcq","q":"قُذفت كرة لأعلى وفق ع = ١٥ن − ٥ن². بعد كم ثانية تصل إلى الأرض مجددًا؟","options":["٥ ثوانٍ","٣ ثوانٍ","١٥ ثانية","ثانية واحدة"],"answer":1,"why":"٥ن(٣ − ن) = ٠ ← ن = ٠ (انطلاق) أو ن = ٣ ثوانٍ."},{"type":"tfr","q":"في مسائل الأعداد الصحيحة دون شرط «موجبة»، قد يكون كلا الحلّين (الموجب والسالب) مقبولين.","answer":true,"reasons":["السالب مقبول للأطوال فقط","نرفض السالب دائمًا في كل المسائل","مثل ٧ و٨ وكذلك −٨ و−٧ لحاصل ضرب ٥٦"],"reason":2},{"type":"tfr","q":"إذا أُضيف ممر عرضه س حول حديقة مستطيلة من الجهات الأربع، فإن الطول الجديد يزيد بمقدار س فقط.","answer":false,"reasons":["بل يزيد بمقدار ٢س (س من كل طرف)","يزيد بمقدار ٤س","لا يتغير الطول"],"reason":0},{"type":"essay","q":"مستطيل يزيد طوله على مثلي عرضه بمقدار ١ سم، ومساحته ٥٥ سم². أوجد أبعاده.","model":"العرض = س، الطول = ٢س + ١. س(٢س+١)=٥٥ ← ٢س²+س−٥٥=٠ ← (٢س+١١)(س−٥)=٠ ← س=٥ سم (العرض)، الطول = ١١ سم."},{"type":"essay","q":"مثلث قائم الزاوية أطوال أضلاعه (س−١)، س، (س+١) سم. أوجد أطوال أضلاعه الثلاثة.","model":"(س−١)²+س²=(س+١)² ← س²−٢س+١+س²=س²+٢س+١ ← س²−٤س=٠ ← س=٤ (لأن س=٠ مرفوض). الأضلاع: ٣، ٤، ٥ سم."}],"hard":[{"type":"mcq","q":"مربع طول ضلعه س زيد بمقدار ٢ سم فأصبحت مساحته ٤٩ سم². ما طول ضلعه الأصلي؟","options":["٣ سم","٧ سم","٥ سم","٩ سم"],"answer":2,"why":"(س+٢)² = ٤٩ ← س + ٢ = ٧ ← س = ٥ سم."},{"type":"mcq","q":"مثلث ارتفاعه يزيد على قاعدته بـ ٢ سم ومساحته ٢٤ سم². ما طول قاعدته؟","options":["١٢ سم","٨ سم","٤ سم","٦ سم"],"answer":3,"why":"١/٢ س(س+٢)=٢٤ ← س²+٢س−٤٨=٠ ← س=٦ سم."},{"type":"mcq","q":"عند إحاطة لوحة أبعادها ٥ سم × ٨ سم بإطار متساوي العرض س من جميع الجهات، يصبح الطول الكلي:","options":["٨ + ٢س","٨ + س","٨ × ٢س","٥ + ٨ + س"],"answer":0,"why":"الإطار يضاف من الجانبين الأيمن والأيسر معًا (+٢س)."},{"type":"mcq","q":"مجموع مربعي عددين صحيحين موجبين متتاليين هو ٦١. ما هما؟","options":["٤ و ٥","٥ و ٦","٦ و ٧","٣ و ٤"],"answer":1,"why":"٥² + ٦² = ٢٥ + ٣٦ = ٦١."},{"type":"tfr","q":"في مسائل المساحة التي تقود إلى معادلة تربيعية، يجب التحقق أن الطول والعرض الناتجين موجبان.","answer":true,"reasons":["يكفي أن يكون أحدهما موجبًا","لأن الأبعاد الهندسية موجبة دائمًا","لا يشترط ذلك"],"reason":1},{"type":"tfr","q":"إذا كان محيط مستطيل ٢٦ م، فإن مجموع طوله وعرضه يساوي ١٣ م.","answer":true,"reasons":["يساوي ٥٢ م","يساوي ٢٦ م","لأن المحيط = ٢(الطول + العرض)"],"reason":2},{"type":"tfr","q":"مساحة المثلث تساوي القاعدة × الارتفاع دون ضرب في ١/٢.","answer":false,"reasons":["بل مساحة المثلث = ١/٢ × القاعدة × الارتفاع","نعم بدون ١/٢","بل القاعدة + الارتفاع"],"reason":0},{"type":"essay","q":"مجموع عدد موجب ومربعه يساوي ٤٢. ما هو العدد؟","model":"س + س² = ٤٢ ← س² + س − ٤٢ = ٠ ← (س+٧)(س−٦)=٠ ← س = ٦ (نرفض −٧ لأنه طلب موجبًا)."},{"type":"essay","q":"تُعطى المسافة الرأسية لحجر يُقذف لأعلى بالعلاقة ع = ٢٥ن − ٥ن². متى يكون الحجر على ارتفاع ٢٠ مترًا؟","model":"٢٥ن − ٥ن² = ٢٠ ← ٥ن² − ٢٥ن + ٢٠ = ٠ ÷ ٥ ← ن² − ٥ن + ٤ = ٠ ← (ن−١)(ن−٤)=٠ ← بعد ١ ثانية (صعودًا) و٤ ثوانٍ (هبوطًا)."},{"type":"essay","q":"غرفة مربعة الشكل، إذا زيد طولها ٣ أمتار ونقص عرضها مترًا واحدًا أصبحت مساحتها ٤٥ م². أوجد طول ضلع الغرفة الأصلي.","model":"(س+٣)(س−١)=٤٥ ← س²+٢س−٣=٤٥ ← س²+٢س−٤٨=٠ ← (س+٨)(س−٦)=٠ ← س = ٦ أمتار."}]}},
  {"id":"g9-math-2-u12-1","grade":"g9","subject":"math","term":2,"unit":12,"no":1,"title":"التطابق","summary":"شرح متحرك بـ SVG لدرس التطابق (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-congruence.html","video":"","pdf":"","notes":["التطابق (≅): تساوي الشكل والقياس تمامًا.","الحالات الأربع: (ض،ض،ض)، (ض،ز،ض)، (ز،ض،ز)، (ق،و،ض).","(ز،ز،ز) تُثبت التشابه فقط، و(ض،ض،ز) لا تكفي للتطابق."],"exercises":["اذكر حالات تطابق المثلثين الأربع مع شرح موجز لكل حالة.","في مثلث متطابق الضلعين أ ب ج (أ ب = أ ج)، رُسم عمود أ د من الرأس أ على القاعدة ب ج. أثبت أن △أ ب د ≅ △أ ج د.","أعطِ مثالًا لمثلثين لهما نفس الزوايا لكنهما غير متطابقين، وفسّر السبب."],"levels":{"easy":[{"type":"mcq","q":"أي مما يأتي ليس من حالات تطابق المثلثين؟","options":["(ز، ز، ز)","(ض، ض، ض)","(ض، ز، ض)","(ق، و، ض)"],"answer":0,"why":"تساوي الزوايا الثلاث فقط يثبت التشابه لا التطابق."},{"type":"mcq","q":"إذا كان △أ ب ج ≅ △س ص ع وكان أ ب = ٧ سم، فما طول س ص؟","options":["١٤ سم","٧ سم","٣٫٥ سم","لا يمكن تحديده"],"answer":1,"why":"الأضلاع المتناظرة في المثلثين المتطابقين متساوية الطول."},{"type":"mcq","q":"ما حالة التطابق التي تثبت تطابق مثلثين قائمين تساوى فيهما الوتر وضلع قائمة؟","options":["(ز، ض، ز)","(ض، ض، ض)","(ق، و، ض)","(ز، ز، ز)"],"answer":2,"why":"قائم ووتر وضلع (RHS)."},{"type":"mcq","q":"في الحالة (ض، ز، ض)، يجب أن تكون الزاوية المعلومة:","options":["خارج المثلث","مقابلة لأكبر ضلع","قائمة دائمًا","محصورة بين الضلعين المعلومين"],"answer":3,"why":"شرط SAS هو أن تكون الزاوية محصورة بين الضلعين."}],"medium":[{"type":"mcq","q":"إذا كان △أ ب ج ≅ △د هـ و وكانت ∠أ = ٥٠° و∠ب = ٦٠°، فما قياس ∠و؟","options":["٧٠°","٥٠°","٦٠°","١١٠°"],"answer":0,"why":"∠ج = ١٨٠° − (٥٠+٦٠) = ٧٠°، و∠و تناظر ∠ج."},{"type":"mcq","q":"قُطر متوازي الأضلاع يقسمه إلى مثلثين متطابقين بحسب حالة:","options":["(ز، ز، ز)","(ض، ض، ض) أو (ز، ض، ز)","(ق، و، ض) دائمًا","لا يتطابقان"],"answer":1,"why":"الأضلاع المتقابلة متساوية والقطر ضلع مشترك (ض،ض،ض)."},{"type":"mcq","q":"هل يتأثر تطابق شكلين إذا أجرينا لأحدهما دورانًا أو انعكاسًا؟","options":["يبقيان متشابهين فقط","نعم، يزول التطابق","لا، يبقيان متطابقين","تتغير مساحتهما"],"answer":2,"why":"الدوران والانعكاس والانسحاب تحافظ على الأطوال والزوايا."},{"type":"tfr","q":"الشكلان المتطابقان لهما نفس المساحة ونفس المحيط دائمًا.","answer":true,"reasons":["لتساوي جميع أبعادهما وزواياهما المتناظرة","قد تختلف مساحتهما","يتساويان في المحيط فقط"],"reason":0},{"type":"tfr","q":"تساوي جميع الزوايا المتناظرة في مثلثين يكفي لإثبات تطابقهما.","answer":false,"reasons":["نعم يكفي للتطابق","بل يكفي للتشابه فقط وليس التطابق","يكفي إذا كانا حادي الزوايا"],"reason":1},{"type":"essay","q":"اذكر حالات تطابق المثلثين الأربع مع شرح موجز لكل حالة.","model":"١) (ض،ض،ض): تساوي الأضلاع الثلاثة. ٢) (ض،ز،ض): ضلعان والزاوية المحصورة بينهما. ٣) (ز،ض،ز): زاويتان وضلع متناظر. ٤) (ق،و،ض): في القائم، تساوي الوتر وضلع قائمة."},{"type":"essay","q":"في مثلث متطابق الضلعين أ ب ج (أ ب = أ ج)، رُسم عمود أ د من الرأس أ على القاعدة ب ج. أثبت أن △أ ب د ≅ △أ ج د.","model":"∠أ د ب = ∠أ د ج = ٩٠° (ق)، أ ب = أ ج (و)، أ د ضلع مشترك (ض). إذن يتطابقان بحالة (ق،و،ض)."}],"hard":[{"type":"mcq","q":"تساوى في مثلثين ضلعان وزاوية غير محصورة بينهما؛ هل هذا يكفي دائمًا لإثبات التطابق؟","options":["يثبت أنهما متساويتا المساحة فقط","نعم يكفي دائمًا","يكفي للمنفرج فقط","لا يكفي دائمًا (إلا في حالة القائم والوتر)"],"answer":3,"why":"الحالة ASS لا تثبت التطابق عمومًا."},{"type":"mcq","q":"مربعان محيط كل منهما ٢٤ سم، العلاقة بينهما أنهما:","options":["متطابقان","متشابهان فقط","مختلفان في المساحة","غير متطابقين"],"answer":0,"why":"طول ضلع كل منهما ٦ سم وجميع زواياهما ٩٠°."},{"type":"mcq","q":"في مثلثين: أ ب = د هـ = ٨ سم، ∠ب = ∠هـ = ٤٠°، ب ج = هـ و = ٥ سم. حالة التطابق هي:","options":["(ض، ض، ض)","(ض، ز، ض)","(ز، ض، ز)","(ق، و، ض)"],"answer":1,"why":"ضلعان والزاوية المحصورة بينهما."},{"type":"mcq","q":"لماذا يُعدّ المثلث الشكل الأكثر ثباتًا في بناء الجسور والرافعات؟","options":["لأن مساحته أكبر ما يمكن","لأن زواياه قائمة","لأن ثبات أضلاعه الثلاثة يثبّت زواياه (ض، ض، ض)","لأنه يحتوي ٤ أضلاع"],"answer":2,"why":"تثبيت الأطوال الثلاثة يمنع تغيّر الشكل هندسيًا."},{"type":"tfr","q":"الضلع المشترك بين مثلثين يُحسب كضلع متساوٍ في برهان التطابق.","answer":true,"reasons":["يُحسب كزاوية","لا يُعدّ ضمن الشروط","لأنه نفس القطعة المستقيمة في كلا المثلثين"],"reason":2},{"type":"tfr","q":"أي شكلين لهما نفس المساحة يكونان بالضرورة متطابقين.","answer":false,"reasons":["مثل مستطيل ٢×٦ ومستطيل ٣×٤، مساحتهما ١٢ لكنهما غير متطابقين","نعم تساوي المساحة يعني التطابق","صحيح للمستطيلات فقط"],"reason":0},{"type":"tfr","q":"في برهان التطابق، يجب كتابة الرؤوس المتناظرة بنفس الترتيب.","answer":true,"reasons":["الترتيب عشوائي","لتحديد الأضلاع والزوايا المتساوية بدقة","يهم في المربعات فقط"],"reason":1},{"type":"essay","q":"أعطِ مثالًا لمثلثين لهما نفس الزوايا لكنهما غير متطابقين، وفسّر السبب.","model":"مثلث متطابق الأضلاع ضلعه ٤ سم وآخر ضلعه ٨ سم؛ جميع الزوايا ٦٠° لكن الأضلاع غير متساوية، لذا هما متشابهان لا متطابقان."},{"type":"essay","q":"مستطيلان متساويان في المساحة (٢٤ سم²): الأول ٤×٦ والثاني ٣×٨. هل هما متطابقان؟ علّل.","model":"لا، لأن أضلاعهما المتناظرة غير متساوية الطول؛ فتساوي المساحة وحده لا يكفي للتطابق."},{"type":"essay","q":"إذا كان △أ ب ج ≅ △ل م ن، وكان أ ب = ٩ سم، م ن = ١٢ سم، ∠ج = ٣٥°، فأوجد ل م، ب ج، ∠ن.","model":"ل م = أ ب = ٩ سم، ب ج = م ن = ١٢ سم، ∠ن = ∠ج = ٣٥°."}]}},
  {"id":"g9-math-2-u12-2","grade":"g9","subject":"math","term":2,"unit":12,"no":2,"title":"التشابه","summary":"شرح متحرك بـ SVG لدرس التشابه (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-similarity.html","video":"","pdf":"","notes":["التشابه: زوايا متساوية وأضلاع متناسبة بمعامل قياس ك.","الزوايا لا تُضرب في ك أبدًا، بينما الأطوال والمحيط تُضرب في ك.","في المثلثات المتداخلة قارن ضلع الصغير بكامل ضلع الكبير."],"exercises":["أثبت أن المستطيل الذي أبعاده ٥ سم × ٨ سم لا يشابه المستطيل الذي أبعاده ٨ سم × ١١ سم.","△أ ب ج يشابه △س ص ع، حيث أ ب = ٦ سم، ب ج = ٩ سم، س ص = ١٠ سم. احسب طول ص ع.","رُسمت قطعة د هـ توازي قاعدة مثلث ب ج بحيث أ د = ٤ سم، د ب = ٦ سم، د هـ = ٥ سم. احسب طول ب ج."],"levels":{"easy":[{"type":"mcq","q":"أي الأشكال الآتية تكون متشابهة دائمًا؟","options":["جميع المستطيلات","جميع المربعات","جميع المعينات","جميع المثلثات القائمة"],"answer":1,"why":"المربعات جميع زواياها ٩٠° وأضلاعها متساوية فتتناسب دائمًا."},{"type":"mcq","q":"مثلثان متشابهان، ضلع في الأول ٦ سم ونظيره في الثاني ١٥ سم. ما معامل التكبير ك؟","options":["٠٫٤","٩","٢٫٥","٣"],"answer":2,"why":"ك = ١٥ ÷ ٦ = ٢٫٥."},{"type":"mcq","q":"في مثلثين متشابهين معامل التكبير ٣. إذا كانت زاوية في الأول ٤٠°، فما قياس نظيرتها في الثاني؟","options":["٨٠°","١٢٠°","١٣٫٣°","٤٠°"],"answer":3,"why":"الزوايا المتناظرة في الأشكال المتشابهة متساوية ولا تُضرب في ك."},{"type":"mcq","q":"يكفي لإثبات تشابه مثلثين تساوي:","options":["زاويتين متناظرتين","ضلعين متناظرين","زاوية واحدة فقط","المساحتين"],"answer":0,"why":"تساوي زاويتين يضمن تساوي الثالثة (حالة ز، ز)."}],"medium":[{"type":"mcq","q":"مستطيلان متشابهان: أبعاد الأول ٤ سم × ٦ سم، وعرض الثاني ١٠ سم. ما طول الثاني؟","options":["١٢ سم","١٥ سم","١٦ سم","١٤ سم"],"answer":1,"why":"ك = ١٠ ÷ ٤ = ٢٫٥؛ الطول = ٦ × ٢٫٥ = ١٥ سم."},{"type":"mcq","q":"إذا كان معامل القياس بين شكلين متشابهين ك = ١، فإن الشكلين:","options":["مختلفان في المساحة","غير متشابهين","متطابقان","متعامدان"],"answer":2,"why":"التشابه بمعامل قياس ١ هو تطابق تام."},{"type":"mcq","q":"مثلث أضلاعه ٣، ٤، ٥ سم يشابه مثلثًا أصغر أضلاعه ٩ سم. ما طول أطول ضلع في المثلث الكبير؟","options":["١٠ سم","١٢ سم","٢٠ سم","١٥ سم"],"answer":3,"why":"ك = ٩ ÷ ٣ = ٣ ← أطول ضلع = ٥ × ٣ = ١٥ سم."},{"type":"tfr","q":"عند تكبير مثلث بمعامل قياس ٢، تتضاعف قياسات زواياه أيضًا.","answer":false,"reasons":["نعم تتضاعف الزوايا","الزوايا تبقى ثابتة تمامًا في التشابه","تقل إلى النصف"],"reason":1},{"type":"tfr","q":"كل مثلثين متطابقين هما بالضرورة متشابهان.","answer":true,"reasons":["فقط في القائم الزاوية","التطابق ينفي التشابه","ومعامل القياس بينهما يساوي ١"],"reason":2},{"type":"essay","q":"أثبت أن المستطيل الذي أبعاده ٥ سم × ٨ سم لا يشابه المستطيل الذي أبعاده ٨ سم × ١١ سم.","model":"رغم تساوي الزوايا (٩٠°)، إلا أن نسبة العرضين ٨/٥ = ١٫٦ ونسبة الطولين ١١/٨ = ١٫٣٧٥، وبما أن النسبتين مختلفتان فالمستطيلان غير متشابهين."},{"type":"essay","q":"△أ ب ج يشابه △س ص ع، حيث أ ب = ٦ سم، ب ج = ٩ سم، س ص = ١٠ سم. احسب طول ص ع.","model":"معامل القياس ك = ١٠ ÷ ٦ = ٥/٣. إذن ص ع = ٩ × (٥/٣) = ١٥ سم."}],"hard":[{"type":"mcq","q":"عند رسم قطعة توازي قاعدة مثلث وتقطع ضلعيه في منتصفيهما، فإن طولها يساوي:","options":["نصف القاعدة","ضعف القاعدة","ثلث القاعدة","مساويًا للقاعدة"],"answer":0,"why":"المثلث الصغير يشابه الكبير بمعامل ١/٢."},{"type":"mcq","q":"في مثلثين متشابهين نسبة التشابه ٢ : ٥. إذا كان محيط الأصغر ١٦ سم، فما محيط الأكبر؟","options":["٣٢ سم","٤٠ سم","١٠٠ سم","٢٠ سم"],"answer":1,"why":"المحيطات تتناسب بنفس معامل الأطوال: ١٦ × (٥/٢) = ٤٠ سم."},{"type":"mcq","q":"هل المستطيل ٤×٦ يشابه المستطيل ٦×٨؟","options":["نعم لأن الفرق ٢ في كليهما","نعم لأن زواياهما ٩٠°","لا، لأن ٤/٦ ≠ ٦/٨","نعم دائمًا"],"answer":2,"why":"٤/٦ = ٠٫٦٧ بينما ٦/٨ = ٠٫٧٥، النسبتان غير متساويتين."},{"type":"mcq","q":"في مثلثين متشابهين، إذا كان أ ب / د هـ = ب ج / هـ و = ٤/٣، وكان أ ب = ١٢ سم، فما طول د هـ؟","options":["١٥ سم","١٦ سم","٨ سم","٩ سم"],"answer":3,"why":"١٢ / د هـ = ٤/٣ ← د هـ = (١٢ × ٣) ÷ ٤ = ٩ سم."},{"type":"tfr","q":"جميع المستطيلات متشابهة لأن جميع زواياها قائمة.","answer":false,"reasons":["لا بد أيضًا من تناسب الأضلاع المتناظرة","نعم جميع المستطيلات متشابهة","فقط إذا كان محيطها زوجيًا"],"reason":0},{"type":"tfr","q":"النسبة بين محيطَي مضلعين متشابهين تساوي معامل القياس ك نفسه.","answer":true,"reasons":["تساوي ك²","لأن المحيط مجموع أطوال أضلاع خطية","تساوي ك³"],"reason":1},{"type":"tfr","q":"المستقيم الموازي لأحد أضلاع مثلث والقاطع للضلعين الآخرين يقطع منه مثلثًا مشابهًا للأصلي.","answer":true,"reasons":["لا علاقة بين المثلثين","يقطع مثلثًا متطابقًا","لتساوي الزوايا المتناظرة واشتراك زاوية الرأس"],"reason":2},{"type":"essay","q":"رُسمت قطعة د هـ توازي قاعدة مثلث ب ج بحيث أ د = ٤ سم، د ب = ٦ سم، د هـ = ٥ سم. احسب طول ب ج.","model":"طول الضلع الكامل أ ب = ٤ + ٦ = ١٠ سم. ك = ١٠ ÷ ٤ = ٢٫٥. إذن ب ج = ٥ × ٢٫٥ = ١٢٫٥ سم."},{"type":"essay","q":"قارن بين التطابق والتشابه في جدول من حيث: الزوايا، الأضلاع، ومعامل القياس.","model":"الزوايا: متساوية في كليهما. الأضلاع: متساوية في التطابق، ومتناسبة في التشابه. معامل القياس: ك=١ في التطابق، وأي عدد موجب ك في التشابه."},{"type":"essay","q":"مثلث أضلاعه ٥، ٧، ١٠ سم يشابه مثلثًا آخر محيطه ٦٦ سم. أوجد أطوال أضلاع المثلث الآخر.","model":"محيط الأول = ٥+٧+١٠ = ٢٢ سم. معامل القياس ك = ٦٦ ÷ ٢٢ = ٣. الأضلاع: ١٥، ٢١، ٣٠ سم."}]}},
  {"id":"g9-math-2-u12-3","grade":"g9","subject":"math","term":2,"unit":12,"no":3,"title":"تطبيقات على التشابه","summary":"شرح متحرك بـ SVG لدرس تطبيقات على التشابه (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-similarity-applications.html","video":"","pdf":"","notes":["أطوال ومحيط: ك | مساحات: ك² | حجوم وسعات وكتل: ك³.","مرّ دائمًا عبر ك عند الانتقال بين المساحة والحجم.","الظلال في نفس اللحظة تكوّن مثلثات قائمة متشابهة لقياس الارتفاعات."],"exercises":["علبتا تمر متشابهتان: ارتفاع الصغيرة ١٠ سم وسعتها ٢٥٠ جم، وارتفاع الكبيرة ٢٠ سم. احسب سعة العلبة الكبيرة.","مجسمان متشابهان مساحتا سطحهما ٢٥ سم² و١٠٠ سم². إذا كان حجم الأصغر ٤٠ سم³، فأوجد حجم الأكبر.","في ساحة مدرسة بصحار، وقف طالب طوله ١٫٦ م فكان طول ظله ٢ م، بينما كان طول ظل مئذنة مجاورة ١٥ م. احسب ارتفاع المئذنة."],"levels":{"easy":[{"type":"mcq","q":"إذا تضاعفت جميع أبعاد مجسم متشابه مرتين (ك = ٢)، فكم مرة يتضاعف حجمه؟","options":["٤ مرات","مرتين","٨ مرات","٦ مرات"],"answer":2,"why":"نسبة الحجوم = ك³ = ٢³ = ٨."},{"type":"mcq","q":"شكلان متشابهان نسبة أطوالهما ١ : ٤. ما نسبة مساحتيهما؟","options":["١ : ٦٤","١ : ٤","١ : ٨","١ : ١٦"],"answer":3,"why":"نسبة المساحات = ١² : ٤² = ١ : ١٦."},{"type":"mcq","q":"طول ظل عمود إنارة ٨ م، وفي نفس اللحظة طول ظل عصا ارتفاعها ١٫٥ م يساوي ٢ م. ما ارتفاع العمود؟","options":["٦ أمتار","١٢ مترًا","٤ أمتار","١٠٫٦ أمتار"],"answer":0,"why":"الارتفاع = ١٫٥ × (٨ ÷ ٢) = ٦ أمتار."},{"type":"mcq","q":"مضلعان متشابهان مساحتاهما ٩ سم² و٣٦ سم². ما معامل قياس الأطوال ك؟","options":["٤","٢","١٦","٣"],"answer":1,"why":"ك² = ٣٦ ÷ ٩ = ٤ ← ك = √٤ = ٢."}],"medium":[{"type":"mcq","q":"مجسمان متشابهان حجماهما ١٠ سم³ و٢٧٠ سم³. ما نسبة أطوالهما؟","options":["١ : ٩","١ : ٢٧","١ : ٣","١ : ٨١"],"answer":2,"why":"ك³ = ٢٧٠ ÷ ١٠ = ٢٧ ← ك = ∛٢٧ = ٣."},{"type":"mcq","q":"زجاجتا عطر متشابهتان ارتفاعاهما ٦ سم و١٢ سم. إذا كانت سعة الصغيرة ٥٠ مل، فما سعة الكبيرة؟","options":["٦٠٠ مل","١٠٠ مل","٢٠٠ مل","٤٠٠ مل"],"answer":3,"why":"ك = ٢ ← ك³ = ٨ ← ٥٠ × ٨ = ٤٠٠ مل."},{"type":"mcq","q":"خريطتان متشابهتان لمعامل أطوال ٣. إذا كانت مساحة منطقة على الصغيرة ١٥ سم²، فما مساحتها على الكبيرة؟","options":["١٣٥ سم²","٤٥ سم²","٤٠٥ سم²","٣٠ سم²"],"answer":0,"why":"ك² = ٩ ← ١٥ × ٩ = ١٣٥ سم²."},{"type":"tfr","q":"نسبة المساحة بين شكلين متشابهين تساوي مربع معامل القياس ك.","answer":true,"reasons":["تساوي ك³","تساوي ك فقط","لأن المساحة حاصل ضرب بُعدين (ك × ك = ك²)"],"reason":2},{"type":"tfr","q":"إذا كان ارتفاع كوب كبير ضعف ارتفاع كوب صغير مشابه له، فإن سعة الكبير ضعف سعة الصغير.","answer":false,"reasons":["بل ٨ أضعاف (٢³ = ٨) لأن السعة حجم","نعم الضعف فقط","بل ٤ أضعاف"],"reason":0},{"type":"essay","q":"علبتا تمر متشابهتان: ارتفاع الصغيرة ١٠ سم وسعتها ٢٥٠ جم، وارتفاع الكبيرة ٢٠ سم. احسب سعة العلبة الكبيرة.","model":"ك = ٢٠ ÷ ١٠ = ٢. نسبة الحجوم (والكتل) = ٢³ = ٨. سعة الكبيرة = ٢٥٠ × ٨ = ٢٠٠٠ جم = ٢ كجم."},{"type":"essay","q":"مجسمان متشابهان مساحتا سطحهما ٢٥ سم² و١٠٠ سم². إذا كان حجم الأصغر ٤٠ سم³، فأوجد حجم الأكبر.","model":"ك² = ١٠٠ ÷ ٢٥ = ٤ ← ك = ٢. ك³ = ٨. حجم الأكبر = ٤٠ × ٨ = ٣٢٠ سم³."}],"hard":[{"type":"mcq","q":"مجسمان متشابهان نسبة مساحتَي سطحهما ٤ : ٩. ما نسبة حجميهما؟","options":["١٦ : ٨١","٨ : ٢٧","٢ : ٣","٤ : ٩"],"answer":1,"why":"ك = ٢/٣ ← ك³ = ٨ : ٢٧."},{"type":"mcq","q":"إذا زيد طول ضلع مربع ٣ مرات، فإن مساحته تصبح أكبر بـ:","options":["٦ مرات","٣ مرات","٩ مرات","٢٧ مرة"],"answer":2,"why":"٣² = ٩ مرات."},{"type":"mcq","q":"تمثال مصغّر لقلعة بنسبة ١ : ١٠ من الحجم الحقيقي (للطول). إذا كان حجم النموذج ٢ لتر، فكم حجم الأصلي؟","options":["٢٠٠٠٠ لتر","٢٠ لترًا","٢٠٠ لتر","٢٠٠٠ لتر"],"answer":3,"why":"ك = ١٠ ← ك³ = ١٠٠٠ ← ٢ × ١٠٠٠ = ٢٠٠٠ لتر."},{"type":"mcq","q":"أي مما يأتي يتناسب مع ك (وليس ك² أو ك³)؟","options":["المحيط","المساحة الجانبية","الحجم","الكتلة لنفس المادة"],"answer":0,"why":"المحيط طول خطي يتناسب مع ك."},{"type":"tfr","q":"لحساب نسبة الحجوم من نسبة المساحات، نأخذ الجذر التربيعي لإيجاد ك ثم نكعّبه.","answer":true,"reasons":["نضرب نسبة المساحة في ٣","مساحة (ك²) → ك → حجم (ك³)","نربّع نسبة المساحة"],"reason":1},{"type":"tfr","q":"يمكن قياس ارتفاع شجرة نخيل عالية بمقارنة طول ظلها مع ظل عصا معلومة الطول في نفس اللحظة.","answer":true,"reasons":["ينجح عند منتصف الليل فقط","لا علاقة للظل بالتشابه","لأن أشعة الشمس المتوازية تكوّن مثلثين قائمين متشابهين"],"reason":2},{"type":"tfr","q":"إذا تضاعف نصف قطر كرة ٣ مرات، تتضاعف مساحتها السطحية ٩ مرات وحجمها ٢٧ مرة.","answer":true,"reasons":["ك=٣ ← ك²=٩ للمساحة، ك³=٢٧ للحجم","كلاهما يتضاعف ٣ مرات","المساحة ٢٧ والحجم ٩"],"reason":0},{"type":"essay","q":"في ساحة مدرسة بصحار، وقف طالب طوله ١٫٦ م فكان طول ظله ٢ م، بينما كان طول ظل مئذنة مجاورة ١٥ م. احسب ارتفاع المئذنة.","model":"ارتفاع المئذنة / ١٫٦ = ١٥ / ٢ ← الارتفاع = ١٫٦ × ٧٫٥ = ١٢ مترًا."},{"type":"essay","q":"مثلثان متشابهان مساحتاهما ١٨ سم² و٥٠ سم². إذا كان محيط الأصغر ٢٤ سم، فأوجد محيط الأكبر.","model":"ك² = ٥٠ ÷ ١٨ = ٢٥/٩ ← ك = ٥/٣. محيط الأكبر = ٢٤ × (٥/٣) = ٤٠ سم."},{"type":"essay","q":"فسّر عمليًا لماذا تكلف علبة عصير أبعادها ضعف علبة صغيرة ٨ أضعاف كمية العصير لكنها تحتاج ٤ أضعاف ورق الكرتون فقط.","model":"العصير يملأ الحجم (يتناسب مع ك³ = ٨)، بينما ورق الكرتون يغطي مساحة السطح (يتناسب مع ك² = ٤)."}]}},
  {"id":"g9-math-2-u13-1","grade":"g9","subject":"math","term":2,"unit":13,"no":1,"title":"الزمن","summary":"شرح متحرك بـ SVG لدرس الزمن (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-time-calculations.html","video":"","pdf":"","notes":["نظام ٢٤ ساعة: أضف ١٢ لأوقات المساء (١م–١١م)، ومنتصف الليل = 00:00.","عشري ← دقائق (×٦٠) | دقائق ← عشري (÷٦٠).","استخدم طريقة القفز للساعة الكاملة لحساب المدد الزمنية دون أخطاء."],"exercises":["انطلقت رحلة مدرسية من نزوى الساعة 06:45 صباحًا وعادت الساعة 03:20 عصرًا. احسب المدة الكلية للرحلة.","حوّل كلاً مما يأتي: (أ) ٣ ساعات و١٢ دقيقة إلى ساعات عشرية. (ب) ١٫٦٥ ساعة إلى ساعات ودقائق.","أقلعت طائرة من مسقط (GMT+4) الساعة 09:30 صباحًا متجهة إلى لندن (GMT+0) في رحلة مدتها ٧ ساعات و٢٠ دقيقة. ما وقت الوصول بالتوقيت المحلي للندن؟"],"levels":{"easy":[{"type":"mcq","q":"كيف يُكتب الوقت ٧:٣٥ مساءً بنظام ٢٤ ساعة؟","options":["21:35","07:35","17:35","19:35"],"answer":3,"why":"٧ + ١٢ = ١٩ ← 19:35."},{"type":"mcq","q":"ما الزمن المكافئ لـ ٢٫٤ ساعة بالساعات والدقائق؟","options":["ساعتان و٢٤ دقيقة","ساعتان و٤٠ دقيقة","ساعتان و٤ دقائق","ساعتان و١٥ دقيقة"],"answer":0,"why":"٠٫٤ × ٦٠ = ٢٤ دقيقة."},{"type":"mcq","q":"حوّل ساعة و٤٥ دقيقة إلى ساعات عشرية:","options":["١٫٤٥ ساعة","١٫٧٥ ساعة","١٫٥ ساعة","١٫٢٥ ساعة"],"answer":1,"why":"٤٥ ÷ ٦٠ = ٠٫٧٥ ← ١٫٧٥ ساعة."},{"type":"mcq","q":"غادرت حافلة مسقط الساعة 07:35 ووصلت صحار الساعة 10:15. ما مدة الرحلة؟","options":["ساعتان و٢٠ دقيقة","٣ ساعات و٢٠ دقيقة","ساعتان و٤٠ دقيقة","٣ ساعات و٤٠ دقيقة"],"answer":2,"why":"من 07:35 إلى 08:00 (٢٥د) + ساعتان + ١٥د = ٢س ٤٠د."}],"medium":[{"type":"mcq","q":"كيف يُكتب ١٢:١٥ بعد منتصف الليل بنظام ٢٤ ساعة؟","options":["01:15","12:15","24:15","00:15"],"answer":3,"why":"الساعة ١٢ صباحًا تُكتب 00 في نظام ٢٤ ساعة."},{"type":"mcq","q":"بدأت مباراة الساعة 18:50 واستمرت ساعة و٤٥ دقيقة. متى انتهت؟","options":["20:35","19:95","20:05","19:35"],"answer":0,"why":"18:50 + ١س = 19:50 + ٤٥د = 20:35."},{"type":"mcq","q":"كم ثانية في ساعة ونصف؟","options":["٣٦٠٠ ثانية","٥٤٠٠ ثانية","٩٠ ثانية","١٨٠٠ ثانية"],"answer":1,"why":"١٫٥ × ٣٦٠٠ = ٥٤٠٠ ثانية."},{"type":"tfr","q":"٢٫٥ ساعة تعني ساعتين و٥٠ دقيقة.","answer":false,"reasons":["بل ساعتين و٣٠ دقيقة لأن ٠٫٥ × ٦٠ = ٣٠","نعم ٥٠ دقيقة","تعني ساعتين و٥ دقائق"],"reason":0},{"type":"tfr","q":"لتحويل الدقائق إلى كسر عشري من الساعة نقسم عدد الدقائق على ٦٠.","answer":true,"reasons":["نقسم على ١٠٠","لأن الساعة الواحدة تحتوي ٦٠ دقيقة","نضرب في ٦٠"],"reason":1},{"type":"essay","q":"انطلقت رحلة مدرسية من نزوى الساعة 06:45 صباحًا وعادت الساعة 03:20 عصرًا. احسب المدة الكلية للرحلة.","model":"٠٣:٢٠ عصرًا = 15:20. من 06:45 إلى 07:00 (١٥د) + ٨ ساعات (إلى 15:00) + ٢٠د = ٨ ساعات و٣٥ دقيقة."},{"type":"essay","q":"حوّل كلاً مما يأتي: (أ) ٣ ساعات و١٢ دقيقة إلى ساعات عشرية. (ب) ١٫٦٥ ساعة إلى ساعات ودقائق.","model":"(أ) ٣ + (١٢÷٦٠) = ٣٫٢ ساعات. (ب) ٠٫٦٥ × ٦٠ = ٣٩ دقيقة ← ساعة و٣٩ دقيقة."}],"hard":[{"type":"mcq","q":"الوقت في عُمان (GMT+4) هو 14:00. كم يكون الوقت في لندن (GMT+0) في نفس اللحظة؟","options":["12:00","18:00","10:00","08:00"],"answer":2,"why":"١٤ − ٤ = 10:00."},{"type":"mcq","q":"وصل قطار الساعة 16:20 بعد رحلة استغرقت ٣ ساعات و٣٥ دقيقة. متى انطلق؟","options":["13:45","13:15","12:55","12:45"],"answer":3,"why":"16:20 − ٣س = 13:20 − ٣٥د = 12:45."},{"type":"mcq","q":"كم دقيقة في ٣/٥ ساعة؟","options":["٣٦ دقيقة","٣٠ دقيقة","٤٥ دقيقة","٢٤ دقيقة"],"answer":0,"why":"(٣/٥) × ٦٠ = ٣٦ دقيقة."},{"type":"mcq","q":"أقلعت طائرة الساعة 22:30 واستغرقت رحلتها ٤ ساعات و١٥ دقيقة. متى وصلت؟","options":["02:15 اليوم التالي","02:45 اليوم التالي","03:45 اليوم التالي","01:45 اليوم التالي"],"answer":1,"why":"22:30 + ١س ٣٠د = 00:00؛ المتبقي ٢س ٤٥د ← 02:45."},{"type":"tfr","q":"الساعة 12:00 ظهرًا تُكتب بنظام ٢٤ ساعة على صورة 00:00.","answer":false,"reasons":["تُكتب 24:00","نعم 00:00 للظهر","بل 12:00، أما 00:00 فهي منتصف الليل"],"reason":2},{"type":"tfr","q":"عند استلاف ساعة في طرح الأوقات نضيف ٦٠ إلى خانة الدقائق.","answer":true,"reasons":["لأن ١ ساعة = ٦٠ دقيقة","نضيف ١٠٠","نضيف ١٠"],"reason":0},{"type":"tfr","q":"إذا كان توقيت مسقط يسبق توقيت لندن بـ ٤ ساعات، فإن 15:00 في مسقط توافق 11:00 في لندن.","answer":true,"reasons":["توافق 19:00","١٥ − ٤ = ١١ صباحًا في لندن","توافق 12:00"],"reason":1},{"type":"essay","q":"أقلعت طائرة من مسقط (GMT+4) الساعة 09:30 صباحًا متجهة إلى لندن (GMT+0) في رحلة مدتها ٧ ساعات و٢٠ دقيقة. ما وقت الوصول بالتوقيت المحلي للندن؟","model":"وقت الوصول بتوقيت مسقط = 09:30 + ٧س ٢٠د = 16:50. نطرح فرق التوقيت (٤ ساعات) ← 12:50 ظهرًا بتوقيت لندن."},{"type":"essay","q":"اشرح لماذا يخطئ الطالب الذي يكتب ٢ ساعة و١٥ دقيقة على صورة ٢٫١٥ ساعة عند حساب السرعة.","model":"لأن ١٥ دقيقة تمثل ربع الساعة (١٥÷٦٠ = ٠٫٢٥) وليست ٠٫١٥؛ الصواب ٢٫٢٥ ساعة."},{"type":"essay","q":"يعمل موظف من 07:30 إلى 14:30 يوميًا عدا استراحة ٣٠ دقيقة، لمدة ٥ أيام أسبوعيًا. كم ساعة عمل صافية يعمل في الأسبوع؟","model":"يوميًا: ٧ ساعات − ٠٫٥ ساعة = ٦٫٥ ساعات. أسبوعيًا: ٦٫٥ × ٥ = ٣٢٫٥ ساعة (٣٢ ساعة و٣٠ دقيقة)."}]}},
  {"id":"g9-math-2-u13-2","grade":"g9","subject":"math","term":2,"unit":13,"no":2,"title":"المُعدّلات","summary":"شرح متحرك بـ SVG لدرس المُعدّلات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-rates.html","video":"","pdf":"","notes":["السرعة = المسافة ÷ الزمن، والسرعة المتوسطة = المسافة الكلية ÷ الزمن الكلي.","كم/س ──÷٣٫٦──▶ م/ث | م/ث ──×٣٫٦──▶ كم/س.","وحّد وحدات الزمن إلى ساعات عشرية قبل استخدام سرعة بـ كم/س."],"exercises":["سافرت أسرة من مسقط إلى نزوى (١٦٠ كم) بسرعة ٨٠ كم/س، ثم توقفت ٣٠ دقيقة، ثم واصلت ٨٠ كم إضافية في ساعة ونصف. احسب السرعة المتوسطة للرحلة كاملة.","حوّل ١٠٨ كم/س إلى م/ث، ثم احسب المسافة التي تقطعها السيارة في ١٢ ثانية بهذه السرعة.","متجر يبيع علبة عصير ٦٠٠ مل بـ ٣٠٠ بيسة، وعلبة ١٫٥ لتر بـ ٦٠٠ بيسة. أيهما أوفر؟ وضّح بالحساب."],"levels":{"easy":[{"type":"mcq","q":"تقطع سيارة ١٥٠ كم في ساعة و٣٠ دقيقة. ما سرعتها المتوسطة بـ كم/س؟","options":["١٠٠ كم/س","١١٥ كم/س","٧٥ كم/س","١٢٠ كم/س"],"answer":0,"why":"١س ٣٠د = ١٫٥ ساعة؛ ١٥٠ ÷ ١٫٥ = ١٠٠ كم/س."},{"type":"mcq","q":"حوّل السرعة ٩٠ كم/س إلى م/ث:","options":["٣٢٤ م/ث","٢٥ م/ث","٩ م/ث","٣٠ م/ث"],"answer":1,"why":"٩٠ ÷ ٣٫٦ = ٢٥ م/ث."},{"type":"mcq","q":"حوّل السرعة ١٥ م/ث إلى كم/س:","options":["٤٥ كم/س","٤٫١٧ كم/س","٥٤ كم/س","٦٠ كم/س"],"answer":2,"why":"١٥ × ٣٫٦ = ٥٤ كم/س."},{"type":"mcq","q":"سار طالب ٣ كم في ٣٠ دقيقة ثم ٥ كم في ساعة ونصف. ما سرعته المتوسطة الكلية؟","options":["٦ كم/س","٥ كم/س","٤٫٧ كم/س","٤ كم/س"],"answer":3,"why":"المسافة الكلية = ٨ كم، الزمن الكلي = ٢ ساعة ← ٨ ÷ ٢ = ٤ كم/س."}],"medium":[{"type":"mcq","q":"ما الزمن اللازم لقطع ٢٧٠ كم بسرعة ثابتة ٩٠ كم/س؟","options":["٣ ساعات","٢٫٥ ساعة","٣٫٥ ساعات","٤ ساعات"],"answer":0,"why":"ن = ف ÷ ع = ٢٧٠ ÷ ٩٠ = ٣ ساعات."},{"type":"mcq","q":"يضخّ محرك ماءً بمعدل ٢٥ لترًا/دقيقة. كم دقيقة يحتاج لملء خزان سعته ٥٠٠ لتر؟","options":["٢٥ دقيقة","٢٠ دقيقة","١٢٫٥ دقيقة","٥٠ دقيقة"],"answer":1,"why":"٥٠٠ ÷ ٢٥ = ٢٠ دقيقة."},{"type":"mcq","q":"عبوة أرز ٥ كجم بسعر ٣٫٥ ريالات، وعبوة ٢ كجم بسعر ١٫٥ ريال. أيهما أوفر بالكيلوجرام؟","options":["لهما نفس السعر للوحدة","عبوة ٢ كجم (٠٫٧٥ ريال/كجم)","عبوة ٥ كجم (٠٫٧٠ ريال/كجم)","لا يمكن المقارنة"],"answer":2,"why":"٣٫٥÷٥ = ٠٫٧٠ ريال/كجم أقل من ١٫٥÷٢ = ٠٫٧٥ ريال/كجم."},{"type":"tfr","q":"السرعة المتوسطة لرحلة من مرحلتين تساوي دائمًا نصف مجموع السرعتين.","answer":false,"reasons":["نعم نصف المجموع دائمًا","بل تساوي المسافة الكلية ÷ الزمن الكلي","تساوي حاصل ضرب السرعتين"],"reason":1},{"type":"tfr","q":"للتحويل من كم/س إلى م/ث نقسم على ٣٫٦.","answer":true,"reasons":["نقسم على ٦٠","نضرب في ٣٫٦","لأن ١٠٠٠ م ÷ ٣٦٠٠ ث = ١ ÷ ٣٫٦"],"reason":2},{"type":"essay","q":"سافرت أسرة من مسقط إلى نزوى (١٦٠ كم) بسرعة ٨٠ كم/س، ثم توقفت ٣٠ دقيقة، ثم واصلت ٨٠ كم إضافية في ساعة ونصف. احسب السرعة المتوسطة للرحلة كاملة.","model":"زمن المرحلة الأولى = ١٦٠÷٨٠ = ٢ ساعة. الزمن الكلي = ٢ + ٠٫٥ + ١٫٥ = ٤ ساعات. المسافة الكلية = ٢٤٠ كم. السرعة المتوسطة = ٢٤٠ ÷ ٤ = ٦٠ كم/س."},{"type":"essay","q":"حوّل ١٠٨ كم/س إلى م/ث، ثم احسب المسافة التي تقطعها السيارة في ١٢ ثانية بهذه السرعة.","model":"١٠٨ ÷ ٣٫٦ = ٣٠ م/ث. المسافة = ٣٠ × ١٢ = ٣٦٠ مترًا."}],"hard":[{"type":"mcq","q":"قطعة معدنية كتلتها ٤٥٠ جم وحجمها ٥٠ سم³. ما كثافتها؟","options":["٩٠ جم/سم³","٠٫١١ جم/سم³","٥٠٠ جم/سم³","٩ جم/سم³"],"answer":3,"why":"الكثافة = ٤٥٠ ÷ ٥٠ = ٩ جم/سم³."},{"type":"mcq","q":"تقطع حافلة مسافة بسرعة ٨٠ كم/س لمدة ساعتين و١٥ دقيقة. ما المسافة المقطوعة؟","options":["١٨٠ كم","١٧٢ كم","١٦٠ كم","٢٠٠ كم"],"answer":0,"why":"٢س ١٥د = ٢٫٢٥ ساعة؛ ٨٠ × ٢٫٢٥ = ١٨٠ كم."},{"type":"mcq","q":"أي مما يأتي يعبر عن معدل استهلاك وقود سيارة؟","options":["كم × لتر","كم / لتر","ريال + لتر","سم³"],"answer":1,"why":"المعدل يقارن المسافة المقطوعة لكل لتر وقود."},{"type":"mcq","q":"تطبع طابعة ٤٨ صفحة في ٣ دقائق. كم صفحة تطبع في ٥ دقائق بنفس المعدل؟","options":["٦٠ صفحة","٧٢ صفحة","٨٠ صفحة","٩٦ صفحة"],"answer":2,"why":"المعدل = ١٦ صفحة/دقيقة؛ ١٦ × ٥ = ٨٠ صفحة."},{"type":"tfr","q":"إذا كانت السرعة ٦٠ كم/س والزمن ٤٥ دقيقة، فإن المسافة تساوي ٦٠ × ٠٫٧٥ = ٤٥ كم.","answer":true,"reasons":["بتحويل ٤٥ دقيقة إلى ٠٫٧٥ ساعة أولًا","تساوي ٦٠ × ٤٥","تساوي ٦٠ × ٠٫٤٥"],"reason":0},{"type":"tfr","q":"المعدل يقارن بين كميتين لهما نفس وحدة القياس دائمًا.","answer":false,"reasons":["نعم نفس الوحدة","بل يقارن بين كميتين مختلفتَي الوحدة مثل كم/س أو ريال/كجم","بلا وحدات دائمًا"],"reason":1},{"type":"tfr","q":"وحدة الكثافة جم/سم³ تعني قسمة الكتلة بالجرام على الحجم بالسنتيمتر المكعب.","answer":true,"reasons":["تعني الحجم ÷ الكتلة","تعني ضرب الكتلة في الحجم","لأن إشارة / تدل على القسمة"],"reason":2},{"type":"essay","q":"متجر يبيع علبة عصير ٦٠٠ مل بـ ٣٠٠ بيسة، وعلبة ١٫٥ لتر بـ ٦٠٠ بيسة. أيهما أوفر؟ وضّح بالحساب.","model":"الأولى: ٣٠٠ ÷ ٠٫٦ = ٥٠٠ بيسة/لتر. الثانية: ٦٠٠ ÷ ١٫٥ = ٤٠٠ بيسة/لتر. إذن علبة ١٫٥ لتر أوفر."},{"type":"essay","q":"خزان ماء سعته ٢٤٠٠ لتر يُملأ بمعدل ٤٠ لترًا/دقيقة ويُفرَّغ منه ماء بمعدل ١٠ لترات/دقيقة في نفس الوقت. كم دقيقة تلزم لملئه؟","model":"صافي معدل الملء = ٤٠ − ١٠ = ٣٠ لترًا/دقيقة. الزمن = ٢٤٠٠ ÷ ٣٠ = ٨٠ دقيقة (ساعة و٢٠ دقيقة)."},{"type":"essay","q":"قطعة ذهب كثافتها ١٩٫٣ جم/سم³ وحجمها ٥ سم³. احسب كتلتها بالجرام.","model":"الكتلة = الكثافة × الحجم = ١٩٫٣ × ٥ = ٩٦٫٥ جم."}]}},
  {"id":"g9-math-2-u14-1","grade":"g9","subject":"math","term":2,"unit":14,"no":1,"title":"التمثيل البياني للدوال التربيعية","summary":"شرح متحرك بـ SVG لدرس التمثيل البياني للدوال التربيعية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-quadratic-graphs.html","video":"","pdf":"","notes":["ص = أ س² + ب س + ج ← قطع مكافئ: أ>٠ (∪ صغرى)، أ<٠ (∩ عظمى).","محور التماثل والرأس عند س = −ب/(٢أ)، والمقطع الصادي (٠، ج).","صل نقاط القطع المكافئ بمنحنى أملس باليد، وانتبه لأقواس العدد السالب عند التربيع."],"exercises":["أكمل جدول القيم للدالة ص = س² − ٢س − ٣ لقيم س من −٢ إلى ٤، وحدّد الرأس ومحور التماثل والمقطع الصادي.","أوجد إحداثيي نقطة التحول ونوعها (عظمى أم صغرى) للدالة ص = −س² + ٤س + ١.","كيف يختلف التمثيل البياني لـ ص = س² − ٥ عن التمثيل البياني لـ ص = س²؟"],"levels":{"easy":[{"type":"mcq","q":"ما اتجاه فتحة المنحنى للدالة ص = −٢س² + ٤س + ١؟","options":["مفتوح لأعلى (∪) وله قيمة صغرى","مفتوح لأسفل (∩) وله قيمة عظمى","خط مستقيم مائل","مفتوح لليمين"],"answer":1,"why":"معامل س² سالب (أ = −٢ < ٠) لذا ينفتح لأسفل."},{"type":"mcq","q":"ما المقطع الصادي للدالة ص = ٣س² − ٥س + ٧؟","options":["(٠، ٣)","(٧، ٠)","(٠، ٧)","(٠، −٥)"],"answer":2,"why":"عند س = ٠ تكون ص = ٧."},{"type":"mcq","q":"ما معادلة محور التماثل للدالة ص = س² − ٦س + ٥؟","options":["ص = ٣","س = −٣","س = ٦","س = ٣"],"answer":3,"why":"س = −(−٦) ÷ (٢×١) = ٣."},{"type":"mcq","q":"ما إحداثيا رأس المنحنى (نقطة التحول) للدالة ص = س² − ٤؟","options":["(٠، −٤)","(−٤، ٠)","(٠، ٤)","(٢، ٠)"],"answer":0,"why":"س = ٠ ← ص = −٤."}],"medium":[{"type":"mcq","q":"في جدول قيم للدالة ص = س² + ١، ما قيمة ص عندما س = −٣؟","options":["−٨","١٠","−٥","٧"],"answer":1,"why":"(−٣)² + ١ = ٩ + ١ = ١٠."},{"type":"mcq","q":"كيف تُوصل نقاط الدالة التربيعية عند رسمها بيانيًا؟","options":["بدوائر منفصلة","بقطع مستقيمة بالمسطرة","بمنحنى أملس باليد دون مسطرة","بخط أفقي"],"answer":2,"why":"القطع المكافئ منحنى أملس لا زوايا فيه."},{"type":"mcq","q":"أي الدوال الآتية أضيق منحنى (أقرب لمحور الصادات)؟","options":["ص = ٢س²","ص = س²","ص = ٠٫٥س²","ص = ٥س²"],"answer":3,"why":"كلما كبرت |أ| ضاق القطع المكافئ."},{"type":"tfr","q":"في الدالة التربيعية ص = أ س² + ب س + ج، إذا كان أ > ٠ فإن للمنحنى قيمة صغرى.","answer":true,"reasons":["ليس له رأس","له قيمة عظمى","لأنه مفتوح لأعلى (∪) فيكون الرأس أخفض نقطة"],"reason":2},{"type":"tfr","q":"عند حساب قيمة ص = س² لـ س = −٤ يكون الناتج −١٦.","answer":false,"reasons":["بل (−٤)² = +١٦ لأن مربع أي عدد حقيقي غير سالب","نعم −١٦","بل −٨"],"reason":0},{"type":"essay","q":"أكمل جدول القيم للدالة ص = س² − ٢س − ٣ لقيم س من −٢ إلى ٤، وحدّد الرأس ومحور التماثل والمقطع الصادي.","model":"القيم: (−٢،٥)، (−١،٠)، (٠،−٣)، (١،−٤)، (٢،−٣)، (٣،٠)، (٤،٥). الرأس (١،−٤)، محور التماثل س=١، المقطع الصادي (٠،−٣)."},{"type":"essay","q":"أوجد إحداثيي نقطة التحول ونوعها (عظمى أم صغرى) للدالة ص = −س² + ٤س + ١.","model":"س = −٤ ÷ (٢×−١) = ٢. ص = −٤ + ٨ + ١ = ٥. الرأس (٢، ٥) وهو قيمة عظمى لأن أ = −١ < ٠."}],"hard":[{"type":"mcq","q":"ما إحداثيا رأس المنحنى للدالة ص = س² − ٤س + ١؟","options":["(٢، −٣)","(−٢، ١٣)","(٢، ١)","(٤، ١)"],"answer":0,"why":"س = ٤/٢ = ٢؛ ص = ٤ − ٨ + ١ = −٣."},{"type":"mcq","q":"إذا كان محور تماثل قطع مكافئ هو س = ٢ ومرّ بالنقطة (٥، ٧)، فأي نقطة أخرى يمر بها حتمًا؟","options":["(−٥، ٧)","(−١، ٧)","(٢، ٧)","(−١، −٧)"],"answer":1,"why":"المسافة من ٢ إلى ٥ هي ٣؛ نتحرك ٣ لليسار: ٢ − ٣ = −١."},{"type":"mcq","q":"أي الدوال الآتية ليست دالة تربيعية؟","options":["ص = ٤ − س²","ص = س²","ص = ٣س + ٥","ص = ٢س² − س"],"answer":2,"why":"ص = ٣س + ٥ دالة خطية من الدرجة الأولى."},{"type":"mcq","q":"ما القيمة الصغرى للدالة ص = س² + ٦؟","options":["١","٠","−٦","٦"],"answer":3,"why":"أقل قيمة لـ س² هي ٠ فتكون أقل قيمة لـ ص هي ٦."},{"type":"tfr","q":"يمر محور التماثل دائمًا برأس القطع المكافئ.","answer":true,"reasons":["يمر بالمقطع الصادي فقط","ويقسم المنحنى إلى نصفين متطابقين تمامًا","يكون أفقيًا دائمًا"],"reason":1},{"type":"tfr","q":"المقطع الصادي للقطع المكافئ ص = ٢س² + ٣س − ٨ هو −٨.","answer":true,"reasons":["هو ٣","هو ٢","لأننا نعوض س = ٠ فينتج ص = −٨"],"reason":2},{"type":"tfr","q":"توصيل نقاط القطع المكافئ بالمسطرة يعطي رسمًا أدق.","answer":false,"reasons":["يجب توصيلها بمنحنى أملس باليد لا بخطوط مستقيمة","نعم بالمسطرة أدق","بالمسطرة للجانب الأيمن فقط"],"reason":0},{"type":"essay","q":"كيف يختلف التمثيل البياني لـ ص = س² − ٥ عن التمثيل البياني لـ ص = س²؟","model":"لهما نفس الشكل والاتساع ومحور التماثل (س=٠)، لكن ص = س² − ٥ مُزاحة ٥ وحدات للأسفل (رأسها (٠، −٥))."},{"type":"essay","q":"يمر قطع مكافئ بنقطة الرأس (٣، −٢) وبالمقطع الصادي (٠، ٧). استنتج نقطة ثالثة على المنحنى بالتماثل.","model":"محور التماثل س = ٣. النقطة (٠، ٧) تبعد ٣ وحدات يسار المحور، فنظيرتها تبعد ٣ وحدات يمينه: (٦، ٧)."},{"type":"essay","q":"لماذا تكون إشارة أ (معامل س²) هي العامل الحاسم في كون مسار مقذوف مفتوحًا لأسفل؟","model":"لأن الجاذبية تسحب المقذوف للأسفل فيكون معامل ن² سالبًا (−٥ن²)، فيأخذ المنحنى شكل (∩) وله أقصى ارتفاع (قيمة عظمى)."}]}},
  {"id":"g9-math-2-u14-2","grade":"g9","subject":"math","term":2,"unit":14,"no":2,"title":"رسم التمثيل البياني للدوال ص = أ/س","summary":"شرح متحرك بـ SVG لدرس رسم التمثيل البياني للدوال ص = أ/س (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-reciprocal-graphs.html","video":"","pdf":"","notes":["ص = أ/س (س≠٠): فرعان منفصلان، لا تصلهما أبدًا عبر محور الصادات.","أ>٠ ← الربعان ١ و٣ | أ<٠ ← الربعان ٢ و٤.","خطا التقارب هما المحوران س = ٠ و ص = ٠."],"exercises":["أكمل جدول القيم لـ ص = ٨/س للقيم س = −٨، −٤، −٢، −١، ١، ٢، ٤، ٨ وصف شكل المنحنى والأرباع التي يقع فيها.","ما المقصود بـ «خط التقارب»؟ واذكر خطَّي التقارب للدالة ص = −٥/س.","يمر منحنى ص = أ/س بالنقطة (−٤، ٣). أوجد قيمة أ، وحدّد في أي ربعين يقع المنحنى."],"levels":{"easy":[{"type":"mcq","q":"لماذا يُشترط س ≠ ٠ في الدالة ص = أ/س؟","options":["لأن ص تكون سالبة","لأن الناتج يكون صفرًا","لأن القسمة على صفر غير معرّفة","لأن المنحنى يصبح مستقيمًا"],"answer":2,"why":"لا يمكن القسمة على صفر في الرياضيات."},{"type":"mcq","q":"في أي ربعين يقع منحنى الدالة ص = ٨/س؟","options":["الثالث والرابع","الثاني والرابع","الأول والثاني","الأول والثالث"],"answer":3,"why":"أ = ٨ > ٠ ← موجب/موجب (الأول) وسالب/سالب (الثالث)."},{"type":"mcq","q":"في أي ربعين يقع منحنى الدالة ص = −٦/س؟","options":["الثاني والرابع","الأول والثالث","الأول والثاني","الأول والرابع"],"answer":0,"why":"أ = −٦ < ٠ ← عند س>٠ تكون ص<٠ (الرابع) وعند س<٠ تكون ص>٠ (الثاني)."},{"type":"mcq","q":"ما خطا التقارب لمنحنى الدالة ص = ١٠/س؟","options":["ص = س و ص = −س","محور السينات (ص=٠) ومحور الصادات (س=٠)","س = ١٠ و ص = ١٠","لا توجد خطوط تقارب"],"answer":1,"why":"يقترب المنحنى من المحورين دون أن يلمسهما."}],"medium":[{"type":"mcq","q":"في الدالة ص = ١٢/س، ما قيمة ص عندما س = ٠٫٥؟","options":["٠٫٢٤","٦","٢٤","١٢٫٥"],"answer":2,"why":"١٢ ÷ ٠٫٥ = ٢٤."},{"type":"mcq","q":"أي العبارات الآتية صحيحة عن منحنى ص = ٤/س؟","options":["يقطع محور السينات عند س = ٤","يمر بنقطة الأصل (٠، ٠)","هو قطع مكافئ","يتكون من فرعين منفصلين لا يقطعان المحورين"],"answer":3,"why":"لا يقطع أيا من المحورين ولا يمر بالأصل."},{"type":"mcq","q":"ما رتبة التماثل الدوراني لمنحنى ص = ٥/س حول نقطة الأصل؟","options":["٢","٤","١","٠"],"answer":0,"why":"ينطبق على نفسه بعد دوران ١٨٠°."},{"type":"tfr","q":"منحنى الدالة ص = أ/س يقطع محور الصادات عند النقطة (٠، أ).","answer":false,"reasons":["لا يقطع محور الصادات أبدًا لأن س ≠ ٠","نعم عند (٠، أ)","يقطعه عند (٠، ١)"],"reason":0},{"type":"tfr","q":"يجب عدم وصل فرعي منحنى ص = أ/س بخط يمر عبر محور الصادات.","answer":true,"reasons":["يجب وصلهما بخط مستقيم","لأن الدالة غير معرّفة عند س = ٠ والفرعان منفصلان","يُوصلان عند (٠، ٠)"],"reason":1},{"type":"essay","q":"أكمل جدول القيم لـ ص = ٨/س للقيم س = −٨، −٤، −٢، −١، ١، ٢، ٤، ٨ وصف شكل المنحنى والأرباع التي يقع فيها.","model":"ص = −١، −٢، −٤، −٨، ٨، ٤، ٢، ١. يتكون من فرعين منفصلين في الربعين الأول والثالث، وخطا تقاربه المحوران س=٠ و ص=٠."},{"type":"essay","q":"ما المقصود بـ «خط التقارب»؟ واذكر خطَّي التقارب للدالة ص = −٥/س.","model":"خط التقارب هو مستقيم يقترب منه المنحنى أكثر فأكثر دون أن يلمسه أو يقطعه. خطا التقارب هما س = ٠ و ص = ٠."}],"hard":[{"type":"mcq","q":"يمر منحنى ص = أ/س بالنقطة (٣، ٦). ما قيمة أ؟","options":["٢","١٨","٩","٠٫٥"],"answer":1,"why":"أ = س × ص = ٣ × ٦ = ١٨."},{"type":"mcq","q":"في الدالة ص = ٢/س، ماذا يحدث لقيمة ص عندما تزداد س وتكبر جدًا؟","options":["تصبح سالبة","تزداد بلا حدود","تقترب من الصفر دون أن تساويه","تساوي ٢"],"answer":2,"why":"قسمة ٢ على عدد كبير جدًا تعطي عددًا قريبًا جدًا من الصفر."},{"type":"mcq","q":"منحنى يمثل علاقة تناسب عكسي بين السرعة (س) والزمن (ص) لرحلة؛ في أي ربع يُرسم؟","options":["الأربعة أرباع","الأول والثالث","الثاني والرابع","الربع الأول فقط"],"answer":3,"why":"السرعة والزمن كميتان موجبتان."},{"type":"mcq","q":"ما محورا التماثل لمنحنى الدالة ص = ٦/س؟","options":["ص = س و ص = −س","س = ٠ و ص = ٠","س = ٦ و ص = ٦","ليس له محور تماثل"],"answer":0,"why":"ينعكس كل فرع حول ص = س و ص = −س."},{"type":"tfr","q":"إذا كان أ < ٠ فإن منحنى ص = أ/س يقع في الربعين الثاني والرابع.","answer":true,"reasons":["يقع في الأول والثاني","يقع في الأول والثالث","لأن إشارتي س و ص تكونان متعاكستين"],"reason":2},{"type":"tfr","q":"يمثل منحنى ص = أ/س علاقة تناسب عكسي.","answer":true,"reasons":["لأن س × ص = أ (مقدار ثابت)","يمثل تناسبًا طرديًا","يمثل علاقة خطية"],"reason":0},{"type":"tfr","q":"في الدالة ص = ١٠/س، كلما اقتربت س من الصفر من اليمين، اقتربت ص من الصفر أيضًا.","answer":false,"reasons":["نعم تقترب من الصفر","بل تكبر ص جدًا بلا حدود (مثل ١٠÷٠٫١ = ١٠٠)","تثبت عند ١٠"],"reason":1},{"type":"essay","q":"يمر منحنى ص = أ/س بالنقطة (−٤، ٣). أوجد قيمة أ، وحدّد في أي ربعين يقع المنحنى.","model":"أ = (−٤)(٣) = −١٢. بما أن أ < ٠ يقع المنحنى في الربعين الثاني والرابع."},{"type":"essay","q":"قارن بين التمثيل البياني للدالة ص = س² والدالة ص = ١/س من حيث: الشكل، المرور بنقطة الأصل، وعدد الفروع.","model":"ص=س²: قطع مكافئ متصل بفرع واحد يمر بـ (٠،٠). ص=١/س: قطع زائد بفرعين منفصلين لا يمر بالأصل ولا يقطع المحورين."},{"type":"essay","q":"في رحلة طولها ١٨٠ كم، العلاقة بين الزمن ن والسرعة ع هي ن = ١٨٠/ع. احسب ن عند ع = ٦٠، ٩٠، ١٢٠ كم/س، واشرح لماذا يظهر فرع واحد فقط.","model":"ن = ٣، ٢، ١٫٥ ساعة. يظهر الربع الأول فقط لأن السرعة والزمن كميتان موجبتان في الواقع."}]}},
  {"id":"g9-math-2-u14-3","grade":"g9","subject":"math","term":2,"unit":14,"no":3,"title":"حلّ المعادلات التربيعية بيانيًا","summary":"شرح متحرك بـ SVG لدرس حلّ المعادلات التربيعية بيانيًا (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-graphical-quadratic-solutions.html","video":"","pdf":"","notes":["حلول د(س) = ٠ هي المقاطع السينية للمنحنى.","لحل د(س) = م س + ك، ارسم المستقيم ص = م س + ك واقرأ قيم س عند التقاطع.","تذكّر: الحل هو الإحداثيات السينية (س) لنقاط التقاطع."],"exercises":["استخدم المنحنى المرسوم ص = س² − ٤س + ٢؛ اكتب معادلة المستقيم الذي ترسمه لحل كل من: (أ) س² − ٤س + ٢ = ٥، (ب) س² − ٥س + ٤ = ٠.","كيف تحدّد من شكل القطع المكافئ فقط ما إذا كانت المعادلة أ س² + ب س + ج = ٠ لها حلّان أم حل وحيد أم لا حل؟","لديك منحنى ص = ٢س² − ٣س − ٢ جاهزًا. ما المعادلة التربيعية التي تحلها إذا رسمت المستقيم ص = س + ٤؟"],"levels":{"easy":[{"type":"mcq","q":"منحنى ص = س² − ٥س + ٦ يقطع محور السينات عند س = ٢ و س = ٣. ما حلا المعادلة س² − ٥س + ٦ = ٠؟","options":["٥ و ٦","−٢ و −٣","٠ و ٦","٢ و ٣"],"answer":3,"why":"المقاطع السينية للمنحنى هي حلول المعادلة."},{"type":"mcq","q":"إذا مسّ منحنى دالة تربيعية محور السينات في نقطة واحدة (٤، ٠)، فكم حلًا للمعادلة د(س) = ٠؟","options":["حل حقيقي وحيد هو س = ٤","حلّان هما ٤ و−٤","لا توجد حلول حقيقية","حلّان هما ٠ و ٤"],"answer":0,"why":"التماس في نقطة واحدة يعني حلًا حقيقيًا وحيدًا مكررًا."},{"type":"mcq","q":"رُسم منحنى ص = س² − ٤س + ١. ما المستقيم اللازم رسمه لحل المعادلة س² − ٤س + ١ = ٥؟","options":["س = ٥","ص = ٥","ص = −٥","ص = س + ٥"],"answer":1,"why":"نساوي ص بالطرف الأيسر ٥ ← المستقيم الأفقي ص = ٥."},{"type":"mcq","q":"إذا وقع منحنى ص = س² + ٢ بالكامل فوق محور السينات، فكم عدد الحلول الحقيقية لـ س² + ٢ = ٠؟","options":["حلّان","حل واحد","لا توجد حلول حقيقية (صفر)","عدد لا نهائي"],"answer":2,"why":"عدم تقاطع المنحنى مع محور السينات يعني عدم وجود حلول حقيقية."}],"medium":[{"type":"mcq","q":"رُسم منحنى ص = س² + ٢س − ٣. ما المستقيم اللازم رسمه لحل س² + ٢س − ٥ = ٠؟","options":["ص = −٥","ص = −٢","ص = ٥","ص = ٢"],"answer":3,"why":"س² + ٢س − ٥ = ٠ ⇔ س² + ٢س − ٣ = ٢ ← نرسم ص = ٢."},{"type":"mcq","q":"رُسم منحنى ص = س² − ٣س + ١. ما المستقيم اللازم رسمه لحل س² − ٤س + ٣ = ٠؟","options":["ص = س − ٢","ص = −س + ٢","ص = س + ٢","ص = ٢س − ١"],"answer":0,"why":"س² − ٣س + ١ = س − ٢ ⇔ س² − ٤س + ٣ = ٠."},{"type":"mcq","q":"رُسم منحنى ص = س². ما المستقيم اللازم رسمه لحل س² − ٢س − ٣ = ٠؟","options":["ص = −٢س − ٣","ص = ٢س + ٣","ص = ٢س − ٣","ص = س + ٣"],"answer":1,"why":"س² = ٢س + ٣ ← نرسم ص = ٢س + ٣."},{"type":"tfr","q":"المقاطع السينية لمنحنى ص = أ س² + ب س + ج هي حلول المعادلة أ س² + ب س + ج = ٠.","answer":true,"reasons":["هي المقطع الصادي","لأن ص = ٠ على محور السينات","هي إحداثيات الرأس"],"reason":1},{"type":"tfr","q":"إذا لم يقطع منحنى دالة تربيعية محور السينات، فإن للمعادلة حلّين سالبين.","answer":false,"reasons":["لها حل صفري","نعم حلّين سالبين","بل لا توجد لها حلول حقيقية أصلًا"],"reason":2},{"type":"essay","q":"استخدم المنحنى المرسوم ص = س² − ٤س + ٢؛ اكتب معادلة المستقيم الذي ترسمه لحل كل من: (أ) س² − ٤س + ٢ = ٥، (ب) س² − ٥س + ٤ = ٠.","model":"(أ) نرسم المستقيم الأفقي ص = ٥. (ب) نعيد ترتيبها: س² − ٤س + ٢ = س − ٢، إذن نرسم المستقيم المائل ص = س − ٢."},{"type":"essay","q":"كيف تحدّد من شكل القطع المكافئ فقط ما إذا كانت المعادلة أ س² + ب س + ج = ٠ لها حلّان أم حل وحيد أم لا حل؟","model":"إن قطع محور السينات في نقطتين فحلّان، وإن مسّه في نقطة واحدة فحل وحيد، وإن لم يقطعه فليس لها حلول حقيقية."}],"hard":[{"type":"mcq","q":"عند حل معادلة تربيعية بيانيًا، ماذا نقرأ من نقطتي التقاطع؟","options":["المسافة بين النقطتين","الإحداثيات الصادية (قيم ص) فقط","الإحداثيات السينية (قيم س) فقط","ميل المستقيم"],"answer":2,"why":"المعادلة في متغير واحد هو س، لذا الحل هو قيم س."},{"type":"mcq","q":"لماذا يُعدّ الحل البياني للمعادلات التربيعية حلًا تقريبيًا غالبًا؟","options":["لأنه يعطي حلًا واحدًا فقط","لأن القانون العام خطأ","لأن المنحنى مستقيم","لأنه يعتمد على دقة الرسم وقراءة تدريج الورق"],"answer":3,"why":"القراءة البصرية من الشبكة تقرّب عادة لأقرب ٠٫١."},{"type":"mcq","q":"رُسم منحنى ص = ٢س² − س − ١. أي معادلة تُحل برسم المستقيم ص = ٣؟","options":["٢س² − س − ٤ = ٠","٢س² − س + ٢ = ٠","٢س² − س − ١ = ٠","٢س² − ٤س − ١ = ٠"],"answer":0,"why":"٢س² − س − ١ = ٣ ⇔ ٢س² − س − ٤ = ٠."},{"type":"mcq","q":"تقاطع منحنى ص = س² مع المستقيم ص = ٩ في النقطتين (−٣، ٩) و(٣، ٩). ما حلا س² − ٩ = ٠؟","options":["٩ و −٩","−٣ و ٣","٠ و ٩","٣ و ٩"],"answer":1,"why":"نأخذ الإحداثيات السينية لنقطتي التقاطع."},{"type":"tfr","q":"يمكن استخدام رسم منحنى ص = س² لحل المعادلة س² − س − ٦ = ٠ برسم المستقيم ص = س + ٦.","answer":true,"reasons":["لأن س² = س + ٦ تكافئ س² − س − ٦ = ٠","برسم ص = −س − ٦","لا يمكن دون رسم منحنى جديد"],"reason":0},{"type":"tfr","q":"عند حل معادلة في س بيانيًا، نكتب الإحداثي الصادي لنقاط التقاطع كحل للمعادلة.","answer":false,"reasons":["نعم نكتب ص","نكتب الإحداثي السيني (س) فقط لأن المجهول هو س","نكتب مجموع س+ص"],"reason":1},{"type":"tfr","q":"الحل البياني يفيد في التحقق البصري السريع من عدد الجذور ومواقعها التقريبية.","answer":true,"reasons":["أدق من القانون العام دائمًا","لا يعطي أي فكرة عن عدد الحلول","حيث يظهر فورًا إن كان هناك حلّان أو حل أو لا حل"],"reason":2},{"type":"essay","q":"لديك منحنى ص = ٢س² − ٣س − ٢ جاهزًا. ما المعادلة التربيعية التي تحلها إذا رسمت المستقيم ص = س + ٤؟","model":"٢س² − ٣س − ٢ = س + ٤ ← ٢س² − ٤س − ٦ = ٠ (أو س² − ٢س − ٣ = ٠)."},{"type":"essay","q":"اشرح كيف تحل المعادلة س² − ٣س − ١ = ٠ بيانيًا باستخدام منحنى ص = س² فقط.","model":"نعيد كتابتها: س² = ٣س + ١. نرسم المستقيم ص = ٣س + ١ على نفس المحاور مع ص = س² ونقرأ الإحداثيات السينية لنقطتي التقاطع."},{"type":"essay","q":"قارن بين مزايا الحل البياني ومزايا الحل الجبري للمعادلات التربيعية.","model":"البياني: يوضح الشكل وعدد الحلول بصريًا ويحل عدة معادلات من منحنى واحد، لكنه تقريبي. الجبري: يعطي قيمًا دقيقة تمامًا."}]}},
  {"id":"g9-math-2-u14-4","grade":"g9","subject":"math","term":2,"unit":14,"no":4,"title":"استخدام التمثيلات البيانية لحل معادلات خطية وغير خطية آنيًا","summary":"شرح متحرك بـ SVG لدرس استخدام التمثيلات البيانية لحل معادلات خطية وغير خطية آنيًا (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-graphical-simultaneous-equations.html","video":"","pdf":"","notes":["حل النظام الآني بيانيًا = الأزواج المرتبة (س، ص) لنقاط التقاطع.","عدد حلول مستقيم + قطع مكافئ: ٠ (لا تقاطع) أو ١ (مماس) أو ٢ (تقاطع).","رتّب المعادلة الخطية بصورة ص = م س + ج، وتحقّق من الحلين في المعادلتين."],"exercises":["حلّ النظام الآتي بيانيًا وتحقق جبريًا: ص = س² − ٢س − ٣ و ص = س − ٣.","أوجد نقاط تقاطع المستقيم ص = ٥ − س مع منحنى الدالة ص = ٦/س.","بيّن لماذا يكون المستقيم ص = ٢س − ١ مماسًّا لمنحنى ص = س²، وأوجد نقطة التماس."],"levels":{"easy":[{"type":"mcq","q":"ما الحل البياني للنظام: ص = س² و ص = س + ٢؟","options":["(−١، ١) و (٢، ٤)","(−١، ٢) و (٢، ١)","س = −١ و ٢ فقط","(١، ١) و (٢، ٤)"],"answer":0,"why":"تقاطع المنحنى والمستقيم عند (−١، ١) و(٢، ٤)."},{"type":"mcq","q":"كم عدد الحلول الممكنة لنظام يتكون من معادلة خطية ومعادلة تربيعية؟","options":["حل واحد فقط دائمًا","٠ أو ١ أو ٢","٣ حلول دائمًا","٤ حلول"],"answer":1,"why":"المستقيم إما لا يقطع القطع المكافئ أو يمسّه أو يقطعه في نقطتين."},{"type":"mcq","q":"عندما يكون المستقيم مماسًّا للقطع المكافئ في نقطة واحدة، كم عدد حلول النظام؟","options":["لا توجد حلول","حلّان","حل واحد فقط","عدد لا نهائي"],"answer":2,"why":"نقطة التماس هي نقطة الالتقاء الوحيدة."},{"type":"mcq","q":"أي الأزواج الآتية يحقق النظام: ص = ٨/س و ص = ٢س؟","options":["(١، ٨) و (٢، ٤)","(٢، ٤) فقط","(٤، ٢) و (−٤، −٢)","(٢، ٤) و (−٢، −٤)"],"answer":3,"why":"عند س=٢: ص=٤؛ وعند س=−٢: ص=−٤."}],"medium":[{"type":"mcq","q":"لرسم المستقيم ٢س + ص = ٦ بسهولة، نعيد كتابته بصورة:","options":["ص = ٦ − ٢س","ص = ٢س − ٦","ص = ٦ + ٢س","ص = ٦ ÷ ٢س"],"answer":0,"why":"ننقل ٢س للطرف الآخر بعكس الإشارة."},{"type":"mcq","q":"يتقاطع منحنى ص = س² − ٣ مع المستقيم ص = ١ عند:","options":["(−١، ١) و (١، ١)","(−٢، ١) و (٢، ١)","(−٣، ١) و (٣، ١)","(٠، −٣)"],"answer":1,"why":"س² − ٣ = ١ ← س² = ٤ ← س = ±٢ و ص = ١."},{"type":"mcq","q":"ما عدد نقاط التقاطع بين الدائرة س² + ص² = ٩ والمستقيم ص = ٥؟","options":["نقطتان","نقطة واحدة","صفر (لا يتقاطعان)","ثلاث نقاط"],"answer":2,"why":"أعلى نقطة في الدائرة هي (٠، ٣) والمستقيم ص = ٥ فوقها."},{"type":"tfr","q":"في حل نظام معادلتين آنيًا، يجب إعطاء قيمتَي (س، ص) معًا لكل نقطة تقاطع.","answer":true,"reasons":["يكفي ذكر ص فقط","يكفي ذكر س فقط","لأن النظام يحتوي على متغيرين س و ص"],"reason":2},{"type":"tfr","q":"يمكن لمستقيم أن يقطع قطعًا مكافئًا في ثلاث نقاط مختلفة.","answer":false,"reasons":["أقصى عدد لنقاط تقاطع مستقيم وقطع مكافئ هو نقطتان","نعم ثلاث نقاط","أربع نقاط"],"reason":0},{"type":"essay","q":"حلّ النظام الآتي بيانيًا وتحقق جبريًا: ص = س² − ٢س − ٣ و ص = س − ٣.","model":"بمساواتهما: س²−٢س−٣ = س−٣ ← س²−٣س=٠ ← س(س−٣)=٠. إذن س=٠ (ص=−٣) أو س=٣ (ص=٠). الحلان: (٠، −٣) و(٣، ٠)."},{"type":"essay","q":"أوجد نقاط تقاطع المستقيم ص = ٥ − س مع منحنى الدالة ص = ٦/س.","model":"٦/س = ٥ − س ← س² − ٥س + ٦ = ٠ ← (س−٢)(س−٣)=٠. الحلان: (٢، ٣) و(٣، ٢)."}],"hard":[{"type":"mcq","q":"لماذا يُنصح باختيار ٣ نقاط عند رسم الخط المستقيم؟","options":["لأنه لا يكفي نقطتان لرسم مستقيم","لأن المستقيم منحنى","لإيجاد ٣ حلول","للتحقق من استقامتها واكتشاف أي خطأ حسابي"],"answer":3,"why":"إذا لم تقع النقطة الثالثة على الخط فهناك خطأ حسابي."},{"type":"mcq","q":"الزوج المرتب (٣، ٥) حل لنظام معادلتين؛ هذا يعني أن (٣، ٥) هي:","options":["نقطة تقاطع التمثيلين البيانيين للمعادلتين","رأس القطع المكافئ دائمًا","المقطع الصادي","نقطة الأصل"],"answer":0,"why":"الحل الآني يحقق المعادلتين معًا أي يقع على كليهما."},{"type":"mcq","q":"ما حلا النظام: ص = س² + ١ و ص = ٢س + ١؟","options":["(٠، ١) فقط","(٠، ١) و (٢، ٥)","(١، ٢) و (٢، ٥)","(−٢، ٥) و (٠، ١)"],"answer":1,"why":"س²+١ = ٢س+١ ← س(س−٢)=٠ ← س=٠ (ص=١) أو س=٢ (ص=٥)."},{"type":"mcq","q":"تقاطع منحنى ص = ١٢/س مع المستقيم ص = ٧ − س عند س = ٣ و س = ٤. ما قيما ص المناظرتان؟","options":["ص = ٧ و ص = ١٢","ص = ٣ و ص = ٤","ص = ٤ و ص = ٣","ص = ١ و ص = ٢"],"answer":2,"why":"عند س=٣: ص=١٢/٣=٤؛ عند س=٤: ص=١٢/٤=٣."},{"type":"tfr","q":"إذا لم يتقاطع المستقيم والمنحنى في الرسم، فليس للنظام حلول حقيقية.","answer":true,"reasons":["يوجد حل صفري","عدم التقاطع يعني عدم وجود زوج حقيقي يحقق المعادلتين معًا","يوجد حلّان سالبان"],"reason":1},{"type":"tfr","q":"المستقيم ص = س يقطع منحنى ص = ٤/س في نقطتين هما (٢، ٢) و(−٢، −٢).","answer":true,"reasons":["لا يقطعه","في (٢، ٢) فقط","لأن س = ٤/س ← س² = ٤ ← س = ±٢"],"reason":2},{"type":"tfr","q":"للتحقق من صحة حل نظام معادلتين، يكفي التعويض به في المعادلة الخطية فقط.","answer":false,"reasons":["يجب التعويض به في كلتا المعادلتين معًا","نعم تكفي الخطية","تكفي غير الخطية فقط"],"reason":0},{"type":"essay","q":"بيّن لماذا يكون المستقيم ص = ٢س − ١ مماسًّا لمنحنى ص = س²، وأوجد نقطة التماس.","model":"س² = ٢س − ١ ← س² − ٢س + ١ = ٠ ← (س − ١)² = ٠ ← حل وحيد س = ١، ص = ١. نقطة التماس (١، ١)."},{"type":"essay","q":"ارسم خطة خطوات واضحة لحل النظام: ص = س² + ٢ و ٢س + ص = ٥ بيانيًا.","model":"١) جدول ورسم منحنى ص = س² + ٢. ٢) ترتيب الخطية ص = ٥ − ٢س ورسمها بـ ٣ نقاط. ٣) قراءة نقطتي التقاطع (−٣، ١١) و(١، ٣)."},{"type":"essay","q":"فسّر هندسيًا سبب عدم وجود حل حقيقي للنظام: ص = س² + ٤ و ص = ٢.","model":"أقل قيمة للمنحنى ص = س² + ٤ هي ٤ عند الرأس (٠، ٤)، بينما المستقيم ص = ٢ يقع تحته تمامًا فلا يتقاطعان."}]}},
  {"id":"g9-math-2-u14-5","grade":"g9","subject":"math","term":2,"unit":14,"no":5,"title":"المزيد من التمثيلات البيانية غير الخطية","summary":"شرح متحرك بـ SVG لدرس المزيد من التمثيلات البيانية غير الخطية (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-more-nonlinear-graphs.html","video":"","pdf":"","notes":["التكعيبية (س³): شكل S أو موجة (بقمة وقاع)، ومكعب السالب سالب.","ميل المنحنى عند نقطة = ميل المماس المرسوم عندها.","في ملء الأوعية: المقطع الأضيق يعطي ارتفاعًا أسرع وميلًا أكبر."],"exercises":["أكمل جدول القيم للدالة التكعيبية ص = س³ − ٣س للقيم س = −٢، −١، ٠، ١، ٢ وحدّد القمة والقاع.","اشرح كيف يختلف منحنى (الارتفاع مقابل الزمن) عند ملء كوبين بالماء بنفس المعدل: الأول أسطواني والثاني مخروطي واسع من الأسفل وضيق من الأعلى.","قارن بصريًا بين منحنيات: ص = ٢س + ١، ص = س²، ص = س³، ص = ١/س."],"levels":{"easy":[{"type":"mcq","q":"ما قيمة ص في الدالة ص = س³ − ٢ عندما س = −٢؟","options":["+٦","−١٠","−٨","−٦"],"answer":1,"why":"(−٢)³ − ٢ = −٨ − ٢ = −١٠."},{"type":"mcq","q":"أي الأشكال الآتية يمثل التمثيل البياني للدالة ص = س³؟","options":["خط مستقيم","قطع مكافئ (∪)","منحنى على شكل حرف S يمر بنقطة الأصل","فرعان منفصلان في الربعين ١ و ٣"],"answer":2,"why":"التكعيبية ص = س³ تأخذ شكل S."},{"type":"mcq","q":"كيف نقدّر ميل منحنى غير خطي عند نقطة محددة عليه؟","options":["نربّع الإحداثي السيني","نقيس طول المنحنى بالمسطرة","نحسب المقطع الصادي","نرسم مماسًّا عند النقطة ونحسب ميله"],"answer":3,"why":"ميل المنحنى عند نقطة = ميل المماس عندها."},{"type":"mcq","q":"إناء على شكل مخروط مقلوب (ضيق من الأسفل وواسع من الأعلى) يُملأ بماء بمعدل ثابت. كيف يكون منحنى الارتفاع-الزمن؟","options":["يرتفع بسرعة أولًا ثم يتباطأ (يقل ميله)","خط مستقيم ثابت الميل","يرتفع ببطء أولًا ثم يتسارع","خط أفقي"],"answer":0,"why":"كلما اتسع الإناء قلّت سرعة ارتفاع سطح الماء."}],"medium":[{"type":"mcq","q":"ما أكبر عدد ممكن من نقاط التحول لدالة تكعيبية؟","options":["نقطة واحدة","نقطتان (قمة وقاع)","ثلاث نقاط","أربع نقاط"],"answer":1,"why":"التكعيبية لها ٠ أو ٢ نقطة تحول."},{"type":"mcq","q":"في أي ربعين يمتد منحنى ص = −س³؟","options":["الأول والثاني","الأول والثالث","الثاني والرابع","الثالث والرابع"],"answer":2,"why":"عند س>٠ تكون ص<٠ (الرابع) وعند س<٠ تكون ص>٠ (الثاني)."},{"type":"mcq","q":"في منحنى المسافة-الزمن، ماذا يعني انحناء المنحنى للأعلى بحيث يزداد ميله؟","options":["الجسم يعود للخلف","الجسم يتباطأ","الجسم متوقف","الجسم يتسارع (تزداد سرعته)"],"answer":3,"why":"الميل يمثل السرعة، وزيادة الميل تعني زيادة السرعة."},{"type":"tfr","q":"مكعب العدد السالب يكون موجبًا مثل مربعه.","answer":false,"reasons":["بل سالبًا لأن سالب × سالب × سالب = سالب","نعم موجب دائمًا","يكون صفرًا"],"reason":0},{"type":"tfr","q":"ميل المنحنى غير الخطي متغيّر من نقطة إلى أخرى ويُقدَّر برسم المماس.","answer":true,"reasons":["ميل المنحنى ثابت","بعكس الخط المستقيم الذي ميله ثابت دائمًا","لا يوجد ميل للمنحنيات"],"reason":1},{"type":"essay","q":"أكمل جدول القيم للدالة التكعيبية ص = س³ − ٣س للقيم س = −٢، −١، ٠، ١، ٢ وحدّد القمة والقاع.","model":"القيم: (−٢،−٢)، (−١،٢)، (٠،٠)، (١،−٢)، (٢،٢). القمة عند (−١، ٢) والقاع عند (١، −٢)."},{"type":"essay","q":"اشرح كيف يختلف منحنى (الارتفاع مقابل الزمن) عند ملء كوبين بالماء بنفس المعدل: الأول أسطواني والثاني مخروطي واسع من الأسفل وضيق من الأعلى.","model":"الأسطواني: خط مستقيم ثابت الميل. المخروطي: منحنى يبدأ بميل صغير (ارتفاع بطيء في القاعدة الواسعة) ثم يزداد ميله (يرتفع أسرع في الأعلى الضيق)."}],"hard":[{"type":"mcq","q":"أي المعادلات الآتية تمثل دائرة مركزها (٠، ٠) ونصف قطرها ٤؟","options":["س² + ص² = ١٦","س² + ص² = ٤","ص = ٤س²","ص = ٤/س"],"answer":0,"why":"س² + ص² = نق² = ٤² = ١٦."},{"type":"mcq","q":"كم عدد الجذور الحقيقية الممكنة للمعادلة التكعيبية س³ − س = ٠؟","options":["جذر واحد فقط","٣ جذور (−١، ٠، ١)","جذران فقط","لا جذور"],"answer":1,"why":"س(س−١)(س+١) = ٠ ← س = ٠، ١، −١."},{"type":"mcq","q":"إناء أسطواني منتظم المقطع يُملأ بالماء بمعدل ثابت؛ منحنى الارتفاع-الزمن له يكون:","options":["قطعًا زائدًا","قطعًا مكافئًا","خطًا مستقيمًا يمر بالأصل","منحنى تكعيبيًا"],"answer":2,"why":"ثبات مساحة المقطع يعني ارتفاعًا بمعدل ثابت."},{"type":"mcq","q":"ما ميل مماس يمر بالنقطتين (١، ٢) و(٣، ١٠)؟","options":["٠٫٢٥","٨","٢","٤"],"answer":3,"why":"(١٠ − ٢) ÷ (٣ − ١) = ٨ ÷ ٢ = ٤."},{"type":"tfr","q":"عند ملء قارورة واسعة من الأسفل وضيقة العنق، يتباطأ ارتفاع الماء عند العنق.","answer":false,"reasons":["يبقى ثابتًا","نعم يتباطأ","بل يتسارع ارتفاع الماء عند العنق الضيق ويزداد الميل"],"reason":2},{"type":"tfr","q":"الدالة ص = س³ − ٣س تكعيبية ويمكن أن تقطع محور السينات في ٣ نقاط.","answer":true,"reasons":["عند س = ٠ و ±√٣","تقطعه في نقطتين فقط","لا تقطعه أبدًا"],"reason":0},{"type":"tfr","q":"في منحنى المسافة-الزمن، الخط الأفقي يدل على أن الجسم يسير بسرعة ثابتة.","answer":false,"reasons":["نعم سرعة ثابتة","بل يدل على أن الجسم متوقف (الميل = ٠ = السرعة)","يدل على تسارع"],"reason":1},{"type":"essay","q":"قارن بصريًا بين منحنيات: ص = ٢س + ١، ص = س²، ص = س³، ص = ١/س.","model":"الأولى خط مستقيم، الثانية قطع مكافئ (∪)، الثالثة تكعيبية بشكل S، الرابعة قطع زائد بفرعين وخطَّي تقارب."},{"type":"essay","q":"رُسم مماس لمنحنى عند نقطة فمرّ المماس بالنقطتين (٠، −١) و(٤، ٧). احسب تقدير ميل المنحنى عند تلك النقطة.","model":"الميل = (٧ − (−١)) ÷ (٤ − ٠) = ٨ ÷ ٤ = ٢."},{"type":"essay","q":"أثبت أن النقطة (−٣، ٤) تقع على الدائرة س² + ص² = ٢٥.","model":"(−٣)² + ٤² = ٩ + ١٦ = ٢٥، إذن تحقق معادلة الدائرة."}]}},
  {"id":"g9-math-2-u15-1","grade":"g9","subject":"math","term":2,"unit":15,"no":1,"title":"فهم النموّ الأسّي والاضمحلال الأسّي","summary":"شرح متحرك بـ SVG لدرس فهم النموّ الأسّي والاضمحلال الأسّي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-exponential-growth-decay.html","video":"","pdf":"","notes":["ص = أ × ب^س: أ القيمة الابتدائية (عند س=٠)، ب عامل التغير.","نمو ر٪: ب = ١ + ر/١٠٠ > ١ | اضمحلال ر٪: ب = ١ − ر/١٠٠ (بين ٠ و١).","النمو الأسي ضرب متكرر (نسبة متتالية ثابتة) وليس جمعًا متكررًا."],"exercises":["اكتب دالة أسية لكل حالة: (أ) عدد سكان ١٠٠٠٠ ينمو بنسبة ٤٪ سنويًا. (ب) حاسوب سعره ٤٠٠ ريال يفقد ٢٥٪ من قيمته سنويًا.","حدّد هل كل دالة تمثل نموًّا أم اضمحلالًا، واذكر النسبة المئوية: (أ) ص = ٨٠ × (١٫١٥)^س، (ب) ص = ٦٠ × (٠٫٦٥)^س.","اشترى خالد سيارة بـ ١٠٠٠٠ ريال تفقد ١٠٪ من قيمتها كل سنة. كم تكون قيمتها بعد ٣ سنوات؟"],"levels":{"easy":[{"type":"mcq","q":"أي الدوال الآتية تمثل نموًّا أسيًا؟","options":["ص = ٥٠ + ١٫٢س","ص = ٥٠ × (٠٫٨)^س","ص = ٥٠ × (١٫٢)^س","ص = ٥٠س²"],"answer":2,"why":"المتغير في الأس والعامل ب = ١٫٢ > ١."},{"type":"mcq","q":"أي الدوال الآتية تمثل اضمحلالًا أسيًا؟","options":["ص = ١٠٠س³","ص = ١٠٠ × (١٫٢٥)^س","ص = ١٠٠ − ٢س","ص = ١٠٠ × (٠٫٧٥)^س"],"answer":3,"why":"العامل ٠ < ٠٫٧٥ < ١ يمثل اضمحلالًا بنسبة ٢٥٪."},{"type":"mcq","q":"في الدالة ص = ٤٠٠ × (١٫٠٦)^س، ما القيمة الابتدائية ونسبة النمو؟","options":["٤٠٠ ونمو ٦٪","٤٠٠ ونمو ٦٠٪","١٫٠٦ ونمو ٤٠٠٪","٤٠٠ واضمحلال ٦٪"],"answer":0,"why":"أ = ٤٠٠ عند س=٠، و ١٫٠٦ − ١ = ٠٫٠٦ = ٦٪."},{"type":"mcq","q":"في الدالة ص = ٨٠٠ × (٠٫٨٥)^س، ما نسبة الاضمحلال في كل فترة؟","options":["٨٥٪","١٥٪","٨٫٥٪","١٫٥٪"],"answer":1,"why":"١ − ٠٫٨٥ = ٠٫١٥ = ١٥٪."}],"medium":[{"type":"mcq","q":"تتضاعف مستعمرة بكتيريا عددها ٢٠٠ كل ساعة. ما عددها بعد ٤ ساعات؟","options":["١٦٠٠","٨٠٠","٣٢٠٠","١٠٠٠"],"answer":2,"why":"٢٠٠ × ٢⁴ = ٢٠٠ × ١٦ = ٣٢٠٠."},{"type":"mcq","q":"مادة كتلتها ٨٠ جم تقل إلى النصف كل يوم. كم يتبقى منها بعد ٣ أيام؟","options":["٥ جم","٢٠ جم","٤٠ جم","١٠ جم"],"answer":3,"why":"٨٠ × (٠٫٥)³ = ٨٠ × ٠٫١٢٥ = ١٠ جم."},{"type":"mcq","q":"في جدول: س=٠ ← ص=٥، س=١ ← ص=١٥، س=٢ ← ص=٤٥. ما قاعدة الدالة؟","options":["ص = ٥ × ٣^س","ص = ٣ × ٥^س","ص = ٥ + ١٠س","ص = ٥س³"],"answer":0,"why":"أ = ٥ والنسبة المتتالية ١٥÷٥ = ٣."},{"type":"tfr","q":"في الدالة ص = أ × ب^س، إذا كان ب = ٠٫٩ فإن الدالة تمثل اضمحلالًا بنسبة ١٠٪.","answer":true,"reasons":["اضمحلال بنسبة ٩٠٪","لأن ١ − ٠٫٩ = ٠٫١ = ١٠٪","نمو بنسبة ١٠٪"],"reason":1},{"type":"tfr","q":"الدالة ص = س³ دالة أسية لأن فيها أسًّا.","answer":false,"reasons":["هي دالة خطية","نعم أسية","بل دالة تكعيبية؛ في الدالة الأسية يكون المتغير في الأس مثل ٣^س"],"reason":2},{"type":"essay","q":"اكتب دالة أسية لكل حالة: (أ) عدد سكان ١٠٠٠٠ ينمو بنسبة ٤٪ سنويًا. (ب) حاسوب سعره ٤٠٠ ريال يفقد ٢٥٪ من قيمته سنويًا.","model":"(أ) ص = ١٠٠٠٠ × (١٫٠٤)^س. (ب) ص = ٤٠٠ × (٠٫٧٥)^س."},{"type":"essay","q":"حدّد هل كل دالة تمثل نموًّا أم اضمحلالًا، واذكر النسبة المئوية: (أ) ص = ٨٠ × (١٫١٥)^س، (ب) ص = ٦٠ × (٠٫٦٥)^س.","model":"(أ) نمو أسي بنسبة ١٥٪. (ب) اضمحلال أسي بنسبة ٣٥٪."}],"hard":[{"type":"mcq","q":"عند س = ٠ في الدالة الأسية ص = أ × ب^س، فإن قيمة ص تساوي:","options":["ب","أ","٠","١"],"answer":1,"why":"لأن ب⁰ = ١، فتكون ص = أ × ١ = أ."},{"type":"mcq","q":"أي مما يأتي يميّز النمو الأسّي عن النمو الخطي؟","options":["أن المتغير في الأساس","جمع مقدار ثابت كل فترة","الضرب في عامل ثابت كل فترة بدلًا من جمع مقدار ثابت","أن التمثيل البياني خط مستقيم"],"answer":2,"why":"النمو الأسي ضرب متكرر في عامل ثابت ب."},{"type":"mcq","q":"جهاز سعره ٥٠٠ ريال يفقد ٢٠٪ من قيمته سنويًا. ما معادلة قيمته بعد س سنة؟","options":["ص = ٥٠٠ − ٢٠س","ص = ٥٠٠ × (٠٫٢)^س","ص = ٥٠٠ × (١٫٢)^س","ص = ٥٠٠ × (٠٫٨)^س"],"answer":3,"why":"عامل الاضمحلال = ١ − ٠٫٢٠ = ٠٫٨٠."},{"type":"mcq","q":"تُعبّر ص = ١٢٠٠ × (٠٫٩٧)^س عن:","options":["اضمحلال أسي بنسبة ٣٪","اضمحلال أسي بنسبة ٩٧٪","نمو أسي بنسبة ٣٪","نمو أسي بنسبة ٩٧٪"],"answer":0,"why":"١ − ٠٫٩٧ = ٠٫٠٣ = ٣٪ اضمحلال."},{"type":"tfr","q":"القيمة الابتدائية للدالة ص = أ × ب^س هي أ وتظهر عند س = ٠.","answer":true,"reasons":["لأن ب⁰ = ١ فتصبح ص = أ","هي ب","تساوي صفرًا دائمًا"],"reason":0},{"type":"tfr","q":"في النمو الأسي، يكون الفرق بين القيم المتتالية ثابتًا.","answer":false,"reasons":["نعم الفرق ثابت","بل النسبة (حاصل القسمة) بين القيم المتتالية هي الثابتة","المجموع ثابت"],"reason":1},{"type":"tfr","q":"الكمية في الاضمحلال الأسي ص = أ × ب^س (أ>٠، ٠<ب<١) تبقى موجبة ولا تصل إلى الصفر رياضيًا.","answer":true,"reasons":["تساوي صفرًا عند س = ١٠","تصبح سالبة بعد فترة","تقترب من الصفر فقط دون أن تساويه"],"reason":2},{"type":"essay","q":"اشترى خالد سيارة بـ ١٠٠٠٠ ريال تفقد ١٠٪ من قيمتها كل سنة. كم تكون قيمتها بعد ٣ سنوات؟","model":"ص = ١٠٠٠٠ × (٠٫٩)³ = ١٠٠٠٠ × ٠٫٧٢٩ = ٧٢٩٠ ريالًا عُمانيًا."},{"type":"essay","q":"قارن بين الجدولين: الأول (١٠، ٢٠، ٣٠، ٤٠) والثاني (١٠، ٢٠، ٤٠، ٨٠). أيهما خطي وأيهما أسي؟ ولماذا؟","model":"الأول خطي لأن الزيادة الثابتة (+١٠). الثاني أسي لأن النسبة الثابتة (×٢) في كل خطوة."},{"type":"essay","q":"تحتوي عينة على ٣٢٠ ملجم من دواء ينخفض تركيزه بنسبة ٥٠٪ كل ٤ ساعات. كم يتبقى بعد ١٢ ساعة؟","model":"عدد الفترات = ١٢ ÷ ٤ = ٣ فترات. المتبقي = ٣٢٠ × (٠٫٥)³ = ٤٠ ملجم."}]}},
  {"id":"g9-math-2-u15-2","grade":"g9","subject":"math","term":2,"unit":15,"no":2,"title":"التمثيلات البيانية للنموّ الأسّي والاضمحلال الأسّي","summary":"شرح متحرك بـ SVG لدرس التمثيلات البيانية للنموّ الأسّي والاضمحلال الأسّي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-exponential-graphs.html","video":"","pdf":"","notes":["المقطع الصادي للدالة ص = أ × ب^س هو (٠، أ) دائمًا.","خط التقارب الأفقي هو محور السينات (ص = ٠) ولا يقطعه المنحنى أبدًا.","لاستخراج المعادلة من الرسم: أ = ص(٠)، و ب = ص(١) ÷ أ."],"exercises":["أكمل جدول ص = ٢ × (١٫٥)^س للقيم س = ٠، ١، ٢، ٣، وصف المقطع الصادي وخط التقارب.","يمر منحنى أسي ص = أ × ب^س بالنقطتين (٠، ١٢) و(٢، ٣). أوجد قيمتَي أ و ب واكتب المعادلة.","اشرح كيف تفرّق بصريًا بين منحنى النمو الأسّي ومنحنى الاضمحلال الأسّي ومنحنى القطع المكافئ."],"levels":{"easy":[{"type":"mcq","q":"ما المقطع الصادي لمنحنى الدالة ص = ٥ × (٢)^س؟","options":["(٠، ١)","(٠، ٢)","(٠، ١٠)","(٠، ٥)"],"answer":3,"why":"عند س = ٠: ص = ٥ × ٢⁰ = ٥."},{"type":"mcq","q":"ما خط التقارب الأفقي لمنحنى الدالة ص = ٣ × (٠٫٧)^س؟","options":["محور السينات (ص = ٠)","محور الصادات (س = ٠)","ص = ٣","ص = ٠٫٧"],"answer":0,"why":"تقترب ص من الصفر دون أن تساويه."},{"type":"mcq","q":"يمر منحنى أسي ص = أ × ب^س بالنقطتين (٠، ٢) و(١، ١٠). ما معادلته؟","options":["ص = ١٠ × ٢^س","ص = ٢ × ٥^س","ص = ٢ × ٨^س","ص = ٥ × ٢^س"],"answer":1,"why":"أ = ٢، ب = ١٠ ÷ ٢ = ٥."},{"type":"mcq","q":"أي المنحنيات الآتية ينخفض من اليسار إلى اليمين؟","options":["ص = ٣^س","ص = ٤ × (١٫٦)^س","ص = ٤ × (٠٫٦)^س","ص = ٠٫٥ × ٢^س"],"answer":2,"why":"لأن الأساس ٠٫٦ محصور بين ٠ و١."}],"medium":[{"type":"mcq","q":"منحنى ص = (١/٣)^س هو انعكاس لمنحنى ص = ٣^س حول:","options":["نقطة الأصل","محور السينات","المستقيم ص = س","محور الصادات"],"answer":3,"why":"لأن (١/٣)^س = ٣^(−س)."},{"type":"mcq","q":"أي النقاط الآتية تقع على منحنى ص = ٣^س؟","options":["(−١، ١/٣)","(−١، −٣)","(٠، ٣)","(٢، ٦)"],"answer":0,"why":"٣^(−١) = ١/٣."},{"type":"mcq","q":"أيهما يصعد أسرع في الربع الأول (س > ٠): ص = ٢^س أم ص = ٥^س؟","options":["ص = ٢^س","ص = ٥^س","يصعدان بنفس السرعة","كلاهما يهبط"],"answer":1,"why":"كلما كبر الأساس ب > ١ كان الصعود أشد انحدارًا."},{"type":"tfr","q":"منحنى الدالة ص = أ × ب^س (أ > ٠) يقطع محور السينات عند النقطة (١، ٠).","answer":false,"reasons":["يقطعه عند (أ، ٠)","نعم عند (١، ٠)","لا يقطع محور السينات أبدًا بل يقترب منه كخط تقارب"],"reason":2},{"type":"tfr","q":"منحنى ص = (٠٫٥)^س هو انعكاس لمنحنى ص = ٢^س حول محور الصادات.","answer":true,"reasons":["لأن (٠٫٥)^س = ٢^(−س)","انعكاس حول محور السينات","لا علاقة بينهما"],"reason":0},{"type":"essay","q":"أكمل جدول ص = ٢ × (١٫٥)^س للقيم س = ٠، ١، ٢، ٣، وصف المقطع الصادي وخط التقارب.","model":"القيم: (٠، ٢)، (١، ٣)، (٢، ٤٫٥)، (٣، ٦٫٧٥). المقطع الصادي (٠، ٢)، وخط التقارب الأفقي محور السينات ص = ٠."},{"type":"essay","q":"يمر منحنى أسي ص = أ × ب^س بالنقطتين (٠، ١٢) و(٢، ٣). أوجد قيمتَي أ و ب واكتب المعادلة.","model":"أ = ١٢. عند س = ٢: ١٢ × ب² = ٣ ← ب² = ١/٤ ← ب = ٠٫٥ (موجب). المعادلة: ص = ١٢ × (٠٫٥)^س."}],"hard":[{"type":"mcq","q":"يمر منحنى أسي بالنقطتين (٠، ٨) و(١، ٤). ما قيمة ب؟","options":["−٤","٢","٠٫٥","٤"],"answer":2,"why":"ب = ٤ ÷ ٨ = ٠٫٥ (اضمحلال أسي)."},{"type":"mcq","q":"كم عدد المقاطع السينية لمنحنى ص = ٢ × (١٫٥)^س؟","options":["ثلاثة مقاطع","مقطع واحد","مقطعان","صفر (لا يقطع محور السينات)"],"answer":3,"why":"قيمة ص موجبة دائمًا ولا تساوي صفرًا."},{"type":"mcq","q":"لتقدير قيمة س عندما ص = ٢٠ من منحنى أسي مرسوم:","options":["نرسم أفقيًا من ص = ٢٠ للمنحنى ثم عموديًا لمحور س","نرسم عموديًا من س = ٢٠","نقسم ٢٠ على أ","نجمع أ + ب"],"answer":0,"why":"القراءة العكسية تبدأ من محور الصادات ثم تنزل لمحور السينات."},{"type":"mcq","q":"ما قيمة ص على منحنى ص = ٤ × (٠٫٥)^س عندما س = −١؟","options":["٢","٨","−٢","١"],"answer":1,"why":"(٠٫٥)^(−١) = ٢ ← ٤ × ٢ = ٨."},{"type":"tfr","q":"يمكن إيجاد القيمة الابتدائية أ مباشرة من المقطع الصادي للمنحنى الأسّي.","answer":true,"reasons":["من المقطع السيني","لأن المقطع الصادي هو (٠، أ)","من خط التقارب"],"reason":1},{"type":"tfr","q":"عندما تكون س سالبة في ص = ٢^س، تكون قيمة ص سالبة أيضًا.","answer":false,"reasons":["تساوي صفرًا","نعم سالبة","بل كسرًا موجبًا أصغر من ١ مثل ٢^(−٢) = ١/٤"],"reason":2},{"type":"tfr","q":"كلما زادت قيمة الأساس ب (> ١)، ازداد انحدار صعود منحنى النمو الأسّي.","answer":true,"reasons":["فمثلًا ٤^س أسرع صعودًا من ٢^س عند س > ٠","يقل الانحدار","لا يتأثر الانحدار"],"reason":0},{"type":"essay","q":"اشرح كيف تفرّق بصريًا بين منحنى النمو الأسّي ومنحنى الاضمحلال الأسّي ومنحنى القطع المكافئ.","model":"النمو الأسي يصعد متسارعًا مع خط تقارب يسارًا، والاضمحلال يهبط مقتربًا من محور س يمينًا، أما القطع المكافئ فله رأس ومحور تماثل ولا خط تقارب."},{"type":"essay","q":"لماذا يقع منحنى ص = ٣ × (٠٫٨)^س بالكامل في النصف العلوي للمستوى الإحداثي؟","model":"لأن أ = ٣ > ٠ و(٠٫٨)^س موجبة لجميع قيم س الحقيقية، فيكون ناتج الضرب ص > ٠ دائمًا."},{"type":"essay","q":"إذا كان منحنى ص = ١٠٠ × (٠٫٥)^س مرسومًا، كيف تجد بيانيًا الزمن الذي تنخفض فيه الكمية إلى ٢٥؟ وما القيمة الدقيقة؟","model":"نرسم خطًا أفقيًا من ص = ٢٥ للمنحنى وننزل عموديًا لمحور س فنجد س = ٢ (لأن ١٠٠ × ٠٫٥² = ٢٥)."}]}},
  {"id":"g9-math-2-u15-3","grade":"g9","subject":"math","term":2,"unit":15,"no":3,"title":"تطبيقات حياتية على النموّ الأسّي والاضمحلال الأسّي","summary":"شرح متحرك بـ SVG لدرس تطبيقات حياتية على النموّ الأسّي والاضمحلال الأسّي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-exponential-applications.html","video":"","pdf":"","notes":["ج = أ × (١ + ر/١٠٠)^ن للنمو المركب، و ج = أ × (١ − ر/١٠٠)^ن للاستهلاك والاضمحلال.","فرّق بين الجملة ج وبين الربح/الانخفاض (|ج − أ|).","احتفظ بدقة الآلة الحاسبة وقرّب الناتج النهائي فقط."],"exercises":["أودع ناصر ٥٠٠٠ ريال عُماني في حساب استثماري يعطي عائدًا مركبًا ٤٪ سنويًا لمدة ٣ سنوات. احسب الجملة والربح الصافي.","اشترت شركة حافلة بـ ٢٠٠٠٠ ريال تفقد ١٥٪ من قيمتها كل عام. كم تساوي بعد ٤ سنوات لأقرب ريال؟","يبلغ عدد طيور في محمية طبيعية ٤٠٠ طائر ويزداد بنسبة ١٢٪ سنويًا. بعد كم سنة كاملة يتجاوز عددها ٦٠٠ طائر؟"],"levels":{"easy":[{"type":"mcq","q":"استثمر شخص ١٠٠٠ ريال بعائد مركب ٥٪ سنويًا لمدة سنتين. ما جملة المبلغ؟","options":["١١٠٢٫٥ ريالًا","١١٠٠ ريال","١٠٥٠ ريالًا","١٢٥٠ ريالًا"],"answer":0,"why":"١٠٠٠ × (١٫٠٥)² = ١١٠٢٫٥ ريالًا."},{"type":"mcq","q":"في السؤال السابق، ما مقدار «الربح الصافي» فقط بعد السنتين؟","options":["١١٠٢٫٥ ريالًا","١٠٢٫٥ ريال","١٠٠ ريال","٥٠ ريالًا"],"answer":1,"why":"الربح = ج − أ = ١١٠٢٫٥ − ١٠٠٠ = ١٠٢٫٥ ريال."},{"type":"mcq","q":"سيارة سعرها ١٢٠٠٠ ريال تفقد ١٠٪ من قيمتها سنويًا. ما قيمتها بعد سنتين؟","options":["١٠٨٠٠ ريال","٩٦٠٠ ريال","٩٧٢٠ ريالًا","٨٤٠٠ ريال"],"answer":2,"why":"١٢٠٠٠ × (٠٫٩)² = ٩٧٢٠ ريالًا."},{"type":"mcq","q":"تتضاعف بكتيريا كل ٣٠ دقيقة. إذا كان عددها ٥٠، فكم عدد الفترات ن خلال ساعتين؟","options":["٣٠ فترة","فترتان","٦ فترات","٤ فترات"],"answer":3,"why":"١٢٠ دقيقة ÷ ٣٠ دقيقة = ٤ فترات."}],"medium":[{"type":"mcq","q":"ما قيمة مبلغ ٥٠٠ ريال بعد ٣ سنوات بعائد مركب ١٠٪ سنويًا؟","options":["٦٦٥٫٥ ريالًا","٦٥٠ ريالًا","٥٥٠ ريالًا","٧٠٠ ريال"],"answer":0,"why":"٥٠٠ × (١٫١)³ = ٥٠٠ × ١٫٣٣١ = ٦٦٥٫٥ ريالًا."},{"type":"mcq","q":"يقل تركيز دواء في الدم بنسبة ٢٠٪ كل ساعة. إذا كانت الجرعة ١٠٠ ملجم، فكم يتبقى بعد ساعتين؟","options":["٦٠ ملجم","٦٤ ملجم","٨٠ ملجم","٤٠ ملجم"],"answer":1,"why":"١٠٠ × (٠٫٨)² = ٦٤ ملجم."},{"type":"mcq","q":"مدينة عدد سكانها ٢٠٠٠٠ نسمة ينمو بمعدل ٢٪ سنويًا. ما الصيغة الصحيحة بعد ن سنة؟","options":["٢٠٠٠٠ × (٠٫٩٨)^ن","٢٠٠٠٠ × (١٫٢)^ن","٢٠٠٠٠ × (١٫٠٢)^ن","٢٠٠٠٠ + ٤٠٠ن"],"answer":2,"why":"٢٪ = ٠٫٠٢ ← عامل النمو ١٫٠٢."},{"type":"tfr","q":"في الفائدة المركبة، يُحسب الربح كل سنة على المبلغ الأصلي فقط دون الأرباح السابقة.","answer":false,"reasons":["بل على الجملة المتراكمة (الأصل + الأرباح السابقة)","نعم على الأصل فقط","يُطرح من الأصل"],"reason":0},{"type":"tfr","q":"انخفاض قيمة سيارة بنسبة ١٥٪ سنويًا لمدة سنتين يعني انخفاضها بنسبة ٣٠٪ إجمالًا.","answer":false,"reasons":["نعم ٣٠٪ بالضبط","بل (٠٫٨٥)² = ٠٫٧٢٢٥ أي انخفاض ٢٧٫٧٥٪ فقط","انخفاض ١٥٪ فقط"],"reason":1},{"type":"essay","q":"أودع ناصر ٥٠٠٠ ريال عُماني في حساب استثماري يعطي عائدًا مركبًا ٤٪ سنويًا لمدة ٣ سنوات. احسب الجملة والربح الصافي.","model":"ج = ٥٠٠٠ × (١٫٠٤)³ = ٥٠٠٠ × ١٫١٢٤٨٦٤ = ٥٦٢٤٫٣٢ ريالًا. الربح الصافي = ٦٢٤٫٣٢ ريالًا."},{"type":"essay","q":"اشترت شركة حافلة بـ ٢٠٠٠٠ ريال تفقد ١٥٪ من قيمتها كل عام. كم تساوي بعد ٤ سنوات لأقرب ريال؟","model":"القيمة = ٢٠٠٠٠ × (٠٫٨٥)⁴ = ٢٠٠٠٠ × ٠٫٥٢٢٠٠٦٢٥ ≈ ١٠٤٤٠ ريالًا عُمانيًا."}],"hard":[{"type":"mcq","q":"لماذا تعطي الفائدة المركبة ربحًا أكبر من الفائدة البسيطة بعد أكثر من سنة؟","options":["لأنها تُطرح كل سنة","لأن نسبتها أكبر دائمًا","لأنها لا تستخدم الأسس","لأن الربح يُضاف للأصل فيُحسب ربح جديد على الأرباح السابقة"],"answer":3,"why":"الربح المركب ينمو أسيًا بمرور السنوات."},{"type":"mcq","q":"آلة قيمتها ٤٠٠٠ ريال تفقد ٢٥٪ سنويًا. كم مقدار الانخفاض في قيمتها بعد سنتين؟","options":["١٧٥٠ ريالًا","٢٢٥٠ ريالًا","٢٠٠٠ ريال","١٠٠٠ ريال"],"answer":0,"why":"القيمة بعد سنتين = ٤٠٠٠×(٠٫٧٥)² = ٢٢٥٠؛ الانخفاض = ٤٠٠٠ − ٢٢٥٠ = ١٧٥٠."},{"type":"mcq","q":"إذا أردنا معرفة بعد كم سنة كاملة يتجاوز استثمار ١٠٠٠ ريال بعائد ٢٠٪ مبلغ ١٥٠٠ ريال، فالجواب هو:","options":["سنتان","٣ سنوات","سنة واحدة","٥ سنوات"],"answer":1,"why":"(١٫٢)² = ١٫٤٤ (١٤٤٠ < ١٥٠٠)، و(١٫٢)³ = ١٫٧٢٨ (١٧٢٨ > ١٥٠٠) ← ٣ سنوات."},{"type":"mcq","q":"تبرد قهوة بحيث يقل فرق حرارتها عن الغرفة بنسبة ١٠٪ كل دقيقة. هذا مثال على:","options":["النمو الخطي","النمو الأسّي","الاضمحلال الأسّي","التناسب الطردي"],"answer":2,"why":"التناقص بنسبة مئوية ثابتة كل دقيقة هو اضمحلال أسي."},{"type":"tfr","q":"عندما يكون التغير «كل ٤ ساعات»، نحسب ن بقسمة الزمن الكلي بالساعات على ٤.","answer":true,"reasons":["نأخذ الزمن كما هو","نضرب الزمن في ٤","لتحديد عدد الفترات التي حدث فيها الضرب في عامل التغير"],"reason":2},{"type":"tfr","q":"لإيجاد عدد السنوات ن التي تصل فيها الكمية لهدف معين في الصف التاسع، نستخدم التجربة والخطأ المنظمة.","answer":true,"reasons":["بتعويض قيم صحيحة لـ ن حتى نعثر على أول سنة تتجاوز الهدف","نحل معادلة خطية","نقسم الهدف على النسبة"],"reason":0},{"type":"tfr","q":"التقريب في الخطوات الوسطى قد يسبب خطأ في الناتج النهائي لمسائل النمو الأسي.","answer":true,"reasons":["لا يؤثر التقريب المبكر","لأن الأس يضخّم أي خطأ تقريب مبكر","يزيد الدقة"],"reason":1},{"type":"essay","q":"يبلغ عدد طيور في محمية طبيعية ٤٠٠ طائر ويزداد بنسبة ١٢٪ سنويًا. بعد كم سنة كاملة يتجاوز عددها ٦٠٠ طائر؟","model":"ن=٣: ٤٠٠×(١٫١٢)³ ≈ ٥٦٢. ن=٤: ٤٠٠×(١٫١٢)⁴ ≈ ٦٢٩ > ٦٠٠. إذن بعد ٤ سنوات كاملة."},{"type":"essay","q":"قارن بين استثمار ١٠٠٠ ريال بعائد ١٠٪ سنويًا لمدة ٣ سنوات بفائدة بسيطة (١٠٠ ريال سنويًا) مقابل فائدة مركبة.","model":"بسيطة: ١٠٠٠ + ٣٠٠ = ١٣٠٠ ريال. مركبة: ١٠٠٠ × (١٫١)³ = ١٣٣١ ريالًا. المركبة أكبر بـ ٣١ ريالًا."},{"type":"essay","q":"عينة مشعة كتلتها ٦٤٠ جم عمر النصف لها ٦ ساعات. احسب الكتلة المتبقية بعد ٢٤ ساعة.","model":"عدد الفترات ن = ٢٤ ÷ ٦ = ٤ فترات. المتبقي = ٦٤٠ × (٠٫٥)⁴ = ٦٤٠ ÷ ١٦ = ٤٠ جم."}]}},
  {"id":"g9-math-2-u16-1","grade":"g9","subject":"math","term":2,"unit":16,"no":1,"title":"مُحيط ومساحة الأشكال ثنائية الأبعاد","summary":"شرح متحرك بـ SVG لدرس مُحيط ومساحة الأشكال ثنائية الأبعاد (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-2d-perimeter-area.html","video":"","pdf":"","notes":["استخدم الارتفاع العمودي دائمًا في المساحات، والأضلاع الخارجية في المحيط.","شبه المنحرف = ١/٢(ق₁+ق₂)×ع | المثلث = ١/٢ ق×ع | المعين = ١/٢×ق₁×ق₂.","١ م² = ١٠٠٠٠ سم²."],"exercises":["احسب مساحة ومحيط متوازي أضلاع طول قاعدته ١٥ سم وضلعه المائل ٨ سم وارتفاعه العمودي ٦ سم.","أرض زراعية على شكل شبه منحرف قاعدتاها المتوازيتان ٣٠ م و٥٠ م، والمسافة العمودية بينهما ٢٠ م. احسب مساحتها.","غرفة على شكل حرف L أبعادها الخارجية ٨ م × ٦ م واقتُطع من زاويتها مستطيل ٣ م × ٢ م. احسب المساحة والمحيط."],"levels":{"easy":[{"type":"mcq","q":"ما مساحة متوازي أضلاع قاعدته ١٢ سم وارتفاعه العمودي ٥ سم وضلعه المائل ٦ سم؟","options":["٧٢ سم²","٦٠ سم²","٣٠ سم²","٣٦ سم²"],"answer":1,"why":"نضرب القاعدة في الارتفاع العمودي فقط: ١٢ × ٥ = ٦٠ سم²."},{"type":"mcq","q":"ما محيط متوازي الأضلاع في السؤال السابق؟","options":["٦٠ سم","٣٤ سم","٣٦ سم","١٨ سم"],"answer":2,"why":"المحيط = ٢ × (١٢ + ٦) = ٣٦ سم (باستخدام الضلع المائل)."},{"type":"mcq","q":"ما مساحة شبه منحرف قاعدتاه المتوازيتان ٦ سم و١٠ سم وارتفاعه ٤ سم؟","options":["٢٠ سم²","٦٤ سم²","٤٠ سم²","٣٢ سم²"],"answer":3,"why":"١/٢ × (٦ + ١٠) × ٤ = ٨ × ٤ = ٣٢ سم²."},{"type":"mcq","q":"مثلث مساحته ٢٨ سم² وقاعدته ٨ سم. ما ارتفاعه العمودي؟","options":["٧ سم","٣٫٥ سم","١٤ سم","٤ سم"],"answer":0,"why":"٢٨ = ١/٢ × ٨ × ع ← ٤ع = ٢٨ ← ع = ٧ سم."}],"medium":[{"type":"mcq","q":"معين طولا قطريه ١٠ سم و١٤ سم. ما مساحته؟","options":["١٤٠ سم²","٧٠ سم²","٤٨ سم²","٣٥ سم²"],"answer":1,"why":"١/٢ × ١٠ × ١٤ = ٧٠ سم²."},{"type":"mcq","q":"كم سنتيمترًا مربعًا في المتر المربع الواحد (١ م²)؟","options":["١٠٠٠ سم²","١٠٠ سم²","١٠٠٠٠ سم²","١٠٠٠٠٠ سم²"],"answer":2,"why":"١٠٠ سم × ١٠٠ سم = ١٠٠٠٠ سم²."},{"type":"mcq","q":"مساحة مثلث قاعدته ٩ م وارتفاعه ٦ م تساوي:","options":["٣٠ م²","٥٤ م²","١٥ م²","٢٧ م²"],"answer":3,"why":"١/٢ × ٩ × ٦ = ٢٧ م²."},{"type":"tfr","q":"في متوازي الأضلاع، نضرب القاعدة في طول الضلع المائل لإيجاد المساحة.","answer":false,"reasons":["نعم في الضلع المائل","بل في الارتفاع العمودي على القاعدة","نضرب في نصف الضلع المائل"],"reason":1},{"type":"tfr","q":"١ م² يساوي ١٠٠٠٠ سم².","answer":true,"reasons":["يساوي ١٠٠٠ سم²","يساوي ١٠٠ سم²","لأن ١ م = ١٠٠ سم فالمربع = ١٠٠ × ١٠٠ = ١٠٠٠٠ سم²"],"reason":2},{"type":"essay","q":"احسب مساحة ومحيط متوازي أضلاع طول قاعدته ١٥ سم وضلعه المائل ٨ سم وارتفاعه العمودي ٦ سم.","model":"المساحة = ١٥ × ٦ = ٩٠ سم². المحيط = ٢ × (١٥ + ٨) = ٤٦ سم."},{"type":"essay","q":"أرض زراعية على شكل شبه منحرف قاعدتاها المتوازيتان ٣٠ م و٥٠ م، والمسافة العمودية بينهما ٢٠ م. احسب مساحتها.","model":"المساحة = ١/٢ × (٣٠ + ٥٠) × ٢٠ = ٤٠ × ٢٠ = ٨٠٠ م²."}],"hard":[{"type":"mcq","q":"عند حساب محيط شكل مركّب قُسّم إلى مستطيلين، هل نجمع الضلع المشترك الداخلي؟","options":["لا، نجمع الأضلاع الخارجية فقط","نعم نجمعه مرة واحدة","نعم نجمعه مرتين","نطرحه من المساحة"],"answer":0,"why":"المحيط هو طول الحد الخارجي للشكل فقط."},{"type":"mcq","q":"شبه منحرف مساحته ٥٠ سم² وارتفاعه ٥ سم وإحدى قاعدتيه ٨ سم. ما طول القاعدة الأخرى؟","options":["٢٠ سم","١٢ سم","١٠ سم","١٨ سم"],"answer":1,"why":"٥٠ = ١/٢(٨+ق₂)×٥ ← ٢٠ = ٨ + ق₂ ← ق₂ = ١٢ سم."},{"type":"mcq","q":"قطعة أرض مستطيلة ٢٠ م × ١٥ م اقتُطع منها مربع طول ضلعه ٥ م. ما المساحة المتبقية؟","options":["٢٥٠ م²","٣٢٥ م²","٢٧٥ م²","٣٠٠ م²"],"answer":2,"why":"٣٠٠ − ٢٥ = ٢٧٥ م²."},{"type":"mcq","q":"مربع محيطه ٣٦ سم؛ ما مساحته؟","options":["١٨ سم²","٣٦ سم²","١٤٤ سم²","٨١ سم²"],"answer":3,"why":"الضلع = ٣٦ ÷ ٤ = ٩ سم ← المساحة = ٩² = ٨١ سم²."},{"type":"tfr","q":"مساحة شبه المنحرف تساوي نصف مجموع القاعدتين المتوازيتين مضروبًا في الارتفاع العمودي.","answer":true,"reasons":["١/٢ (ق₁ + ق₂) × ع","مجموع القاعدتين × الارتفاع","ق₁ × ق₂ × ع"],"reason":0},{"type":"tfr","q":"مساحة الطائرة الورقية تساوي نصف حاصل ضرب طولَي قطريها المتعامدين.","answer":true,"reasons":["ق₁ × ق₂","١/٢ × ق₁ × ق₂","مجموع القطرين"],"reason":1},{"type":"tfr","q":"إذا ضاعفنا طول ضلع مربع مرتين، فإن محيطه يتضاعف مرتين ومساحته تتضاعف مرتين.","answer":false,"reasons":["المحيط لا يتغير","كلاهما ٤ مرات","محيطه يتضاعف مرتين لكن مساحته تتضاعف ٤ مرات"],"reason":2},{"type":"essay","q":"غرفة على شكل حرف L أبعادها الخارجية ٨ م × ٦ م واقتُطع من زاويتها مستطيل ٣ م × ٢ م. احسب المساحة والمحيط.","model":"المساحة = (٨×٦) − (٣×٢) = ٤٨ − ٦ = ٤٢ م². المحيط = ٨+٦+٥+٢+٣+٤ = ٢٨ م (نفس محيط المستطيل الكبير)."},{"type":"essay","q":"معين مساحته ٦٠ سم² وطول أحد قطريه ١٢ سم. أوجد طول القطر الآخر.","model":"٦٠ = ١/٢ × ١٢ × ق₂ ← ٦٠ = ٦ ق₂ ← ق₂ = ١٠ سم."},{"type":"essay","q":"حوّل ٢٫٥ م² إلى سنتيمترات مربعة، موضحًا السبب.","model":"٢٫٥ × ١٠٠٠٠ = ٢٥٠٠٠ سم²، لأن كل متر مربع يساوي ١٠٠ سم × ١٠٠ سم = ١٠٠٠٠ سم²."}]}},
  {"id":"g9-math-2-u16-2","grade":"g9","subject":"math","term":2,"unit":16,"no":2,"title":"مُحيط الدائرة ومساحتها","summary":"شرح متحرك بـ SVG لدرس مُحيط الدائرة ومساحتها (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-circle-circumference-area.html","video":"","pdf":"","notes":["ح = ٢πنق = πق | م = πنق² (اقسم القطر على ٢ أولًا!).","محيط نصف الدائرة = πنق + ٢نق | محيط القطاع = القوس + ٢نق.","طول القوس = (θ/٣٦٠)×٢πنق | مساحة القطاع = (θ/٣٦٠)×πنق²."],"exercises":["احسب مساحة ومحيط دائرة قطرها ١٤ سم بدلالة π ثم مقربًا لأقرب منزلة عشرية (π ≈ ٣٫١٤٢).","قطاع دائري نصف قطره ٩ سم وزاويته المركزية ١٢٠°. احسب طول القوس، محيط القطاع، ومساحته بدلالة π.","حديقة دائرية قطرها ٢٠ م يحيط بها ممر دائري عرضه ٢ م. احسب مساحة الممر بدلالة π."],"levels":{"easy":[{"type":"mcq","q":"دائرة نصف قطرها ٧ سم. ما محيطها باستخدام π = ٢٢/٧؟","options":["٢٢ سم","١٥٤ سم","٤٤ سم","٨٨ سم"],"answer":2,"why":"٢ × (٢٢/٧) × ٧ = ٤٤ سم."},{"type":"mcq","q":"دائرة قطرها ١٢ سم. ما مساحتها بدلالة π؟","options":["٢٤π سم²","١٤٤π سم²","١٢π سم²","٣٦π سم²"],"answer":3,"why":"نق = ١٢ ÷ ٢ = ٦ سم ← م = π × ٦² = ٣٦π سم²."},{"type":"mcq","q":"ما محيط نصف دائرة نصف قطرها ٧ سم (استخدم π = ٢٢/٧)؟","options":["٣٦ سم","٢٢ سم","٢٩ سم","٤٤ سم"],"answer":0,"why":"طول القوس = ٢٢ سم + القطر ١٤ سم = ٣٦ سم."},{"type":"mcq","q":"قطاع دائري زاويته المركزية ٩٠° ونصف قطره ٤ سم. ما مساحته بدلالة π؟","options":["١٦π سم²","٤π سم²","٨π سم²","٢π سم²"],"answer":1,"why":"(٩٠/٣٦٠) × π × ١٦ = ١/٤ × ١٦π = ٤π سم²."}],"medium":[{"type":"mcq","q":"ما طول قوس دائرة نصف قطرها ١٠ سم وزاويته المركزية ١٨٠° بدلالة π؟","options":["٥π سم","٢٠π سم","١٠π سم","١٠٠π سم"],"answer":2,"why":"(١٨٠/٣٦٠) × ٢π × ١٠ = ١٠π سم."},{"type":"mcq","q":"دائرة مساحتها ٦٤π سم². ما طول قطرها؟","options":["٤ سم","٨ سم","٣٢ سم","١٦ سم"],"answer":3,"why":"نق² = ٦٤ ← نق = ٨ سم ← القطر = ١٦ سم."},{"type":"mcq","q":"عجلة محيطها ٢ متر. كم دورة كاملة تدور لقطع مسافة ١٠٠ متر؟","options":["٥٠ دورة","٢٠٠ دورة","٢٥ دورة","١٠٠ دورة"],"answer":0,"why":"١٠٠ ÷ ٢ = ٥٠ دورة."},{"type":"tfr","q":"محيط نصف دائرة يساوي نصف محيط الدائرة الكاملة فقط.","answer":false,"reasons":["يساوي ربع المحيط","نعم نصف المحيط فقط","يجب إضافة طول القطر المستقيم (π نق + ٢ نق)"],"reason":2},{"type":"tfr","q":"لإيجاد مساحة دائرة أُعطي قطرها، نقسم القطر على ٢ أولًا ثم نربّع ونضرب في π.","answer":true,"reasons":["لأن القانون π نق² يعتمد على نصف القطر","نربّع القطر مباشرة","نضرب القطر في π"],"reason":0},{"type":"essay","q":"احسب مساحة ومحيط دائرة قطرها ١٤ سم بدلالة π ثم مقربًا لأقرب منزلة عشرية (π ≈ ٣٫١٤٢).","model":"نق = ٧ سم. المحيط = ١٤π ≈ ٤٤٫٠ سم. المساحة = ٤٩π ≈ ١٥٣٫٩ سم²."},{"type":"essay","q":"قطاع دائري نصف قطره ٩ سم وزاويته المركزية ١٢٠°. احسب طول القوس، محيط القطاع، ومساحته بدلالة π.","model":"الكسر = ١٢٠/٣٦٠ = ١/٣. طول القوس = (١/٣)×١٨π = ٦π سم. محيط القطاع = ٦π + ١٨ سم. المساحة = (١/٣)×٨١π = ٢٧π سم²."}],"hard":[{"type":"mcq","q":"قطاع دائري زاويته ٧٢° يمثل أي كسر من الدائرة الكاملة؟","options":["١/٤","١/٥","١/٦","١/٣"],"answer":1,"why":"٧٢ ÷ ٣٦٠ = ١/٥."},{"type":"mcq","q":"مساحة حلقة دائرية (دائرتان متحدتا المركز نق₁=٥ سم، نق₂=٣ سم) بدلالة π هي:","options":["٢٥π سم²","٤π سم²","١٦π سم²","٣٤π سم²"],"answer":2,"why":"π(٥² − ٣²) = π(٢٥ − ٩) = ١٦π سم²."},{"type":"mcq","q":"محيط قطاع دائري نصف قطره ٥ سم وطول قوسه ٨ سم يساوي:","options":["٢٠ سم","١٣ سم","٨ سم","١٨ سم"],"answer":3,"why":"محيط القطاع = طول القوس + ٢ نق = ٨ + ١٠ = ١٨ سم."},{"type":"mcq","q":"إذا تضاعف نصف قطر دائرة مرتين، فإن مساحتها:","options":["تتضاعف ٤ مرات","تتضاعف مرتين","تبقى ثابتة","تتضاعف ٨ مرات"],"answer":0,"why":"π(٢نق)² = ٤ π نق²."},{"type":"tfr","q":"القطاع الدائري الذي زاويته المركزية ١٢٠° مساحته ثلث مساحة الدائرة.","answer":true,"reasons":["مساحته ربع الدائرة","لأن ١٢٠ ÷ ٣٦٠ = ١/٣","مساحته نصف الدائرة"],"reason":1},{"type":"tfr","q":"المساحة تقاس بوحدات طول مثل سم بينما المحيط يقاس بـ سم².","answer":false,"reasons":["كلاهما بـ سم²","نعم صحيح","العكس تمامًا: المحيط بـ سم والمساحة بـ سم²"],"reason":2},{"type":"tfr","q":"طول قوس القطاع يتناسب طرديًا مع زاويته المركزية θ عند ثبات نصف القطر.","answer":true,"reasons":["لأن طول القوس = (θ/٣٦٠) × ٢πنق","يتناسب عكسيًا","لا يعتمد على الزاوية"],"reason":0},{"type":"essay","q":"حديقة دائرية قطرها ٢٠ م يحيط بها ممر دائري عرضه ٢ م. احسب مساحة الممر بدلالة π.","model":"نق الداخلي = ١٠ م، نق الخارجي = ١٢ م. مساحة الممر = π(١٢² − ١٠²) = π(١٤٤ − ١٠٠) = ٤٤π م²."},{"type":"essay","q":"إذا كان محيط دائرة يساوي ٦٢٫٨ سم (اعتبر π = ٣٫١٤)، فاحسب مساحتها.","model":"نق = ٦٢٫٨ ÷ (٢ × ٣٫١٤) = ١٠ سم. المساحة = ٣٫١٤ × ١٠² = ٣١٤ سم²."},{"type":"essay","q":"ملعب جري يتكون من مستطيل ٨٠ م × ٤٠ م ونصفَي دائرة على طرفيه القصيرين (قطر كل منهما ٤٠ م). احسب محيطه الخارجي بدلالة π.","model":"نصفا الدائرة يشكّلان دائرة كاملة قطرها ٤٠ م، محيطها ٤٠π م. المحيط الكلي = ٨٠ + ٨٠ + ٤٠π = ١٦٠ + ٤٠π م."}]}},
  {"id":"g9-math-2-u16-3","grade":"g9","subject":"math","term":2,"unit":16,"no":3,"title":"مساحة الأشكال ثلاثية الأبعاد وحجمها","summary":"شرح متحرك بـ SVG لدرس مساحة الأشكال ثلاثية الأبعاد وحجمها (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-3d-surface-area-volume.html","video":"","pdf":"","notes":["المنشور والأسطوانة = القاعدة × ع | الهرم والمخروط = ١/٣ القاعدة × ع.","الكرة: الحجم ٤/٣ πنق³ | السطح ٤πنق².","١ لتر = ١٠٠٠ سم³ | ١ م³ = ١٠٠٠ لتر، ولا تحسب الأوجه الداخلية في مساحة السطح."],"exercises":["أسطوانة مغلقة نصف قطرها ٦ سم وارتفاعها ١٠ سم. احسب حجمها ومساحة سطحها الكلية بدلالة π.","مخروط نصف قطره ٦ سم وارتفاعه ٨ سم. احسب حجمه، وطول راسمه، ومساحة سطحه الكلية بدلالة π.","خزان ماء على شكل متوازي مستطيلات أبعاده ٢ م × ١٫٥ م × ١ م. احسب حجمه بالمتر المكعب وسعته باللترات."],"levels":{"easy":[{"type":"mcq","q":"أسطوانة نصف قطرها ٥ سم وارتفاعها ١٠ سم. ما حجمها بدلالة π؟","options":["٥٠٠π سم³","٥٠π سم³","١٠٠π سم³","٢٥٠π سم³"],"answer":3,"why":"ح = π نق² ع = π × ٢٥ × ١٠ = ٢٥٠π سم³."},{"type":"mcq","q":"ما حجم مخروط له نفس قاعدة وارتفاع الأسطوانة السابقة؟","options":["٢٥٠π/٣ سم³","٢٥٠π سم³","١٢٥π سم³","٧٥٠π سم³"],"answer":0,"why":"حجم المخروط يساوي ثلث حجم الأسطوانة المشتركة معه في القاعدة والارتفاع."},{"type":"mcq","q":"كرة نصف قطرها ٣ سم. ما حجمها بدلالة π؟","options":["٢٧π سم³","٣٦π سم³","١٢π سم³","١٠٨π سم³"],"answer":1,"why":"(٤/٣) × π × ٣³ = (٤/٣) × ٢٧π = ٣٦π سم³."},{"type":"mcq","q":"ما مساحة سطح كرة نصف قطرها ٥ سم بدلالة π؟","options":["٥٠π سم²","٢٥π سم²","١٠٠π سم²","٥٠٠π سم²"],"answer":2,"why":"٤ π نق² = ٤ × ٢٥π = ١٠٠π سم²."}],"medium":[{"type":"mcq","q":"هرم قاعدته مربعة طول ضلعها ٦ سم وارتفاعه ١٠ سم. ما حجمه؟","options":["٦٠ سم³","٣٦٠ سم³","١٨٠ سم³","١٢٠ سم³"],"answer":3,"why":"١/٣ × ٣٦ × ١٠ = ١٢٠ سم³."},{"type":"mcq","q":"متوازي مستطيلات أبعاده ٤ سم، ٥ سم، ١٠ سم. ما مساحة سطحه الكلية؟","options":["٢٢٠ سم²","٢٠٠ سم²","١١٠ سم²","١٨٠ سم²"],"answer":0,"why":"٢(٢٠ + ٤٠ + ٥٠) = ٢ × ١١٠ = ٢٢٠ سم²."},{"type":"mcq","q":"خزان ماء حجمه ٣٥٠٠ سم³. كم لترًا يتسع؟","options":["٣٥ لترًا","٣٫٥ لترات","٠٫٣٥ لتر","٣٥٠ لترًا"],"answer":1,"why":"٣٥٠٠ ÷ ١٠٠٠ = ٣٫٥ لترات."},{"type":"tfr","q":"حجم الهرم يساوي ثلث حجم المنشور الذي يساويه في القاعدة والارتفاع.","answer":true,"reasons":["ح = ١/٣ × مساحة القاعدة × ع","يساوي النصف","يساوي الربع"],"reason":0},{"type":"tfr","q":"المساحة الكلية لأسطوانة مفتوحة من الأعلى هي ٢πنق ع + ٢πنق².","answer":false,"reasons":["نعم قاعدتان","بل ٢πنق ع + πنق² لأن لها قاعدة واحدة فقط","بل ٢πنق ع فقط"],"reason":1},{"type":"essay","q":"أسطوانة مغلقة نصف قطرها ٦ سم وارتفاعها ١٠ سم. احسب حجمها ومساحة سطحها الكلية بدلالة π.","model":"الحجم = π × ٣٦ × ١٠ = ٣٦٠π سم³. مساحة السطح = ٢π(٦)(١٠) + ٢π(٣٦) = ١٢٠π + ٧٢π = ١٩٢π سم²."},{"type":"essay","q":"مخروط نصف قطره ٦ سم وارتفاعه ٨ سم. احسب حجمه، وطول راسمه، ومساحة سطحه الكلية بدلالة π.","model":"الحجم = ١/٣ × π × ٣٦ × ٨ = ٩٦π سم³. الراسم ل = √(٣٦+٦٤) = ١٠ سم. المساحة الكلية = π(٦)(١٠) + ٣٦π = ٩٦π سم²."}],"hard":[{"type":"mcq","q":"مخروط نصف قطره ٣ سم وارتفاعه ٤ سم. ما طول راسمه (ل)؟","options":["١٢ سم","٧ سم","٥ سم","٢٥ سم"],"answer":2,"why":"ل = √(٣² + ٤²) = √٢٥ = ٥ سم."},{"type":"mcq","q":"ما مساحة السطح الكلية لنصف كرة مصمتة نصف قطرها نق؟","options":["π نق²","٢ π نق²","٤ π نق²","٣ π نق²"],"answer":3,"why":"السطح المنحني ٢πنق² + القاعدة الدائرية πنق² = ٣πنق²."},{"type":"mcq","q":"منشور ثلاثي مساحة مقطعه المثلث ١٢ سم² وطوله ١٥ سم. ما حجمه؟","options":["١٨٠ سم³","٦٠ سم³","٩٠ سم³","٣٦٠ سم³"],"answer":0,"why":"ح = مساحة المقطع × الطول = ١٢ × ١٥ = ١٨٠ سم³."},{"type":"mcq","q":"ما المساحة الجانبية لأسطوانة نصف قطرها ٤ سم وارتفاعها ١٠ سم بدلالة π؟","options":["٤٠π سم²","٨٠π سم²","١١٢π سم²","١٦٠π سم²"],"answer":1,"why":"المساحة الجانبية = ٢ π نق ع = ٢ × ٤ × ١٠ π = ٨٠π سم²."},{"type":"tfr","q":"١ لتر يساوي ١٠٠٠ سم³.","answer":true,"reasons":["يساوي ١٠٠٠٠ سم³","يساوي ١٠٠ سم³","لذلك نقسم سم³ على ١٠٠٠ للتحويل إلى لترات"],"reason":2},{"type":"tfr","q":"في مجسم مركّب من أسطوانة يعلوها مخروط، نجمع مساحة الدائرة المشتركة بينهما ضمن مساحة السطح الخارجية.","answer":false,"reasons":["لا تُحسب لأنها داخلية غير مكشوفة","نعم نجمعها مرتين","نجمعها مرة واحدة"],"reason":0},{"type":"tfr","q":"في المخروط القائم يرتبط الراسم ل بنصف القطر نق والارتفاع ع بنظرية فيثاغورس: ل² = نق² + ع².","answer":true,"reasons":["ل = نق + ع","لأن ع عمودي على نق ويشكلان مثلثًا قائمًا وتره ل","ل² = ع² − نق²"],"reason":1},{"type":"essay","q":"خزان ماء على شكل متوازي مستطيلات أبعاده ٢ م × ١٫٥ م × ١ م. احسب حجمه بالمتر المكعب وسعته باللترات.","model":"الحجم = ٢ × ١٫٥ × ١ = ٣ م³. السعة = ٣ × ١٠٠٠ = ٣٠٠٠ لتر."},{"type":"essay","q":"كرة مساحتها السطحية ٦٤π سم². أوجد نصف قطرها ثم احسب حجمها بدلالة π.","model":"٤πنق² = ٦٤π ← نق² = ١٦ ← نق = ٤ سم. الحجم = (٤/٣)π(٦٤) = ٢٥٦π/٣ سم³."},{"type":"essay","q":"مكعب طول ضلعه ١٠ سم صُهر وأُعيد تشكيله على هيئة متوازي مستطيلات قاعدته ٢٠ سم × ٥ سم. ما ارتفاعه الجديد؟","model":"حجم المكعب = ١٠³ = ١٠٠٠ سم³. ١٠٠٠ = ٢٠ × ٥ × ع ← ١٠٠ع = ١٠٠٠ ← ع = ١٠ سم."}]}},
  {"id":"g9-math-2-u17-1","grade":"g9","subject":"math","term":2,"unit":17,"no":1,"title":"سعر الصرف","summary":"شرح متحرك بـ SVG لدرس سعر الصرف (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-exchange-rates.html","video":"","pdf":"","notes":["١ عملة(أ) = س عملة(ب): أ ← ب (× س) | ب ← أ (÷ س).","تحقق منطقيًا: التحويل من عملة أقوى لأضعف يكبّر الرقم، والعكس يصغّره.","وحّد العملة دائمًا قبل مقارنة الأسعار."],"exercises":["إذا كان سعر الصرف ١ ريال عُماني = ٢٫٦٠ دولار أمريكي، حوّل: (أ) ٣٥٠ ريالًا إلى دولارات، (ب) ٦٥٠ دولارًا إلى ريالات.","ساعة سعرها ٨٥ ريالًا في عُمان، وسعرها ٧٦٠ درهمًا في دبي (١ ريال = ٩٫٥٠ درهم). أين تكون أرخص وبكم ريال؟","حوّل سالم ٤٠٠ ريال إلى يورو بسعر ١ ريال = ٢٫٤٠ يورو، ثم أنفق ٦٠٠ يورو وعاد وحوّل الباقي إلى ريالات بنفس السعر. كم ريالًا عاد به؟"],"levels":{"easy":[{"type":"mcq","q":"إذا كان ١ ريال عُماني = ٢٫٦٠ دولار أمريكي، فكم دولارًا يساوي ٢٠٠ ريال؟","options":["٥٢٠ دولارًا","٧٦٫٩٢ دولارًا","٢٠٢٫٦ دولارًا","٢٦٠ دولارًا"],"answer":0,"why":"٢٠٠ × ٢٫٦٠ = ٥٢٠ دولارًا."},{"type":"mcq","q":"بالمعدل نفسه (١ ريال = ٢٫٦٠ دولار)، كم ريالًا عُمانيًا يساوي ٣٩٠ دولارًا؟","options":["١٠١٤ ريالًا","١٥٠ ريالًا","١٣٠ ريالًا","١٨٠ ريالًا"],"answer":1,"why":"٣٩٠ ÷ ٢٫٦٠ = ١٥٠ ريالًا."},{"type":"mcq","q":"إذا كان ١ ريال عُماني = ٩٫٥٠ درهم إماراتي، فكم درهمًا يساوي ٤٠ ريالًا؟","options":["٤٩٫٥ درهمًا","٤٫٢١ درهم","٣٨٠ درهمًا","٣٦٠ درهمًا"],"answer":2,"why":"٤٠ × ٩٫٥٠ = ٣٨٠ درهمًا."},{"type":"mcq","q":"بالمعدل السابق (١ ريال = ٩٫٥٠ درهم)، كم ريالًا يساوي ١٩٠ درهمًا؟","options":["٢٥ ريالًا","١٨٠٥ ريالات","١٩ ريالًا","٢٠ ريالًا"],"answer":3,"why":"١٩٠ ÷ ٩٫٥٠ = ٢٠ ريالًا."}],"medium":[{"type":"mcq","q":"إذا كان ١ ريال = ٢٫٤٠ يورو، فكم ريالًا يساوي ١ يورو تقريبًا؟","options":["٠٫٤١٧ ريال (٤١٧ بيسة)","٢٫٤٠ ريال","١٫٤٠ ريال","٠٫٢٤٠ ريال"],"answer":0,"why":"١ ÷ ٢٫٤٠ ≈ ٠٫٤١٧ ريال."},{"type":"mcq","q":"كتاب سعره ١٠ ريالات في مسقط، و٢٢ دولارًا عبر الإنترنت (١ ريال = ٢٫٦٠ دولار). أيهما أرخص؟","options":["في مسقط","عبر الإنترنت (≈ ٨٫٤٦ ريالات)","متساويان تمامًا","لا يمكن التحديد"],"answer":1,"why":"٢٢ ÷ ٢٫٦٠ ≈ ٨٫٤٦ ريالات < ١٠ ريالات."},{"type":"mcq","q":"إذا كان ١ جنيه إسترليني = ٠٫٥٠ ريال عُماني، فكم ريالًا يساوي ٨٠ جنيهًا؟","options":["٨٠٫٥ ريالًا","١٦٠ ريالًا","٤٠ ريالًا","٢٠ ريالًا"],"answer":2,"why":"٨٠ × ٠٫٥٠ = ٤٠ ريالًا."},{"type":"tfr","q":"إذا كان ١ ريال عُماني = ٢٫٦٠ دولار، فإن التحويل من الدولار إلى الريال يتم بالضرب في ٢٫٦٠.","answer":false,"reasons":["نعم بالضرب","بل بالقسمة على ٢٫٦٠ لأن الدولار أصغر من الريال","بالطرح من ٢٫٦٠"],"reason":1},{"type":"tfr","q":"لمقارنة سعر سلعة في بلدين بعملتين مختلفتين، يجب تحويلهما إلى نفس العملة أولًا.","answer":true,"reasons":["نجمع السعرين","نقارن الأرقام مباشرة","حتى تكون المقارنة على مقياس نقدي واحد"],"reason":2},{"type":"essay","q":"إذا كان سعر الصرف ١ ريال عُماني = ٢٫٦٠ دولار أمريكي، حوّل: (أ) ٣٥٠ ريالًا إلى دولارات، (ب) ٦٥٠ دولارًا إلى ريالات.","model":"(أ) ٣٥٠ × ٢٫٦٠ = ٩١٠ دولارات. (ب) ٦٥٠ ÷ ٢٫٦٠ = ٢٥٠ ريالًا عُمانيًا."},{"type":"essay","q":"ساعة سعرها ٨٥ ريالًا في عُمان، وسعرها ٧٦٠ درهمًا في دبي (١ ريال = ٩٫٥٠ درهم). أين تكون أرخص وبكم ريال؟","model":"في دبي: ٧٦٠ ÷ ٩٫٥٠ = ٨٠ ريالًا. إذن أرخص في دبي بـ ٥ ريالات عُمانية."}],"hard":[{"type":"mcq","q":"تحويل ٥٠٠ ريال في صرافة تأخذ عمولة ١٪؛ كم قيمة العمولة؟","options":["١٠ ريالات","٥٠ ريالًا","٠٫٥ ريال","٥ ريالات"],"answer":3,"why":"٥٠٠ × ٠٫٠١ = ٥ ريالات."},{"type":"mcq","q":"عند التحويل من عملة أجنبية إلى عملة الأساس المعطاة في صورة (١ أساس = س أجنبية) نستخدم عملية:","options":["القسمة على س","الضرب في س","الجمع مع س","الطرح من س"],"answer":0,"why":"العكس دائمًا بالقسمة على س."},{"type":"mcq","q":"سافر طالب بـ ٣٠٠ ريال وحوّلها إلى يورو بسعر ١ ريال = ٢٫٤٠ يورو، ثم أنفق ٥٠٠ يورو. كم يورو تبقى معه؟","options":["١٢٠ يورو","٢٢٠ يورو","٧٢٠ يورو","٣٠٠ يورو"],"answer":1,"why":"٣٠٠ × ٢٫٤٠ = ٧٢٠ يورو؛ المتبقي = ٧٢٠ − ٥٠٠ = ٢٢٠ يورو."},{"type":"mcq","q":"اشترى مسافر هدية بـ ٤٧٥ درهمًا إماراتيًا (١ ريال = ٩٫٥٠ درهم). كم تكلفتها بالريال العُماني؟","options":["٥٥ ريالًا","٤٥ ريالًا","٥٠ ريالًا","٤٧٫٥ ريالًا"],"answer":2,"why":"٤٧٥ ÷ ٩٫٥٠ = ٥٠ ريالًا."},{"type":"tfr","q":"إذا كان ١ ريال = ٩٫٥٠ درهم، فإن ١ درهم يساوي ١ ÷ ٩٫٥٠ ريال.","answer":true,"reasons":["مقلوب سعر الصرف يعطي التحويل العكسي","يساوي ٩٫٥٠ ريال","يساوي ٠٫٩٥ ريال"],"reason":0},{"type":"tfr","q":"إذا كان المبلغ بالريال العُماني أصغر من المبلغ المكافئ له بالدولار، فهذا يدل أن قيمة الريال أعلى من قيمة الدولار.","answer":true,"reasons":["يدل أن الدولار أقوى","فالوحدة الواحدة من الريال تشتري أكثر من دولارين ونصف","يدل أن العملتين متساويتان"],"reason":1},{"type":"tfr","q":"العمولة التي تتقاضاها محلات الصرافة تُضاف مجانًا إلى رصيد المسافر.","answer":false,"reasons":["لا توجد عمولات في الصرافة","نعم تُضاف هدية","بل تُقتطع كأجر خدمة للصرافة"],"reason":2},{"type":"essay","q":"حوّل سالم ٤٠٠ ريال إلى يورو بسعر ١ ريال = ٢٫٤٠ يورو، ثم أنفق ٦٠٠ يورو وعاد وحوّل الباقي إلى ريالات بنفس السعر. كم ريالًا عاد به؟","model":"٤٠٠ × ٢٫٤٠ = ٩٦٠ يورو. الباقي = ٩٦٠ − ٦٠٠ = ٣٦٠ يورو. بالريال = ٣٦٠ ÷ ٢٫٤٠ = ١٥٠ ريالًا."},{"type":"essay","q":"إذا كان ١ ريال = ٠٫٢٦ × ١٠ دولار، أوجد سعر صرف ١ دولار بالريال العُماني لأقرب ٣ منازل عشرية.","model":"١ ريال = ٢٫٦٠ دولار ← ١ دولار = ١ ÷ ٢٫٦٠ ≈ ٠٫٣٨٥ ريال (٣٨٥ بيسة)."},{"type":"essay","q":"اشترت عائلة تذاكر بقيمة ١٢٠ جنيهًا إسترلينيًا (١ ريال = ٢٫٠٠ جنيه). فإذا أضاف البنك عمولة ٢٪ على السعر بالريال، فكم دُفع إجمالًا؟","model":"السعر بالريال = ١٢٠ ÷ ٢ = ٦٠ ريالًا. مع العمولة ٢٪ = ٦٠ × ١٫٠٢ = ٦١٫٢٠ ريالًا."}]}},
  {"id":"g9-math-2-u17-2","grade":"g9","subject":"math","term":2,"unit":17,"no":2,"title":"المكسب","summary":"شرح متحرك بـ SVG لدرس المكسب (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-earnings-and-income.html","video":"","pdf":"","notes":["صافي الدخل = إجمالي الدخل − الاستقطاعات.","العمل الإضافي = ساعات × أجر الساعة × (١٫٥ أو ٢).","السنة = ١٢ شهرًا = ٥٢ أسبوعًا (لا تضرب الأسبوعي في ٤ للشهر!)."],"exercises":["يعمل موظف ٣٥ ساعة أسبوعيًا بأجر ٤ ريالات/ساعة، وفي أحد الأسابيع عمل ٦ ساعات إضافية بأجر مرة ونصف، و٤ ساعات يوم الجمعة بأجر مضاعف. احسب إجمالي دخله لذلك الأسبوع.","يتقاضى مندوب مبيعات راتبًا أساسيًا ٤٠٠ ريال + عمولة ٣٪ على المبيعات التي تزيد عن ٢٠٠٠ ريال. إذا باع بـ ٨٠٠٠ ريال، احسب إجمالي دخله.","إجمالي راتب موظفة ٩٠٠ ريال شهريًا، يُخصم منه ٧٪ للتقاعد و٢٥ ريالًا للتأمين الصحي. احسب صافي راتبها الشهري."],"levels":{"easy":[{"type":"mcq","q":"موظف راتبه السنوي ٩٦٠٠ ريال عُماني. كم راتبه الشهري؟","options":["٧٥٠ ريالًا","٨٠٠ ريال","٩٦٠ ريالًا","٦٠٠ ريال"],"answer":1,"why":"٩٦٠٠ ÷ ١٢ = ٨٠٠ ريال."},{"type":"mcq","q":"يعمل فني بأجر ٥ ريالات للساعة. كم يكسب مقابل ٤ ساعات إضافية بأجر «مرة ونصف»؟","options":["٤٠ ريالًا","٢٠ ريالًا","٣٠ ريالًا","٢٥ ريالًا"],"answer":2,"why":"٤ × ٥ × ١٫٥ = ٣٠ ريالًا."},{"type":"mcq","q":"بائع راتبه الأساسي ٢٥٠ ريالًا + عمولة ٤٪ على المبيعات. إذا باع بـ ٥٠٠٠ ريال، ما إجمالي دخله؟","options":["٥٠٠ ريال","٢٠٠ ريال","٢٧٠ ريالًا","٤٥٠ ريالًا"],"answer":3,"why":"العمولة = ٠٫٠٤ × ٥٠٠٠ = ٢٠٠؛ الإجمالي = ٢٥٠ + ٢٠٠ = ٤٥٠ ريالًا."},{"type":"mcq","q":"إجمالي راتب موظف ٧٠٠ ريال، وتُخصم منه ٧٪ للتأمينات الاجتماعية. ما صافي راتبه؟","options":["٦٥١ ريالًا","٦٩٣ ريالًا","٦٣٠ ريالًا","٧٤٩ ريالًا"],"answer":0,"why":"٧٠٠ × ٠٫٩٣ = ٦٥١ ريالًا (الخصم ٤٩ ريالًا)."}],"medium":[{"type":"mcq","q":"ما العلاقة الصحيحة بين صافي الدخل وإجمالي الدخل والاستقطاعات؟","options":["إجمالي الدخل = صافي الدخل − الاستقطاعات","صافي الدخل = إجمالي الدخل − الاستقطاعات","صافي الدخل = إجمالي الدخل + الاستقطاعات","الاستقطاعات = صافي الدخل × الإجمالي"],"answer":1,"why":"الاستقطاعات تُطرح من الإجمالي لإعطاء الصافي."},{"type":"mcq","q":"خياط يتقاضى ٢٫٥ ريال لكل ثوب. كم يكسب إذا خاط ٢٤ ثوبًا؟","options":["٤٨ ريالًا","٥٠ ريالًا","٦٠ ريالًا","٧٢ ريالًا"],"answer":2,"why":"٢٤ × ٢٫٥ = ٦٠ ريالًا."},{"type":"mcq","q":"كم أسبوعًا في السنة الميلادية عند حساب الرواتب؟","options":["٣٦ أسبوعًا","٤٨ أسبوعًا","٥٠ أسبوعًا","٥٢ أسبوعًا"],"answer":3,"why":"السنة تُحسب بـ ٥٢ أسبوعًا و١٢ شهرًا."},{"type":"tfr","q":"صافي الدخل يكون دائمًا أكبر من إجمالي الدخل.","answer":false,"reasons":["لا علاقة بينهما","نعم أكبر دائمًا","بل أقل منه أو مساويًا له لأن الاستقطاعات تُخصم من الإجمالي"],"reason":2},{"type":"tfr","q":"أجر العمل الإضافي بمعدل «مرة ونصف» يعني ضرب أجر الساعة العادي في ١٫٥.","answer":true,"reasons":["فإذا كان الأجر ٤ ريالات يصبح ٦ ريالات للساعة الإضافية","يعني ضربه في ٢","يعني إضافة ١٫٥ ريال فقط"],"reason":0},{"type":"essay","q":"يعمل موظف ٣٥ ساعة أسبوعيًا بأجر ٤ ريالات/ساعة، وفي أحد الأسابيع عمل ٦ ساعات إضافية بأجر مرة ونصف، و٤ ساعات يوم الجمعة بأجر مضاعف. احسب إجمالي دخله لذلك الأسبوع.","model":"عادي: ٣٥×٤ = ١٤٠. إضافي ١٫٥: ٦×٤×١٫٥ = ٣٦. إضافي ×٢: ٤×٤×٢ = ٣٢. الإجمالي = ١٤٠ + ٣٦ + ٣٢ = ٢٠٨ ريالات."},{"type":"essay","q":"يتقاضى مندوب مبيعات راتبًا أساسيًا ٤٠٠ ريال + عمولة ٣٪ على المبيعات التي تزيد عن ٢٠٠٠ ريال. إذا باع بـ ٨٠٠٠ ريال، احسب إجمالي دخله.","model":"المبيعات الخاضعة للعمولة = ٨٠٠٠ − ٢٠٠٠ = ٦٠٠٠ ريال. العمولة = ٠٫٠٣ × ٦٠٠٠ = ١٨٠ ريالًا. الإجمالي = ٤٠٠ + ١٨٠ = ٥٨٠ ريالًا."}],"hard":[{"type":"mcq","q":"عامل أجر ساعته العادية ٣ ريالات، عمل ٤٠ ساعة عادية + ٥ ساعات إضافية بأجر مضاعف (×٢). ما أجره الكلي؟","options":["١٥٠ ريالًا","١٣٥ ريالًا","١٢٠ ريالًا","١٦٠ ريالًا"],"answer":0,"why":"عادي: ٤٠×٣=١٢٠؛ إضافي: ٥×٣×٢=٣٠؛ الكلي = ١٥٠ ريالًا."},{"type":"mcq","q":"أيهما أعلى دخلًا سنويًا: ١٢٠ ريالًا أسبوعيًا أم ٥٠٠ ريال شهريًا؟","options":["٥٠٠ ريال شهريًا (٦٠٠٠ ريال سنويًا)","١٢٠ ريالًا أسبوعيًا (٦٢٤٠ ريالًا سنويًا)","متساويان تمامًا","لا يمكن المقارنة"],"answer":1,"why":"١٢٠ × ٥٢ = ٦٢٤٠ > ٥٠٠ × ١٢ = ٦٠٠٠."},{"type":"mcq","q":"يُعرف المبلغ الذي يتقاضاه البائع كنسبة مئوية من قيمة مبيعاته بـ:","options":["المعاش","الاستقطاع","العمولة","الضريبة"],"answer":2,"why":"العمولة نسبة من المبيعات."},{"type":"mcq","q":"إذا كان صافي راتب موظف ٥٤٠ ريالًا بعد خصم ١٠٪ استقطاعات، فما إجمالي راتبه؟","options":["٥٥٠ ريالًا","٥٩٤ ريالًا","٤٨٦ ريالًا","٦٠٠ ريال"],"answer":3,"why":"٥٤٠ ÷ ٠٫٩٠ = ٦٠٠ ريال (نسبة مئوية عكسية!)."},{"type":"tfr","q":"لتحويل الراتب الأسبوعي إلى سنوي نضرب في ٤٨.","answer":false,"reasons":["نعم في ٤٨","بل نضرب في ٥٢ لأن السنة ٥٢ أسبوعًا","نضرب في ١٢"],"reason":1},{"type":"tfr","q":"الدخل القائم على العمولة يزداد كلما زادت قيمة مبيعات الموظف.","answer":true,"reasons":["يقل بزيادة المبيعات","ثابت لا يتغير","لأن العمولة نسبة مئوية من إجمالي المبيعات"],"reason":2},{"type":"tfr","q":"تُحسب نسبة التأمينات أو الاستقطاعات النسبية عادةً من إجمالي الدخل.","answer":true,"reasons":["ثم تُطرح منه للحصول على صافي الدخل","تُحسب من الصافي","تُضاف للإجمالي"],"reason":0},{"type":"essay","q":"إجمالي راتب موظفة ٩٠٠ ريال شهريًا، يُخصم منه ٧٪ للتقاعد و٢٥ ريالًا للتأمين الصحي. احسب صافي راتبها الشهري.","model":"خصم التقاعد = ٠٫٠٧ × ٩٠٠ = ٦٣ ريالًا. مجموع الاستقطاعات = ٦٣ + ٢٥ = ٨٨ ريالًا. الصافي = ٩٠٠ − ٨٨ = ٨١٢ ريالًا."},{"type":"essay","q":"قارن بين عرضي عمل: (أ) ٥٥٠ ريالًا شهريًا، (ب) ١٣٠ ريالًا أسبوعيًا. أيهما أفضل وبكم سنويًا؟","model":"(أ) ٥٥٠ × ١٢ = ٦٦٠٠ ريال/سنة. (ب) ١٣٠ × ٥٢ = ٦٧٦٠ ريال/سنة. إذن العرض (ب) أفضل بـ ١٦٠ ريالًا سنويًا."},{"type":"essay","q":"إذا كان صافي راتب موظف ٧٤٤ ريالًا بعد خصم ٧٪ استقطاعات، فأوجد إجمالي راتبه الأصلي.","model":"عامل الضرب = ٠٫٩٣. الإجمالي = ٧٤٤ ÷ ٠٫٩٣ = ٨٠٠ ريال عُماني."}]}},
  {"id":"g9-math-2-u17-3","grade":"g9","subject":"math","term":2,"unit":17,"no":3,"title":"اقتراض النقود واستثمارها","summary":"شرح متحرك بـ SVG لدرس اقتراض النقود واستثمارها (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-borrowing-and-investing.html","video":"","pdf":"","notes":["فائدة بسيطة: ف = (أ×ر×ن)÷١٠٠ (حوّل الأشهر لسنوات بالقسمة على ١٢!).","فائدة مركبة: ج = أ(١ + ر/١٠٠)^ن، والربح = ج − أ.","سعر التقسيط = الدفعة المقدمة + (عدد الأقساط × القسط)."],"exercises":["استثمر شخص ٣٠٠٠ ريال بمعدل ٥٪ سنويًا لمدة ٣ سنوات. احسب الجملة والفائدة (أ) بالفائدة البسيطة، (ب) بالفائدة المركبة، وأوجد الفرق.","ثلاجة سعرها النقدي ٣٢٠ ريالًا، وتُباع بالتقسيط بدفعة مقدمة ٥٠ ريالًا + ١٢ قسطًا شهريًا قيمة كل قسط ٢٥ ريالًا. احسب السعر بالتقسيط والزيادة المئوية عن السعر النقدي.","اقترضت أسرة ٦٠٠٠ ريال بتمويل بسيط ٦٪ سنويًا لمدة ٤ سنوات. احسب المبلغ الإجمالي للسداد وقيمة القسط الشهري."],"levels":{"easy":[{"type":"mcq","q":"ما الفائدة البسيطة لمبلغ ٢٠٠٠ ريال بمعدل ٥٪ سنويًا لمدة ٣ سنوات؟","options":["٢٣٠٠ ريال","١٠٠ ريال","٣٠٠ ريال","١٥٠ ريالًا"],"answer":2,"why":"(٢٠٠٠ × ٥ × ٣) ÷ ١٠٠ = ٣٠٠ ريال."},{"type":"mcq","q":"ما جملة المبلغ في السؤال السابق؟","options":["٢١٥٠ ريالًا","٣٠٠ ريال","٢١٠٠ ريال","٢٣٠٠ ريال"],"answer":3,"why":"ج = أ + ف = ٢٠٠٠ + ٣٠٠ = ٢٣٠٠ ريال."},{"type":"mcq","q":"ما جملة استثمار ١٠٠٠ ريال بفائدة مركبة ١٠٪ سنويًا لمدة سنتين؟","options":["١٢١٠ ريالات","١٢٠٠ ريال","١١٠٠ ريال","٢١٠ ريالات"],"answer":0,"why":"١٠٠٠ × (١٫١)² = ١٢١٠ ريالات."},{"type":"mcq","q":"جهاز سعره النقدي ٤٠٠ ريال، وبالتقسيط: ٥٠ ريالًا مقدمًا + ١٠ أقساط كل منها ٤٠ ريالًا. كم يزيد سعر التقسيط عن النقدي؟","options":["٤٥٠ ريالًا","٥٠ ريالًا","٤٠ ريالًا","١٠٠ ريال"],"answer":1,"why":"التقسيط = ٥٠ + ٤٠٠ = ٤٥٠ ريالًا؛ الزيادة = ٤٥٠ − ٤٠٠ = ٥٠ ريالًا."}],"medium":[{"type":"mcq","q":"احسب الفائدة البسيطة لمبلغ ١٢٠٠ ريال بمعدل ٦٪ سنويًا لمدة ٦ أشهر:","options":["٤٣٢ ريالًا","٧٢ ريالًا","٣٦ ريالًا","١٨ ريالًا"],"answer":2,"why":"٦ أشهر = ٠٫٥ سنة؛ (١٢٠٠ × ٦ × ٠٫٥) ÷ ١٠٠ = ٣٦ ريالًا."},{"type":"mcq","q":"استُثمر مبلغ ٨٠٠ ريال بفائدة بسيطة فكسب ١٦٠ ريالًا خلال ٤ سنوات. ما المعدل السنوي ر؟","options":["١٠٪","٤٪","٨٪","٥٪"],"answer":3,"why":"ر = (١٠٠ × ١٦٠) ÷ (٨٠٠ × ٤) = ١٦٠٠٠ ÷ ٣٢٠٠ = ٥٪."},{"type":"mcq","q":"للسنة الأولى فقط وبنفس المعدل والمبلغ، الفائدة المركبة السنوية مقارنة بالبسيطة تكون:","options":["مساوية لها تمامًا","أكبر منها دائمًا","أصغر منها دائمًا","ضعفها"],"answer":0,"why":"في السنة الأولى (ن = ١) يكون أ(١+ر/١٠٠) = أ + أر/١٠٠."},{"type":"tfr","q":"في الفائدة البسيطة يتساوى مقدار الفائدة المكتسبة في كل سنة.","answer":true,"reasons":["لأنها تُحسب دائمًا على المبلغ الأصلي الثابت أ","تزداد كل سنة","تنقص كل سنة"],"reason":0},{"type":"tfr","q":"عند حساب الفائدة البسيطة لمدة ٩ أشهر نعوض ن = ٩ في القانون.","answer":false,"reasons":["نعم ن = ٩","بل ن = ٩/١٢ = ٠٫٧٥ سنة لأن المعدل سنوي","بل ن = ٠٫٩"],"reason":1},{"type":"essay","q":"استثمر شخص ٣٠٠٠ ريال بمعدل ٥٪ سنويًا لمدة ٣ سنوات. احسب الجملة والفائدة (أ) بالفائدة البسيطة، (ب) بالفائدة المركبة، وأوجد الفرق.","model":"(أ) بسيطة: ف = (٣٠٠٠×٥×٣)/١٠٠ = ٤٥٠ ريالًا، ج = ٣٤٥٠ ريالًا. (ب) مركبة: ج = ٣٠٠٠×(١٫٠٥)³ = ٣٤٧٢٫٨٨ ريالًا، ف = ٤٧٢٫٨٨ ريالًا. الفرق = ٢٢٫٨٨ ريالًا."},{"type":"essay","q":"ثلاجة سعرها النقدي ٣٢٠ ريالًا، وتُباع بالتقسيط بدفعة مقدمة ٥٠ ريالًا + ١٢ قسطًا شهريًا قيمة كل قسط ٢٥ ريالًا. احسب السعر بالتقسيط والزيادة المئوية عن السعر النقدي.","model":"بالتقسيط = ٥٠ + (١٢×٢٥) = ٣٥٠ ريالًا. الزيادة = ٣٠ ريالًا. النسبة المئوية = (٣٠ ÷ ٣٢٠) × ١٠٠٪ ≈ ٩٫٣٨٪."}],"hard":[{"type":"mcq","q":"تُحسب الفائدة المركبة على:","options":["المبلغ الأصلي فقط","المبلغ الأصلي مضافًا إليه الفوائد المتراكمة سابقًا","الفوائد فقط دون الأصل","القسط الشهري فقط"],"answer":1,"why":"كل سنة تضاف الفائدة للأصل لتوليد فائدة جديدة."},{"type":"mcq","q":"كم سنة يلزم لمبلغ ١٠٠٠ ريال بمعدل بسيط ٨٪ سنويًا ليحقق فائدة مقدارها ٢٤٠ ريالًا؟","options":["٤ سنوات","سنتان","٣ سنوات","٥ سنوات"],"answer":2,"why":"ن = (١٠٠ × ٢٤٠) ÷ (١٠٠٠ × ٨) = ٣ سنوات."},{"type":"mcq","q":"مبلغ إجمالي لتمويل ٣٦٠٠ ريال يُسدَّد على ١٨ قسطًا شهريًا متساويًا. ما قيمة القسط الشهري؟","options":["١٥٠ ريالًا","١٨٠ ريالًا","٢٥٠ ريالًا","٢٠٠ ريال"],"answer":3,"why":"٣٦٠٠ ÷ ١٨ = ٢٠٠ ريال."},{"type":"mcq","q":"إذا كان المعدل السنوي ٦٪، فكم يكون الزمن ن (بالسنوات) لمدة ٣ أشهر؟","options":["٠٫٢٥ سنة (١/٤)","٣ سنوات","٠٫٣ سنة","٠٫٥ سنة"],"answer":0,"why":"٣ ÷ ١٢ = ٠٫٢٥ سنة."},{"type":"tfr","q":"تتفوق الفائدة المركبة على الفائدة البسيطة ابتداءً من السنة الثانية فصاعدًا.","answer":true,"reasons":["البسيطة أكبر دائمًا","تتفوق من السنة الأولى","لأنها تبدأ بحساب عائد على عائد السنة الأولى"],"reason":2},{"type":"tfr","q":"السعر الإجمالي بالتقسيط يساوي الدفعة المقدمة زائد مجموع الأقساط كلها.","answer":true,"reasons":["التقسيط = المقدم + (عدد الأقساط × القسط)","يساوي مجموع الأقساط فقط","يساوي السعر النقدي"],"reason":0},{"type":"tfr","q":"طول فترة سداد التمويل يقلل التكلفة الإجمالية للتمويل.","answer":false,"reasons":["نعم يقلل التكلفة","بل يزيد التكلفة الإجمالية رغم أنه يقلل القسط الشهري","لا يؤثر على التكلفة"],"reason":1},{"type":"essay","q":"اقترضت أسرة ٦٠٠٠ ريال بتمويل بسيط ٦٪ سنويًا لمدة ٤ سنوات. احسب المبلغ الإجمالي للسداد وقيمة القسط الشهري.","model":"ف = (٦٠٠٠×٦×٤)/١٠٠ = ١٤٤٠ ريالًا. الإجمالي = ٧٤٤٠ ريالًا. القسط الشهري (على ٤٨ شهرًا) = ٧٤٤٠ ÷ ٤٨ = ١٥٥ ريالًا."},{"type":"essay","q":"ما المبلغ الأصلي الذي يحقق فائدة بسيطة قدرها ٣٦٠ ريالًا خلال ٣ سنوات بمعدل ٤٪ سنويًا؟","model":"أ = (١٠٠ × ٣٦٠) ÷ (٤ × ٣) = ٣٦٠٠٠ ÷ ١٢ = ٣٠٠٠ ريال عُماني."},{"type":"essay","q":"اشرح باختصار الفرق بين الفائدة البسيطة والفائدة المركبة ومتى يتساويان.","model":"البسيطة تُحسب على الأصل فقط (نمو خطي)، أما المركبة فتُحسب على الأصل + الفوائد السابقة (نمو أسي). يتساويان عند ن = ١ سنة فقط."}]}},
  {"id":"g9-math-2-u17-4","grade":"g9","subject":"math","term":2,"unit":17,"no":4,"title":"البيع والشراء","summary":"شرح متحرك بـ SVG لدرس البيع والشراء (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-buying-and-selling.html","video":"","pdf":"","notes":["نسبة الربح/الخسارة = (المقدار ÷ سعر التكلفة) × ١٠٠٪.","نسبة الخصم = (الخصم ÷ السعر المُعلن) × ١٠٠٪.","لإيجاد السعر الأصلي (التكلفة أو المعلن) اقسم السعر الجديد على عامل الضرب."],"exercises":["اشترى تاجر ٨٠ كجم من البرتقال بسعر ٠٫٥٠٠ ريال للكيلوجرام. تلف منها ٨ كجم، وباع الباقي بسعر ٠٫٧٥٠ ريال للكيلوجرام. احسب صافي ربحه ونسبة ربحه المئوية.","باع متجر جهاز تلفاز بـ ٢٧٦ ريالًا محققًا ربحًا نسبته ١٥٪. احسب سعر التكلفة الأصلي ومقدار الربح.","أعلن محل عن خصم ٢٥٪ على حقيبة سعرها المعلن ٣٦ ريالًا. احسب السعر بعد الخصم، ثم احسب السعر النهائي بعد إضافة ٥٪ ضريبة قيمة مضافة."],"levels":{"easy":[{"type":"mcq","q":"اشترى تاجر ساعة بـ ٤٠ ريالًا وباعها بـ ٥٠ ريالًا. ما النسبة المئوية للربح؟","options":["١٢٥٪","٢٠٪","١٠٪","٢٥٪"],"answer":3,"why":"الربح = ١٠؛ (١٠ ÷ ٤٠) × ١٠٠٪ = ٢٥٪."},{"type":"mcq","q":"اشترى شخص هاتفًا بـ ٢٠٠ ريال وباعه بعد فترة بـ ١٥٠ ريالًا. ما النسبة المئوية للخسارة؟","options":["٢٥٪","٣٣٫٣٪","٥٠٪","٧٥٪"],"answer":0,"why":"الخسارة = ٥٠؛ (٥٠ ÷ ٢٠٠) × ١٠٠٪ = ٢٥٪."},{"type":"mcq","q":"سلعة تكلفتها ٨٠ ريالًا، بكم يجب بيعها لتحقيق ربح ٣٠٪؟","options":["١١٠ ريالات","١٠٤ ريالات","٥٦ ريالًا","٩٦ ريالًا"],"answer":1,"why":"٨٠ × ١٫٣٠ = ١٠٤ ريالات."},{"type":"mcq","q":"باع متجر طاولة بـ ٩٢ ريالًا بربح ١٥٪. ما سعر تكلفتها الأصلي؟","options":["٧٧ ريالًا","٧٨٫٢ ريالًا","٨٠ ريالًا","٨٥ ريالًا"],"answer":2,"why":"٩٢ ÷ ١٫١٥ = ٨٠ ريالًا."}],"medium":[{"type":"mcq","q":"بيعت دراجة بـ ٦٠ ريالًا بخسارة ٢٥٪. ما سعر شرائها الأصلي؟","options":["٨٥ ريالًا","٧٥ ريالًا","٤٥ ريالًا","٨٠ ريالًا"],"answer":3,"why":"٦٠ ÷ ٠٫٧٥ = ٨٠ ريالًا."},{"type":"mcq","q":"تُحسب النسبة المئوية للربح أو الخسارة بقسمة مقدار الربح أو الخسارة على:","options":["سعر التكلفة (الشراء)","سعر البيع","مجموع السعرين","الفرق بين السعرين"],"answer":0,"why":"المرجع دائمًا هو سعر التكلفة."},{"type":"mcq","q":"ثوب سعره المعلن ٢٥ ريالًا عليه خصم ٢٠٪. كم يدفع المشتري؟","options":["٥ ريالات","٢٠ ريالًا","٢٢ ريالًا","١٨ ريالًا"],"answer":1,"why":"٢٥ × ٠٫٨٠ = ٢٠ ريالًا."},{"type":"tfr","q":"لحساب النسبة المئوية للربح نقسم مقدار الربح على سعر البيع ثم نضرب في ١٠٠٪.","answer":false,"reasons":["نعم على سعر البيع","بل نقسم دائمًا على سعر التكلفة (الشراء)","نقسم على ١٠٠"],"reason":1},{"type":"tfr","q":"لإيجاد سعر التكلفة لسلعة بيعت بربح ٢٠٪ نقسم سعر البيع على ١٫٢٠.","answer":true,"reasons":["نطرح ٢٠٪ من سعر البيع","نضرب في ٠٫٨٠","لأن سعر البيع يمثل ١٢٠٪ من سعر التكلفة"],"reason":2},{"type":"essay","q":"اشترى تاجر ٨٠ كجم من البرتقال بسعر ٠٫٥٠٠ ريال للكيلوجرام. تلف منها ٨ كجم، وباع الباقي بسعر ٠٫٧٥٠ ريال للكيلوجرام. احسب صافي ربحه ونسبة ربحه المئوية.","model":"التكلفة = ٨٠ × ٠٫٥ = ٤٠ ريالًا. الكمية المباعة = ٧٢ كجم. المبيعات = ٧٢ × ٠٫٧٥ = ٥٤ ريالًا. الربح = ١٤ ريالًا. نسبة الربح = (١٤÷٤٠)×١٠٠٪ = ٣٥٪."},{"type":"essay","q":"باع متجر جهاز تلفاز بـ ٢٧٦ ريالًا محققًا ربحًا نسبته ١٥٪. احسب سعر التكلفة الأصلي ومقدار الربح.","model":"التكلفة = ٢٧٦ ÷ ١٫١٥ = ٢٤٠ ريالًا. مقدار الربح = ٢٧٦ − ٢٤٠ = ٣٦ ريالًا."}],"hard":[{"type":"mcq","q":"اشترى تاجر ٢٠ كتابًا بـ ٣ ريالات للكتاب، وباعها جميعًا بـ ٧٥ ريالًا. ما نسبة ربحه؟","options":["٢٠٪","١٥٪","٢٥٪","٣٠٪"],"answer":2,"why":"التكلفة = ٦٠ ريالًا؛ الربح = ١٥؛ (١٥÷٦٠)×١٠٠٪ = ٢٥٪."},{"type":"mcq","q":"فاتورة مطعم ٥٠ ريالًا خُصم منها ١٠٪ ثم أُضيفت ٥٪ ضريبة قيمة مضافة. كم المبلغ النهائي؟","options":["٥٢٫٥٠ ريالًا","٤٧٫٥٠ ريالًا","٤٥ ريالًا","٤٧٫٢٥ ريالًا"],"answer":3,"why":"٥٠ × ٠٫٩٠ × ١٫٠٥ = ٤٧٫٢٥ ريالًا."},{"type":"mcq","q":"معطف سعره المعلن ٦٠ ريالًا بيع في التنزيلات بـ ٤٢ ريالًا. ما النسبة المئوية للخصم؟","options":["٣٠٪","١٨٪","٤٢٫٨٪","٢٥٪"],"answer":0,"why":"الخصم = ١٨؛ (١٨ ÷ ٦٠) × ١٠٠٪ = ٣٠٪."},{"type":"mcq","q":"إذا كان سعر البيع أقل من سعر التكلفة، فإن التاجر يحقق:","options":["ربحًا","خسارة","تعادلًا","عمولة"],"answer":1,"why":"البيع < التكلفة يعني خسارة."},{"type":"tfr","q":"تُحسب النسبة المئوية للخصم بقسمة مقدار الخصم على السعر المُعلن قبل التخفيض.","answer":true,"reasons":["نسبة الخصم = (الخصم ÷ السعر المعلن) × ١٠٠٪","على السعر بعد الخصم","على سعر التكلفة"],"reason":0},{"type":"tfr","q":"خصم ١٠٪ ثم إضافة ضريبة ٥٪ يعطي نفس النتيجة كإضافة ضريبة ٥٪ ثم خصم ١٠٪.","answer":true,"reasons":["النتيجة مختلفة","لأن الضرب إبدالي: ٠٫٩٠ × ١٫٠٥ = ١٫٠٥ × ٠٫٩٠ = ٠٫٩٤٥","يكون خصمًا صافيًا ٥٪"],"reason":1},{"type":"tfr","q":"إذا اشترى تاجر سلعة بـ ٥٠ ريالًا وباعها بـ ٥٠ ريالًا، فنسبة ربحه ١٠٠٪.","answer":false,"reasons":["نسبة ربحه ٥٠٪","نعم ١٠٠٪","بل ٠٪ لأنه لم يحقق ربحًا ولا خسارة"],"reason":2},{"type":"essay","q":"أعلن محل عن خصم ٢٥٪ على حقيبة سعرها المعلن ٣٦ ريالًا. احسب السعر بعد الخصم، ثم احسب السعر النهائي بعد إضافة ٥٪ ضريبة قيمة مضافة.","model":"بعد الخصم = ٣٦ × ٠٫٧٥ = ٢٧ ريالًا. مع الضريبة = ٢٧ × ١٫٠٥ = ٢٨٫٣٥ ريالًا عُمانيًا."},{"type":"essay","q":"اشترى ماجد سيارة مستعملة بـ ٣٢٠٠ ريال، وأصلحها بـ ٣٠٠ ريال، ثم باعها بـ ٤٢٠٠ ريال. احسب النسبة المئوية لربحه.","model":"إجمالي التكلفة = ٣٢٠٠ + ٣٠٠ = ٣٥٠٠ ريال. الربح = ٤٢٠٠ − ٣٥٠٠ = ٧٠٠ ريال. نسبة الربح = (٧٠٠ ÷ ٣٥٠٠) × ١٠٠٪ = ٢٠٪."},{"type":"essay","q":"بيعت قطعة أثاث بـ ١٥٢ ريالًا بخسارة ٢٠٪. كم كان يجب أن تُباع لتحقيق ربح ١٠٪؟","model":"التكلفة = ١٥٢ ÷ ٠٫٨٠ = ١٩٠ ريالًا. للبيع بربح ١٠٪: ١٩٠ × ١٫١٠ = ٢٠٩ ريالات."}]}}
